function injectHeaderCssOnce(){
  if (document.getElementById('eh2-header-style')) return;
  var css = `
    #${ids.header}{position:relative;display:grid;grid-template-columns:1fr auto;align-items:center;row-gap:6px;margin-bottom:4px;min-height:36px;padding:0 12px;}
    #${ids.keyWrap}{display:flex;align-items:center;gap:8px;justify-self:end;width:260px;white-space:nowrap;}
    #${ids.keySelect}{padding:6px 8px;border:1px solid #e2e8f0;border-radius:8px;background:#fff;font:12px Arial;width:160px}
  `;
  var st=document.createElement('style'); st.id='eh2-header-style'; st.textContent=css; document.head.appendChild(st);
}
function ensureHeaderEl(){ var h=getEl(ids.header); if(!h){ h=document.createElement('div'); h.id=ids.header; h.className='eh-header'; (getCardEl()||document.body).prepend(h);} return h; }
function keyIdOf(it){ try{return String(it.dataKey && (it.dataKey.name ?? it.dataKey.label ?? ''));}catch(_){return '';} }
function keyLabelOf(it){ try{return String((it.dataKey&&(it.dataKey.label||it.dataKey.name))||'Data Key');}catch(_){return 'Data Key';} }
function collectDataKeys(){ var seen={}; dataKeyList=[]; (self.ctx.data||[]).forEach(function(it){ var id=keyIdOf(it); if(!id) return; var label=keyLabelOf(it); if(!seen[id]){seen[id]=true; dataKeyList.push({id,label});}}); }
function buildKeyDropdown(){
  injectHeaderCssOnce();
  var header=ensureHeaderEl();
  var range = getEl(ids.rangeGroup);
  if (range && range.parentElement!==header){ try{ header.insertBefore(range, header.firstChild); }catch(_){ } }

  var wrap=document.getElementById(ids.keyWrap); if(!wrap){ wrap=document.createElement('div'); wrap.id=ids.keyWrap; header.appendChild(wrap); }
  collectDataKeys();
  wrap.innerHTML = `<label>Customer:</label><select id="${ids.keySelect}"></select>`;
  var sel=getEl(ids.keySelect); sel.innerHTML='';
  dataKeyList.forEach(k=>{ var o=document.createElement('option'); o.value=k.id; o.textContent=k.label; sel.appendChild(o); });
  if (!selectedKeyId || !dataKeyList.some(x=>String(x.id)===String(selectedKeyId))) selectedKeyId = dataKeyList.length?dataKeyList[0].id:null;
  if (selectedKeyId) sel.value = selectedKeyId;
  sel.onchange=function(){ selectedKeyId=this.value; self.onDataUpdated(); };
}

