function wireHourModeButtons(){
  const group = getEl(ids.hourGroup); if(!group) return;
  group.addEventListener('click', function(ev){
    const btn = ev.target.closest('.eh-btn--chip'); if(!btn) return;
    const mode = btn.getAttribute('data-hour-mode'); if (mode===hourMode) return;
    hourMode = mode;
    Array.from(group.querySelectorAll('.eh-btn--chip')).forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    if(lastHeatmapMap){ updateCanvasSize(); drawHeatmap(lastHeatmapMap);
      const wrap=document.querySelector('.eh-scroll-wrap');
      if (wrap && mode==='10h'){ setTimeout(()=>wrap.scrollLeft=wrap.scrollWidth/3.2,100); } else if (wrap) wrap.scrollLeft=0; }
  });
}
function wireRangeButtons(){
  var wrap=getEl(ids.rangeGroup); if(!wrap) return;
  wrap.addEventListener('click', function(ev){
    var btn=ev.target.closest('.eh-btn--chip'); if(!btn) return;
    Array.from(wrap.querySelectorAll('.eh-btn--chip')).forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    var mode=btn.getAttribute('data-range');
    if (mode==='custom') openRangeModal();
    else { setPresetRange(mode); self.onDataUpdated(); }
  });
}
function setPresetRange(mode){
  currentMode = mode;
  var now=new Date(); var end=endOfDay(now).getTime(); var start=new Date(now);
  if (mode==='1d') start=startOfDay(now);
  else if (mode==='1w'){ start.setDate(now.getDate()-6); start=startOfDay(start); }
  else if (mode==='1m'){ start.setDate(now.getDate()-29); start=startOfDay(start); }
  startMs=start.getTime(); endMs=end; buildDaysCount();
}
function setActiveRangeChip(mode){
  var wrap=getEl(ids.rangeGroup); if(!wrap) return;
  Array.from(wrap.querySelectorAll('.eh-btn--chip')).forEach(b=>b.classList.remove('active'));
  var target=wrap.querySelector(`[data-range="${mode}"]`); if(target) target.classList.add('active');
}

/*************** MODAL (2 CALENDARS) ***************/
var modalState = { start:null, end:null, base:null };
function daysInMatrix(baseDate){
  var y=baseDate.getFullYear(), m=baseDate.getMonth();
  var first=new Date(y,m,1), dowMon0=(first.getDay()+6)%7, dim=daysInMonth(y,m), prevDim=daysInMonth(y,m-1);
  var cells=[];
  for (var i=0;i<dowMon0;i++) cells.push({y:y,m:m-1,d:prevDim-dowMon0+1+i,out:true});
  for (var d=1; d<=dim; d++) cells.push({y:y,m:m,d:d,out:false});
  while (cells.length%7!==0){ var last=cells[cells.length-1]; cells.push({y:last.m===11?last.y+1:last.y,m:(last.m+1)%12,d:(last.d||0)+1,out:true}); }
  while (cells.length<42){ var L=cells[cells.length-1]; cells.push({y:L.m===11?L.y+1:L.y,m:(L.m+1)%12,d:(L.d||0)+1,out:true}); }
  return cells;
}
function sameDate(a,b){ return a && b && a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(); }
function isBetween(d, a, b){ if(!a||!b) return false; var x=a.getTime(), y=b.getTime(); if(x>y){var t=x;x=y;y=t;} var t0=startOfDay(d).getTime(); return t0>=startOfDay(x).getTime() && t0<=startOfDay(y).getTime(); }

function renderCalendars(){
  var left = modalState.base ? firstOfMonth(modalState.base) : firstOfMonth(new Date());
  var right = firstOfMonth(addMonths(left,1));
  getEl(ids.titleL).textContent = monthLabel(left);
  getEl(ids.titleR).textContent = monthLabel(right);
  fillGrid(getEl(ids.gridL), left);
  fillGrid(getEl(ids.gridR), right);
}
function fillGrid(container, monthDate){
  container.innerHTML='';
  daysInMatrix(monthDate).forEach(function(c){
    var realMonth=(c.m%12+12)%12, realYear=c.m<0?c.y-1:(c.m>11?c.y+1:c.y);
    var d=new Date(realYear,realMonth,c.d);
    var el=document.createElement('div'); el.className='eh2-day'+(c.out?' out':''); el.textContent=String(c.d);
    if (modalState.start && sameDate(d, modalState.start)) el.classList.add('edge','sel');
    if (modalState.end && sameDate(d, modalState.end)) el.classList.add('edge','sel');
    if (modalState.start && modalState.end && isBetween(d, modalState.start, modalState.end)) el.classList.add('in');
    el.onclick=function(){
      if (c.out) return;
      if (!modalState.start || (modalState.start && modalState.end)){
        modalState.start = startOfDay(d); modalState.end=null;
      } else {
        if (d.getTime() < modalState.start.getTime()){ modalState.end = modalState.start; modalState.start = startOfDay(d); }
        else { modalState.end = startOfDay(d); }
      }
      renderCalendars();
    };
    container.appendChild(el);
  });
}

function openRangeModal(){
  var overlay=getEl(ids.overlay);
  var now = new Date();
  // seed selection từ range hiện tại nếu có
  if (startMs && endMs){
    modalState.start = startOfDay(new Date(startMs));
    modalState.end   = startOfDay(new Date(endMs));
  } else {
    modalState.start = mondayOfCurrentWeek(now);
    modalState.end   = startOfDay(now);
  }
  modalState.base = firstOfMonth(modalState.start||now);
  renderCalendars();

  // GẮN HANDLER NGAY TẠI ĐÂY (ghi đè mỗi lần mở)
  getEl(ids.prevL).onclick = function(){ modalState.base = addMonths(modalState.base,-1); renderCalendars(); };
  getEl(ids.nextL).onclick = function(){ modalState.base = addMonths(modalState.base, 1); renderCalendars(); };
  getEl(ids.prevR).onclick = function(){ modalState.base = addMonths(modalState.base,-1); renderCalendars(); };
  getEl(ids.nextR).onclick = function(){ modalState.base = addMonths(modalState.base, 1); renderCalendars(); };

  getEl(ids.quickWeek).onclick = function(){
    var s=mondayOfCurrentWeek(now), e=startOfDay(now);
    modalState.start=s; modalState.end=e; modalState.base=firstOfMonth(s); renderCalendars();
  };
  getEl(ids.quickMonth).onclick = function(){
    var s=startOfDay(new Date(now.getFullYear(), now.getMonth(), 1)), e=startOfDay(now);
    modalState.start=s; modalState.end=e; modalState.base=firstOfMonth(s); renderCalendars();
  };

  getEl(ids.close).onclick  = closeOverlay;
  getEl(ids.cancel).onclick = closeOverlay;
  overlay.onclick = function(ev){ if (ev.target===overlay) closeOverlay(); };

  // ✅ APPLY: cập nhật range + render ngay
  getEl(ids.apply).onclick = function(){
    if (!modalState.start){ alert('Select start date'); return; }
    if (!modalState.end) modalState.end = modalState.start;
    var s = startOfDay(modalState.start), e = endOfDay(modalState.end);
    if (e < s){ var t=s; s=e; e=t; }
    startMs = s.getTime();
    endMs   = e.getTime();
    currentMode = 'custom';
    buildDaysCount();
    closeOverlay();
    setActiveRangeChip('custom');   // đồng bộ chip
    self.onDataUpdated();           // 🔥 vẽ lại heatmap
  };

  // hiển thị
  window.addEventListener('keydown', escToClose);
  overlay.style.display='block';

  function closeOverlay(){
    overlay.style.display='none';
    window.removeEventListener('keydown', escToClose);
  }
  function escToClose(e){ if(e.key==='Escape') closeOverlay(); }
}


/*************** INIT / RESIZE / DESTROY ***************/
var resizeObs=null;
self.onInit = function(){
  injectLegendRightStylesOnce();
  buildKeyDropdown();
  var layout = ensureMainWrap(); heatmapCanvas=layout.canvas; heatmapCtx=heatmapCanvas.getContext('2d');
  wireRangeButtons(); wireHourModeButtons();
  setPresetRange('1w');   // default 7 ngày
  updateCanvasSize(); self.onDataUpdated();
  try{ resizeObs=new ResizeObserver(function(){ if(updateCanvasSize()&&lastHeatmapMap) drawHeatmap(lastHeatmapMap); }); resizeObs.observe(getEl(ids.main)); }catch(_){}
  safeSetupTooltip();
};
self.onResize = function(){ if(updateCanvasSize()&&lastHeatmapMap) drawHeatmap(lastHeatmapMap); };
self.onDestroy = function(){ try{resizeObs&&resizeObs.disconnect();}catch(_){} };

/*************** LEGEND / DATA / DRAW ***************/
function renderLegend(){
  var legend=getEl(ids.legend); if(!legend){ legend=document.createElement('div'); legend.id=ids.legend; }
  var main=getEl(ids.main)||ensureMainWrap().main; if(legend.parentElement!==main) main.appendChild(legend);
  legend.innerHTML='';
  var PALETTE=getPaletteForSelectedKey();
  if (!BINS.length || BINS[BINS.length-1].to !== domainMax) BINS = buildDiscreteBinsZeroToMax(domainMax, LEVEL_COUNT);
  BINS.forEach(function(b){
    var chip=document.createElement('div'); chip.className='eh-chip';
    var sw=document.createElement('span'); sw.className='eh-swatch'; sw.style.background=PALETTE[b.level];
    var txt=document.createElement('span'); txt.textContent = b.to<b.from ? '—' : (b.from+' – '+b.to);
    chip.appendChild(sw); chip.appendChild(txt); legend.appendChild(chip);
  });
}
function agg(arr){ if(!arr||!arr.length) return 0; return arr.reduce((a,b)=>a+b,0); }
function formatInt(v){ return isFinite(v)? String(Math.round(v)) : '—'; }

self.onDataUpdated = function(){
  buildKeyDropdown(); ensureMainWrap();
  if (!self.ctx.data || self.ctx.data.length<1) { renderLegend(); updateCanvasSize(); drawNoData('No data'); return; }
  if (!selectedKeyId) { renderLegend(); updateCanvasSize(); drawNoData('No data'); return; }

  var items=(self.ctx.data||[]).filter(function(it){ return keyIdOf(it)===selectedKeyId; });
  if (!items.length){ renderLegend(); updateCanvasSize(); drawNoData('No data'); return; }

  var rows=Math.max(1,yDays); var map={};
  for (var h=0; h<24; h++) for (var d=0; d<rows; d++) map[h+'_'+d]={values:[], value:0, has:false};

  function pushSeries(series){
    for (var i=0;i<series.length;i++){
      var p=series[i]; if(!p||p.length<2) continue;
      var ts=Number(p[0]), val=Number(p[1]); if(!isFinite(ts)||!isFinite(val)) continue;
      if (ts<startMs||ts>endMs) continue;
      var dIdx=dayIndexOf(ts); if(dIdx<0||dIdx>=rows) continue;
      var hr=new Date(ts).getHours(); var key=hr+'_'+dIdx; map[key].values.push(val); map[key].has=true;
    }
  }
  items.forEach(function(item){ var series=Array.isArray(item&&item.data)?item.data:[]; if(series.length) pushSeries(series); });
  Object.keys(map).forEach(function(k){ map[k].value = agg(map[k].values); });
  lastHeatmapMap = map;

  var now=new Date(), nowHour=now.getHours(), baseDay=startOfDay(startMs).getTime(), maxVal=-Infinity;
  for (var hh=0; hh<24; hh++){
    for (var dd=0; dd<rows; dd++){
      var theDay=new Date(baseDay+dd*MS.day);
      var skip=(hh===nowHour && ymd(theDay)===ymd(now));
      if (skip) continue;
      var cell=map[hh+'_'+dd], v=cell&&cell.value;
      if (cell&&cell.has&&isFinite(v)&&v>maxVal) maxVal=v;
    }
  }
  if (!isFinite(maxVal)) maxVal=0;
  domainMin=0; domainMax=Math.max(0,Math.ceil(maxVal));
  BINS = buildDiscreteBinsZeroToMax(domainMax, LEVEL_COUNT);

  renderLegend(); updateCanvasSize(); drawHeatmap(map);
};

function drawNoData(msg){
  var c=getEl(ids.canvas), ctx=c?c.getContext('2d'):null; if(!c||!ctx) return;
  updateCanvasSize(); ctx.clearRect(0,0,c.width,c.height);
  ctx.fillStyle='#64748b'; ctx.font='14px Arial'; ctx.textAlign='center';
  ctx.fillText(msg||'No data', c.width/2, c.height/2);
}
function drawHeatmap(map){
  const c=getEl(ids.canvas), ctx=c.getContext('2d'); ctx.clearRect(0,0,c.width,c.height);
  const rows=Math.max(1,yDays);
  const padL=PAD_HM.L, padT=PAD_HM.T, padR=PAD_HM.R, padB=PAD_HM.B;
  const gridW=c.width-padL-padR, gridH=c.height-padT-padB;

  const startHour = hourMode==='10h'? 7 : 0;
  const endHour   = hourMode==='10h'? 19:23;
  const cols=endHour-startHour+1;

  const cw=gridW/cols, ch=gridH/rows;

  // x-axis hours
  ctx.fillStyle="#475569"; ctx.font="12px Arial"; ctx.textAlign="center";
  for (let h=startHour; h<=endHour; h+=2){
    ctx.fillText(String(h).padStart(2,'0')+":00", padL+(h-startHour)*cw+cw/2, padT-6);
  }
  // y-axis days
  ctx.textAlign="right";
  for (let d=0; d<rows; d++){
    const y=padT+d*ch+ch/2;
    const date=new Date(startOfDay(startMs).getTime()+d*MS.day);
    const label=date.toLocaleDateString("en-GB",{weekday:"short",day:"2-digit",month:"short"});
    ctx.fillText(label, padL-6, y+4);
  }

  const PALETTE=getPaletteForSelectedKey();
  for (let hh=startHour; hh<=endHour; hh++){
    for (let dd=0; dd<rows; dd++){
      const x0=padL+(hh-startHour)*cw, y0=padT+dd*ch;
      const cell=map[hh+'_'+dd]; const v=(cell&&cell.value)||0;
      const lc=levelColor(v, !!(cell&&cell.has), domainMin, domainMax, PALETTE);
      ctx.fillStyle=lc.css; ctx.fillRect(x0+1, y0+1, cw-2, ch-2);
      if (cell&&cell.has&&cw>26&&ch>20){
        ctx.fillStyle=(lc.level>=0&&lc.lum<0.5)?"#fff":"#0f172a";
        ctx.font="11px Arial"; ctx.textAlign="center";
        ctx.fillText(formatInt(v), x0+cw/2, y0+ch/2+4);
      }
    }
  }
}

/*************** SIZE & TOOLTIP ***************/
function updateCanvasSize(){
  const canvas=getEl(ids.canvas); if(!canvas) return false;
  const card=getCardEl(), header=getEl(ids.header);
  const cs=getComputedStyle(card), padV=parseFloat(cs.paddingTop)+parseFloat(cs.paddingBottom);
  const headerH=header?header.offsetHeight:0, cardH=card?card.clientHeight:400;
  const availableH=cardH-(padV+headerH), targetH=Math.max(260,Math.floor(availableH));

  const cardW=card?card.clientWidth:800;
  const totalCols=hourMode==='10h'?13:24; const cellMinWidth=60;
  const targetW=Math.max(cardW, totalCols*cellMinWidth + PAD_HM.L + PAD_HM.R);

  let changed=false;
  if (canvas.width!==targetW){ canvas.width=targetW; changed=true; }
  if (canvas.height!==targetH){ canvas.height=targetH; changed=true; }

  const wrap=canvas.parentElement;
  if (wrap){ wrap.style.width="100%"; wrap.style.flex="1 1 auto"; wrap.style.height=(targetH-35)+"px"; }
  return changed;
}
function safeSetupTooltip(){
  const canvas=getEl(ids.canvas), tooltip=getEl(ids.tooltip), card=getCardEl(); if(!canvas||!tooltip||!card) return;
  if(!tooltip.parentElement){ try{card.appendChild(tooltip);}catch(_){ } }
  function hide(){ tooltip.style.display='none'; canvas.style.cursor='default'; }
  function show(clientX,clientY,html){
    tooltip.innerHTML=html; tooltip.style.display='block';
    const cardBox=card.getBoundingClientRect(), tt=tooltip.getBoundingClientRect();
    const x=clientX-cardBox.left, y=clientY-cardBox.top;
    tooltip.style.left=Math.max(12, x-tt.width/2)+'px';
    tooltip.style.top =Math.max(12, y-tt.height-12)+'px';
  }
  canvas.addEventListener('mousemove', function(ev){
    if(!lastHeatmapMap||!startMs||!endMs) return hide();
    const rect=canvas.getBoundingClientRect(), mx=ev.clientX-rect.left, my=ev.clientY-rect.top;
    const padL=PAD_HM.L,padT=PAD_HM.T,padR=PAD_HM.R,padB=PAD_HM.B;
    const gridW=canvas.width-padL-padR, gridH=canvas.height-padT-padB;
    const rows=Math.max(1,yDays), startHour=hourMode==='10h'?7:0, endHour=hourMode==='10h'?19:23, cols=endHour-startHour+1;
    const cw=gridW/cols, ch=gridH/rows;
    if(mx<padL||mx>padL+gridW||my<padT||my>padT+gridH) return hide();
    const hh=startHour+Math.floor((mx-padL)/cw), dd=Math.floor((my-padT)/ch);
    const key=hh+'_'+dd, cell=lastHeatmapMap[key]; if(!cell) return hide();
    const v=(cell&&cell.value)||0, date=new Date(startOfDay(startMs).getTime()+dd*MS.day);
    const h0=String(hh).padStart(2,'0')+":00", h1=String((hh+1)%24).padStart(2,'0')+":00";
    const ds=date.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});
    if(!cell.has) show(ev.clientX,ev.clientY,`<b>${ds}</b><br>${h0} – ${h1}<br><b>No data</b>`);
    else show(ev.clientX,ev.clientY,`<b>${ds}</b><br>${h0} – ${h1}<br>People: <b>${formatInt(v)}</b>`);
  });
  canvas.addEventListener('mouseleave', ()=>tooltip.style.display='none');
}

/*************** BOOT ***************/
document.addEventListener('DOMContentLoaded', function(){
  if(!self.ctx) self.ctx = { data: [] };
  if(typeof self.onInit==='function') self.onInit();
});

