/* Giữ widget full-size trong card của ThingsBoard */
:host, .tb-widget, .tb-widget-container {
  height: 100%;
}

#wrap {
  height: 100%; /* JS sẽ set 90% theo logic gốc khi init */
  width: 100%;
}

#gender-pie {
  display: block;
  width: 100%;
  height: 100%;
}

descriptor.controllerScript:
/* global Chart, ChartDataLabels */
self.onInit = function () {
  // ====== DOM & context ======
  const $root = self.ctx.$container[0];
  const wrap = $root.querySelector('#wrap');
  const canvas = $root.querySelector('#gender-pie');
  if (!wrap || !canvas) {
    self.ctx.$container.html('<div id="wrap" style="height:100%"><canvas id="gender-pie"></canvas></div>');
  }
  const _wrap = self.ctx.$container[0].querySelector('#wrap');
  const _canvas = self.ctx.$container[0].querySelector('#gender-pie');
  const ctx = _canvas.getContext('2d');

  // ====== Settings ======
  const S = Object.assign({
    labels: ['Male','Female'],
    colors: ['#59B5FF', '#FF96D0'],
    spacingPx: 0,          // v2 không hỗ trợ
    offsetPx: 10,          // v2 không hỗ trợ
    hoverOffsetPx: 8,      // v2 không hỗ trợ
    cutout: '0%',          // v2: chỉ tác dụng với doughnut. Pie = 0%
    radius: '80%',         // v2 không hỗ trợ
    paddingPx: 2,
    borderRadius: 4,       // v2 không hỗ trợ
    legendPosition: 'bottom',
    datalabelFontSize: 16,
    showCenterTotal: false,
    centerTotalFont: '600 16px Inter, system-ui, sans-serif',
    centerTotalFmt: (m,f)=>`Total: ${m+f}`,

    // ====== Thêm mới cho "tách miếng" & khe hở ======
    explodePx: 1,          // khoảng đẩy mỗi miếng (px)
    ringGapPx: 2           // độ rộng “khe” giữa các miếng (px) bằng borderWidth
  }, (self.ctx.settings || {}));

  // ====== Full area ======
  self.ctx.$container.css({ height: '100%', padding: 0, margin: 0 });
  _wrap.style.height = '90%';

  // ====== Retina-safe sizing ======
  function sizeCanvas() {
    const w = _wrap.clientWidth || 300;
    const h = _wrap.clientHeight || 200;
    const dpr = (window.devicePixelRatio || 1);
    _canvas.style.width = w + 'px';
    _canvas.style.height = h + 'px';
    _canvas.width = Math.floor(w * dpr);
    _canvas.height = Math.floor(h * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  sizeCanvas();

  // ====== Helpers (normalize & lấy dữ liệu) ======
  function normalizeGenderStr(s){
    if (s == null) return '';
    const t = String(s).replace(/"/g,'').trim().toLowerCase();
    if (t === 'male' || t === 'm' || t === 'nam' || t === '1' || t === 'true') return 'male';
    if (t === 'female' || t === 'f' || t === 'nu' || t === 'nữ' || t === '0' || t === 'false') return 'female';
    if (t.startsWith('m')) return 'male';
    if (t.startsWith('f')) return 'female';
    return '';
  }
  function safeParseArray(x){
    if (Array.isArray(x)) return x;
    if (typeof x === 'string') {
      try { const arr = JSON.parse(x); return Array.isArray(arr) ? arr : null; } catch(_e){}
    }
    return null;
  }
  function extractGenders(payload){
    if (payload && typeof payload === 'object' && 'v' in payload) payload = payload.v;
    if (payload && typeof payload === 'object' && 'value' in payload && Object.keys(payload).length === 1) payload = payload.value;

    if (typeof payload === 'string'){
      const arr = safeParseArray(payload);
      if (arr) return arr.map(x => normalizeGenderStr(x)).filter(Boolean);
      const g = normalizeGenderStr(payload); return g ? [g] : [];
    }
    if (Array.isArray(payload)){
      return payload.map(x => normalizeGenderStr(x)).filter(Boolean);
    }
    if (payload && typeof payload === 'object'){
      let g = payload.gender ?? payload.genders ?? (payload.values && (payload.values.gender ?? payload.values.genders));
      if (g != null){
        const arr = safeParseArray(g) || (Array.isArray(g) ? g : [g]);
        return arr.map(x => normalizeGenderStr(x)).filter(Boolean);
      }
      const ma = payload.male_ages || (payload.values && payload.values.male_ages);
      const fa = payload.female_ages || (payload.values && payload.values.female_ages);
      const mCnt = (safeParseArray(ma) || (Array.isArray(ma) ? ma : [])).length;
      const fCnt = (safeParseArray(fa) || (Array.isArray(fa) ? fa : [])).length;
      const out = [];
      for (let i=0;i<mCnt;i++) out.push('male');
      for (let i=0;i<fCnt;i++) out.push('female');
      return out;
    }
    return [];
  }
  function getTWRange(ctx){
    try{
      const stw = (ctx && ctx.defaultSubscription && ctx.defaultSubscription.subscriptionTimewindow) || ctx.timewindow;
      const now = Date.now();
      if (stw?.realtime?.timewindowMs) return { start: now - stw.realtime.timewindowMs, end: now };
      const fixed = stw?.history?.fixedTimewindow;
      if (fixed?.startTimeMs && fixed?.endTimeMs) return { start: fixed.startTimeMs, end: fixed.endTimeMs };
      if (stw?.history?.timewindowMs) return { start: now - stw.history.timewindowMs, end: now };
    } catch(_e){}
    return { start: -Infinity, end: Infinity };
  }
  function collectGenderCountsFromTB(ctx){
    const rng = getTWRange(ctx);
    let male = 0, female = 0;
    try{
      const sub = ctx && ctx.defaultSubscription;
      const blocks = (sub && sub.data) || [];
      for (let i=0;i<blocks.length;i++){
        const block = blocks[i] || {};
        const arrs = [block.data || [], block.latestData || []];
        for (const dataArr of arrs){
          for (let j=0;j<dataArr.length;j++){
            const p = dataArr[j]; if (!p || p.length < 2) continue;
            const ts = p[0]; if (!(ts >= rng.start && ts <= rng.end)) continue;
            const gs = extractGenders(p[1]);
            for (let k=0;k<gs.length;k++){ if (gs[k]==='male') male++; else if (gs[k]==='female') female++; }
          }
        }
      }
    } catch(_e){}
    return { male, female };
  }
  function computeCounts(){
    const c = collectGenderCountsFromTB(self.ctx);
    if ((c.male + c.female) > 0) return c;
    return [].reduce((a,v)=>{
      const k=normalizeGenderStr(v); if (k) a[k]=(a[k]||0)+1; return a;
    }, {male:0,female:0});

  }

  // ====== Plugins cho Chart.js v2 ======
  if (typeof ChartDataLabels !== 'undefined') {
    Chart.plugins.register(ChartDataLabels);
  }

  // Plugin: hiện tổng ở giữa (nếu bật)
  const CenterTotalPlugin = {
    id: 'centerTotal',
    afterDraw: function(chart) {
      const opts = (chart.options && chart.options.centerTotal) ||
                   (chart.options && chart.options.plugins && chart.options.plugins.centerTotal) || {};
      if (!opts.enabled) return;

      const ds = chart.data && chart.data.datasets && chart.data.datasets[0];
      if (!ds) return;
      const total = (ds.data || []).reduce((a,b)=>a+(+b||0),0);
      const label = (opts.formatter || (t=>String(t)))(total);

      const meta = chart.getDatasetMeta && chart.getDatasetMeta(0);
      const center = meta && meta.data && meta.data[0] && meta.data[0].getCenterPoint
        ? meta.data[0].getCenterPoint()
        : null;
      if (!center) return;

      const ctx2 = chart.chart.ctx;
      ctx2.save();
      ctx2.font = opts.font || '600 16px system-ui';
      ctx2.textAlign = 'center';
      ctx2.textBaseline = 'middle';
      ctx2.fillStyle = opts.color || '#444';
      ctx2.fillText(label, center.x, center.y);
      ctx2.restore();
    }
  };
  Chart.plugins.register(CenterTotalPlugin);

  // Plugin: tách miếng (explode) cho pie v2
//   const ExplodePiePlugin = {
//     id: 'explodePie',
//     afterUpdate: function(chart) {
//       const cfg = chart.options && chart.options.plugins && chart.options.plugins.explodePie;
//       if (!cfg || !cfg.enabled) return;
//       const off = Number(cfg.offset || 0);
//       if (!off) return;

//       const meta = chart.getDatasetMeta(0);
//       if (!meta || !meta.data) return;

//       meta.data.forEach(function(arc){
//         const m = arc && arc._model;
//         if (!m) return;
//         const mid = (m.startAngle + m.endAngle) / 2;
//         const dx = Math.cos(mid) * off;
//         const dy = Math.sin(mid) * off;
//         m.x += dx;
//         m.y += dy;
//       });
//     }
//   };
//   Chart.plugins.register(ExplodePiePlugin);
// Plugin: tách miếng (explode) cho pie v2 — KHÔNG cộng dồn
// Plugin: tách miếng (explode) cho Chart.js v2 — cố định, không cộng dồn
const ExplodePiePlugin = {
  id: 'explodePie',
  afterUpdate: function(chart) {
    const cfg = chart.options && chart.options.plugins && chart.options.plugins.explodePie;
    if (!cfg || !cfg.enabled) return;

    const off = Number(cfg.offset || 0);
    if (!off) return;

    const meta = chart.getDatasetMeta(0);
    if (!meta || !meta.data || !chart.chartArea) return;

    // Tâm gốc của pie lấy từ chartArea -> tuyệt đối, không bị cộng dồn
    const baseX = (chart.chartArea.left + chart.chartArea.right) / 2;
    const baseY = (chart.chartArea.top + chart.chartArea.bottom) / 2;

    meta.data.forEach(function(arc){
      const m = arc && arc._model;
      if (!m) return;

      // Góc giữa lát
      const mid = (m.startAngle + m.endAngle) / 2;

      // Offset tuyệt đối từ tâm gốc
      const dx = Math.cos(mid) * off;
      const dy = Math.sin(mid) * off;

      // GÁN LẠI tuyệt đối -> không cộng dồn
      m.x = baseX + dx;
      m.y = baseY + dy;

      // Đảm bảo view sync với model trong tick hiện tại
      if (arc._view) {
        arc._view.x = m.x;
        arc._view.y = m.y;
      }
    });
  }
};
Chart.plugins.register(ExplodePiePlugin);



  const padPx = (typeof S.paddingPx === 'number' && S.paddingPx >= 0)
    ? S.paddingPx
    : Math.ceil(Math.max(2, S.ringGapPx || 0)) + 6;

  const counts = computeCounts();

  // Lấy màu nền card để viền khớp nền (tạo khe hở như spacing)
  let cardBg = '#fff';
  try {
    const cs = window.getComputedStyle(_wrap);
    if (cs && cs.backgroundColor) cardBg = cs.backgroundColor;
  } catch (_e) {}

  self.chart = new Chart(ctx, {
    type: 'pie',
    data: {
      labels: S.labels,
      datasets: [{
        data: [counts.male, counts.female],
        backgroundColor: S.colors,
        borderWidth: (S.ringGapPx || 2),   // khe giữa các lát
        borderColor: cardBg
      }]
    },
    options: {
      responsive: false,
      maintainAspectRatio: false,
      cutoutPercentage: 0, // pie
      layout: { padding: { top: padPx, right: padPx, bottom: padPx, left: padPx } },

      legend: {
        position: S.legendPosition,
        labels: {
          padding: 8,
          usePointStyle: true
        }
      },

      tooltips: {
        callbacks: {
          label: function (tooltipItem, data) {
            try {
              const ds = (data && data.datasets && data.datasets[tooltipItem.datasetIndex]) || { data: [] };
              const val = Number(ds.data[tooltipItem.index] || 0);
              const total = (ds.data || []).reduce((a,b)=>a+(+b||0),0);
              const lab = (data.labels && data.labels[tooltipItem.index]) || '';
              const pct = total ? ((val/total*100).toFixed(1)) : '0.0';
              return ' ' + lab + ': ' + val + ' (' + pct + '%)';
            } catch (_e) { return ''; }
          }
        }
      },

      plugins: {
        // Bật tách miếng
        explodePie: { enabled: true, offset: S.explodePx },

        datalabels: {
          display: true,
          color: '#fff',
          font: { weight: 'bold', size: S.datalabelFontSize },
          formatter: function(value, ctx) {
            const ds = ctx.dataset || { data: [] };
            const total = (ds.data || []).reduce(function(a, b){ return a + (+b||0); }, 0);
            if (!total) return '0%';
            const val = Number(value || 0);
            const percentage = ((val / total) * 100).toFixed(1);
            return percentage + '%';
          },
          anchor: 'center',
          align: 'center'
        },
        centerTotal: {
          enabled: !!S.showCenterTotal,
          font: S.centerTotalFont,
          formatter: function (_total) { return S.centerTotalFmt(counts.male, counts.female); },
          color: '#333'
        }
      },

      // con trỏ khi hover
      onHover: function(evt, el) {
        const target = evt && (evt.target || (evt.native && evt.native.target));
        if (target) target.style.cursor = (el && el.length) ? 'pointer' : 'default';
      },

      animation: { animateRotate: true, animateScale: true, duration: 900, easing: 'easeOutQuart' }
    }
  });

  // ====== Live update ======
  self.onDataUpdated = function () {
    if (!self.chart) return;
    const c = computeCounts();
    const ds = self.chart.data.datasets[0];
    ds.data = [c.male, c.female];
    self.chart.update();
  };

  // ====== Resize ======
  self.onResize = function () {
    if (!self.chart) return;
    sizeCanvas();
    self.chart.resize();
  };
};

self.onDestroy = function () {
  if (self.chart) { self.chart.destroy(); self.chart = null; }
};

