// energy-heatmap.js (JP localized)

/*************** STATE & CONST ***************/
var heatmapCanvas, heatmapCtx;
var lastHeatmapMap = null;
var startMs = null, endMs = null;     // range đang áp dụng
var yDays = 7;
var hourMode = '10h';
var currentMode = '1w';
var lastKeyIdsHash = '';
// NEW: tắt tooltip khi tương tác với select
var suppressTooltip = false;

var PAD_HM = { L:86, T:30, R:20, B:22 };
var LEVEL_COUNT = 5;
var domainMin = 0, domainMax = 1;
var BINS = [];

var ids = {
  main:'eh2-main', canvas:'eh2-canvas',
  header:'eh2-header', rangeGroup:'eh2-range-group',
  hourGroup:'eh2-hour-mode-group',
  legend:'eh2-legend', tooltip:'eh2-tooltip',
  keyWrap:'eh2-key-wrap', keySelect:'eh2-key-select',
  // modal
  overlay:'eh2-range-overlay',
  prevL:'eh2-prevL', nextL:'eh2-nextL', titleL:'eh2-titleL', gridL:'eh2-gridL',
  prevR:'eh2-prevR', nextR:'eh2-nextR', titleR:'eh2-titleR', gridR:'eh2-gridR',
  close:'eh2-close', cancel:'eh2-cancel', apply:'eh2-apply',
  quickWeek:'eh2-week-cur', quickMonth:'eh2-month-cur'
};

/*************** PALETTE & HELPERS ***************/
var NO_DATA_COLOR = '#eeeeee';
var COLORS_BLUE   = ['#F1FFF6','#C9F5DB','#7EE2A8','#2FB463','#0B4A2A'];
var COLORS_GREEN  = ['#FBEAEA', '#F2BDBD', '#E47D7D', '#CD5C5C', '#6B1F1F'];
var COLORS_YELLOW = ['#FFF9E5','#FFE7A9','#FFD166','#FFB020','#7A4E00'];

var selectedKeyId = null, dataKeyList = [];
function getPaletteForSelectedKey(){
  var idx = 0;
  for (var i=0;i<dataKeyList.length;i++) if(String(dataKeyList[i].id)===String(selectedKeyId)){idx=i;break;}
  return [COLORS_GREEN,COLORS_BLUE,COLORS_YELLOW][idx%3];
}

var MS = { day: 86400000 };
function startOfDay(d){ var x=new Date(d); x.setHours(0,0,0,0); return x; }
function endOfDay(d){ var x=new Date(d); x.setHours(23,59,59,999); return x; }
function dayIndexOf(ts){ return Math.floor((startOfDay(ts)-startOfDay(startMs))/MS.day); }
function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }
function getEl(id){ return document.getElementById(id); }
function getCardEl(){ try{ if(self&&self.ctx&&self.ctx.$container&&self.ctx.$container[0]) return self.ctx.$container[0]; }catch(_){}
  return document.querySelector('#eh2-root .eh-card') || document.body;
}
function buildDaysCount(){
  var a = startOfDay(startMs).getTime(), b = startOfDay(endMs).getTime();
  yDays = clamp(Math.floor((b - a)/MS.day) + 1, 1, 366);
}
function ymd(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function daysInMonth(y,m){ return new Date(y,m+1,0).getDate(); }
function firstOfMonth(d){ return new Date(d.getFullYear(), d.getMonth(), 1); }
function addMonths(d,n){ return new Date(d.getFullYear(), d.getMonth()+n, 1); }
// JP month label
function monthLabel(d){
  return d.toLocaleDateString('ja-JP', { year:'numeric', month:'short' }); // 2025年10月
}
function mondayOfCurrentWeek(now){ var dow=(now.getDay()+6)%7; var mon=new Date(now); mon.setDate(now.getDate()-dow); return startOfDay(mon); }

/*************** BINS & COLORS ***************/
function buildDiscreteBinsZeroToMax(max, levels){
  max = Math.max(0, Math.ceil(isFinite(max) ? max : 0));
  var bins = [];
  if (levels <= 1) { bins.push({ from:0, to:max, level:0 }); return bins; }
  var total = max + 1, base = Math.floor(total/levels), extra = total%levels, start=0;
  for (var i=0;i<levels;i++){
    var len = base + (i<extra?1:0);
    var end = i<levels-1 ? (start+len-1) : max;
    if (len<=0) end = start-1;
    bins.push({from:start,to:end,level:i}); start=end+1;
  }
  return bins;
}
function hexToRgb(hex){ var h=hex.replace('#',''); if(h.length===3)h=h.split('').map(x=>x+x).join(''); var n=parseInt(h,16); return {r:(n>>16)&255,g:(n>>8)&255,b:n&255}; }
function luminance(r,g,b){ function s(u){u/=255; return u<=0.03928?u/12.92:Math.pow((u+0.055)/1.055,2.4);} var R=s(r),G=s(g),B=s(b); return 0.2126*R+0.7152*G+0.0722*B; }
function levelColor(val, hasData, min, max, PALETTE){
  if (!hasData || !isFinite(val)) return { css: NO_DATA_COLOR, level: -1, lum: 1 };
  var dMax = Math.max(0, Math.ceil(max));
  if (!BINS.length || BINS[BINS.length-1].to !== dMax) BINS = buildDiscreteBinsZeroToMax(dMax, LEVEL_COUNT);
  var vInt = Math.floor(Math.max(0,val)+1e-9); if (vInt>dMax) vInt=dMax;
  var lvl=0; for (var i=0;i<BINS.length;i++){ var b=BINS[i]; if(vInt>=b.from && vInt<=b.to){ lvl=b.level; break; } }
  var rgb=hexToRgb(PALETTE[lvl]); return { css: PALETTE[lvl], level:lvl, lum:luminance(rgb.r,rgb.g,rgb.b) };
}

