function injectHeaderCssOnce(){
  if (document.getElementById('eh2-header-style')) return;
  var css = `
    #${ids.header}{position:relative;display:grid;grid-template-columns:1fr auto;align-items:center;row-gap:6px;margin-bottom:4px;min-height:36px;padding:0 12px;}
    #${ids.keyWrap}{display:flex;align-items:center;gap:8px;justify-self:end;width:260px;white-space:nowrap;position:relative;z-index:3;}
    #${ids.keySelect}{padding:6px 8px;border:1px solid #e2e8f0;border-radius:8px;background:#fff;font:12px Arial;width:160px}
  `;
  var st=document.createElement('style'); st.id='eh2-header-style'; st.textContent=css; document.head.appendChild(st);
}

function injectTooltipCssOnce(){
  if (document.getElementById('eh2-tooltip-style')) return;
  var css = `
    #${ids.tooltip}{
      position:absolute;display:none;padding:6px 8px;border:1px solid rgba(2,6,23,.12);
      border-radius:8px;background:#fff;box-shadow:0 6px 20px rgba(2,6,23,.12);
      font:12px/1.4 Arial;color:#0f172a;pointer-events:none; /* quan trọng: không chặn chuột */
      z-index:2; /* dưới dropdown (wrapper z-index:3) */
    }
  `;
  var st=document.createElement('style'); st.id='eh2-tooltip-style'; st.textContent=css; document.head.appendChild(st);
}

function ensureHeaderEl(){ var h=getEl(ids.header); if(!h){ h=document.createElement('div'); h.id=ids.header; h.className='eh-header'; (getCardEl()||document.body).prepend(h);} return h; }
function keyIdOf(it){ try{return String(it.dataKey && (it.dataKey.name ?? it.dataKey.label ?? ''));}catch(_){return '';} }
function keyLabelOf(it){ try{return String((it.dataKey&&(it.dataKey.label||it.dataKey.name))||'データキー');}catch(_){return 'データキー';} }
function collectDataKeys(){ var seen={}; dataKeyList=[]; (self.ctx.data||[]).forEach(function(it){ var id=keyIdOf(it); if(!id) return; var label=keyLabelOf(it); if(!seen[id]){seen[id]=true; dataKeyList.push({id,label});}}); }

function hideTooltip(){
  var t = getEl(ids.tooltip);
  if (t) t.style.display = 'none';
}

