function buildKeyDropdown(){
  injectHeaderCssOnce();

  var header = ensureHeaderEl();
  var range  = getEl(ids.rangeGroup);
  if (range && range.parentElement !== header) {
    try { header.insertBefore(range, header.firstChild); } catch(_){}
  }

  var wrap = document.getElementById(ids.keyWrap);
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = ids.keyWrap;
    header.appendChild(wrap);
  }

  // Thu thập keys & tính "hash" để so sánh thay vì rebuild mù
  collectDataKeys();
  var curHash = JSON.stringify(dataKeyList.map(k => String(k.id)));

  // Nếu dropdown đang focus HOẶC danh sách key không đổi → KHÔNG rebuild
  var sel = getEl(ids.keySelect);
  var isFocused = (document.activeElement === sel);

  if (sel && (isFocused || curHash === lastKeyIdsHash)) {
    // Chỉ đồng bộ value đã chọn nếu cần
    if (selectedKeyId && sel.value !== String(selectedKeyId)) {
      sel.value = String(selectedKeyId);
    }
    return; // Giữ nguyên DOM để không làm đóng menu
  }

  // ==== Rebuild khi: chưa có select hoặc keys đã thay đổi và dropdown KHÔNG focus
  wrap.innerHTML = '<label>顧客：</label><select id="'+ids.keySelect+'" autocomplete="off"></select>';
  sel = getEl(ids.keySelect);

  // Fill options
  sel.innerHTML = '';
  dataKeyList.forEach(function(k){
    var o = document.createElement('option');
    o.value = k.id;
    o.textContent = k.label;
    sel.appendChild(o);
  });

  // Chốt selected
  if (!selectedKeyId || !dataKeyList.some(x => String(x.id) === String(selectedKeyId))) {
    selectedKeyId = dataKeyList.length ? dataKeyList[0].id : null;
  }
  if (selectedKeyId) sel.value = String(selectedKeyId);

  // ==== Ổn định tương tác & tooltip như cũ ====
  var dropdownOpen = false;
  function disableTooltips(){ suppressTooltip = true; hideTooltip(); }
  function enableTooltips(){ suppressTooltip = false; }

  sel.addEventListener('mousedown', function(e){
    e.stopPropagation();
    dropdownOpen = true;
    disableTooltips();
  }, true);

  sel.addEventListener('focus', function(){
    dropdownOpen = true;
    disableTooltips();
  });

  sel.addEventListener('change', function(){
    selectedKeyId = this.value;
