/*************** MODAL (2 CALENDARS) ***************/
var modalState = { start:null, end:null, base:null };
function daysInMatrix(baseDate){
  var y=baseDate.getFullYear(), m=baseDate.getMonth();
  var first=new Date(y,m,1), dowMon0=(first.getDay()+6)%7, dim=daysInMonth(y,m), prevDim=daysInMonth(y,m-1);
  var cells=[];
  for (var i=0;i<dowMon0;i++) cells.push({y:y,m:m-1,d:prevDim-dowMon0+1+i,out:true});
  for (var d=1; d<=dim; d++) cells.push({y:y,m:m,d:d,out:false});
  while (cells.length%7!==0){ var last=cells[cells.length-1]; cells.push({y:last.m===11?last.y+1:last.y,m:(last.m+1)%12,d:(last.d||0)+1,out:true}); }
  while (cells.length<42){ var L=cells[cells.length-1]; cells.push({y:L.m===11?L.y+1:L.y,m:(L.m+1)%12,d:(L.d||0)+1,out:true}); }
  return cells;
}
function sameDate(a,b){ return a && b && a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(); }
function isBetween(d, a, b){ if(!a||!b) return false; var x=a.getTime(), y=b.getTime(); if(x>y){var t=x;x=y;y=t;} var t0=startOfDay(d).getTime(); return t0>=startOfDay(x).getTime() && t0<=startOfDay(y).getTime(); }

function renderCalendars(){
  var left = modalState.base ? firstOfMonth(modalState.base) : firstOfMonth(new Date());
  var right = firstOfMonth(addMonths(left,1));
  getEl(ids.titleL).textContent = monthLabel(left);   // JP
  getEl(ids.titleR).textContent = monthLabel(right);  // JP
  fillGrid(getEl(ids.gridL), left);
  fillGrid(getEl(ids.gridR), right);
}
function fillGrid(container, monthDate){
  container.innerHTML='';
  daysInMatrix(monthDate).forEach(function(c){
    var realMonth=(c.m%12+12)%12, realYear=c.m<0?c.y-1:(c.m>11?c.y+1:c.y);
    var d=new Date(realYear,realMonth,c.d);
    var el=document.createElement('div'); el.className='eh2-day'+(c.out?' out':''); el.textContent=String(c.d);
    if (modalState.start && sameDate(d, modalState.start)) el.classList.add('edge','sel');
    if (modalState.end && sameDate(d, modalState.end)) el.classList.add('edge','sel');
    if (modalState.start && modalState.end && isBetween(d, modalState.start, modalState.end)) el.classList.add('in');
    el.onclick=function(){
      if (c.out) return;
      if (!modalState.start || (modalState.start && modalState.end)){
        modalState.start = startOfDay(d); modalState.end=null;
      } else {
        if (d.getTime() < modalState.start.getTime()){ modalState.end = modalState.start; modalState.start = startOfDay(d); }
        else { modalState.end = startOfDay(d); }
      }
      renderCalendars();
    };
    container.appendChild(el);
  });
}

function openRangeModal(){
  var overlay=getEl(ids.overlay);
  var now = new Date();
  // seed selection từ range hiện tại nếu có
  if (startMs && endMs){
    modalState.start = startOfDay(new Date(startMs));
    modalState.end   = startOfDay(new Date(endMs));
  } else {
    modalState.start = mondayOfCurrentWeek(now);
    modalState.end   = startOfDay(now);
  }
  modalState.base = firstOfMonth(modalState.start||now);
  renderCalendars();

  // GẮN HANDLER NGAY TẠI ĐÂY (ghi đè mỗi lần mở)
  getEl(ids.prevL).onclick = function(){ modalState.base = addMonths(modalState.base,-1); renderCalendars(); };
  getEl(ids.nextL).onclick = function(){ modalState.base = addMonths(modalState.base, 1); renderCalendars(); };
  getEl(ids.prevR).onclick = function(){ modalState.base = addMonths(modalState.base,-1); renderCalendars(); };
  getEl(ids.nextR).onclick = function(){ modalState.base = addMonths(modalState.base, 1); renderCalendars(); };

  getEl(ids.quickWeek).onclick = function(){
    var s=mondayOfCurrentWeek(now), e=startOfDay(now);
    modalState.start=s; modalState.end=e; modalState.base=firstOfMonth(s); renderCalendars();
  };
  getEl(ids.quickMonth).onclick = function(){
    var s=startOfDay(new Date(now.getFullYear(), now.getMonth(), 1)), e=startOfDay(now);
    modalState.start=s; modalState.end=e; modalState.base=firstOfMonth(s); renderCalendars();
  };

  getEl(ids.close).onclick  = closeOverlay;
  getEl(ids.cancel).onclick = closeOverlay;
  overlay.onclick = function(ev){ if (ev.target===overlay) closeOverlay(); };

  // ✅ APPLY: cập nhật range + render ngay
  getEl(ids.apply).onclick = function(){
    if (!modalState.start){ alert('開始日を選択してください'); return; } // JP
    if (!modalState.end) modalState.end = modalState.start;
    var s = startOfDay(modalState.start), e = endOfDay(modalState.end);
    if (e < s){ var t=s; s=e; e=t; }
    startMs = s.getTime();
    endMs   = e.getTime();
    currentMode = 'custom';
    buildDaysCount();
    closeOverlay();
    setActiveRangeChip('custom');   // đồng bộ chip
    self.onDataUpdated();           // 🔥 vẽ lại heatmap
  };

  // hiển thị
  window.addEventListener('keydown', escToClose);
  overlay.style.display='block';

  function closeOverlay(){
    overlay.style.display='none';
    window.removeEventListener('keydown', escToClose);
  }
  function escToClose(e){ if(e.key==='Escape') closeOverlay(); }
}


