self.onInit = function() {
    var $injector = self.ctx.$scope.$injector;
    var utils = $injector.get(self.ctx.servicesMap.get('utils'));

    var cssParser = new cssjs();
    cssParser.testMode = false;
    var namespace = 'html-card-' + hashCode(self.ctx.settings.cardCss || '');
    cssParser.cssPreviewNamespace = namespace;
    cssParser.createStyleElement(namespace, self.ctx.settings.cardCss || '');
    self.ctx.$container.addClass(namespace);

    var evtFnPrefix = 'htmlCard_' + Math.abs(hashCode((self.ctx.settings.cardCss || '') + (self.ctx.settings.cardHtml || '') + self.ctx.widget.id));
    var cardHtml =  '<div style="height:100%; font-size:13px; line-height:1.4;" onclick="' + evtFnPrefix + '_onClickFn(event)">' + // 👈 chỉnh font nhỏ hơn ở đây
                        (self.ctx.settings.cardHtml || '') +
                    '</div>';
    cardHtml = replaceCustomTranslations(cardHtml);
    self.ctx.$container.html(cardHtml);

    window[evtFnPrefix + '_onClickFn'] = function (event) {
        self.ctx.actionsApi.elementClick(event);
    };

    const now = new Date();
    const hour = now.getHours();

    let message = "";
    let title = "";
    let iconName = "";
    let titleEmoji = "";
    let messageEmoji = "";

    if (hour < 10) {
        title = "Good morning! I’d like to share a hint with you:";
        message = "The number of customers is calm at the moment. It’s a good time to rearrange the displays and restock the products.";
        iconName = "sun";
        titleEmoji = "🌅";
        messageEmoji = "☕";
    } else if (hour >= 10 && hour <= 16) {
        title = "Hello! I have a few suggestions:";
        message = "I’ve noticed that visitor activity is quite high. Let’s encourage the staff to actively engage with customers during this time.";
        iconName = "activity";
        titleEmoji = "☀️";
        messageEmoji = "💪";
    } else if (hour > 16 && hour <= 21) {
        title = "Peak Hours Alert!";
        message = "A large number of visitors have been detected! Let’s respond quickly and politely to make the most of this sales opportunity.";
        iconName = "alert";
        titleEmoji = "🌇";
        messageEmoji = "🚀";
    } else {
        title = "Everything is running smoothly!";
        message = "The situation is stable at the moment.";
        iconName = "check";
        titleEmoji = "🌙";
        messageEmoji = "😴";
    }

    title = `${titleEmoji} ${title}`;
    message = `${message} ${messageEmoji}`;

    const container = self.ctx.$container[0];
    const titleEl = container.querySelector("#title");
    const msgEl   = container.querySelector("#message");
    const iconEl  = container.querySelector("#icon");

    if (titleEl) {
        titleEl.innerText = title;
        titleEl.style.fontSize = "14px";  // 👈 tiêu đề nhỏ gọn nhưng vẫn nổi bật
    }
    if (msgEl) {
        msgEl.innerText = message;
        msgEl.style.fontSize = "12px";    // 👈 nội dung nhỏ hơn một chút
    }

    // ❌ Không chèn SVG để loại bỏ ký hiệu line gấp khúc
    if (iconEl) iconEl.style.display = "none";

    function hashCode(str) {
        var hash = 0, i, char;
        if (!str || str.length === 0) return hash;
        for (i = 0; i < str.length; i++) {
            char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return hash;
    }

    function replaceCustomTranslations(pattern) {
        var customTranslationRegex = new RegExp('{i18n:[^{}]+}', 'g');
        return pattern.replace(customTranslationRegex, getTranslationText);
    }

    function getTranslationText(variable) {
        return utils.customTranslation(variable, variable);
    }
};

self.actionSources = function() {
    return {
        'elementClick': {
            name: 'widget-action.element-click',
            multiple: true
        }
    };
};

self.onDestroy = function() {};

