descriptor.controllerScript:
/* global Chart, ChartDataLabels */
self.onInit = function () {
  // ==== DOM ====
  var $root = self.ctx.$container[0];
  var wrap = $root.querySelector('#wrap');
  var canvas = $root.querySelector('#age-pie');
  if (!wrap || !canvas) {
    self.ctx.$container.html('<div id="wrap" style="height:100%"><canvas id="age-pie"></canvas></div>');
  }
  var _wrap = self.ctx.$container[0].querySelector('#wrap');
  var _canvas = self.ctx.$container[0].querySelector('#age-pie');
  var ctx = _canvas.getContext('2d');

  // ==== Settings (đồng bộ style với widget giới tính) ====
  var S = Object.assign({
    labels: ['0-15', '16-25', '26-45', '>45'],
    colors: ['#0EA54D', '#38A5FF', '#FFAE2B', '#E97CFF'],
    legendPosition: 'bottom',
    datalabelFontSize: 16,
    paddingPx: 0.2,
    ringGapPx: 0.2,          // khe giữa các lát (viền cùng màu nền)
    explodePx: 1,          // đẩy lát ra ngoài (px)

    // Tổng ở giữa (tuỳ chọn)
    showCenterTotal: false,
    centerTotalFont: '600 16px Inter, system-ui, sans-serif',
    centerTotalFmt: function (total) { return 'Total: ' + total; }
  }, (self.ctx.settings || {}));

  // ==== Retina-safe sizing ====
  function sizeCanvas() {
    var w = _wrap.clientWidth || 300;
    var h = _wrap.clientHeight || 200;
    var dpr = (window.devicePixelRatio || 1);
    _canvas.style.width = w + 'px';
    _canvas.style.height = h + 'px';
    _canvas.width = Math.floor(w * dpr);
    _canvas.height = Math.floor(h * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  self.ctx.$container.css({ height: '100%', padding: 0, margin: 0 });
  _wrap.style.height = '90%';
  sizeCanvas();

  // ==== Helpers (data) ====
  function safeParseArray(x){ if (Array.isArray(x)) return x; if (typeof x==='string'){ try{var a=JSON.parse(x); return Array.isArray(a)?a:null;}catch(_){}} return null; }
  function extractAges(payload){
    if (payload && typeof payload==='object' && 'v' in payload) payload = payload.v;
    if (payload && typeof payload==='object' && 'value' in payload && Object.keys(payload).length===1) payload = payload.value;
    if (typeof payload==='string'){ var arr=safeParseArray(payload); if (arr) return arr.map(function(x){return parseInt(x);}).filter(function(x){return !isNaN(x)&&x>=0;}); var n=parseInt(payload); return (!isNaN(n)&&n>=0)?[n]:[]; }
    if (Array.isArray(payload)) return payload.map(function(x){return parseInt(x);}).filter(function(x){return !isNaN(x)&&x>=0;});
    if (payload && typeof payload==='object'){ var ages = payload.ages!=null?payload.ages:payload.age; if (ages!=null){ var a=safeParseArray(ages)||(Array.isArray(ages)?ages:[ages]); return a.map(function(x){return parseInt(x);}).filter(function(x){return !isNaN(x)&&x>=0;}); } }
    return [];
  }
  function getTWRange(ctxTB){
    try{
      var stw = (ctxTB && ctxTB.defaultSubscription && ctxTB.defaultSubscription.subscriptionTimewindow) || ctxTB.timewindow;
      var now = Date.now();
      if (stw && stw.realtime && stw.realtime.timewindowMs) return {start: now - stw.realtime.timewindowMs, end: now};
      var fixed = stw && stw.history && stw.history.fixedTimewindow;
      if (fixed && fixed.startTimeMs && fixed.endTimeMs) return {start: fixed.startTimeMs, end: fixed.endTimeMs};
      if (stw && stw.history && stw.history.timewindowMs) return {start: now - stw.history.timewindowMs, end: now};
    }catch(_){}
    return {start: -Infinity, end: Infinity};
  }
  function categorizeAge(age){ if (age<=15) return 0; if (age<=25) return 1; if (age<=45) return 2; return 3; }
  function collectAgeGroupsFromTB(ctxTB){
    var rng=getTWRange(ctxTB), g=[0,0,0,0];
    try{
      var sub=ctxTB && ctxTB.defaultSubscription; var blocks=(sub && sub.data)||[];
      for (var i=0;i<blocks.length;i++){
        var b=blocks[i]||{}; var arrs=[b.data||[], b.latestData||[]];
        for (var ai=0; ai<arrs.length; ai++){
          var dataArr=arrs[ai];
          for (var j=0;j<dataArr.length;j++){
            var p=dataArr[j]; if (!p || p.length<2) continue;
            var ts=p[0]; if (!(ts>=rng.start && ts<=rng.end)) continue;
            var ages=extractAges(p[1]); for (var k=0;k<ages.length;k++) g[categorizeAge(ages[k])]++; } } }
    }catch(_){}
    return g;
  }
  function computeCounts(){
    var g=collectAgeGroupsFromTB(self.ctx), total=g.reduce(function(a,b){return a+b;},0);
    if (total>0) return g;
    // Fallback demo giống bản trên (có dữ liệu dự phòng)
    var demo=[], out=[0,0,0,0]; demo.forEach(function(a){ out[categorizeAge(a)]++; }); return out;
  }

  // ==== Plugin: CenterTotal (giống giao diện widget giới tính) ====
  var CenterTotalPlugin = {
    id: 'centerTotal',
    afterDraw: function(chart) {
      var opts = (chart.options && chart.options.centerTotal) ||
                 (chart.options && chart.options.plugins && chart.options.plugins.centerTotal) || {};
      if (!opts.enabled) return;

      var ds = chart.data && chart.data.datasets && chart.data.datasets[0];
      if (!ds) return;
      var total = (ds.data || []).reduce(function(a,b){ return a + (+b||0); }, 0);
      var label = (opts.formatter || function(t){ return String(t); })(total);

      var meta = chart.getDatasetMeta && chart.getDatasetMeta(0);
      var center = meta && meta.data && meta.data[0] && meta.data[0].getCenterPoint
        ? meta.data[0].getCenterPoint()
        : null;
      if (!center) return;

      var ctx2 = chart.chart.ctx;
      ctx2.save();
      ctx2.font = opts.font || '600 16px system-ui';
      ctx2.textAlign = 'center';
      ctx2.textBaseline = 'middle';
      ctx2.fillStyle = opts.color || '#444';
      ctx2.fillText(label, center.x, center.y);
      ctx2.restore();
    }
  };
  Chart.plugins.register(CenterTotalPlugin);

  // ==== Plugin: Explode pie KHÔNG cộng dồn (dựa chartArea) ====
  var ExplodePiePlugin = {
    id: 'explodePie',
    afterUpdate: function(chart) {
      var cfg = chart.options && chart.options.plugins && chart.options.plugins.explodePie;
      if (!cfg || !cfg.enabled) return;

      var off = Number(cfg.offset || 0);
      if (!off) return;

      var meta = chart.getDatasetMeta(0);
      if (!meta || !meta.data || !chart.chartArea) return;

      var baseX = (chart.chartArea.left + chart.chartArea.right) / 2;
      var baseY = (chart.chartArea.top + chart.chartArea.bottom) / 2;

      meta.data.forEach(function(arc){
        var m = arc && arc._model;
        if (!m) return;

        var mid = (m.startAngle + m.endAngle) / 2;
        var dx = Math.cos(mid) * off;
        var dy = Math.sin(mid) * off;

        m.x = baseX + dx;
        m.y = baseY + dy;

        if (arc._view) {
          arc._view.x = m.x;
          arc._view.y = m.y;
        }
      });
    }
  };
  Chart.plugins.register(ExplodePiePlugin);

  // (khuyên dùng) plugin datalabels
  if (typeof ChartDataLabels !== 'undefined') Chart.plugins.register(ChartDataLabels);

  // ==== Màu nền card để làm viền (tạo khe) ====
  var cardBg = '#fff';
  try { var cs = window.getComputedStyle(_wrap); if (cs && cs.backgroundColor) cardBg = cs.backgroundColor; } catch (_e) {}

  var counts = computeCounts();

  // Padding “thông minh” như bản trên: ưu tiên S.paddingPx nếu hợp lệ, ngược lại tính theo ringGap
  var padPx = (typeof S.paddingPx === 'number' && S.paddingPx >= 0)
    ? S.paddingPx
    : Math.ceil(Math.max(2, S.ringGapPx || 0)) + 6;

  // ==== Chart ====
  self.chart = new Chart(ctx, {
    type: 'pie',
    data: {
      labels: S.labels,
      datasets: [{
        data: counts,
        backgroundColor: S.colors,
        borderWidth: (S.ringGapPx || 2),
        borderColor: cardBg
      }]
    },
    options: {
      responsive: false,
      maintainAspectRatio: false,
      cutoutPercentage: 0, // pie
      layout: { padding: { top: padPx, right: padPx, bottom: padPx, left: padPx } },

      legend: {
        position: S.legendPosition,
        labels: { padding: 8, usePointStyle: true }
      },

      tooltips: {
        callbacks: {
          label: function (tooltipItem, data) {
            try {
              var ds = (data && data.datasets && data.datasets[tooltipItem.datasetIndex]) || { data: [] };
              var val = Number(ds.data[tooltipItem.index] || 0);
              var total = (ds.data || []).reduce(function(a,b){ return a + (+b||0); }, 0);
              var lab = (data.labels && data.labels[tooltipItem.index]) || '';
              var pct = total ? ((val/total*100).toFixed(1)) : '0.0';
              return ' ' + lab + ': ' + val + ' (' + pct + '%)';
            } catch (_e) { return ''; }
          }
        }
      },

      plugins: {
        explodePie: { enabled: true, offset: S.explodePx },

        datalabels: {
          display: true,
          color: '#fff',
          font: { weight: 'bold', size: S.datalabelFontSize },
          formatter: function(value, ctx) {
            var ds = ctx.dataset || { data: [] };
            var total = (ds.data || []).reduce(function(a, b){ return a + (+b||0); }, 0);
            if (!total) return '0%';
            var val = Number(value || 0);
            var percentage = ((val / total) * 100).toFixed(1);
            return percentage + '%';
          },
          anchor: 'center',
          align: 'center'
        },

        centerTotal: {
          enabled: !!S.showCenterTotal,
          font: S.centerTotalFont,
          formatter: function (total) { return S.centerTotalFmt(total); },
          color: '#333'
        }
      },

      onHover: function (evt, el) {
        var target = evt && (evt.target || (evt.native && evt.native.target));
        if (target) target.style.cursor = (el && el.length) ? 'pointer' : 'default';
      },

      animation: { animateRotate: true, animateScale: true, duration: 900, easing: 'easeOutQuart' }
    }
  });

  // ==== Live update & Resize ====
  self.onDataUpdated = function () {
    if (!self.chart) return;
    var next = computeCounts();
    var ds = self.chart.data.datasets[0];
    ds.data = next;
    self.chart.update();
  };
  self.onResize = function () { if (!self.chart) return; sizeCanvas(); self.chart.resize(); };
};

self.onDestroy = function () { if (self.chart) { self.chart.destroy(); self.chart = null; } };

