descriptor.controllerScript:
/* ThingsBoard – Digital Gauge
   Percent = SUM(key1 in timewindow) / SUM(key2 in timewindow) * 100
   Works for SINGLE + ALL devices (from state)
   - ALWAYS uses timewindow SUM (no dependency on ctx.data timing)
   - Handles state changes, avoids stale results
*/

(function () {
  let pending = null;
  let isFetching = false;
  let seq = 0;

  function safeGetToken() {
    return localStorage.getItem('jwt_token') || localStorage.getItem('token') || '';
  }

  function extractDeviceId(ent) {
    if (!ent) return null;
    if (typeof ent === 'string') return ent;
    if (typeof ent.id === 'string') return ent.id;
    if (ent.id && typeof ent.id.id === 'string') return ent.id.id;
    return null;
  }

  function dedupe(arr) {
    const out = [];
    const set = new Set();
    (arr || []).forEach(x => {
      const v = String(x || '').trim();
      if (v && !set.has(v)) { set.add(v); out.push(v); }
    });
    return out;
  }

  function readStateParams() {
    const sc = self.ctx.stateController;
    if (!sc) return {};
    try { const p = sc.getStateParams(); if (p && typeof p === 'object') return p; } catch (e) {}
    try { const p2 = sc.getStateParams('default'); if (p2 && typeof p2 === 'object') return p2; } catch (e) {}
    return {};
  }

  function getAllDeviceIdsFromState(stateParams) {
    const list = stateParams.entities || stateParams.entityIds || [];
    const ids = [];

    if (Array.isArray(list)) list.forEach(e => { const id = extractDeviceId(e); if (id) ids.push(id); });
    else { const id = extractDeviceId(list); if (id) ids.push(id); }

    return dedupe(ids);
  }

  function getSingleDeviceIdFromStateOrDs(stateParams) {
    const fromState = stateParams.selectedDeviceId || stateParams.id || extractDeviceId(stateParams.entityId);
    if (fromState && fromState !== '__ALL__') return fromState;

    // fallback: first datasource entity
    const ds0 = self.ctx.datasources && self.ctx.datasources[0];
    const ent = ds0 && (ds0.entityId || ds0.entity);
    const uuid = extractDeviceId(ent);
    if (uuid) return uuid;

    // fallback: subscription
    const sub = self.ctx.defaultSubscription;
    if (sub && Array.isArray(sub.data) && sub.data.length) {
      const dk0 = sub.data[0];
      const e = dk0?.datasource?.entityId || dk0?.dataKey?.datasource?.entityId || dk0?.datasource?.entity;
      const u2 = extractDeviceId(e);
      if (u2) return u2;
    }
    return null;
  }

  function normalizeKeyName(raw) {
    const s = String(raw || '').trim();
    if (!s) return '';
    const parts = s.split(':').map(x => x.trim()).filter(Boolean);
    return (parts.length ? parts[parts.length - 1] : s).trim();
  }

  function getConfiguredKeyNameByIndex(idx) {
    const k =
      self.ctx?.datasources?.[0]?.dataKeys?.[idx]?.name ||
      self.ctx?.defaultSubscription?.dataKeys?.[idx]?.name ||
      self.ctx?.defaultSubscription?.data?.[idx]?.dataKey?.name ||
      self.ctx?.data?.[idx]?.dataKey?.name ||
      null;
    return normalizeKeyName(k);
  }

  function getTimeWindow() {
    const tw = self.ctx.defaultSubscription?.subscriptionTimewindow;
    const startTs = tw?.minTime || tw?.fixedWindow?.startTimeMs;
    const endTs = tw?.maxTime || tw?.fixedWindow?.endTimeMs;
    return { startTs, endTs };
  }

  function pickIntervalMs(startTs, endTs) {
    const span = Number(endTs) - Number(startTs);
    const DAY = 24 * 60 * 60 * 1000;
    if (span <= 2 * DAY) return 60 * 60 * 1000; // 1h
    if (span <= 60 * DAY) return DAY;           // 1d
    return 30 * DAY;                            // ~1 month
  }

  async function fetchAgg(deviceId, keys, startTs, endTs, agg, interval) {
    const token = safeGetToken();
    const keysStr = keys.join(',');

    const url =
      `/api/plugins/telemetry/DEVICE/${deviceId}/values/timeseries` +
      `?keys=${encodeURIComponent(keysStr)}` +
      `&startTs=${Number(startTs)}` +
      `&endTs=${Number(endTs)}` +
      `&agg=${encodeURIComponent(agg)}` +
      `&interval=${Number(interval)}` +
      `&limit=50000`;

    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
      }
    });

    if (!res.ok) return null;
    return res.json();
  }

  function sumBuckets(arr) {
    let s = 0;
    for (const p of (arr || [])) {
      const v = Number(p?.value);
      if (Number.isFinite(v)) s += v;
    }
    return s;
  }

  async function computeSumForDevices(deviceIds, key1, key2, startTs, endTs) {
    const interval = pickIntervalMs(startTs, endTs);
    const agg = 'SUM';

    let sum1 = 0;
    let sum2 = 0;

    await Promise.all(deviceIds.map(async (id) => {
      const json = await fetchAgg(id, [key1, key2], startTs, endTs, agg, interval);
      if (!json) return;

      sum1 += sumBuckets(Array.isArray(json[key1]) ? json[key1] : []);
      sum2 += sumBuckets(Array.isArray(json[key2]) ? json[key2] : []);
    }));

    return { sum1, sum2 };
  }

  function computePercent(sum1, sum2) {
    const a = Number(sum1), b = Number(sum2);
    if (!Number.isFinite(a) || !Number.isFinite(b)) return 0;
    if (b <= 0) return 0;
    let p = (a / b) * 100;
    if (!Number.isFinite(p) || isNaN(p)) p = 0;
    return Math.max(0, Math.min(100, p));
  }

  function updateGauge(percent) {
    const p = Number.isFinite(percent) ? percent : 0;

    // Ensure gauge exists
    if (!self.ctx.gauge) return;

    if (self.ctx.gauge.setValue) {
      self.ctx.gauge.setValue(p);
      self.ctx.gauge.update && self.ctx.gauge.update();
      return;
    }

    // Fallback: synthetic data (rare)
    const orig = self.ctx.data;
    self.ctx.data = [{
      datasource: orig?.[0]?.datasource || {},
      dataKey: { name: 'percentage', type: 'timeseries' },
      data: [[Date.now(), p]]
    }];
    self.ctx.gauge.update && self.ctx.gauge.update();
    self.ctx.data = orig;
  }

  function scheduleUpdate(delayMs) {
    if (pending) clearTimeout(pending);
    pending = setTimeout(processUpdate, delayMs);
  }

  async function processUpdate() {
    const mySeq = ++seq;

    const key1 = getConfiguredKeyNameByIndex(0);
    const key2 = getConfiguredKeyNameByIndex(1);
    if (!key1 || !key2) {
      updateGauge(0);
      return;
    }

    const { startTs, endTs } = getTimeWindow();
    if (!startTs || !endTs) {
      updateGauge(0);
      return;
    }

    const stateParams = readStateParams();
    const deviceMode = stateParams.selectedDeviceMode || stateParams.mode;
    const isAllMode = deviceMode === 'ALL';

    let deviceIds = [];
    if (isAllMode) {
      deviceIds = getAllDeviceIdsFromState(stateParams);
    } else {
      const one = getSingleDeviceIdFromStateOrDs(stateParams);
      if (one) deviceIds = [one];
    }

    // If still empty, fallback: use whatever alias bound (first entity in state)
    if (!deviceIds.length) {
      const fallback = extractDeviceId(stateParams.entityId) || stateParams.id;
      if (fallback) deviceIds = [fallback];
    }

    console.log('[gauge] compute', { deviceMode, deviceIds, key1, key2, startTs, endTs });

    if (isFetching) return;
    isFetching = true;

    try {
      const { sum1, sum2 } = await computeSumForDevices(deviceIds, key1, key2, startTs, endTs);

      // ignore stale result if a newer update happened
      if (mySeq !== seq) return;

      const p = computePercent(sum1, sum2);
      console.log('[gauge] sums', { sum1, sum2, percent: p });

      updateGauge(p);
    } catch (e) {
      console.warn('[gauge] compute failed', e);
      updateGauge(0);
    } finally {
      isFetching = false;
    }
  }

  // ===== lifecycle =====
  self.onInit = function () {
    self.ctx.gauge = new TbCanvasDigitalGauge(self.ctx, 'digitalGauge');

    if (self.ctx.gauge.setUnit) self.ctx.gauge.setUnit('%');
    if (self.ctx.gauge.setMinMax) self.ctx.gauge.setMinMax(0, 100);

    // state change -> refresh aliases + recompute (delay to let TB bind)
    if (self.ctx.stateController && self.ctx.stateController.stateChanged) {
      self.stateSubscription = self.ctx.stateController.stateChanged().subscribe(function () {
        try { self.ctx.updateAliases && self.ctx.updateAliases(); } catch (e) {}
        isFetching = false;
        scheduleUpdate(220);
      });
    }

    scheduleUpdate(50);
  };

  self.onDataUpdated = function () {
    // whenever TB pushes, recompute (small debounce)
    scheduleUpdate(80);
  };

  self.onResize = function () {
    if (self.ctx.gauge && self.ctx.gauge.resize) self.ctx.gauge.resize();
  };

  self.typeParameters = function () {
    return {
      maxDatasources: 1,
      maxDataKeys: 2,
      singleEntity: false,       // allow ALL
      supportsUnitConversion: false
    };
  };

  self.onMobileModeChanged = function () {
    if (self.ctx.gauge && self.ctx.gauge.mobileModeChanged) self.ctx.gauge.mobileModeChanged();
  };

  self.onDestroy = function () {
    if (self.stateSubscription) {
      self.stateSubscription.unsubscribe();
      self.stateSubscription = null;
    }
    if (self.ctx.gauge && self.ctx.gauge.destroy) self.ctx.gauge.destroy();
  };
})();

