let selectedFile = null;
const FLASK_SERVER = 'https://visiflow-dev.m-tech.com.vn'; // URL Flask server của bạn

self.onInit = function() {
    initializeWidget();
};

async function loadCustomers() {
    try {
        const storeSelect = document.getElementById('store');

        const response = await fetch(`${FLASK_SERVER}/api/content-customers`);
        const data = await response.json();

        if (data.success && data.customers) {
            // Clear all existing options
            storeSelect.innerHTML = '';

            // Add default option
            const defaultOption = document.createElement('option');
            defaultOption.value = '';
            defaultOption.textContent = 'Select store';
            storeSelect.appendChild(defaultOption);

            // Add customers as options
            data.customers.forEach(customer => {
                const option = document.createElement('option');
                option.value = customer.title; // Dùng title làm value

                // Format display text: "Title (City) - Country"
                let displayText = customer.title;
                if (customer.city) {
                    displayText += ` (${customer.city})`;
                }
                if (customer.country) {
                    displayText += ` - ${customer.country}`;
                }
                option.textContent = displayText;
                storeSelect.appendChild(option);
            });

            // console.log(`✓ Loaded ${data.customers.length} customers from ThingsBoard`);
        } else {
            // console.error('Failed to load customers:', data.error);

            // Show error option
            storeSelect.innerHTML = '';
            const errorOption = document.createElement('option');
            errorOption.value = '';
            errorOption.textContent = 'Error loading customers';
            storeSelect.appendChild(errorOption);

            showStatus('Failed to load customers list', 'error');
        }
    } catch (error) {
        // console.error('Error loading customers:', error);

        const storeSelect = document.getElementById('store');
        storeSelect.innerHTML = '';
        const errorOption = document.createElement('option');
        errorOption.value = '';
        errorOption.textContent = 'Error loading customers';
        storeSelect.appendChild(errorOption);

        showStatus('Error loading customers list', 'error');
    }
}

function initializeWidget() {
    const uploadArea = document.getElementById('uploadArea');
    const fileInput = document.getElementById('fileInput');
    const browseBtn = document.getElementById('browseBtn');
    const submitBtn = document.getElementById('submitBtn');

    // Load customers from ThingsBoard
    loadCustomers();

    // Number input handlers
    document.getElementById('touchDelayInc').addEventListener('click', function() {
        incrementValue('touchDelay');
    });

    document.getElementById('touchDelayDec').addEventListener('click', function() {
        decrementValue('touchDelay');
    });

    document.getElementById('durationInc').addEventListener('click', function() {
        incrementValue('duration');
    });

    document.getElementById('durationDec').addEventListener('click', function() {
        decrementValue('duration');
    });

    // Browse button
    browseBtn.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        fileInput.click();
    });

    // Upload area click
    uploadArea.addEventListener('click', function(e) {
        if (e.target === browseBtn) return;
        fileInput.click();
    });

    // Drag and drop
    uploadArea.addEventListener('dragover', function(e) {
        e.preventDefault();
        uploadArea.classList.add('dragover');
    });

    uploadArea.addEventListener('dragleave', function() {
        uploadArea.classList.remove('dragover');
    });

    uploadArea.addEventListener('drop', function(e) {
        e.preventDefault();
        uploadArea.classList.remove('dragover');
        const files = e.dataTransfer.files;
        if (files.length > 0) {
            handleFile(files[0]);
        }
    });

    // File input change
    fileInput.addEventListener('change', function(e) {
        if (e.target.files.length > 0) {
            handleFile(e.target.files[0]);
        }
    });

    // Submit button
    submitBtn.addEventListener('click', function() {
        uploadContent();
    });
}

function incrementValue(id) {
    const input = document.getElementById(id);
    input.value = parseInt(input.value) + 1;
}

function decrementValue(id) {
    const input = document.getElementById(id);
    if (parseInt(input.value) > 0) {
        input.value = parseInt(input.value) - 1;
    }
}

function handleFile(file) {
    if (!file.type.startsWith('video/')) {
        showStatus('Please select a video file', 'error');
        return;
    }

    selectedFile = file;
    const filePreview = document.getElementById('filePreview');
    filePreview.style.display = 'block';
    filePreview.innerHTML = `📹 ${file.name} (${(file.size / 1024 / 1024).toFixed(2)} MB)`;
}

function showStatus(message, type) {
    const statusEl = document.getElementById('statusMessage');
    statusEl.textContent = message;
    statusEl.className = `status-message ${type}`;
    statusEl.style.display = 'block';

    setTimeout(function() {
        statusEl.style.display = 'none';
    }, 5000);
}

async function uploadContent() {
    // Validate required fields
    const store = document.getElementById('store').value;
    const touchDelay = document.getElementById('touchDelay').value;
    const duration = document.getElementById('duration').value;
    const refLink = document.getElementById('refLink').value;
    const description = document.getElementById('description').value;
    const coordinate = document.getElementById('coordinate').value || '0';

    if (!store || !touchDelay || !duration || !refLink || !description || !selectedFile) {
        showStatus('Please fill all required fields and select a file', 'error');
        return;
    }

    const submitBtn = document.getElementById('submitBtn');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Uploading...';

    try {
        // Upload to Flask server (device token is handled by server)
        const formData = new FormData();
        formData.append('video', selectedFile);
        formData.append('store', store);
        formData.append('touchDelay', touchDelay);
        formData.append('duration', duration);
        formData.append('coordinate', coordinate);
        formData.append('contentType', document.getElementById('contentType').value);
        formData.append('refLink', refLink);
        formData.append('description', description);
        // Device token không cần gửi nữa, server sẽ dùng từ config

        const response = await fetch(`${FLASK_SERVER}/upload`, {
            method: 'POST',
            body: formData
        });

        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || 'Upload failed');
        }

        const result = await response.json();
        showStatus(`✓ Success! ${result.contentCount} videos in library`, 'success');

        // Reset form
        document.getElementById('store').value = '';
        document.getElementById('touchDelay').value = '1';
        document.getElementById('duration').value = '1';
        document.getElementById('coordinate').value = '0';
        document.getElementById('refLink').value = '';
        document.getElementById('description').value = '';
        document.getElementById('fileInput').value = '';
        document.getElementById('filePreview').style.display = 'none';
        selectedFile = null;

    } catch (error) {
        // console.error('Upload error:', error);
        showStatus('✗ Upload failed: ' + error.message, 'error');
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Upload';
    }
}

