self.onInit = function () {
  const ctx = self.ctx;

  // ===== 2 BASE_URL =====
  const BASE_URL_TABLET = "https://visiflow-dev.m-tech.com.vn/webrtc2221/";       // Tablet Device
  const BASE_URL_EDGE   = "https://visiflow-dev.m-tech.com.vn/webrtc-drawline/";  // Edge Device
//   const BASE_URL_EDGE   = "https://skds1x9p-8008.asse.devtunnels.ms/"; 
  const PROFILE_KEY = "default";
  const IFRAME_SANDBOX = ""; // "allow-scripts allow-same-origin" nếu cần

  // ==== DOM ====
  const root = ctx.$container[0];

  // HTML từ tab HTML đã được ThingsBoard render vào root.
  // Lấy card cấu hình (fallback khi không có label)
  const configCard = root.querySelector('.tb-config-merge');

  // Tạo wrapper cho iframe (view video) – nằm cùng cấp với card
  const iframeWrapper = document.createElement('div');
  Object.assign(iframeWrapper.style, {
    position: "relative",
    width: "100%",
    height: "100%",
    background: "#000",
    overflow: "hidden",
    display: "none"  // ban đầu ẩn – chỉ hiện khi label hợp lệ
  });

  const iframe = document.createElement("iframe");
  Object.assign(iframe.style, {
    border: "0",
    width: "100%",
    height: "100%",
    display: "block"
  });
  if (IFRAME_SANDBOX && IFRAME_SANDBOX.trim()) {
    iframe.setAttribute("sandbox", IFRAME_SANDBOX.trim());
  }
  iframeWrapper.appendChild(iframe);

  // Gắn wrapper vào root (card vẫn giữ nguyên)
  root.appendChild(iframeWrapper);

  // ===== helper show/hide =====
  let currentBaseUrl = null;     // URL đang dùng
  let lastState = null;          // 'config' | 'edge' | 'tablet'

  function showConfigCard() {
    if (lastState === 'config') return;
    lastState = 'config';

    if (configCard) {
      configCard.style.display = 'flex';   // để card của bạn hiển thị
    }
    iframeWrapper.style.display = 'none';
  }

  function showIframe(url, stateKey) {
    if (!url) {
      showConfigCard();
      return;
    }
    if (lastState === stateKey && currentBaseUrl === url) {
      // không đổi gì
    } else {
      lastState = stateKey;
      currentBaseUrl = url;
      iframe.src = url;
    }

    iframeWrapper.style.display = 'block';
    if (configCard) {
      configCard.style.display = 'none';
    }
  }

  // ==== LẤY NGÔN NGỮ CURRENT CỦA THINGSBOARD ====
  function detectTbLang() {
    const langAttr = (document.documentElement.getAttribute("lang") || "").toLowerCase();
    const ls =
      (window.localStorage.getItem("tbLang") ||
       window.localStorage.getItem("language") ||
       "").toLowerCase();
    const nav = (navigator.language || navigator.userLanguage || "").toLowerCase();

    let raw = langAttr || ls || nav || "en";
    if (raw.startsWith("ja")) return "ja";
    if (raw.startsWith("en")) return "en";
    return "en";
  }

  // ==== LẤY DEVICE TỪ DATASOURCE ====
  function getDeviceFromDatasource() {
    const sub = ctx.defaultSubscription;
    if (!sub || !sub.datasources || !sub.datasources.length) {
      return null;
    }

    const ds = sub.datasources[0];

    let entityId = null;
    let entityType = null;
    let entityName = null;

    if (ds.entityId) {
      if (typeof ds.entityId === "string") {
        entityId = ds.entityId;
      } else if (typeof ds.entityId === "object") {
        entityId   = ds.entityId.id || ds.entityId.entityId || null;
        entityType = ds.entityId.entityType || null;
      }
    }

    if (!entityId && ds.entity && typeof ds.entity === "object") {
      entityId   = ds.entity.id   || entityId;
      entityType = ds.entity.type || entityType;
    }

    entityType = entityType || ds.entityType || "DEVICE";
    entityName = ds.entityName || ds.name || (ds.entity && ds.entity.name) || entityId;

    if (!entityId) {
      return null;
    }

    return {
      id: entityId,
      name: entityName || entityId,
      type: entityType
    };
  }

  // ===== CHUẨN HOÁ LABEL: trim + lowercase + gộp space =====
  function normalizeLabel(raw) {
    if (raw === undefined || raw === null) return null;
    let s = String(raw).trim().toLowerCase();
    if (!s) return null;
    s = s.replace(/\s+/g, " "); // "  Edge   Device " -> "edge device"
    return s;
  }

  // ===== đọc deviceLabel và quyết định hiển thị gì =====
  function updateByDeviceLabel(dev) {
    if (!dev || dev.type !== "DEVICE") {
      // nếu alias không phải DEVICE thì cứ để card config
      showConfigCard();
      return;
    }

    const url =
      `/api/plugins/telemetry/DEVICE/${dev.id}` +
      `/values/attributes/SERVER_SCOPE?keys=deviceLabel`;

    ctx.http.get(url).subscribe(
      function success(resp) {
        const data = resp.data || resp;
        let rawLabel = null;

        if (Array.isArray(data)) {
          data.forEach(it => {
            if (it && it.key === "deviceLabel") {
              rawLabel = it.value;
            }
          });
        }

        const norm = normalizeLabel(rawLabel);
        // console.log("deviceLabel raw =", rawLabel, "norm =", norm);

        if (!norm) {
          // Không có label → chỉ hiện card HTML, không load link
          showConfigCard();
          return;
        }

        if (norm === "edge-type" || norm === "edge") {
          showIframe(BASE_URL_EDGE, 'edge');
          return;
        }

        if (norm === "tablet-type" || norm === "tablet") {
          showIframe(BASE_URL_TABLET, 'tablet');
          return;
        }

        // Label lạ → cũng hiện card thông báo
        showConfigCard();
      },
      function error(err) {
        // Lỗi đọc attribute → cũng hiện card
        // console.warn("read deviceLabel error:", err);
        showConfigCard();
      }
    );
  }

  // ==== GỬI DEVICE + LANG + PROFILE VÀO IFRAME ====
  function sendContextToIframe() {
    const dev = getDeviceFromDatasource();
    const lang = detectTbLang();

    // quyết định dùng iframe hay card
    updateByDeviceLabel(dev);

    const payload = {
      type: "TB_DEVICE_SELECTED",
      lang,
      profile: PROFILE_KEY
    };

    if (dev) {
      payload.deviceId = dev.id;
      payload.deviceName = dev.name;
    }

    try {
      iframe.contentWindow.postMessage(payload, "*");
    } catch (err) {
      // console.error("postMessage error:", err);
    }
  }

  // Gửi device vài lần lúc đầu để iframe chắc chắn nhận
  let retryCount = 0;
  function autoSendContext() {
    sendContextToIframe();
    retryCount++;
    if (retryCount < 10) {
      setTimeout(autoSendContext, 200);
    }
  }
  autoSendContext();

  // ==== LIFECYCLE ====
  self.onDataUpdated = function () {
    sendContextToIframe();
  };

  self.onResize = function () {};
  self.onDestroy = function () {};

  iframe.addEventListener("load", function () {
    setTimeout(sendContextToIframe, 200);
  });
};

