descriptor.controllerScript:
const BASE_URL = 'https://visiflow-dev.m-tech.com.vn';

self.onInit = function () {
    console.log('[RPA_report_jp] ウィジェットが初期化されました');
    initializeWidget();
};

self.onDataUpdated = function () {
    console.log('[RPA_report_jp] 📊 ウィジェットデータが更新されました');
};

function initializeWidget() {
    self.storeSelect = document.getElementById('storeSelect');
    self.statusEl = document.getElementById('status');

    // Add change listener
    self.storeSelect.addEventListener('change', () => {
        const selectedStore = self.storeSelect.value;
        if (selectedStore) {
            loadReport(selectedStore);
        }
    });

    // Initialize store list
    init();
}

async function init() {
    setStatus('拠点を読み込み中...');
    try {
        console.log('[RPA_report_jp] ウィジェットを初期化中...');
        const stores = await fetchDeviceTypes();
        console.log('[RPA_report_jp] 取得した拠点:', stores);
        fillSelect(self.storeSelect, stores, null);
        setStatus('');

        // Auto-select first store
        if (stores.length) {
            self.storeSelect.value = stores[0];
            loadReport(stores[0]);
        } else {
            console.warn('[RPA_report_jp] 拠点が見つかりません');
            setStatus('利用可能な拠点がありません');
        }
    } catch (error) {
        console.error('[RPA_report_jp] init()でエラーが発生しました:', error);
        setStatus('拠点の読み込みエラー: ' + error.message);
    }
}

function fillSelect(selectEl, items, placeholder) {
    selectEl.innerHTML = '';

    if (placeholder) {
        const ph = document.createElement('option');
        ph.value = '';
        ph.textContent = placeholder;
        selectEl.appendChild(ph);
    }

    items.forEach(item => {
        const opt = document.createElement('option');
        opt.value = item;
        opt.textContent = item;
        selectEl.appendChild(opt);
    });
}

function setStatus(msg) {
    self.statusEl.textContent = msg || '';
}

function getToken() {
    const jwtToken = localStorage.getItem('jwt_token');
    const token = localStorage.getItem('token');
    return jwtToken || token || '';
}

async function apiGet(url) {
    const token = getToken();
    console.log('[RPA_report_jp] API GET:', url);

    const res = await fetch(url, {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
        }
    });

    console.log('[RPA_report_jp] APIレスポンス:', {
        url: url,
        status: res.status,
        ok: res.ok
    });

    if (!res.ok) {
        const errorText = await res.text();
        console.error('[RPA_report_jp] APIエラー:', errorText);
        throw new Error(`HTTP ${res.status} when GET ${url}: ${errorText}`);
    }

    return res.json();
}

async function fetchDeviceTypes() {
    const user = self.ctx.currentUser;
    console.log('[RPA_report_jp] デバイスタイプを取得中。ユーザー権限:', user ? user.authority : '不明');

    // CUSTOMER_USER: Fetch all assigned devices and extract unique types
    if (user && user.authority === 'CUSTOMER_USER') {
        const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
        if (!customerId) {
            console.error('[RPA_report_jp] ❌ CUSTOMER_USERのカスタマーIDが見つかりません');
            return [];
        }

        const pageSize = 1000;
        const url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=0`;
        console.log('[RPA_report_jp] カスタマーユーザー: タイプを抽出するためにすべてのデバイスを取得中:', url);

        try {
            const r = await apiGet(url);
            const data = r.data || [];
            console.log(`[RPA_report_jp] カスタマーの${data.length}台のデバイスを取得しました。`);

            const uniqueTypes = [...new Set(data.map(d => d.type))].filter(Boolean).sort();
            console.log('[RPA_report_jp] カスタマーデバイスから抽出したユニークタイプ:', uniqueTypes);
            return uniqueTypes;
        } catch (e) {
            console.error('[RPA_report_jp] タイプのカスタマーデバイス取得エラー:', e);
            return [];
        }
    }

    // TENANT_ADMIN: Fetch all device types from system
    console.log('[RPA_report_jp] テナント管理者: /api/device/typesからすべてのデバイスタイプを取得中');
    const r = await apiGet('/api/device/types');
    console.log('[RPA_report_jp] /api/device/typesからの生のレスポンス:', r);

    let types = Array.isArray(r) ? r : (r.deviceTypes || []);

    if (types.length > 0 && typeof types[0] === 'object') {
        types = types.map(t => {
            const typeName = t.type || t.name || t.deviceType || t.label || JSON.stringify(t);
            return typeName;
        });
    }

    return types;
}

function loadReport(storeName) {
    const reportFrame = document.getElementById('reportFrame');
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');

    if (!storeName) {
        showError('拠点が選択されていません。ドロップダウンから拠点を選択してください。');
        return;
    }

    // Show loading
    if (loadingOverlay) {
        loadingOverlay.style.display = 'flex';
    }
    if (errorOverlay) {
        errorOverlay.style.display = 'none';
    }

    // Construct report URL (Japanese)
    const fileName = 'rpa_report_jp.html';
    let reportUrl = `${BASE_URL}/web_server/${fileName}`;

    // Add store parameter
    reportUrl += `?store=${encodeURIComponent(storeName)}`;

    console.log('[RPA_report_jp] レポートURLを読み込み中:', reportUrl);
    console.log('[RPA_report_jp] 拠点:', storeName);

    if (reportFrame) {
        reportFrame.src = reportUrl;

        // Handle iframe load
        reportFrame.onload = function () {
            console.log('[RPA_report_jp] レポートiframeが正常に読み込まれました');
            if (loadingOverlay) {
                setTimeout(() => {
                    loadingOverlay.style.display = 'none';
                }, 500);
            }
        };

        // Handle iframe error
        reportFrame.onerror = function () {
            console.error('[RPA_report_jp] レポートiframeの読み込みに失敗しました');
            showError();
        };

        // Timeout fallback
        setTimeout(() => {
            if (loadingOverlay && loadingOverlay.style.display !== 'none') {
                loadingOverlay.style.display = 'none';
            }
        }, 5000);
    }
}

function showError(customMessage) {
    const loadingOverlay = document.getElementById('loadingOverlay');
