descriptor.controllerScript:
let currentUserId = null;
const BASE_URL = 'https://visiflow-dev.m-tech.com.vn';

self.onInit = function () {
    initializeWidget();
};

self.onDataUpdated = function () {
    updateUserInfo();
};

function initializeWidget() {
    updateUserInfo();
}

function updateUserInfo() {
    // Get userId from JWT token in localStorage (most reliable)
    try {
        if (typeof localStorage !== 'undefined') {
            const jwtToken = localStorage.getItem('jwt_token');
            if (jwtToken) {
                try {
                    const payload = JSON.parse(atob(jwtToken.split('.')[1]));
                    currentUserId = payload.sub || payload.userId || null;
                    console.log('[AI Summary View] Got userId from JWT:', currentUserId);
                } catch (e) {
                    console.warn('[AI Summary View] Failed to parse JWT:', e);
                }
            }
        }

        // Fallback: Get from authService
        if (!currentUserId && self.ctx.$injector) {
            try {
                const authService = self.ctx.$injector.get('authService');
                if (authService && authService.getCurrentAuthUser) {
                    const user = authService.getCurrentAuthUser();
                    if (user) {
                        currentUserId = user.sub || user.userId || null;
                    }
                }
            } catch (e) { }
        }

        // Fallback: Get from URL params
        if (!currentUserId) {
            const urlParams = new URLSearchParams(window.location.search);
            currentUserId = urlParams.get('userId') || urlParams.get('deviceId') || null;
        }

    } catch (e) {
        console.warn('[AI Summary View] Error getting user info:', e);
    }

    if (currentUserId) {
        loadReport();
    } else {
        showError();
    }
}

function loadReport() {
    const reportFrame = document.getElementById('reportFrame');
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');

    if (!currentUserId) {
        showError();
        return;
    }

    // Show loading
    if (loadingOverlay) {
        loadingOverlay.style.display = 'flex';
    }
    if (errorOverlay) {
        errorOverlay.style.display = 'none';
    }

    // Construct report URL with userId
    const fileName = 'AI_summary.html';
    let reportUrl = `${BASE_URL}/web_server/${fileName}?userId=${encodeURIComponent(currentUserId)}`;

    if (reportFrame) {
        reportFrame.src = reportUrl;

        // Handle iframe load
        reportFrame.onload = function () {
            // console.log('Report iframe loaded successfully');
            if (loadingOverlay) {
                setTimeout(() => {
                    loadingOverlay.style.display = 'none';
                }, 500);
            }
        };

        // Handle iframe error
        reportFrame.onerror = function () {
            // console.error('Failed to load report iframe');
            showError();
        };

        // Timeout fallback
        setTimeout(() => {
            if (loadingOverlay && loadingOverlay.style.display !== 'none') {
                loadingOverlay.style.display = 'none';
            }
        }, 5000);
    }
}

function showError() {
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');

    if (loadingOverlay) {
        loadingOverlay.style.display = 'none';
    }
    if (errorOverlay) {
        errorOverlay.style.display = 'flex';
    }
}

self.onResize = function () {
    // Handle widget resize if needed
    // console.log('Widget resized');
};

self.onDestroy = function () {
    // console.log('RPA Report Widget destroyed');
};

