descriptor.controllerScript:
const BACKEND_URL = 'https://visiflow-dev.m-tech.com.vn';

const CONFIG = {
    maxRetries: 2,
    baseScale: 1.0,                           // Full scale for text clarity
    fallbackScales: [0.8, 0.6],               // Fallbacks for retry
    maxDpr: 2.0,                              // Higher DPR for sharper text
    preferFormat: 'image/jpeg',               // JPEG is faster to encode than PNG
    altFormats: ['image/webp'],               // Simplified fallback
    qualitySteps: [0.9, 0.8, 0.7],            // Higher quality to preserve text
    timeout: 60000,                           // 60s for capture
    maxFileSize: 10 * 1024 * 1024,
    uploadTimeout: 120000,                    // 2 minutes for slow mobile networks
    imageTimeout: 25000,                      // 25s for loading images
    blobTimeout: 30000,                       // 30s for toBlob encoding
    maxCanvasDimension: 3000                  // Higher limit for better quality
};

self.onInit = function () {
    self.ctx.$scope.actionWidget.onInit();

    // Check for html-to-image library (loaded as htmlToImage global)
    if (typeof htmlToImage === 'undefined') {
        showPermanentError('html-to-image ライブラリがありません。リソースにCDNを追加してください。');
        return;
    }

    injectStyles();

    const originalOnClick = self.ctx.$scope.actionWidget.onClick;

    self.ctx.$scope.actionWidget.onClick = function ($event) {
        const button = getButtonElement();
        if (!button || button.dataset.processing === 'true') return;

        // Show unified modal starting with confirmation state
        showConfirmModal(async () => {
            // ON CONFIRM CLICKED:
            button.dataset.processing = 'true';
            button.disabled = true;

            // Transform modal to AI processing state (single message for entire process)
            updateToProgress();

            let attempt = 0;
            let lastError = null;

            while (attempt < CONFIG.maxRetries) {
                try {
                    const pixelRatio = getScaledFactor(attempt);

                    await waitForAssets();
                    await sleep(300);

                    const target = findDashboardElement();
                    if (!target) throw new Error('ダッシュボード要素が見つかりません');

                    const blob = await captureWithHtmlToImage(target, pixelRatio);

                    if (!blob || blob.size === 0) {
                        throw new Error('スクリーンショットの取得に失敗しました');
                    }

                    let finalBlob = blob;
                    if (blob.size > CONFIG.maxFileSize) {
                        finalBlob = await compressBlob(blob, CONFIG.maxFileSize);
                    }

                    const result = await uploadToBackend(finalBlob);

                    showSuccessModal();
                    await sleep(1200);

                    if (originalOnClick) {
                        try { originalOnClick.call(self.ctx.$scope.actionWidget, $event); } catch (e) { }
                    }
                    break;

                } catch (err) {
                    lastError = err;
                    attempt++;
                    if (attempt >= CONFIG.maxRetries) {
                        showErrorModal(lastError?.message || '失敗しました');
                        button.disabled = false;
                        button.dataset.processing = 'false';
                        return;
                    }
                    // Silent retry, no UI update
                    await sleep(800);
                }
            }

            // Cleanup if successful (modal closes itself via showSuccessModal timeout)
            // But we need to reset button state
            setTimeout(() => {
                button.disabled = false;
                button.dataset.processing = 'false';
            }, 1500);

        }, () => {
            // ON CANCEL CLICKED:
            // Nothing to do, modal closes itself
        });
    };
};



function getScaledFactor(attemptIndex) {
    const dpr = Math.min(CONFIG.maxDpr, window.devicePixelRatio || 1);
    const base = (attemptIndex === 0)
        ? CONFIG.baseScale
        : (CONFIG.fallbackScales[attemptIndex - 1] || CONFIG.fallbackScales.slice(-1)[0]);
    return dpr * base;
}

async function waitForAssets() {
    try {
        if (document.fonts && document.fonts.ready) {
            await Promise.race([document.fonts.ready, sleep(3000)]);
        }
    } catch (_) { }
    const imgs = Array.from(document.images || []);
    const waits = imgs
        .filter(img => !img.complete)
        .map(img => new Promise(res => {
            const done = () => res();
            img.addEventListener('load', done, { once: true });
            img.addEventListener('error', done, { once: true });
        }));
    if (waits.length) {
        await Promise.race([Promise.all(waits), sleep(4000)]);
    }
}

// Capture using html-to-image library
async function captureWithHtmlToImage(element, pixelRatio) {
    return new Promise(async (resolve, reject) => {
        const timeoutId = setTimeout(() => reject(new Error('キャプチャタイムアウト')), CONFIG.timeout);

        try {
            // Freeze animations during capture
            const freezeStyle = document.createElement('style');
            freezeStyle.id = 'tb-freeze-anim';
            freezeStyle.textContent = `
                *, *::before, *::after {
                    animation-play-state: paused !important;
                    transition: none !important;
                }
            `;
            document.head.appendChild(freezeStyle);

            // html-to-image options
            const options = {
                pixelRatio: pixelRatio,
                backgroundColor: '#ffffff',
                cacheBust: true,
                // Filter out problematic elements
                filter: (node) => {
                    if (node.tagName === 'VIDEO') return false;
                    if (node.tagName === 'IFRAME') return false;
                    if (node.tagName === 'EMBED') return false;
                    if (node.tagName === 'OBJECT') return false;
                    return true;
                },
                // Font handling - MUST embed fonts for icons (Material Icons)
                skipFonts: false,  // DO NOT skip fonts - needed for icons!
                includeQueryParams: true,  // Include query params for font URLs
                // Quality settings
                quality: CONFIG.qualitySteps[0],
                type: 'image/jpeg'
            };

            // Use toBlob for direct blob output
            const blob = await htmlToImage.toBlob(element, options);

            clearTimeout(timeoutId);
            freezeStyle.remove();

            if (!blob) {
                reject(new Error('html-to-imageがnullを返しました'));
                return;
            }

            resolve(blob);
        } catch (e) {
            clearTimeout(timeoutId);
            document.getElementById('tb-freeze-anim')?.remove();
            reject(e);
        }
    });
}

// Compress blob if it's too large
async function compressBlob(blob, maxSize) {
    // Create image from blob
    const img = new Image();
    const url = URL.createObjectURL(blob);

    await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
        img.src = url;
    });

    URL.revokeObjectURL(url);

    // Try progressively smaller sizes
    for (const quality of CONFIG.qualitySteps) {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;

        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        const compressedBlob = await new Promise(resolve => {
            canvas.toBlob(resolve, 'image/jpeg', quality);
        });

        // Cleanup
        canvas.width = 0;
        canvas.height = 0;

        if (compressedBlob && compressedBlob.size <= maxSize) {
            return compressedBlob;
        }
    }

    // Last resort: scale down the image
    const scaleFactor = 0.5;
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.width * scaleFactor);
    canvas.height = Math.round(img.height * scaleFactor);

    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    const smallBlob = await new Promise(resolve => {
        canvas.toBlob(resolve, 'image/jpeg', 0.6);
    });

    canvas.width = 0;
    canvas.height = 0;

    return smallBlob || blob;
}

async function uploadToBackend(blob) {
    const formData = new FormData();
    const ext = blob.type.includes('png') ? 'png' : (blob.type.includes('webp') ? 'webp' : 'jpg');
    formData.append('screenshot', blob, `dashboard.${ext}`);

    // Get current user info from ThingsBoard
    let userId = null;
    let userName = 'Unknown User';
    let userAuthority = 'USER';

    try {
        // Method 1: Get from JWT token in localStorage (most reliable)
        if (typeof localStorage !== 'undefined') {
            const jwtToken = localStorage.getItem('jwt_token');
            if (jwtToken) {
                try {
                    const payload = JSON.parse(atob(jwtToken.split('.')[1]));
                    userId = payload.sub || payload.userId || null;
                    userAuthority = payload.scopes?.[0] || payload.authority || 'USER';
                    console.log('[AI Summary] Got userId from JWT:', userId);
                } catch (e) {
                    console.warn('[AI Summary] Failed to parse JWT:', e);
                }
            }
        }

        // Method 2: Get from authService
        if (!userId && self.ctx.$injector) {
            try {
                const authService = self.ctx.$injector.get('authService');
                if (authService && authService.getCurrentAuthUser) {
                    const user = authService.getCurrentAuthUser();
                    if (user) {
                        userId = user.sub || user.userId || null;
                        userAuthority = user.scopes?.[0] || user.authority || userAuthority;
                        console.log('[AI Summary] Got userId from authService:', userId);
                    }
                }
            } catch (e) { }
        }

        // Method 3: Get from dashboard state/context
        if (!userId && self.ctx.stateController) {
            try {
                const state = self.ctx.stateController.getStateParams();
                if (state && state.entityId) {
                    userId = state.entityId.id || null;
                    console.log('[AI Summary] Got userId from stateController:', userId);
                }
            } catch (e) { }
        }

        // Method 4: Get user email from $scope
        if (!userId && self.ctx.$scope && self.ctx.$scope.$root) {
            const rootUser = self.ctx.$scope.$root.currentUser;
            if (rootUser) {
                userId = rootUser.id?.id || rootUser.email || null;
                userName = rootUser.email || rootUser.name || userName;
                console.log('[AI Summary] Got userId from $scope.$root:', userId);
            }
        }

        // Method 5: Generate from current window URL (dashboard specific)
        if (!userId) {
            const urlParams = new URLSearchParams(window.location.search);
            const entityId = urlParams.get('entityId') || urlParams.get('deviceId');
            if (entityId) {
                userId = entityId;
                console.log('[AI Summary] Got entityId from URL:', userId);
            }
        }

        // FALLBACK: Use timestamp-based unique ID
        if (!userId) {
            userId = 'session_' + Date.now();
            console.log('[AI Summary] Using fallback session ID:', userId);
        }

    } catch (e) {
        console.warn('[AI Summary] Error getting user info:', e);
        userId = 'error_' + Date.now();
    }

    formData.append('userId', userId);
    formData.append('userName', userName);
    formData.append('userAuthority', userAuthority);

    console.log('[AI Summary] Uploading with userId:', userId, 'userName:', userName);

    const controller = new AbortController();
    const tid = setTimeout(() => controller.abort(), CONFIG.uploadTimeout);

    try {
        const res = await fetch(`${BACKEND_URL}/api/analyze-dashboard`, {
            method: 'POST',
            body: formData,
            signal: controller.signal
        });
        clearTimeout(tid);
        if (!res.ok) {
            const txt = await res.text();
            throw new Error(`HTTP ${res.status}: ${txt.slice(0, 160)}`);
        }
        const json = await res.json();
        if (!json.success) throw new Error(json.error || 'バックエンドエラー');

        return json;
    } catch (e) {
        clearTimeout(tid);
        if (e.name === 'AbortError') throw new Error('アップロードタイムアウト');
        throw e;
    }
}

function findDashboardElement() {
    const selectors = [
        'tb-dashboard-page .tb-dashboard',
        'tb-dashboard .tb-dashboard',
        '.tb-dashboard-container',
        'gridster',
        '.gridster',
        'tb-dashboard-page mat-drawer-content',
        '.mat-drawer-content .tb-dashboard',
        'tb-dashboard'
    ];
    for (const sel of selectors) {
        const el = document.querySelector(sel);
        if (el) {
            return el;
        }
    }
    return document.body;
}

function getButtonElement() {
    if (self.ctx.$scope.actionWidget?.buttonElement) {
        return self.ctx.$scope.actionWidget.buttonElement;
    }
    const container = self.ctx.$container?.[0] || self.ctx.$containerParent?.[0];
    if (container) {
        const btn = container.querySelector('button');
        if (btn) return btn;
    }
    if (self.ctx.$scope.$element) {
        const btn = self.ctx.$scope.$element[0]?.querySelector('button');
        if (btn) return btn;
    }
    return document.querySelector('tb-command-button-widget button');
}

function injectStyles() {
    if (document.getElementById('tb-screenshot-styles')) return;
    const style = document.createElement('style');
    style.id = 'tb-screenshot-styles';
    style.textContent = `
    .tb-progress-modal {
      position: fixed !important;
