      box-shadow: 0 20px 40px rgba(0,0,0,0.15) !important;
      display: flex !important;
      flex-direction: column !important;
      align-items: center !important;
      gap: 20px !important;
      min-width: 320px !important;
      max-width: 90vw !important;
      transition: all 0.3s ease !important;
    }

    /* AI Animation Container */
    .tb-ai-animation {
      position: relative !important;
      width: 80px !important;
      height: 80px !important;
      display: flex !important;
      align-items: center !important;
      justify-content: center !important;
    }

    /* Pulsing rings */
    .tb-ai-ring {
      position: absolute !important;
      border: 2px solid #ED1C24 !important;
      border-radius: 50% !important;
      animation: pulse-ring 2s ease-out infinite !important;
    }
    .tb-ai-ring:nth-child(1) { width: 60px !important; height: 60px !important; animation-delay: 0s !important; }
    .tb-ai-ring:nth-child(2) { width: 80px !important; height: 80px !important; animation-delay: 0.5s !important; }
    .tb-ai-ring:nth-child(3) { width: 100px !important; height: 100px !important; animation-delay: 1s !important; }

    @keyframes pulse-ring {
      0% { transform: scale(0.8); opacity: 1; }
      100% { transform: scale(1.3); opacity: 0; }
    }

    /* AI Brain Icon */
    .tb-ai-icon {
      font-size: 36px !important;
      z-index: 1 !important;
      animation: float 2s ease-in-out infinite !important;
    }

    @keyframes float {
