      gap: 12px !important;
      margin-top: 8px !important;
      width: 100% !important;
      justify-content: center !important;
    }
    .tb-modal-btn {
      padding: 10px 24px !important;
      border-radius: 8px !important;
      border: none !important;
      font-weight: 600 !important;
      cursor: pointer !important;
      font-size: 14px !important;
      transition: all 0.2s ease !important;
    }
    .tb-modal-btn:hover { transform: translateY(-1px) !important; }
    .tb-modal-btn:active { transform: translateY(0) !important; }
    .tb-btn-confirm { background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%) !important; color: white !important; }
    .tb-btn-cancel { background: #f1f5f9 !important; color: #475569 !important; }
    .tb-warning-box {
      background: #fef3c7 !important;
      border-left: 4px solid #f59e0b !important;
      padding: 12px 16px !important;
      border-radius: 8px !important;
      font-size: 13px !important;
      color: #92400e !important;
      width: 100% !important;
      text-align: left !important;
    }

    /* Success animation */
    .tb-success-icon {
      font-size: 48px !important;
      animation: pop-in 0.3s ease !important;
    }
    @keyframes pop-in {
      0% { transform: scale(0); }
      70% { transform: scale(1.2); }
      100% { transform: scale(1); }
    }

    .tb-screenshot-permanent-error {
      position: absolute !important;
      inset: 0 !important;
      background: rgba(244,67,54,0.9) !important;
      display: flex !important;
      align-items: center !important;
      justify-content: center !important;
      padding: 10px !important;
      text-align: center !important;
      font-size: 11px !important;
      color: white !important;
      z-index: 99999 !important;
    }
  `;
    document.head.appendChild(style);
}

// Unified Modal Functions

function showConfirmModal(onConfirm, onCancel) {
    closeProgressModal();
    const modal = document.createElement('div');
    modal.className = 'tb-progress-modal';

    const content = `
        <div class="tb-progress-content" style="align-items: flex-start; text-align: left; min-width: 400px;">
            <div style="font-size: 14px; color: #666; margin-bottom: 8px;">AIまとめ</div>
            <div style="font-size: 20px; color: #333; font-weight: 400; margin-bottom: 20px;">
                現在のダッシュボードの概要をご希望ですか？
            </div>
            <div class="tb-warning-box" style="margin-bottom: 24px;">
                <div style="display: flex; gap: 8px; align-items: flex-start;">
                    <span style="font-size: 16px;">⚠️</span>
                    <div>
                        <strong>重要：</strong><br>
                        ご確認いただける場合、処理が正常に完了するまでダッシュボードに触れたり操作したりしないでください。
                    </div>
                </div>
            </div>
            <div style="display: flex; gap: 16px; width: 100%; justify-content: flex-end;">
                <button id="tb-modal-cancel" style="background: none; border: none; color: #666; font-size: 14px; cursor: pointer; padding: 8px 16px;">キャンセル</button>
                <button id="tb-modal-confirm" style="background: none; border: none; color: #e53935; font-size: 14px; font-weight: 500; cursor: pointer; padding: 8px 16px;">確認</button>
            </div>
        </div>
    `;

    modal.innerHTML = content;
    document.body.appendChild(modal);

    // Bind events
    document.getElementById('tb-modal-cancel').onclick = () => {
        closeProgressModal();
        if (onCancel) onCancel();
    };

    document.getElementById('tb-modal-confirm').onclick = () => {
        // Transform to progress state
        const btnConfirm = document.getElementById('tb-modal-confirm');
        const btnCancel = document.getElementById('tb-modal-cancel');
        if (btnConfirm) btnConfirm.disabled = true;
        if (btnCancel) btnCancel.disabled = true;

        if (onConfirm) onConfirm();
    };
}

function updateToProgress() {
    const content = document.querySelector('.tb-progress-content');
    if (!content) return;

    // Show AI processing animation with robot SVG icon
    content.innerHTML = `
        <div class="tb-ai-animation">
            <div class="tb-ai-ring"></div>
            <div class="tb-ai-ring"></div>
            <div class="tb-ai-ring"></div>
            <svg class="tb-ai-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#ED1C24" width="40" height="40">
                <path d="M22 14H21C21 10.13 17.87 7 14 7H13V5.73C13.6 5.39 14 4.74 14 4C14 2.9 13.11 2 12 2S10 2.9 10 4C10 4.74 10.4 5.39 11 5.73V7H10C6.13 7 3 10.13 3 14H2C1.45 14 1 14.45 1 15V18C1 18.55 1.45 19 2 19H3V20C3 21.11 3.9 22 5 22H19C20.11 22 21 21.11 21 20V19H22C22.55 19 23 18.55 23 18V15C23 14.45 22.55 14 22 14M21 17H19V20H5V17H3V16H5V14C5 11.24 7.24 9 10 9H14C16.76 9 19 11.24 19 14V16H21V17M8.5 13.5L10.86 15.86L9.68 17.04L8.5 15.86L7.32 17.04L6.14 15.86L8.5 13.5M15.5 13.5L17.86 15.86L16.68 17.04L15.5 15.86L14.32 17.04L13.14 15.86L15.5 13.5Z"/>
            </svg>
        </div>
        <div class="tb-progress-text">AIが処理中です</div>
        <div class="tb-progress-subtext">しばらくお待ちください...</div>
    `;
}

function updateProgressModal(title, subtitle = '') {
    const modal = document.querySelector('.tb-progress-modal');
    if (modal) {
        const textEl = modal.querySelector('.tb-progress-text');
        const subEl = modal.querySelector('.tb-progress-subtext');
        if (textEl) textEl.textContent = title;
        if (subEl) {
            subEl.textContent = subtitle;
            subEl.style.display = subtitle ? 'block' : 'none';
        }
    }
}

function closeProgressModal() {
    document.querySelector('.tb-progress-modal')?.remove();
}

function showSuccessModal() {
    const content = document.querySelector('.tb-progress-content');
    if (content) {
        content.innerHTML = `
            <span class="tb-success-icon">✅</span>
            <div class="tb-progress-text">完了！</div>
            <div class="tb-progress-subtext">AIがダッシュボードの分析を完了しました</div>
        `;
    }
    setTimeout(closeProgressModal, 1500);
}

function showErrorModal(rawMsg) {
    const content = document.querySelector('.tb-progress-content');
    if (!content) return;

    // Convert technical errors to user-friendly messages (Japanese)
    let userMessage = '問題が発生しました。後でもう一度お試しください。';
    let subMessage = '問題が解決しない場合は、サポートにお問い合わせください。';

    const msgLower = (rawMsg || '').toLowerCase();

    if (msgLower.includes('quota') || msgLower.includes('resource_exhausted') || msgLower.includes('429')) {
        userMessage = 'サービスが一時的に混雑しています';
        subMessage = 'しばらく待ってからもう一度お試しください。';
    } else if (msgLower.includes('timeout') || msgLower.includes('timed out')) {
        userMessage = 'リクエストに時間がかかりすぎました';
        subMessage = '接続を確認してもう一度お試しください。';
    } else if (msgLower.includes('network') || msgLower.includes('fetch') || msgLower.includes('connection')) {
        userMessage = '接続エラー';
        subMessage = 'インターネット接続を確認してください。';
    } else if (msgLower.includes('not found') || msgLower.includes('404')) {
        userMessage = 'サービスが利用できません';
        subMessage = 'AIサービスは現在利用できません。';
    } else if (msgLower.includes('500') || msgLower.includes('server')) {
        userMessage = 'サーバーエラー';
        subMessage = 'サーバーに問題が発生しています。後でもう一度お試しください。';
    }

    content.innerHTML = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#dc2626" width="48" height="48">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>
        </svg>
        <div class="tb-progress-text" style="color: #dc2626;">${userMessage}</div>
        <div class="tb-progress-subtext">${subMessage}</div>
        <button class="tb-modal-btn" style="background: #dc2626; color: white; margin-top: 12px;" onclick="document.querySelector('.tb-progress-modal')?.remove()">閉じる</button>
    `;

    // Log actual error for debugging
    console.error('[AI Summary] Error:', rawMsg);
}

function showPermanentError(msg) {
    const button = getButtonElement();
    if (!button) return;
    const overlay = document.createElement('div');
    overlay.className = 'tb-screenshot-permanent-error';
    overlay.textContent = msg;
    button.appendChild(overlay);
    button.disabled = true;
}
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

self.onDestroy = function () {
    document.getElementById('tb-screenshot-styles')?.remove();
    document.getElementById('tb-freeze-anim')?.remove();
};

descriptor.templateCss:
/* ===================================
   MODERN LINEAR STYLE WIDGET
   Inspired by Vercel/Linear Design
   =================================== */

/* Container */
.store-selector-widget {
    width: 100%;
    height: 100%;
    padding: 12px;
    background: #ffffff;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    /* Fluid font scaling */
    font-size: clamp(11px, min(2vw, 3vh), 15px);
    color: #111827;
}

/* Row Layout */
.selector-row {
    display: flex;
    gap: 12px;
    flex: 1;
    width: 100%;
    align-items: flex-start;
    /* Align to top */
}

/* Form Fields */
.form-field {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

/* Flex Ratios (3:7) */
.store-field {
    flex: 3;
}

.device-field {
    flex: 7;
}

/* Labels - Modern & Clean */
.field-label {
    display: block;
    font-size: 0.75em;
    font-weight: 600;
    color: #374151;
    /* Gray-700 */
    margin-bottom: 6px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: 0.01em;
}

/* Select Wrapper - The "Linear" Look */
.select-wrapper {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 36px;
    /* Touch target size */
    max-height: 48px;
    /* Cap height for aesthetics */
    background: #ffffff;
    border: 1px solid #E5E7EB;
    /* Gray-200 */
    border-radius: 6px;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    /* Subtle shadow */
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
}

/* Hover State */
.select-wrapper:hover {
    border-color: #D1D5DB;
    /* Gray-300 */
    background: #F9FAFB;
    /* Gray-50 */
    box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.05);
}

/* Focus State */
.select-wrapper:focus-within {
    border-color: #000000;
    /* High contrast focus */
    box-shadow: 0 0 0 1px #000000, 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    background: #ffffff;
}

/* Native Select Styling */
.mat-select {
    width: 100%;
    height: 100%;
    padding: 0 32px 0 12px;
    /* Space for arrow */
    font-size: 1em;
    font-weight: 500;
    color: #111827;
    /* Gray-900 */
    background: transparent;
    border: none;
    outline: none;
    cursor: pointer;
    appearance: none;
    /* Remove default arrow */
    -webkit-appearance: none;
    -moz-appearance: none;
    line-height: 1.5;
    border-radius: 6px;
}

/* Custom Chevron Arrow (SVG) */
.select-wrapper::after {
    content: '';
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 16px;
    background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M4 6L8 10L12 6' stroke='%236B7280' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.select-wrapper:hover::after {
    opacity: 1;
}

/* Options */
.mat-select option {
    color: #111827;
    background: #ffffff;
    padding: 8px;
}

/* Disabled State */
.mat-select:disabled {
    color: #9CA3AF;
    /* Gray-400 */
    cursor: not-allowed;
}

.select-wrapper:has(.mat-select:disabled) {
    background: #F3F4F6;
    /* Gray-100 */
    border-color: #E5E7EB;
    box-shadow: none;
}

/* Status Text */
.status-container {
    margin-top: 8px;
    display: none;
    /* Hidden by default */
}

.status-container:not(:empty) {
    display: block;
}

.status-text {
    font-size: 0.8em;
    color: #6B7280;
    /* Gray-500 */
    font-weight: 500;
}

/* Responsive Adjustments */

/* Tiny Widget */
@media (max-width: 300px),
(max-height: 120px) {
    .store-selector-widget {
        padding: 8px;
        font-size: 10px;
    }

    .selector-row {
        gap: 6px;
    }

    .select-wrapper {
        min-height: 28px;
        border-radius: 4px;
    }

    .mat-select {
        padding-right: 24px;
    }
}

/* Stacked Layout for Narrow Widths */
@media (max-width: 350px) {
    .selector-row {
        flex-direction: column;
        gap: 8px;
    }

    .store-field,
    .device-field {
        flex: auto;
        width: 100%;
    }
}

/* Large Widget */
@media (min-width: 600px) and (min-height: 200px) {
    .store-selector-widget {
        padding: 16px;
        font-size: 14px;
    }

    .selector-row {
        gap: 16px;
    }

    .select-wrapper {
        min-height: 40px;
    }
}

descriptor.controllerScript:
self.onInit = function () {
    self.typeSelect = document.getElementById('typeSelect');
    self.deviceSelect = document.getElementById('deviceSelect');
    self.statusEl = document.getElementById('status');

    self.typeSelect.addEventListener('change', async () => {
        const type = self.typeSelect.value;
        await loadDevicesByType(type);
        persistSelection();
    });

    self.deviceSelect.addEventListener('change', () => {
        persistSelection();
    });

    init();
};

async function init() {
    setStatus('Loading device types...');
    try {
        console.log('[store_type] Initializing widget...');
        const types = await fetchDeviceTypes();
        console.log('[store_type] Fetched device types:', types);
        fillSelect(self.typeSelect, types, null);
        setStatus('');

        // ✅ Try to restore last selection from localStorage
        const savedSelection = restoreSelection();

        if (savedSelection && savedSelection.deviceType && types.includes(savedSelection.deviceType)) {
            console.log('[store_type] 📦 Restoring saved selection:', savedSelection);
            self.typeSelect.value = savedSelection.deviceType;
            await loadDevicesByType(savedSelection.deviceType);

            // Restore device selection if available
            if (savedSelection.deviceId) {
                self.deviceSelect.value = savedSelection.deviceId;
            }
            persistSelection();
        } else if (types.length) {
            // Fallback: auto-load devices for first type
            self.typeSelect.value = types[0];
            await loadDevicesByType(types[0]);
            persistSelection();
        } else {
            console.warn('[store_type] No device types found');
            setStatus('No device types available');
        }
    } catch (error) {
        console.error('[store_type] Error in init():', error);
        setStatus('Error loading device types: ' + error.message);
    }
}

async function loadDevicesByType(type) {
    if (!type) {
        fillSelect(self.deviceSelect, [], '-- Select device --');
        return;
    }
    setStatus('Loading devices...');
    try {
        console.log('[store_type] Loading devices for type:', type);
        const devices = await fetchDevices(type);
        self.currentDevices = devices; // Store for multi-select
        console.log('[store_type] Fetched devices:', devices);

        // Determine options based on device count
        let deviceOptions = [];
        let defaultSelection = '';

        if (devices.length === 1) {
            // Single device: Remove "All devices" option, auto-select the only device
            console.log('[store_type] Single device detected. Removing "All devices" option.');
            deviceOptions = devices.map(d => ({ value: d.id, label: d.name }));
            defaultSelection = devices[0].id;
        } else {
            // Multiple devices (or 0): Keep "All devices" option, auto-select it
            console.log('[store_type] Multiple devices detected. Adding "All devices" option.');
            deviceOptions = [
                { value: '__ALL__', label: `All devices` },
                ...devices.map(d => ({ value: d.id, label: d.name }))
            ];
            defaultSelection = '__ALL__';
        }

        // No placeholder - start directly with options
        fillSelect(self.deviceSelect, deviceOptions, null);

        // Auto-select default
        self.deviceSelect.value = defaultSelection;
        persistSelection();

        setStatus('');
    } catch (error) {
        console.error('[store_type] Error loading devices:', error);
        setStatus('Error loading devices: ' + error.message);
    }
}

function fillSelect(selectEl, items, placeholder) {
    selectEl.innerHTML = '';

    // Only add placeholder if provided
    if (placeholder) {
        const ph = document.createElement('option');
        ph.value = '';
        ph.textContent = placeholder;
        selectEl.appendChild(ph);
    }

    items.forEach(it => {
        const opt = document.createElement('option');
        if (typeof it === 'string') {
            opt.value = it;
            opt.textContent = it;
        } else {
            opt.value = it.value;
            opt.textContent = it.label;
        }
        selectEl.appendChild(opt);
    });
}

function setStatus(msg) {
    self.statusEl.textContent = msg || '';
}

function getToken() {
    const jwtToken = localStorage.getItem('jwt_token');
    const token = localStorage.getItem('token');
    const result = jwtToken || token || '';

    console.log('[store_type] Token lookup:', {
        jwt_token: jwtToken ? 'found' : 'not found',
        token: token ? 'found' : 'not found',
        using: result ? 'token available' : 'NO TOKEN'
    });

    return result;
}

async function apiGet(url) {
    const token = getToken();
    console.log('[store_type] API GET:', url);

    const res = await fetch(url, {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
        }
    });

    console.log('[store_type] API Response:', {
        url: url,
        status: res.status,
        ok: res.ok
    });

    if (!res.ok) {
        const errorText = await res.text();
        console.error('[store_type] API Error:', errorText);
        throw new Error(`HTTP ${res.status} when GET ${url}: ${errorText}`);
    }

    return res.json();
}

async function fetchDeviceTypes() {
    const user = self.ctx.currentUser;
    console.log('[store_type] Fetching device types. User authority:', user ? user.authority : 'unknown');

    // CUSTOMER_USER: Fetch all assigned devices and extract unique types
    if (user && user.authority === 'CUSTOMER_USER') {
        const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
        if (!customerId) {
            console.error('[store_type] ❌ Customer ID missing for CUSTOMER_USER');
            return [];
        }

        const pageSize = 1000; // Fetch large batch to get all types
        const url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=0`;
        console.log('[store_type] Customer User: Fetching all devices to extract types from:', url);

        try {
            const r = await apiGet(url);
            const data = r.data || [];
            console.log(`[store_type] Fetched ${data.length} devices for customer.`);

            // Extract unique types
            const uniqueTypes = [...new Set(data.map(d => d.type))].filter(Boolean).sort();
            console.log('[store_type] Extracted unique types from customer devices:', uniqueTypes);
            return uniqueTypes;
        } catch (e) {
            console.error('[store_type] Error fetching customer devices for types:', e);
            return [];
        }
    }

    // TENANT_ADMIN: Fetch all device types from system
    console.log('[store_type] Tenant Admin: Fetching all device types from /api/device/types');
    const r = await apiGet('/api/device/types');
    console.log('[store_type] Raw response from /api/device/types:', r);

    let types = Array.isArray(r) ? r : (r.deviceTypes || []);

    if (types.length > 0 && typeof types[0] === 'object') {
        types = types.map(t => {
            const typeName = t.type || t.name || t.deviceType || t.label || JSON.stringify(t);
            return typeName;
        });
    }

    return types;
}

async function fetchDevices(deviceType) {
    const pageSize = 100;
    const page = 0;

    let url;
    const user = self.ctx.currentUser;
    console.log('[store_type] Current user authority:', user ? user.authority : 'unknown');

    if (user && user.authority === 'CUSTOMER_USER') {
        // Handle both object {id: '...'} and string formats
        const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;

        if (!customerId) {
            console.error('[store_type] ❌ Could not find customerId for CUSTOMER_USER:', user);
            throw new Error('Customer ID not found for current user');
        }

        url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=${page}&type=${encodeURIComponent(deviceType)}`;
        console.log('[store_type] Using Customer API for device fetch. CustomerId:', customerId);
    } else {
        url = `/api/tenant/deviceInfos?pageSize=${pageSize}&page=${page}&type=${encodeURIComponent(deviceType)}`;
        console.log('[store_type] Using Tenant API for device fetch');
    }
    console.log('[store_type] Fetching devices from:', url);
    console.log('[store_type] Filtering by device type:', deviceType);

    const r = await apiGet(url);
    console.log('[store_type] Raw response from deviceInfos:', r);

    const data = r.data || [];
    console.log('[store_type] Extracted device data count:', data.length);

    if (data.length > 0) {
        const deviceTypes = data.map(d => d.type).filter((v, i, a) => a.indexOf(v) === i);
        console.log('[store_type] Device types in response:', deviceTypes);
        console.log('[store_type] Expected type:', deviceType);

        const allMatchExpected = data.every(d => d.type === deviceType);
        if (!allMatchExpected) {
            console.warn('[store_type] WARNING: Response contains devices of different types!');
            console.warn('[store_type] This means the API is not filtering by type parameter.');
            console.warn('[store_type] Devices will be filtered client-side.');
        }
    }

    return data
        .filter(x => x.type === deviceType)
        .map(x => ({
            id: (x.id && (x.id.id || x.id)) || x.id,
            name: x.name || x.label || x.deviceName || '(unnamed)',
            type: x.type
        }));
}

// ===== localStorage helpers =====
const STORAGE_KEY = 'store_type_selection';

function saveSelection(type, deviceId, deviceName, mode) {
    try {
        const selection = {
            deviceType: type,
            deviceId: deviceId,
            deviceName: deviceName,
            mode: mode,
            timestamp: Date.now()
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(selection));
        console.log('[store_type] 💾 Saved to localStorage:', selection);
    } catch (e) {
        console.warn('[store_type] Failed to save to localStorage:', e);
    }
}

function restoreSelection() {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            const selection = JSON.parse(saved);
            console.log('[store_type] 📦 Restored from localStorage:', selection);
            return selection;
        }
    } catch (e) {
        console.warn('[store_type] Failed to restore from localStorage:', e);
    }
    return null;
}

function persistSelection() {
    const selectedType = self.typeSelect.value;
    const selectedDeviceId = self.deviceSelect.value;
    const selectedDeviceName =
        self.deviceSelect.options[self.deviceSelect.selectedIndex]?.text || '';

    console.log('[store_type] 🔍 persistSelection called:', {
        type: selectedType,
        deviceId: selectedDeviceId,
        deviceName: selectedDeviceName,
        deviceIdIsEmpty: selectedDeviceId === '',
        deviceIdIsAll: selectedDeviceId === '__ALL__'
    });

    if (!self.ctx || !self.ctx.stateController) {
        console.error('[store_type] ❌ stateController not available');
        return;
    }

    try {
        // Note: selectedDeviceType is already included in the 'default' state params below
        // No need to update it separately to avoid multiple state change events

        // ========= ALL DEVICES =========
        if (selectedDeviceId === '__ALL__') {
            console.log('[store_type] 📋 All devices selected for type:', selectedType);

            const devices = self.currentDevices || [];
            const entityList = devices.map(d => ({
                entityType: 'DEVICE',
                id: d.id
            }));

            // ✅ ALL params in ONE object for 'default' state
            // For ALL mode, we include both entity list AND custom params
            const stateParams = {
                // For timeseries widgets - multiple formats for compatibility
                entities: entityList,
                entityIds: entityList, // Array format for entity alias
                entityId: entityList.length > 0 ? { entityType: 'DEVICE', id: entityList[0].id } : null,

                // Entity info (first entity as fallback, or empty)
                entityType: 'DEVICE',
                id: entityList.length > 0 ? entityList[0].id : null,

                // Custom params (for static widgets - read via getStateParams())
                selectedDeviceMode: 'ALL',
                selectedDeviceType: selectedType,
                selectedDeviceId: '__ALL__',
                selectedDeviceName: selectedDeviceName,

                // Additional info
                name: selectedDeviceName,
                label: selectedDeviceName,
                type: selectedType,
                mode: 'ALL',
                count: entityList.length
            };

            console.log('[store_type] 🔄 Updating current state with ALL params (ALL mode):', stateParams);

            // ✅ Single updateState call with ALL params (null = current state)
            self.ctx.stateController.updateState(null, stateParams, true);

            self.selected = {
                deviceType: selectedType,
                deviceId: '__ALL__',
                deviceName: selectedDeviceName,
                mode: 'ALL',
                count: entityList.length
            };

            // ✅ Save to localStorage for cross-state sync
            saveSelection(selectedType, '__ALL__', selectedDeviceName, 'ALL');

            console.log('[store_type] ✅ All devices mode activated');

            return;
        }

        // ========= SINGLE DEVICE =========
        if (selectedDeviceId) {
            console.log('[store_type] ➡️ Entering SINGLE device block');

            // ✅ ALL params in ONE object for 'default' state
            // - entityType + id + entityId: Required for timeseries widgets (entity alias binding)
            // - selectedDeviceMode/Id/Name/Type: Required for static widgets (via getStateParams())
            const stateParams = {
                // Entity info (for timeseries widgets - entity alias may look for these in different formats)
                entityType: 'DEVICE',
                id: selectedDeviceId,
                entityId: { entityType: 'DEVICE', id: selectedDeviceId }, // Nested format for entity alias
                name: selectedDeviceName,
                label: selectedDeviceName,

                // Custom params (for static widgets - read via getStateParams())
                selectedDeviceMode: 'SINGLE',
                selectedDeviceType: selectedType,
                selectedDeviceId: selectedDeviceId,
                selectedDeviceName: selectedDeviceName,

                // Mode shorthand
                mode: 'SINGLE',
                type: selectedType
            };

            console.log('[store_type] 🔄 Updating current state with ALL params:', stateParams);

            // ✅ Single updateState call with ALL params (null = current state)
            // getStateParams() returns this object, so both widget types can read it
            self.ctx.stateController.updateState(null, stateParams, true);

            // Update internal state
            self.selected = {
                deviceType: selectedType,
                deviceId: selectedDeviceId,
                deviceName: selectedDeviceName,
                entity: { entityType: 'DEVICE', id: selectedDeviceId },
                mode: 'SINGLE'
            };

            // ✅ Save to localStorage for cross-state sync
            saveSelection(selectedType, selectedDeviceId, selectedDeviceName, 'SINGLE');

            console.log('[store_type] ✅ Single device mode activated');
            return;
        } else {
            console.warn('[store_type] ⚠️ selectedDeviceId is empty or null');
        }



        // ========= NO SELECTION =========
        console.warn('[store_type] No device selected. Clearing related states.');

        // ✅ ALL params in ONE object - set to null/NONE for clearing
        const stateParams = {
            entityType: null,
            id: null,
            name: null,
            label: null,
            entities: null,

            selectedDeviceMode: 'NONE',
            selectedDeviceType: selectedType || null,
            selectedDeviceId: null,
            selectedDeviceName: null,

            mode: 'NONE',
            type: selectedType || null,
            count: 0
        };

        console.log('[store_type] 🔄 Updating current state with NONE params');
        self.ctx.stateController.updateState(null, stateParams, true);

        self.selected = null;

        // ✅ Clear localStorage
        localStorage.removeItem(STORAGE_KEY);
        console.log('[store_type] 🗑️ Cleared localStorage');

    } catch (e) {
        console.error('[store_type] Error updating state:', e);
    }
}



/** boilerplate */
self.onDestroy = function () { };
self.onDataUpdated = function () { };
self.onResize = function () { };

