descriptor.controllerScript:
self.onInit = function () {
    self.ctx.ngZone.run(function () {
        // Initialize scope variables
        self.ctx.$scope.isLoadingDeviceLabel = true;
        self.ctx.$scope.deviceLabel = '';
        self.ctx.$scope.isTabletDevice = false;
        self.ctx.$scope.isEdgeDevice = false;

        // Tablet widget variables
        self.ctx.$scope.form = {
            threshold: undefined,
            is_camera_uvc: false,
            is_rtsp_camera: true,
            is_live_camera: false,
            url_rtsp_camera: '',
            url_rtsp_device: ''
        };

        // Edge widget variables
        self.ctx.$scope.cameraConfigs = [];
        self.ctx.$scope.selectedCameraId = null;
        self.ctx.$scope.selectedCamera = null;
        self.ctx.$scope.isAddingNewCamera = false;
        self.ctx.$scope.newCamera = {
            id: '',
            url: '',
            mode: '',
            fps: 10,
            width: 1440,
            height: 810
        };

        init();

        self.ctx.detectChanges();
    });
};

function init() {
    const s = self.ctx.settings || {};
    const scope = self.ctx.$scope;
    const $i = scope.$injector;

    // === Services ===
    const attributeService = $i.get(self.ctx.servicesMap.get('attributeService'));

    // ✅ Save to self so loadDeviceFromState can access them
    self.attributeService = attributeService;
    self.scope = scope;

    // === UI config ===
    scope.title = s.title || 'Statistic Configuration';
    scope.showTitle = !!(s.title && s.title.length);
    scope.buttonLabel = s.buttonText || 'Update';
    scope.statusMsg = '';
    scope.error = '';
    scope.saving = false;
    scope.updateDisabled = true;

    scope.styleButton = s.styleButton || { isPrimary: true, isRaised: true };
    scope.customStyle = (scope.styleButton.isPrimary === false)
        ? {
            'background-color': scope.styleButton.bgColor || '#e0e0e0',
            'color': scope.styleButton.textColor || '#000'
        }
        : {};

    // Current device info - save to self for cross-function access
    self.currentDeviceId = null;
    self.currentDeviceName = null;

    // Tablet widget variables
    let preservedPoints = null;
    const emptyForm = {
        threshold: undefined,
        is_camera_uvc: false,
        is_rtsp_camera: true,
        is_live_camera: false,
        url_rtsp_camera: '',
        url_rtsp_device: ''
    };

    // Edge widget variables
    const emptyCameraConfig = {
        id: '',
        url: '',
        mode: '',
        fps: 10,
        width: 1440,
        height: 810
    };

    // ===== Update button disabled state =====
    function updateUpdateDisabledState() {
        // Disable update if no device selected or in ALL mode
        scope.updateDisabled = !self.currentDeviceId || self.currentDeviceId === '__ALL__';
    }

    // ===== Get Device from Dashboard State (Priority) or Datasource =====
    function getDeviceFromDatasource() {
        try {
            // ✅ PRIORITY: Check dashboard state from store_type widget first
            if (self.ctx.stateController) {
                const stateParams = self.ctx.stateController.getStateParams();
                const deviceMode = stateParams?.selectedDeviceMode;
                const selectedDeviceId = stateParams?.selectedDeviceId;
                const selectedDeviceName = stateParams?.selectedDeviceName;
                const deviceCount = stateParams?.selectedEntity?.count;

                // console.log('[statistic_config_merge] Dashboard State:', {
                //    mode: deviceMode,
                //    deviceId: selectedDeviceId,
                //    deviceName: selectedDeviceName,
                //    count: deviceCount
                //});

                // Handle "All devices" mode
                if (deviceMode === 'ALL') {
                    // console.log('[statistic_config_merge] ✅ All devices mode - no label needed');
                    return {
                        id: '__ALL__',
                        name: selectedDeviceName || 'All devices',
                        type: 'DEVICE',
                        mode: 'ALL',
                        count: deviceCount || 0
                    };
                }

                // Handle single device mode from dashboard state
                if (deviceMode === 'SINGLE' && selectedDeviceId && selectedDeviceId !== '__ALL__') {
                    // console.log('[statistic_config_merge] ✅ Single device from state:', selectedDeviceId);
                    return {
                        id: selectedDeviceId,
                        name: selectedDeviceName || 'Device',
                        type: 'DEVICE',
                        mode: 'SINGLE'
                    };
                }
            }

            // Fallback: Try to get from defaultSubscription
            if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.targetDeviceId) {
                const deviceId = self.ctx.defaultSubscription.targetDeviceId;
                const deviceName = self.ctx.defaultSubscription.targetDeviceName || 'Device';
                // console.log('[statistic_config_merge] ℹ️ Device from defaultSubscription:', deviceId);
                return {
                    id: deviceId,
                    name: deviceName,
                    type: 'DEVICE'
                };
            }

            // Fallback: Try to get from datasources (old logic)
            const datasources = self.ctx.datasources;
            const deviceMap = new Map();

            if (datasources && datasources.length > 0) {
                datasources.forEach(function (datasource) {
                    if (datasource.type === 'entity' && datasource.entityType === 'DEVICE') {
                        const deviceId = datasource.entityId;
                        const deviceName = datasource.entityName || datasource.name || 'Unknown Device';

                        if (deviceId && !deviceMap.has(deviceId)) {
                            deviceMap.set(deviceId, {
                                id: deviceId,
                                name: deviceName,
                                type: datasource.entityType
                            });
                        }
                    } else if (datasource.entityFilter) {
                        if (datasource.dataKeys && datasource.dataKeys.length > 0) {
                            datasource.dataKeys.forEach(function (dataKey) {
                                if (dataKey.settings && dataKey.settings.entity) {
                                    const deviceId = dataKey.settings.entity.id;
                                    const deviceName = dataKey.settings.entity.name || dataKey.name || 'Unknown Device';

                                    if (deviceId && !deviceMap.has(deviceId)) {
                                        deviceMap.set(deviceId, {
                                            id: deviceId,
                                            name: deviceName,
                                            type: 'DEVICE'
                                        });
                                    }
                                }
                            });
                        }
                    }
                });

                if (self.ctx.data && self.ctx.data.length > 0) {
                    self.ctx.data.forEach(function (data) {
                        if (data.datasource && data.datasource.entityId && data.datasource.entityType === 'DEVICE') {
                            const deviceId = data.datasource.entityId;
                            const deviceName = data.datasource.entityName || data.datasource.name || 'Unknown Device';

                            if (deviceId && !deviceMap.has(deviceId)) {
                                deviceMap.set(deviceId, {
                                    id: deviceId,
                                    name: deviceName,
                                    type: 'DEVICE'
                                });
                            }
                        }
                    });
                }
            }

            const devices = Array.from(deviceMap.values());
            if (devices.length === 0) {
                // console.log('[statistic_config_merge] ⚠️ No device found in any source');
                return null;
            }

            // console.log('[statistic_config_merge] ℹ️ Device from datasource:', devices[0].id);
            return devices[0];

        } catch (error) {
            // console.error('[statistic_config_merge] Error in getDeviceFromDatasource:', error);
            return null;
        }
    }

    // ===== Load deviceLabel and determine widget type =====
    function loadDeviceLabel(deviceId, deviceInfo) {
        const scope = self.scope;
        const attributeService = self.attributeService;

        // console.log('[statistic_config_merge] 🔍 loadDeviceLabel called:', {
        //  deviceId: deviceId,
        //  hasScope: !!scope,
        //  hasAttributeService: !!attributeService,
        //   deviceInfo: deviceInfo
        //});

        if (!scope || !attributeService) {
            // console.error('[statistic_config_merge] ❌ Missing dependencies:', {
            //scope: !!scope,
            //  attributeService: !!attributeService
            //});
            return;
        }

        if (!deviceId) {
            // console.warn('[statistic_config_merge] ⚠️ No deviceId provided');
            scope.isLoadingDeviceLabel = false;
            scope.error = '⚠ No device found. Please configure device in widget datasource or dashboard entity selection.';
            self.ctx.detectChanges();
            return;
        }

        // ✅ Strict State Check: Ensure we match the current dashboard state
        if (self.ctx.stateController) {
            const stateParams = self.ctx.stateController.getStateParams();
            const currentMode = stateParams?.selectedDeviceMode;

            // If Dashboard is in ALL mode, force widget to ALL mode
            if (currentMode === 'ALL') {
                deviceId = '__ALL__';
            }
            // If Dashboard is in SINGLE mode, but we somehow got ALL (mismatch), stop to avoid showing ALL view
            else if (currentMode === 'SINGLE' && deviceId === '__ALL__') {
                scope.isLoadingDeviceLabel = false;
                scope.statusMsg = 'Please select a device';
                scope.error = '';
                updateUpdateDisabledState();
                self.ctx.detectChanges();
                return;
            }
        }

        // ✅ Handle "All devices" mode - keep current form but disable buttons
        if (deviceId === '__ALL__') {
            scope.isLoadingDeviceLabel = false;
            // If no device type is set yet, default to Tablet
            if (!scope.isTabletDevice && !scope.isEdgeDevice) {
                scope.isTabletDevice = true;
                scope.isEdgeDevice = false;
                scope.form = { ...emptyForm };
            }
            // DON'T reset isTabletDevice or isEdgeDevice - keep current form visible
            scope.error = ''; // Clear error
            const count = deviceInfo?.count || 0;
            scope.statusMsg = `⚠️ Cannot update Statistic App Config in "All Devices". Please select a single device.`;
            updateUpdateDisabledState();
            // console.log('[statistic_config_merge] ✅ All devices mode - keeping current form with disabled buttons');
            self.ctx.detectChanges();
            return;
        }

        // ✅ Clear previous status/error to prevent scope overlap
        scope.statusMsg = '';
        scope.error = '';

        scope.isLoadingDeviceLabel = true;
        self.ctx.detectChanges();

        const eid = { entityType: 'DEVICE', id: deviceId };

        // console.log('[statistic_config_merge] 📡 Calling getEntityAttributes for device:', deviceId);

        // Load deviceLabel from SERVER_SCOPE attributes
        attributeService.getEntityAttributes(eid, 'SERVER_SCOPE', ['deviceLabel']).subscribe(
            function success(resp) {
                // console.log('[statistic_config_merge] ✅ Received deviceLabel response:', resp);

                if (resp && resp.length > 0 && resp[0].value) {
                    scope.deviceLabel = resp[0].value;
                    // console.log('[statistic_config_merge] ✅ deviceLabel value:', scope.deviceLabel);

                    // Case-insensitive comparison
                    const labelLower = scope.deviceLabel.toLowerCase().trim();

                    if (labelLower === 'tablet-type') {
                        // console.log('[statistic_config_merge] ✅ Detected Tablet device');
                        scope.isTabletDevice = true;
                        scope.isEdgeDevice = false;
                        // Load tablet widget config
                        loadTabletConfig(deviceId);

                        // Clear Edge config to ensure strict scope isolation
                        scope.cameraConfigs = [];
                        scope.selectedCameraId = null;
                        scope.selectedCamera = null;
                        scope.newCamera = { ...emptyCameraConfig };
                        scope.isAddingNewCamera = false;
                    } else if (labelLower === 'edge-type') {
                        // console.log('[statistic_config_merge] ✅ Detected Edge device');
                        scope.isTabletDevice = false;
                        scope.isEdgeDevice = true;
                        // Load edge widget config
                        loadEdgeConfig(deviceId);

                        // Clear Tablet config to ensure strict scope isolation
                        scope.form = { ...emptyForm };
                        preservedPoints = null;
                    } else {
                        // Unknown device type
                        // console.warn('[statistic_config_merge] ⚠️ Unknown deviceLabel:', scope.deviceLabel);
                        scope.isTabletDevice = false;
                        scope.isEdgeDevice = false;
                        scope.isLoadingDeviceLabel = false;
                    }
                } else {
                    // No deviceLabel found
                    // console.warn('[statistic_config_merge] ⚠️ No deviceLabel found in response');
                    scope.deviceLabel = '';
                    scope.isTabletDevice = false;
                    scope.isEdgeDevice = false;
                    scope.isLoadingDeviceLabel = false;
                    scope.error = '⚠ deviceLabel not found in server attributes';
                }
                self.ctx.detectChanges();
            },
            function fail(error) {
                // console.error('[statistic_config_merge] ❌ Failed to load deviceLabel:', error);
                scope.isLoadingDeviceLabel = false;
                scope.error = '⚠ Failed to load deviceLabel: ' + (error.message || 'Unknown error');
                self.ctx.detectChanges();
            }
        );
    }

    // ===== Load Tablet Config (from statistic_config widget) =====
    function loadTabletConfig(deviceId) {
        const eid = { entityType: 'DEVICE', id: deviceId };
        const keyName = s.keyName || 'statistic_config';

        attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
            function success(resp) {
                if (resp && resp.length > 0 && resp[0].value) {
                    try {
                        const json = JSON.parse(resp[0].value);

                        // Preserve points field if it exists
                        if (json.points && Array.isArray(json.points)) {
                            preservedPoints = json.points;
                        } else {
                            preservedPoints = null;
                        }

                        scope.form = { ...emptyForm, ...json };
                        delete scope.form.points;

                        // Convert boolean fields to string for dropdown
                        if (scope.form.is_camera_uvc === true || scope.form.is_camera_uvc === 'true') {
                            scope.form.is_camera_uvc = 'true';
                        } else {
                            scope.form.is_camera_uvc = 'false';
                        }

                        if (scope.form.is_rtsp_camera === true || scope.form.is_rtsp_camera === 'true') {
                            scope.form.is_rtsp_camera = 'true';
                        } else {
                            scope.form.is_rtsp_camera = 'false';
                        }

                        // Ensure is_camera_uvc and is_rtsp_camera are always opposite
                        if (scope.form.is_camera_uvc === 'true') {
                            scope.form.is_rtsp_camera = 'false';
                        } else {
                            scope.form.is_rtsp_camera = 'true';
                        }

                        if (scope.form.is_live_camera === true || scope.form.is_live_camera === 'true') {
                            scope.form.is_live_camera = 'true';
                        } else {
                            scope.form.is_live_camera = 'false';
                        }

                        const urlRtspDevice = (scope.form.url_rtsp_device || '').trim();
                        if (!urlRtspDevice || urlRtspDevice.length === 0) {
                            scope.form.is_live_camera = 'false';
                        }

                        if (scope.form.threshold !== undefined && scope.form.threshold !== null) {
                            if (typeof scope.form.threshold === 'string') {
                                const parsed = parseFloat(scope.form.threshold);
                                scope.form.threshold = isNaN(parsed) ? undefined : parsed;
                            } else if (typeof scope.form.threshold !== 'number') {
                                scope.form.threshold = undefined;
                            }
                        }

                        scope.statusMsg = '✅ Tablet config loaded';
                    } catch (e) {
                        scope.form = { ...emptyForm };
                        preservedPoints = null;
                        scope.error = '⚠ Failed to parse config';
                    }
                } else {
                    scope.form = { ...emptyForm };
                    preservedPoints = null;
                    scope.statusMsg = 'ℹ No config found for this device';
                }

                scope.isLoadingDeviceLabel = false;
                updateUpdateDisabledState();
                self.ctx.detectChanges();

                // Clear status message after 2 seconds
                setTimeout(function () {
                    self.ctx.ngZone.run(function () {
                        scope.statusMsg = '';
                        self.ctx.detectChanges();
                    });
                }, 2000);
            },
            function fail(error) {
                scope.form = { ...emptyForm };
                preservedPoints = null;
                scope.isLoadingDeviceLabel = false;
                scope.error = '⚠ Failed to load config: ' + (error.message || 'Unknown error');
                self.ctx.detectChanges();
            }
        );
    }

    // ===== Load Edge Config (from statistic_config_edge widget) =====
    function loadEdgeConfig(deviceId) {
        const eid = { entityType: 'DEVICE', id: deviceId };
        const keyName = s.keyName || 'statistic_config';

        attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
            function success(resp) {
                if (resp && resp.length > 0 && resp[0].value) {
                    try {
                        let json = resp[0].value;

                        if (typeof json === 'string') {
                            json = JSON.parse(json);
                        }
                        if (typeof json === 'string') {
                            json = JSON.parse(json);
                        }

                        if (Array.isArray(json)) {
                            scope.cameraConfigs = json.map(function (config) {
                                return {
                                    id: config.id || '',
                                    url: config.url || '',
                                    mode: config.mode || '',
                                    fps: config.fps || 10,
                                    width: config.width || 1440,
                                    height: config.height || 810,
                                    point: Array.isArray(config.point) ? config.point : [0, 0, 0, 0]
                                };
                            });

                            if (scope.cameraConfigs.length > 0 && !scope.isAddingNewCamera) {
                                scope.selectedCameraId = scope.cameraConfigs[0].id;
                                scope.selectedCamera = { ...scope.cameraConfigs[0] };
                            }

                            scope.statusMsg = '✅ Loaded ' + scope.cameraConfigs.length + ' camera configuration(s)';
                        } else {
                            scope.cameraConfigs = [];
                            scope.error = '⚠ statistic_config is not an array';
                        }
                    } catch (e) {
                        scope.cameraConfigs = [];
                        scope.error = '⚠ Failed to parse statistic_config: ' + e.message;
                    }
                } else {
                    scope.cameraConfigs = [];
                    scope.statusMsg = 'ℹ No camera configurations found for this device';
                }

                scope.isLoadingDeviceLabel = false;
                updateUpdateDisabledState();
                self.ctx.detectChanges();

                // Clear status message after 2 seconds
                setTimeout(function () {
                    self.ctx.ngZone.run(function () {
                        scope.statusMsg = '';
                        self.ctx.detectChanges();
                    });
                }, 2000);
            },
            function fail(error) {
                scope.cameraConfigs = [];
                scope.isLoadingDeviceLabel = false;
                scope.error = '⚠ Failed to load camera configurations: ' + (error.message || 'Unknown error');
                self.ctx.detectChanges();
            }
        );
    }

    // ===== Load device from dashboard state (NO datasource dependency) =====
    function loadDeviceFromState() {
        // console.log('[statistic_config_merge] 🔄 Loading device from dashboard state...');

        const scope = self.scope;
        if (!scope) {
            // console.error('[statistic_config_merge] ❌ Scope not initialized yet');
            return;
        }

        if (!self.ctx.stateController) {
            // console.warn('[statistic_config_merge] ⚠️ No stateController available');
            scope.isLoadingDeviceLabel = false;
            scope.error = '⚠ Dashboard state controller not available';
            self.ctx.detectChanges();
            return;
        }

        // Always fetch latest params from controller
        const stateParams = self.ctx.stateController.getStateParams();

        const deviceMode = stateParams?.selectedDeviceMode;
        const selectedDeviceId = stateParams?.selectedDeviceId;
        const selectedDeviceName = stateParams?.selectedDeviceName;
        const deviceCount = stateParams?.selectedEntity?.count;

        // console.log('[statistic_config_merge] 📊 Dashboard State:', {
        //  mode: deviceMode,
        //  deviceId: selectedDeviceId,
        //  deviceName: selectedDeviceName,
        //    count: deviceCount
        //});

        // ✅ Handle undefined/null state (store_type hasn't set state yet)
        if (!deviceMode || deviceMode === 'NONE') {
            // console.log('[statistic_config_merge] ℹ️ No device mode set yet - waiting for store_type widget');
            scope.isLoadingDeviceLabel = false;
            scope.deviceLabel = '';
            scope.isTabletDevice = false;
            scope.isEdgeDevice = false;
            scope.error = '';
            scope.statusMsg = 'Please select a device from the Store/Device selector';
            self.currentDeviceId = null;
            self.currentDeviceName = null;
            updateUpdateDisabledState();
            self.ctx.detectChanges();
            return;
        }

        // Handle "All devices" mode
        if (deviceMode === 'ALL') {
            // console.log('[statistic_config_merge] ✅ All devices mode - keeping current form with disabled buttons');
            scope.isLoadingDeviceLabel = false;
            // If no device type is set yet, default to Tablet
            if (!scope.isTabletDevice && !scope.isEdgeDevice) {
                scope.isTabletDevice = true;
                scope.isEdgeDevice = false;
                scope.form = { ...emptyForm };
            }
            // DON'T reset isTabletDevice or isEdgeDevice - keep current form visible
            scope.error = '';
            scope.statusMsg = `⚠️ Cannot update Statistic App Config in "All Devices". Please select a single device.`;
            self.currentDeviceId = '__ALL__';
            self.currentDeviceName = selectedDeviceName || 'All devices';
            updateUpdateDisabledState();
            self.ctx.detectChanges();
            return;
        }

        // Handle single device mode
        if (deviceMode === 'SINGLE' && selectedDeviceId && selectedDeviceId !== '__ALL__') {
            // console.log('[statistic_config_merge] ✅ Single device mode:', selectedDeviceId);
            self.currentDeviceId = selectedDeviceId;
            self.currentDeviceName = selectedDeviceName || 'Device';
            loadDeviceLabel(selectedDeviceId, {
                id: selectedDeviceId,
                name: selectedDeviceName,
                mode: 'SINGLE'
            });
            return;
        }

        // No valid state found
        // console.log('[statistic_config_merge] ℹ️ No valid device state found');
        scope.isLoadingDeviceLabel = false;
        scope.error = '';
        scope.statusMsg = 'Please select a device from the Store/Device selector';
        self.currentDeviceId = null;
        self.currentDeviceName = null;
        updateUpdateDisabledState();
        self.ctx.detectChanges();
    }

    // ✅ Save reference to self so it can be accessed from subscription
    self.loadDeviceFromState = loadDeviceFromState;

    // ✅ Verify all dependencies before setup
    // console.log('[statistic_config_merge] 🔍 Dependencies check:', {
    //   hasScope: !!self.scope,
    //   hasAttributeService: !!self.attributeService,
    //   hasStateController: !!self.ctx.stateController
    //});

    // ✅ Setup state change listener AFTER loadDeviceFromState is defined
    if (self.ctx.stateController) {
        // console.log('[statistic_config_merge] ✅ Setting up dashboard state listener');

        // Subscribe to state changes with DEBOUNCE
        let stateChangeTimeout;
        self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
            // console.log('[statistic_config_merge] 📡 Dashboard state changed event received');

            if (stateChangeTimeout) {
                clearTimeout(stateChangeTimeout);
            }

            stateChangeTimeout = setTimeout(function () {
                // console.log('[statistic_config_merge] ⏳ Debounce complete, reloading device...');
                self.ctx.ngZone.run(function () {
                    if (self.loadDeviceFromState) {
                        self.loadDeviceFromState();
                    } else {
                        // console.error('[statistic_config_merge] ❌ loadDeviceFromState not found!');
                    }
                });
            }, 200); // Wait 200ms for all state updates to settle
        });
    } else {
        // console.warn('[statistic_config_merge] ⚠️ No stateController available for subscription');
    }

    // Load device from state on init with retry
    let retryCount = 0;
    function tryLoad() {
        if (self.scope && self.attributeService) {
            // console.log('[statistic_config_merge] ✅ Dependencies ready, loading device');
            loadDeviceFromState();
        } else {
            retryCount++;
            if (retryCount < 3) {
                // console.warn('[statistic_config_merge] ⚠️ Retry', retryCount, '- dependencies not ready');
                setTimeout(tryLoad, 200);
            } else {
                // console.error('[statistic_config_merge] ❌ Failed after 3 retries');
            }
        }
    }
    setTimeout(tryLoad, 300);

    // onDataUpdated - not needed since we listen to state changes
    self.onDataUpdated = function () {
        // Widget now listens to dashboard state changes instead of datasource updates
        // State changes are handled by the stateChanged() subscription in onInit
    };

    // ===== TABLET WIDGET FUNCTIONS =====

    scope.onCameraUvcChange = function (event) {
        self.ctx.ngZone.run(function () {
            var newValue = null;
            if (event) {
                if (event.value !== undefined) {
                    newValue = event.value;
                } else if (event.source && event.source.value !== undefined) {
                    newValue = event.source.value;
                }
            }

            if (newValue === null || newValue === undefined) {
                newValue = scope.form.is_camera_uvc;
            }

            if (newValue === true) newValue = 'true';
            if (newValue === false) newValue = 'false';
            if (newValue !== 'true' && newValue !== 'false') {
                newValue = 'false';
            }

            scope.form.is_camera_uvc = newValue;

            if (newValue === 'true') {
                scope.form.is_rtsp_camera = 'false';
            } else {
                scope.form.is_rtsp_camera = 'true';
            }

            self.ctx.detectChanges();
        });
    };

    scope.onRtspCameraChange = function (event) {
        self.ctx.ngZone.run(function () {
            var newValue = null;
            if (event) {
                if (event.value !== undefined) {
                    newValue = event.value;
                } else if (event.source && event.source.value !== undefined) {
                    newValue = event.source.value;
                }
            }

            if (newValue === null || newValue === undefined) {
                newValue = scope.form.is_rtsp_camera;
            }

            if (newValue === true) newValue = 'true';
            if (newValue === false) newValue = 'false';
            if (newValue !== 'true' && newValue !== 'false') {
                newValue = 'false';
            }

            scope.form.is_rtsp_camera = newValue;

            if (newValue === 'true') {
                scope.form.is_camera_uvc = 'false';
            } else {
                scope.form.is_camera_uvc = 'true';
            }

            self.ctx.detectChanges();
        });
    };

    scope.shouldShowUrlRtspHint = function () {
        const isLiveCamera = scope.form.is_live_camera === 'true' || scope.form.is_live_camera === true;
        const urlRtspCamera = (scope.form.url_rtsp_camera || '').trim();
        return isLiveCamera && !urlRtspCamera;
    };

    scope.isLiveCameraEnabled = function () {
        const urlRtspDevice = (scope.form.url_rtsp_device || '').trim();
        return urlRtspDevice.length > 0;
    };

    scope.onUrlRtspDeviceChange = function () {
        self.ctx.ngZone.run(function () {
            const urlRtspDevice = (scope.form.url_rtsp_device || '').trim();

            if (!urlRtspDevice || urlRtspDevice.length === 0) {
                scope.form.is_live_camera = 'false';
            }

            self.ctx.detectChanges();
        });
    };

    scope.clearAll = function () {
        if (!confirm('Are you sure you want to clear all configurations?')) {
            return;
        }

        if (!self.currentDeviceId || self.currentDeviceId === '__ALL__') {
            return;
        }

        scope.saving = true;
        scope.statusMsg = 'Clearing...';
        scope.error = '';

        const eid = { entityType: 'DEVICE', id: self.currentDeviceId };
        const keyName = s.keyName || 'statistic_config';
        const attributeData = [{
            key: keyName,
            value: JSON.stringify({})
        }];

        attributeService.saveEntityAttributes(eid, 'SHARED_SCOPE', attributeData).subscribe(
            function success() {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '✅ Cleared successfully!';
                    scope.error = '';
                    scope.form = { ...emptyForm };
                    preservedPoints = null;
                    self.ctx.detectChanges();
                });
            },
            function fail(error) {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '';
                    scope.error = '⚠ Clear failed: ' + (error.message || 'Unknown error');
                    self.ctx.detectChanges();
                });
            }
        );
    };

    scope.save = function () {
        scope.statusMsg = '';
        scope.error = '';

        if (!self.currentDeviceId || self.currentDeviceId === '__ALL__') {
            scope.error = '⚠ No device selected. Please select a specific device.';
            self.ctx.detectChanges();
            return;
        }

        const isLiveCamera = scope.form.is_live_camera === 'true' || scope.form.is_live_camera === true;
        const urlRtspCamera = (scope.form.url_rtsp_camera || '').trim();

        if (isLiveCamera && !urlRtspCamera) {
            scope.error = '⚠ url_rtsp_camera is required when is_live_camera is true';
            scope.statusMsg = '';
            self.ctx.detectChanges();
            return;
        }

        scope.saving = true;

        let thresholdValue = undefined;
        if (scope.form.threshold !== undefined && scope.form.threshold !== null) {
            if (typeof scope.form.threshold === 'number') {
                thresholdValue = scope.form.threshold;
            } else if (typeof scope.form.threshold === 'string') {
                const parsed = parseFloat(scope.form.threshold);
                thresholdValue = isNaN(parsed) ? undefined : parsed;
            }
        }

        const urlRtspDevice = (scope.form.url_rtsp_device || '').trim();
        let isLiveCameraValue = false;

        if (urlRtspDevice && urlRtspDevice.length > 0) {
            isLiveCameraValue = scope.form.is_live_camera === 'true' || scope.form.is_live_camera === true;
        } else {
            isLiveCameraValue = false;
        }

        const formData = {
            threshold: thresholdValue,
            is_camera_uvc: scope.form.is_camera_uvc === 'true' || scope.form.is_camera_uvc === true,
            is_rtsp_camera: scope.form.is_rtsp_camera === 'true' || scope.form.is_rtsp_camera === true,
            is_live_camera: isLiveCameraValue,
            url_rtsp_camera: scope.form.url_rtsp_camera || '',
            url_rtsp_device: scope.form.url_rtsp_device || ''
        };

        if (preservedPoints && Array.isArray(preservedPoints)) {
            formData.points = preservedPoints;
        } else {
            formData.points = [0, 0, 0, 0];
        }

        const eid = { entityType: 'DEVICE', id: self.currentDeviceId };
        const keyName = s.keyName || 'statistic_config';
        const attributeData = [{
            key: keyName,
            value: JSON.stringify(formData)
        }];

        attributeService.saveEntityAttributes(eid, 'SHARED_SCOPE', attributeData).subscribe(
            function success() {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '✅ Updated successfully!';
                    scope.error = '';
                    self.ctx.detectChanges();
                });
            },
            function fail(error) {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '';
                    scope.error = '⚠ Update failed: ' + (error.message || 'Unknown error');
                    self.ctx.detectChanges();
                });
            }
        );
    };

    // ===== EDGE WIDGET FUNCTIONS =====

    scope.onCameraSelect = function () {
        self.ctx.ngZone.run(function () {
            const selectedId = scope.selectedCameraId;

            if (selectedId) {
                const camera = scope.cameraConfigs.find(function (config) {
                    return config.id === selectedId;
                });

                if (camera) {
                    scope.selectedCamera = { ...camera };
                } else {
                    scope.selectedCamera = null;
                }
            } else {
                scope.selectedCamera = null;
            }

            self.ctx.detectChanges();
        });
    };

    scope.showAddCameraForm = function () {
        self.ctx.ngZone.run(function () {
            scope.isAddingNewCamera = true;
            scope.newCamera = { ...emptyCameraConfig };
            scope.statusMsg = '';
            scope.error = '';
            self.ctx.detectChanges();
        });
    };

    scope.cancelAddCamera = function () {
        self.ctx.ngZone.run(function () {
            scope.isAddingNewCamera = false;
            scope.newCamera = { ...emptyCameraConfig };
            scope.statusMsg = '';
            scope.error = '';

            if (scope.cameraConfigs.length > 0) {
                scope.selectedCameraId = scope.cameraConfigs[0].id;
                scope.selectedCamera = { ...scope.cameraConfigs[0] };
            }

            self.ctx.detectChanges();
        });
    };

    scope.saveNewCamera = function () {
        scope.statusMsg = '';
        scope.error = '';

        if (!self.currentDeviceId || self.currentDeviceId === '__ALL__') {
            scope.error = '⚠ No device selected. Please select a specific device.';
            self.ctx.detectChanges();
            return;
        }

        if (!scope.newCamera.id || scope.newCamera.id.trim() === '') {
            scope.error = '⚠ Camera ID is required';
            self.ctx.detectChanges();
            return;
        }

        if (!scope.newCamera.url || scope.newCamera.url.trim() === '') {
            scope.error = '⚠ URL is required';
            self.ctx.detectChanges();
            return;
        }

        const existingCamera = scope.cameraConfigs.find(function (config) {
            return config.id === scope.newCamera.id;
        });

        if (existingCamera) {
            scope.error = '⚠ Camera ID already exists';
            self.ctx.detectChanges();
            return;
        }

        scope.saving = true;

        const newCameraData = {
            id: scope.newCamera.id,
            url: scope.newCamera.url,
            mode: scope.newCamera.mode,
            fps: parseInt(scope.newCamera.fps) || 10,
            width: parseInt(scope.newCamera.width) || 1440,
            height: parseInt(scope.newCamera.height) || 810,
            point: [0, 0, 0, 0]
        };

        const updatedConfigs = [...scope.cameraConfigs, newCameraData];

        const eid = { entityType: 'DEVICE', id: self.currentDeviceId };
        const keyName = s.keyName || 'statistic_config';
        const attributeData = [{
            key: keyName,
            value: JSON.stringify(updatedConfigs)
        }];

        attributeService.saveEntityAttributes(eid, 'SHARED_SCOPE', attributeData).subscribe(
            function success() {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '✅ Camera added successfully!';
                    scope.error = '';

                    scope.cameraConfigs = updatedConfigs;
                    scope.isAddingNewCamera = false;
                    scope.selectedCameraId = newCameraData.id;
                    scope.selectedCamera = { ...newCameraData };
                    scope.newCamera = { ...emptyCameraConfig };

                    setTimeout(function () {
                        self.ctx.ngZone.run(function () {
                            scope.statusMsg = '';
                            self.ctx.detectChanges();
                        });
                    }, 2000);

                    self.ctx.detectChanges();
                });
            },
            function fail(error) {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '';
                    scope.error = '⚠ Add failed: ' + (error.message || 'Unknown error');
                    self.ctx.detectChanges();
                });
            }
        );
    };

    scope.updateCamera = function () {
        scope.statusMsg = '';
        scope.error = '';

        if (!self.currentDeviceId || self.currentDeviceId === '__ALL__') {
            scope.error = '⚠ No device selected. Please select a specific device.';
            self.ctx.detectChanges();
            return;
        }

        if (!scope.selectedCamera) {
            scope.error = '⚠ No camera selected';
            self.ctx.detectChanges();
            return;
        }

        if (!scope.selectedCamera.url || scope.selectedCamera.url.trim() === '') {
            scope.error = '⚠ URL is required';
            self.ctx.detectChanges();
            return;
        }

        scope.saving = true;

        const existingCamera = scope.cameraConfigs.find(function (config) {
            return config.id === scope.selectedCamera.id;
        });

        const updatedCameraData = {
            id: scope.selectedCamera.id,
            url: scope.selectedCamera.url,
            mode: scope.selectedCamera.mode,
            fps: parseInt(scope.selectedCamera.fps) || 10,
            width: parseInt(scope.selectedCamera.width) || 1440,
            height: parseInt(scope.selectedCamera.height) || 810,
            point: existingCamera && existingCamera.point ? existingCamera.point : [0, 0, 0, 0]
        };

        const updatedConfigs = scope.cameraConfigs.map(function (config) {
            if (config.id === scope.selectedCamera.id) {
                return updatedCameraData;
            }
            return config;
        });

        const eid = { entityType: 'DEVICE', id: self.currentDeviceId };
        const keyName = s.keyName || 'statistic_config';
        const attributeData = [{
            key: keyName,
            value: JSON.stringify(updatedConfigs)
        }];

        attributeService.saveEntityAttributes(eid, 'SHARED_SCOPE', attributeData).subscribe(
            function success() {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '✅ Camera updated successfully!';
                    scope.error = '';

                    scope.cameraConfigs = updatedConfigs;
                    scope.selectedCamera = { ...updatedCameraData };

                    setTimeout(function () {
                        self.ctx.ngZone.run(function () {
                            scope.statusMsg = '';
                            self.ctx.detectChanges();
                        });
                    }, 2000);

                    self.ctx.detectChanges();
                });
            },
            function fail(error) {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '';
                    scope.error = '⚠ Update failed: ' + (error.message || 'Unknown error');
                    self.ctx.detectChanges();
                });
            }
        );
    };

    scope.deleteCamera = function () {
        if (!scope.selectedCamera) {
            return;
        }

        if (!self.currentDeviceId || self.currentDeviceId === '__ALL__') {
            return;
        }

        if (!confirm('Are you sure you want to delete camera "' + scope.selectedCamera.id + '"?')) {
            return;
        }

        scope.saving = true;
        scope.statusMsg = 'Deleting...';
        scope.error = '';

        const updatedConfigs = scope.cameraConfigs.filter(function (config) {
            return config.id !== scope.selectedCamera.id;
        });

        const eid = { entityType: 'DEVICE', id: self.currentDeviceId };
        const keyName = s.keyName || 'statistic_config';
        const attributeData = [{
            key: keyName,
            value: JSON.stringify(updatedConfigs)
        }];

        attributeService.saveEntityAttributes(eid, 'SHARED_SCOPE', attributeData).subscribe(
            function success() {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '✅ Camera deleted successfully!';
                    scope.error = '';

                    scope.cameraConfigs = updatedConfigs;
                    scope.selectedCameraId = null;
                    scope.selectedCamera = null;

                    if (scope.cameraConfigs.length > 0) {
                        scope.selectedCameraId = scope.cameraConfigs[0].id;
                        scope.selectedCamera = { ...scope.cameraConfigs[0] };
                    }

                    setTimeout(function () {
                        self.ctx.ngZone.run(function () {
                            scope.statusMsg = '';
                            self.ctx.detectChanges();
                        });
                    }, 2000);

                    self.ctx.detectChanges();
                });
            },
            function fail(error) {
                self.ctx.ngZone.run(function () {
                    scope.saving = false;
                    scope.statusMsg = '';
                    scope.error = '⚠ Delete failed: ' + (error.message || 'Unknown error');
                    self.ctx.detectChanges();
                });
            }
        );
    };
}

/** boilerplate */
self.onDestroy = function () {
    // Cleanup state change subscription
    if (self.stateChangeSubscription) {
        // console.log('[statistic_config_merge] 🧹 Cleaning up state subscription');
        self.stateChangeSubscription.unsubscribe();
    }
};

self.onResize = function () { };

