(function () {
    let chart = null;

    self.onInit = function () {
        if (typeof moment !== 'undefined') {
            moment.locale('en');
        }

        const canvas = self.ctx.$container[0].querySelector('#chart');
        const ctx = canvas.getContext('2d');

        chart = new Chart(ctx, {
            type: 'line',
            data: { datasets: [] },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: { duration: 800, easing: 'easeOutQuart' },
                legend: { display: true, position: 'top', labels: { usePointStyle: true, boxWidth: 3 } },
                tooltips: {
                    backgroundColor: '#FFFFFF',
                    titleFontColor: '#000000',
                    bodyFontColor: '#000000',
                    borderColor: 'rgba(0,0,0,0.15)',
                    borderWidth: 1,
                    displayColors: true,
                    intersect: false,
                    mode: 'index',
                    callbacks: {
                        title: function (items, data) {
                            const ti = items[0];
                            const ds = data.datasets[ti.datasetIndex];
                            const pt = ds && ds.data ? ds.data[ti.index] : null;
                            const ts = (pt && (pt.t || pt.x)) || ti.xLabel || ti.label;
                            const m = (typeof moment !== 'undefined') ? moment(Number(ts)) : null;
                            return m && m.isValid()
                                ? m.format('YYYY-MM-DD')
                                : (ti.label || ti.xLabel || '');
                        },
                        labelPointStyle: function () { return { PointStyle: 'true', rotation: 0 }; },
                        labelColor: function (tooltipItem, chart) {
                            const ds = chart.config.data.datasets[tooltipItem.datasetIndex];
                            const c = ds.borderColor || '#666';
                            return { borderColor: c, backgroundColor: c };
                        }
                    }
                },
                scales: {
                    xAxes: [{
                        type: 'time',
                        time: {
                            tooltipFormat: 'HH:mm',
                            displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'YYYY-MM-DD', month: 'MMM' }
                        },
                        distribution: 'linear',
                        scaleLabel: { display: true, labelString: 'Date Time' },
                        ticks: { source: 'data' },
                        offset: false
                    }],
                    yAxes: [{ scaleLabel: { display: true, labelString: 'People Count' }, ticks: { beginAtZero: true } }]
                },
                pan: { enabled: true, mode: 'x' },
                zoom: { enabled: true, mode: 'x' },
                elements: { point: { radius: 2, hoverRadius: 5, hitRadius: 6 } } // nhỏ thôi để vẫn thấy điểm thưa
            }
        });
    };

    self.onResize = function () { if (chart) chart.resize(); };
    self.onDestroy = function () { if (chart) { chart.destroy(); chart = null; } };

    self.onDataUpdated = function () {
        if (!chart) return;

        const sub = self.ctx.defaultSubscription;
        console.log('[line_chart] onDataUpdated. Subscription:', sub);
        if (sub && sub.data) {
            console.log('[line_chart] Data length:', sub.data.length);
            sub.data.forEach((d, i) => console.log(`[line_chart] Dataset ${i}:`, d.dataKey.label, 'Points:', d.data.length));
        }
        const tw = sub?.subscriptionTimewindow;

        let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
        let endTime = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

        // Day mode → dùng full day 00:00–23:59 để không cắt mất data ngoài 7–19h
        if (isDayMode(tw)) {
            const [s0, e24] = getDayWindowFull(tw);
            startTime = s0; endTime = e24;
        }

        const spanDays = (endTime && startTime) ? (endTime - startTime) / (24 * 60 * 60 * 1000) : 0;

        // Heuristic ổn định theo span:
        // - >= 300 ngày: xem như "năm" → unit 'month'
        // - >= 7 ngày và < 300: xem như "tháng" → unit 'day'
        // - <= 2 ngày: xem chi tiết theo giờ → unit 'hour'
        const isYearMode = spanDays >= 300;
        const isMonthMode = !isYearMode && spanDays > 1;
        const isHourlyGapMode = spanDays <= 1;

        const datasets = buildDatasetsFromSubscription(sub, startTime, endTime, {
            isMonthMode, isYearMode, isHourlyGapMode
        });
        chart.data.datasets = datasets;

        applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
        chart.update();
    };

    // ===== Helpers =====

    function buildDatasetsFromSubscription(subscription, startTime, endTime, opts) {
        const results = [];
        if (!subscription || !Array.isArray(subscription.data)) return results;

        const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
        const fallbackColors = ['#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12', '#16a085', '#c0392b', '#2c3e50'];

        // Map to aggregate data: KeyName -> Map<Timestamp, Value>
        const aggregatedData = new Map();
        const keyColors = new Map();

        subscription.data.forEach((dk, idx) => {
            const key = dk.dataKey || {};
            const fullLabel = key.label || key.name || `Series ${idx + 1}`;
            const color = key.color || fallbackColors[idx % fallbackColors.length];

            // Extract the actual data key name (e.g., "pass_total" from "Device Name - pass_total")
            const keyName = key.name || fullLabel.split(' - ').pop() || fullLabel;

            console.log('[line_chart] Processing:', { fullLabel, keyName, dataPoints: dk.data?.length || 0 });

            // Store color for this key name (first one wins)
            if (!keyColors.has(keyName)) {
                keyColors.set(keyName, color);
            }

            let points = (dk.data || [])
                .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
                .map(p => ({ t: Number(p[0]), y: p[1] }));

            // Normalize points to align timestamps for aggregation
            let mode = 'hour';
            if (isMonthMode) mode = 'day';
            if (isYearMode) mode = 'month';

            // Fill gaps to ensure we have points at all intervals for correct summing
            points = fillGapsWithNull(points, startTime, endTime, mode);

            // Aggregate by key name (not full label)
            if (!aggregatedData.has(keyName)) {
                aggregatedData.set(keyName, new Map());
            }
            const timeMap = aggregatedData.get(keyName);

            points.forEach(p => {
                const currentVal = timeMap.get(p.t) || 0;
                const valToAdd = (p.y !== null && p.y !== undefined) ? Number(p.y) : 0;
                timeMap.set(p.t, currentVal + valToAdd);
            });
        });

        console.log('[line_chart] Aggregated keys:', Array.from(aggregatedData.keys()));

        // Convert aggregated data back to datasets
        aggregatedData.forEach((timeMap, keyName) => {
            // Convert map to array and sort by time
            let points = Array.from(timeMap.entries())
                .map(([t, y]) => ({ t, y }))
                .sort((a, b) => a.t - b.t);

            // Stitch zero before data for visual continuity if needed
            points = stitchZeroBeforeData(points);

            const color = keyColors.get(keyName);

            console.log('[line_chart] Creating dataset:', keyName, 'Points:', points.length);

            results.push({
                label: keyName,
                data: points,
                borderColor: color,
                backgroundColor: color,
                fill: false,
                borderWidth: 5,
                lineTension: 0.3,
                spanGaps: false,
                pointRadius: 2,
                pointHitRadius: 6,
                pointHoverRadius: 5,
                pointStyle: 'circle',
                showLine: true
            });
        });

        return results;
    }

    // ===== Fill gaps =====
    // mode: 'hour' | 'day' | 'month'
    function fillGapsWithNull(data, startTime, endTime, mode) {
        if (!Array.isArray(data) || data.length === 0 || !startTime || !endTime) return data || [];

        const map = {};
        const normKey = (ms) => {
            const x = new Date(ms);
            if (mode === 'hour') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
            if (mode === 'day') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
            if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
        };

        data.forEach(p => {
            const ts = normKey(p.t);
            map[ts] = p.y;
        });

        const filled = [];

        if (mode === 'hour') {
            const STEP = 60 * 60 * 1000;
            const start = Math.floor(startTime / STEP) * STEP; // ⬅️ canh về đầu giờ
            const end = Math.ceil(endTime / STEP) * STEP;  // ⬅️ canh về cuối giờ
            for (let t = start; t <= end; t += STEP) {
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
            }
            return filled;
        }

        if (mode === 'day') {
            const DAY = 24 * 60 * 60 * 1000;
            const sDate = new Date(startTime);
            const eDate = new Date(endTime);
            const start = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate()).getTime(); // ⬅️ về 00:00
            const end = new Date(eDate.getFullYear(), eDate.getMonth(), eDate.getDate()).getTime(); // ⬅️ về 00:00
            for (let t = start; t <= end; t += DAY) {
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
            }
            return filled;
        }

        if (mode === 'month') {
            const s = new Date(startTime);
            const e = new Date(endTime);
            let cur = new Date(s.getFullYear(), s.getMonth(), 1);
            const endM = new Date(e.getFullYear(), e.getMonth(), 1);
            for (; cur.getTime() <= endM.getTime(); cur.setMonth(cur.getMonth() + 1)) {
                const t = cur.getTime();
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
            }
            return filled;
        }

        return data;
    }

    // Chèn y=0 trước một điểm non-null nếu trước đó là null (tạo “chân”)
    function stitchZeroBeforeData(points) {
        if (!Array.isArray(points) || points.length === 0) return points || [];
        const out = [];
        for (let i = 0; i < points.length; i++) {
            const curr = points[i];
            const prev = i > 0 ? points[i - 1] : null;
            if (prev && prev.y == null && curr.y != null) {
                out.push({ t: prev.t, y: 0 });
            }
            out.push(curr);
        }
        return out;
    }

    //   function applyTimeScaleForWindow(chart, startTime, endTime, opts) {
    //     const xAxis = chart.options.scales.xAxes[0];
    //     const { isMonthMode, isYearMode } = opts || {};
    //     let minMs = startTime ? Number(startTime) : undefined;
    //     let maxMs = endTime   ? Number(endTime)   : undefined;

    //     if (isMonthMode) {
    //       // chốt min/max về đầu-ngày/cuối-ngày để luôn hiện theo NGÀY
    //       const s = new Date(minMs), e = new Date(maxMs);
    //       const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 0, 0, 0, 0).getTime();
    //       const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 23, 59, 59, 999).getTime();
    //       minMs = minDay; maxMs = maxDay;
    //     }

    //     xAxis.ticks.min = minMs;
    //     xAxis.ticks.max = maxMs;
    //     xAxis.time.min  = minMs;
    //     xAxis.time.max  = maxMs;

    //     if (isYearMode) {
    //       xAxis.time.unit = 'month';
    //       xAxis.time.stepSize = 1;
    //       xAxis.time.displayFormats.month = 'MMM';
    //       xAxis.offset = true;
    //     } else if (isMonthMode) {
    //       xAxis.time.unit = 'day';
    //       xAxis.time.stepSize = 1; // mỗi ngày một vạch
    //       xAxis.time.displayFormats.day = 'MMM DD';
    //       xAxis.time.tooltipFormat = 'YYYY-MM-DD';
    //       xAxis.offset = true;
    //     } else {
    //       xAxis.time.unit = 'hour';
    //       xAxis.time.stepSize = 1;
    //       xAxis.time.displayFormats.hour = 'HH:mm';
    //       xAxis.offset = false;
    //     }
    //   }
    function applyTimeScaleForWindow(chart, startTime, endTime, opts) {
        const xAxis = chart.options.scales.xAxes[0];
        const { isMonthMode, isYearMode } = opts || {};
        let minMs = startTime ? Number(startTime) : undefined;
        let maxMs = endTime ? Number(endTime) : undefined;

        // === Nếu đang ở Day Mode → chỉ hiển thị từ 07:00–19:00 ===
        if (isDayMode(self.ctx.defaultSubscription?.subscriptionTimewindow)) {
            const s = new Date(minMs);
            const e = new Date(minMs); // dùng cùng ngày
            const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 7, 0, 0, 0).getTime();   // 07:00
            const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 19, 0, 0, 0).getTime();  // 19:00
            minMs = minDay;
            maxMs = maxDay;

            xAxis.time.unit = 'hour';
            xAxis.time.stepSize = 1;
            xAxis.time.displayFormats.hour = 'HH:mm';
            xAxis.time.tooltipFormat = 'HH:mm';
            xAxis.offset = false;
        }
        else if (isYearMode) {
            xAxis.time.unit = 'month';
            xAxis.time.stepSize = 1;
            xAxis.time.displayFormats.month = 'MMM';
            xAxis.offset = true;
        }
        else if (isMonthMode) {
            const s = new Date(minMs), e = new Date(maxMs);
            const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 0, 0, 0, 0).getTime();
            const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 23, 59, 59, 999).getTime();
            minMs = minDay; maxMs = maxDay;

            xAxis.time.unit = 'day';
            xAxis.time.stepSize = 1;
            xAxis.time.displayFormats.day = 'MMM DD';
            xAxis.time.tooltipFormat = 'YYYY-MM-DD';
            xAxis.offset = true;
        }
        else {
            xAxis.time.unit = 'hour';
            xAxis.time.stepSize = 1;
            xAxis.time.displayFormats.hour = 'HH:mm';
            xAxis.offset = false;
        }

        // Áp dụng min/max cuối cùng
        xAxis.ticks.min = minMs;
        xAxis.ticks.max = maxMs;
        xAxis.time.min = minMs;
        xAxis.time.max = maxMs;
    }


    function isDayMode(tw) {
        if (!tw) return false;
        const start = tw.minTime || tw.fixedWindow?.startTimeMs;
        const end = tw.maxTime || tw.fixedWindow?.endTimeMs;
        if (!start || !end) return false;
        const ONE_DAY = 24 * 60 * 60 * 1000;
        if (end - start > ONE_DAY + 15 * 60 * 1000) return false;
        const s = new Date(start), e = new Date(end);
        return s.getFullYear() === e.getFullYear() &&
            s.getMonth() === e.getMonth() &&
            s.getDate() === e.getDate();
    }

    // full-day window 00:00–23:59:59.999
    function getDayWindowFull(tw) {
        const ref = tw.fixedWindow?.startTimeMs || tw.minTime || Date.now();
        const d = new Date(ref);
        const y = d.getFullYear(), m = d.getMonth(), day = d.getDate();
        const start0 = new Date(y, m, day, 0, 0, 0, 0).getTime();
        const end24 = new Date(y, m, day, 23, 59, 59, 999).getTime();
        return [start0, end24];
    }
})();

