descriptor.controllerScript:
(function () {
    let chart = null;

    self.onInit = function () {
        if (typeof moment !== 'undefined') {
            moment.locale('en');
        }

        const canvas = self.ctx.$container[0].querySelector('#chart');
        const ctx = canvas.getContext('2d');

        chart = new Chart(ctx, {
            type: 'line',
            data: { datasets: [] },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: { duration: 800, easing: 'easeOutQuart' },
                legend: { display: true, position: 'top', labels: { usePointStyle: true, boxWidth: 3 } },
                tooltips: {
                    backgroundColor: '#FFFFFF',
                    titleFontColor: '#000000',
                    bodyFontColor: '#000000',
                    borderColor: 'rgba(0,0,0,0.15)',
                    borderWidth: 1,
                    displayColors: true,
                    intersect: false,
                    mode: 'index',
                    callbacks: {
                        title: function (items, data) {
                            const ti = items[0];
                            const ds = data.datasets[ti.datasetIndex];
                            const pt = ds && ds.data ? ds.data[ti.index] : null;
                            const ts = (pt && (pt.t || pt.x)) || ti.xLabel || ti.label;
                            const m = (typeof moment !== 'undefined') ? moment(Number(ts)) : null;
                            return m && m.isValid()
                                ? m.format('YYYY-MM-DD')
                                : (ti.label || ti.xLabel || '');
                        },
                        labelPointStyle: function () { return { PointStyle: 'true', rotation: 0 }; },
                        labelColor: function (tooltipItem, chart) {
                            const ds = chart.config.data.datasets[tooltipItem.datasetIndex];
                            const c = ds.borderColor || '#666';
                            return { borderColor: c, backgroundColor: c };
                        }
                    }
                },
                scales: {
                    xAxes: [{
                        type: 'time',
                        time: {
                            tooltipFormat: 'HH:mm',
                            displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'YYYY-MM-DD', month: 'MMM' }
                        },
                        distribution: 'linear',
                        scaleLabel: { display: true, labelString: 'Date Time' },
                        ticks: { source: 'data' },
                        offset: false
                    }],
                    yAxes: [{ scaleLabel: { display: true, labelString: 'People Count' }, ticks: { beginAtZero: true } }]
                },
                pan: { enabled: true, mode: 'x' },
                zoom: { enabled: true, mode: 'x' },
                elements: { point: { radius: 2, hoverRadius: 5, hitRadius: 6 } }
            }
        });

        // ✅ Subscribe to dashboard state changes to detect mode switches
        if (self.ctx.stateController) {
            let stateDebounce = null;
            self.stateSubscription = self.ctx.stateController.stateChanged().subscribe(function () {
                console.log('[line_chart] 📡 Dashboard state changed - triggering refresh');
                // Debounce state changes
                if (stateDebounce) clearTimeout(stateDebounce);
                stateDebounce = setTimeout(() => {
                    if (self.onDataUpdated) {
                        self.onDataUpdated();
                    }
                }, 200);
            });
        }
    };

    self.onResize = function () { if (chart) chart.resize(); };
    self.onDestroy = function () {
        if (self.stateSubscription) {
            self.stateSubscription.unsubscribe();
            self.stateSubscription = null;
        }
        if (chart) {
            chart.destroy();
            chart = null;
        }
    };

    // Track fetch state to prevent concurrent fetches
    let isFetchingAllDevices = false;
    let pendingUpdateTimeout = null;

    self.onDataUpdated = function () {
        if (!chart) return;

        // Debounce to prevent rapid multiple calls
        if (pendingUpdateTimeout) {
            clearTimeout(pendingUpdateTimeout);
        }

        pendingUpdateTimeout = setTimeout(() => {
            processDataUpdate();
        }, 100);
    };

    function processDataUpdate() {
        if (!chart) return;

        const sub = self.ctx.defaultSubscription;
        const tw = sub?.subscriptionTimewindow;

        let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
        let endTime = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

        // Day mode → dùng full day 00:00–23:59 để không cắt mất data ngoài 7–19h
        if (isDayMode(tw)) {
            const [s0, e24] = getDayWindowFull(tw);
            startTime = s0; endTime = e24;
        }

        const spanDays = (endTime && startTime) ? (endTime - startTime) / (24 * 60 * 60 * 1000) : 0;
        const isYearMode = spanDays >= 300;
        const isMonthMode = !isYearMode && spanDays > 1;
        const isHourlyGapMode = spanDays <= 1;

        // Extract dataKeys from subscription
        const dataKeys = (sub?.data || []).map(dk => dk.dataKey?.name).filter(Boolean);

        // ✅ Check if we're in "All devices" mode from dashboard state
        const stateController = self.ctx.stateController;
        const stateParams = stateController ? stateController.getStateParams() : {};
        const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;
        const isAllDevicesMode = deviceMode === 'ALL';
        const entitiesFromState = stateParams?.entities || stateParams?.entityIds || [];
        const storeName = stateParams?.selectedDeviceName || stateParams?.name || 'All Devices';

        // Extract color and label mapping from subscription data keys
        const colorMap = {};
        const labelMap = {};
        (sub?.data || []).forEach(dk => {
            const keyName = dk.dataKey?.name;
            const keyColor = dk.dataKey?.color;
            const keyLabel = dk.dataKey?.label;
            if (keyName && keyColor) {
                colorMap[keyName] = keyColor;
            }
            if (keyName && keyLabel) {
                labelMap[keyName] = keyLabel;
            }
        });

        console.log('[line_chart] 📊 Mode check:', { deviceMode, isAllDevicesMode, entitiesCount: entitiesFromState.length });
        console.log('[line_chart] 🔍 Full stateParams:', stateParams);
        console.log('[line_chart] 🔍 dataKeys:', dataKeys);
        console.log('[line_chart] 🎨 colorMap:', colorMap);
        console.log('[line_chart] 🏷️ labelMap:', labelMap);
        console.log('[line_chart] 🔍 Condition check:', {



            isAllDevicesMode,
            'entitiesFromState.length > 1': entitiesFromState.length > 1,
            'dataKeys.length > 0': dataKeys.length > 0,
            willEnterALLMode: isAllDevicesMode && entitiesFromState.length > 1 && dataKeys.length > 0
        });

        if (isAllDevicesMode && entitiesFromState.length > 1 && dataKeys.length > 0) {
            // ✅ ALL DEVICES MODE: Fetch telemetry for all devices manually

            // Prevent concurrent fetches
            if (isFetchingAllDevices) {
                console.log('[line_chart] ⏳ Fetch already in progress, skipping...');
                return;
            }
            isFetchingAllDevices = true;

            console.log('[line_chart] 🔄 ALL mode - Fetching telemetry for', entitiesFromState.length, 'devices');
            console.log('[line_chart] 📊 DataKeys to fetch:', dataKeys);
            console.log('[line_chart] ⏱️ Aggregation mode:', {
                isHourlyGapMode: isHourlyGapMode ? 'by HOUR' : false,
                isMonthMode: isMonthMode ? 'by DAY' : false,
                isYearMode: isYearMode ? 'by MONTH' : false,
                spanDays: spanDays
            });

            fetchAllDevicesTelemetry(entitiesFromState, dataKeys, startTime, endTime, { isMonthMode, isYearMode, isHourlyGapMode })
                .then(aggregatedData => {
                    const datasets = buildDatasetsFromAggregatedData(
                        aggregatedData,
                        storeName,
                        startTime,
                        endTime,
                        { isMonthMode, isYearMode, isHourlyGapMode, colorMap, labelMap }
                    );


                    chart.data.datasets = datasets;
                    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
                    chart.update();
                })
                .catch(err => {
                    console.error('[line_chart] ❌ Error fetching all devices telemetry:', err);
                    // Fallback to subscription data
                    const datasets = buildDatasetsFromSubscription(sub, startTime, endTime, {
                        isMonthMode, isYearMode, isHourlyGapMode
                    });
                    chart.data.datasets = datasets;
                    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
                    chart.update();
                })
                .finally(() => {
                    isFetchingAllDevices = false;
                });
        } else {
            // ✅ SINGLE DEVICE MODE: Use subscription data as before
            // Reset flag in case we switched from ALL mode
            isFetchingAllDevices = false;

            console.log('[line_chart] 📊 SINGLE mode - Using subscription data');
            console.log('[line_chart] 📊 Subscription data length:', sub?.data?.length || 0);

            const datasets = buildDatasetsFromSubscription(sub, startTime, endTime, {
                isMonthMode, isYearMode, isHourlyGapMode
            });

            console.log('[line_chart] 📊 Built datasets:', datasets.length);

            chart.data.datasets = datasets;
            applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
            chart.update();
        }
    }

    // ===== Fetch telemetry for all devices and aggregate =====
    // Helper: Normalize timestamp based on mode (for aggregation grouping)
    // Helper: Normalize timestamp based on mode (for aggregation grouping)
    let _normalizeFirstCall = true;
    function normalizeTimestamp(ms, opts) {
        const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};

        if (_normalizeFirstCall) {
            console.log('[line_chart] 🔍 normalizeTimestamp first call - opts:', opts);
            console.log('[line_chart] 🔍 Extracted values:', { isMonthMode, isYearMode, isHourlyGapMode });
            _normalizeFirstCall = false;
        }

        const x = new Date(ms);

        let result;
        if (isYearMode) {
            // Year view → aggregate by month
            result = new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
        } else if (isMonthMode) {
            // Month view → aggregate by day
            result = new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
        } else if (isHourlyGapMode) {
            // Day view → aggregate by hour
            result = new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
        } else {
            // Default: round to nearest day (for month-ish spans)
            result = new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
        }

        // Debug log for first few calls (sampling)
        if (Math.random() < 0.2) {
            console.log(`[line_chart] 🕒 Normalize: ${new Date(ms).toISOString()} -> ${new Date(result).toISOString()} | Mode: ${isHourlyGapMode ? 'HOUR' : (isMonthMode ? 'DAY' : 'DEFAULT')}`);
        }
        return result;
    }

    async function fetchAllDevicesTelemetry(entities, keys, startTime, endTime, opts) {
        console.log('[line_chart] 📥 fetchAllDevicesTelemetry opts:', opts);
        const aggregatedData = {}; // keyName -> { normalizedTimestamp -> sum }

        // Initialize aggregated data structure
        keys.forEach(key => {
            aggregatedData[key] = {};
        });

        // Fetch telemetry for each device in parallel
        const fetchPromises = entities.map(async (entity) => {
            const deviceId = entity.id || entity;
            const keysStr = keys.join(',');

            // ThingsBoard API endpoint for historical telemetry
            const url = `/api/plugins/telemetry/DEVICE/${deviceId}/values/timeseries?keys=${encodeURIComponent(keysStr)}&startTs=${startTime}&endTs=${endTime}&limit=10000&agg=NONE`;

            console.log('[line_chart] 📡 Fetching telemetry for device:', deviceId);

            try {
                // Get JWT token from localStorage (same as store_type widget)
                const jwtToken = localStorage.getItem('jwt_token') || localStorage.getItem('token') || '';

                const response = await fetch(url, {
                    method: 'GET',
                    headers: {
                        'Content-Type': 'application/json',
                        ...(jwtToken ? { 'X-Authorization': 'Bearer ' + jwtToken } : {})
                    }
                });

                if (!response.ok) {
                    console.warn('[line_chart] ⚠️ Failed to fetch telemetry for device:', deviceId, response.status);
                    return;
                }

                const data = await response.json();

                // Log detailed data for debugging
                let deviceDataSummary = {};
                Object.keys(data).forEach(keyName => {
                    const points = data[keyName] || [];
                    const sum = points.reduce((acc, p) => acc + (Number(p.value) || 0), 0);
                    deviceDataSummary[keyName] = { points: points.length, sum: sum };

                    // Log first few timestamps to check range
                    if (points.length > 0) {
                        console.log(`[line_chart] 🔍 Device ${deviceId.substring(0, 8)} Key ${keyName} - First TS: ${points[0].ts} (${new Date(points[0].ts).toISOString()}), Last TS: ${points[points.length - 1].ts} (${new Date(points[points.length - 1].ts).toISOString()})`);
                    }
                });
                console.log('[line_chart] ✅ Device:', deviceId.substring(0, 8), 'Data:', deviceDataSummary);

                // Process each key's data
                Object.keys(data).forEach(keyName => {
                    if (!aggregatedData[keyName]) {
                        aggregatedData[keyName] = {};
                    }

                    const points = data[keyName] || [];
                    points.forEach((point, index) => {
                        const ts = point.ts;
                        // ✅ Normalize timestamp to group data correctly
                        const normalizedTs = normalizeTimestamp(ts, opts);

                        // Debug log for first few points to see what's happening
                        if (index < 5) {
                            console.log(`[line_chart] 🐛 Point ${index}: ${ts} (${new Date(ts).toISOString()}) -> ${normalizedTs} (${new Date(normalizedTs).toISOString()})`);
                        }

                        const val = Number(point.value) || 0;

                        if (!aggregatedData[keyName][normalizedTs]) {
                            aggregatedData[keyName][normalizedTs] = 0;
                        }
                        aggregatedData[keyName][normalizedTs] += val;
                    });
                });

            } catch (error) {
                console.error('[line_chart] ❌ Error fetching telemetry for device:', deviceId, error);
            }
        });

        await Promise.all(fetchPromises);

        console.log('[line_chart] ✅ Aggregated data:', Object.keys(aggregatedData).map(k => ({
            key: k,
            points: Object.keys(aggregatedData[k]).length
        })));

        return aggregatedData;
    }

    // ===== Build datasets from aggregated data =====
    function buildDatasetsFromAggregatedData(aggregatedData, storeName, startTime, endTime, opts) {
        const results = [];
        const { isMonthMode, isYearMode, isHourlyGapMode, colorMap, labelMap } = opts || {};
        const fallbackColors = ['#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12', '#16a085', '#c0392b', '#2c3e50'];

        let colorIndex = 0;
        Object.keys(aggregatedData).forEach(keyName => {
            const dataMap = aggregatedData[keyName];
            let points = Object.keys(dataMap)
                .map(ts => ({ t: Number(ts), y: dataMap[ts] }))
                .sort((a, b) => a.t - b.t);

            // Apply gap filling
            if (isHourlyGapMode) {
                points = fillGapsWithNull(points, startTime, endTime, 'hour');
            } else if (isMonthMode) {
                points = fillGapsWithNull(points, startTime, endTime, 'day');
            } else if (isYearMode) {
                points = fillGapsWithNull(points, startTime, endTime, 'month');
            }
            points = stitchZeroBeforeData(points);

            // Use color from colorMap if available, otherwise use fallback
            const color = (colorMap && colorMap[keyName]) || fallbackColors[colorIndex % fallbackColors.length];

            // Use label from labelMap if available, otherwise use keyName
            const displayLabel = (labelMap && labelMap[keyName]) || keyName;

            colorIndex++;

            results.push({
                label: `${displayLabel}`,
                data: points,
                borderColor: color,
                backgroundColor: color,
                fill: false,
                borderWidth: 5,
                lineTension: 0.3,
                spanGaps: false,
                pointRadius: 2,
                pointHitRadius: 6,
                pointHoverRadius: 5,
                pointStyle: 'circle',
                showLine: true
            });
        });

        return results;
    }



    // ===== Helpers =====

    function buildDatasetsFromSubscription(subscription, startTime, endTime, opts) {
        const results = [];
        if (!subscription || !Array.isArray(subscription.data)) return results;

        const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
        const fallbackColors = ['#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12', '#16a085', '#c0392b', '#2c3e50'];

        // ✅ Check if we're in "All devices" mode from dashboard state
        const stateController = self.ctx.stateController;
        const stateParams = stateController ? stateController.getStateParams() : {};
        const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;
        const isAllDevicesMode = deviceMode === 'ALL';
        const storeName = stateParams?.selectedDeviceName || stateParams?.name || 'All Devices';
        const entitiesFromState = stateParams?.entities || stateParams?.entityIds || [];

        console.log('[line_chart] 📊 State params:', {
            deviceMode: deviceMode,
            isAllDevicesMode: isAllDevicesMode,
            storeName: storeName,
            entitiesCount: entitiesFromState.length,
            entities: entitiesFromState
        });

        // Check how many unique devices are in subscription data
        const uniqueDevices = new Set();
        subscription.data.forEach((dk) => {
            const entityId = dk.datasource?.entityId || dk.dataKey?.datasource?.entityId;
            if (entityId) uniqueDevices.add(entityId);
        });

        console.log('[line_chart] 📊 Subscription data:', {
            dataLength: subscription.data.length,
            uniqueDevicesInData: uniqueDevices.size,
            uniqueDeviceIds: Array.from(uniqueDevices)
        });

        // Determine if we should aggregate:
        // - Mode is ALL AND (we have multiple devices in data OR we have entities from state)
        const shouldAggregate = isAllDevicesMode && (uniqueDevices.size > 1 || entitiesFromState.length > 1);

        console.log('[line_chart] shouldAggregate:', shouldAggregate);

        if (shouldAggregate && subscription.data.length > 0) {
            // ✅ AGGREGATE MODE: Sum data from all devices into one dataset per dataKey
            console.log('[line_chart] ✅ Aggregating data from', uniqueDevices.size, 'devices');

            // Group data by dataKey name (e.g., 'people_count', 'temperature')
            const keyGroups = {};

            subscription.data.forEach((dk, idx) => {
                const key = dk.dataKey || {};
                const keyName = key.name || `Series ${idx + 1}`;
                const color = key.color || fallbackColors[idx % fallbackColors.length];

                if (!keyGroups[keyName]) {
                    keyGroups[keyName] = {
                        label: `${storeName} - Total ${key.label || keyName}`,
                        color: color,
                        dataMap: {} // timestamp -> value
                    };
                }

                // Add data points to the group, summing values at same timestamps
                (dk.data || [])
                    .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
                    .forEach(p => {
                        const ts = Number(p[0]);
                        const normalizedTs = normalizeTimestamp(ts, { isMonthMode, isYearMode, isHourlyGapMode });
                        const val = Number(p[1]) || 0;

                        if (!keyGroups[keyName].dataMap[normalizedTs]) {
                            keyGroups[keyName].dataMap[normalizedTs] = 0;
                        }
                        keyGroups[keyName].dataMap[normalizedTs] += val;
                    });
            });

            // Convert aggregated data to chart format
            Object.keys(keyGroups).forEach((keyName) => {
                const group = keyGroups[keyName];
                let points = Object.keys(group.dataMap)
                    .map(ts => ({ t: Number(ts), y: group.dataMap[ts] }))
                    .sort((a, b) => a.t - b.t);

                // Fill gaps
                if (isHourlyGapMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'hour');
                } else if (isMonthMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'day');
                } else if (isYearMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'month');
                }
                points = stitchZeroBeforeData(points);

                results.push({
                    label: group.label,
                    data: points,
                    borderColor: group.color,
                    backgroundColor: group.color,
                    fill: false,
                    borderWidth: 5,
                    lineTension: 0.3,
                    spanGaps: false,
                    pointRadius: 2,
                    pointHitRadius: 6,
                    pointHoverRadius: 5,
                    pointStyle: 'circle',
                    showLine: true
                });
            });

        } else {
            // ✅ SINGLE DEVICE MODE: Show individual device data as before
            subscription.data.forEach((dk, idx) => {
                const key = dk.dataKey || {};
                const label = key.label || key.name || `Series ${idx + 1}`;
                const color = key.color || fallbackColors[idx % fallbackColors.length];

                let points = (dk.data || [])
                    .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
                    .map(p => ({ t: Number(p[0]), y: p[1] }));

                if (isHourlyGapMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'hour');
                } else if (isMonthMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'day');
                } else if (isYearMode) {
                    points = fillGapsWithNull(points, startTime, endTime, 'month');
                }
                points = stitchZeroBeforeData(points);

                results.push({
                    label,
                    data: points,
                    borderColor: color,
                    backgroundColor: color,
                    fill: false,
                    borderWidth: 5,
                    lineTension: 0.3,
                    spanGaps: false,
                    pointRadius: 2,
                    pointHitRadius: 6,
                    pointHoverRadius: 5,
                    pointStyle: 'circle',
                    showLine: true
                });
            });
        }

        return results;
    }



    // ===== Fill gaps =====
    // mode: 'hour' | 'day' | 'month'
    function fillGapsWithNull(data, startTime, endTime, mode) {
        if (!Array.isArray(data) || data.length === 0 || !startTime || !endTime) return data || [];

        const map = {};
        const normKey = (ms) => {
            const x = new Date(ms);
            if (mode === 'hour') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
            if (mode === 'day') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
            if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
            return ms;
        };

        data.forEach(p => {
            const ts = normKey(p.t);
            map[ts] = p.y;
        });

        const filled = [];

        if (mode === 'hour') {
            const sDate = new Date(startTime);
            const eDate = new Date(endTime);
            // Start at beginning of the hour
            let current = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate(), sDate.getHours(), 0, 0, 0);
            const endTs = eDate.getTime();

            while (current.getTime() <= endTs) {
                const t = current.getTime();
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
                current.setHours(current.getHours() + 1);
            }
            return filled;
        }

        if (mode === 'day') {
            const sDate = new Date(startTime);
            const eDate = new Date(endTime);
            // Start at beginning of the day
            let current = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate(), 0, 0, 0, 0);
            const endTs = eDate.getTime();

            while (current.getTime() <= endTs) {
                const t = current.getTime();
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
                current.setDate(current.getDate() + 1);
            }
            return filled;
        }

        if (mode === 'month') {
            const sDate = new Date(startTime);
            const eDate = new Date(endTime);
            // Start at beginning of the month
            let current = new Date(sDate.getFullYear(), sDate.getMonth(), 1, 0, 0, 0, 0);
            const endTs = eDate.getTime();

            while (current.getTime() <= endTs) {
                const t = current.getTime();
                filled.push({ t, y: map.hasOwnProperty(t) ? map[t] : null });
                current.setMonth(current.getMonth() + 1);
            }
            return filled;
        }

        return data;
    }

    // Chèn y=0 trước một điểm non-null nếu trước đó là null (tạo “chân”)
    function stitchZeroBeforeData(points) {
        if (!Array.isArray(points) || points.length === 0) return points || [];
        const out = [];
        for (let i = 0; i < points.length; i++) {
            const curr = points[i];
            const prev = i > 0 ? points[i - 1] : null;
            if (prev && prev.y == null && curr.y != null) {
                out.push({ t: prev.t, y: 0 });
            }
            out.push(curr);
        }
        return out;
    }

