let scheduleData = [];
let filteredScheduleData = [];

// ===== Get Flask Server URL =====
// Get from widget settings or use default
function getFlaskServerUrl() {
    try {
        const s = self.ctx.settings || {};
        return s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';
    } catch (e) {
        return 'http://127.0.0.1:5003';
    }
}

// ===== Get Tenant Username (for multi-tenant support) =====
function getTenantUsername() {
    try {
        // Try to get from ThingsBoard user context
        if (self.ctx.user && self.ctx.user.email) {
            return self.ctx.user.email;
        }
        // Try from userInfo
        if (self.ctx.userInfo && self.ctx.userInfo.email) {
            return self.ctx.userInfo.email;
        }
        // Try from $rootScope (ThingsBoard internal)
        if (self.ctx.$scope && self.ctx.$scope.$root && self.ctx.$scope.$root.currentUser && self.ctx.$scope.$root.currentUser.email) {
            return self.ctx.$scope.$root.currentUser.email;
        }
    } catch (e) {
        // // console.warn('[ScheduleView] Could not get tenant username:', e);
    }
    return null;
}

// ⚠️ WEBHOOK-ONLY MODE: No polling, no SSE
// Widget only updates on:
// 1. Initial load
// 2. Manual refresh (user action)
// 3. ThingsBoard webhook events (if configured)

let isModalOpen = false;
let isLoadingSchedules = false;
let currentPage = 1;
const ROWS_PER_PAGE = 10;
let sortColumn = null;
let sortDirection = 'asc';

// Current device tracking
let currentDeviceId = null;
let currentDeviceName = null;

// Language translations
const translations = {
    en: {
        weekdays: {
            full: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
            short: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        },
        months: {
            full: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
            short: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
        }
    },
    ja: {
        weekdays: {
            full: ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'],
            short: ['日', '月', '火', '水', '木', '金', '土']
        },
        months: {
            full: ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'],
            short: ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月']
        }
    }
};

// Get current language from ThingsBoard
function getCurrentLanguage() {
    try {
        // Try to get language from ThingsBoard context
        if (self.ctx && self.ctx.settings && self.ctx.settings.language) {
            return self.ctx.settings.language;
        }
        // Fallback to user settings
        if (self.ctx && self.ctx.$scope && self.ctx.$scope.userLang) {
            return self.ctx.$scope.userLang;
        }
        // Check URL parameter
        const urlParams = new URLSearchParams(window.location.search);
        const lang = urlParams.get('lang');
        if (lang) return lang;

        // Default to English
        return 'en';
    } catch (error) {
        // // console.warn('Error getting language:', error);
        return 'en';
    }
}

// Load Flatpickr library dynamically
let flatpickrLoaded = false;
let flatpickrLoadPromise = null;

function loadFlatpickrLibrary() {
    if (flatpickrLoaded) {
        return Promise.resolve();
    }

    if (flatpickrLoadPromise) {
        return flatpickrLoadPromise;
    }

    flatpickrLoadPromise = new Promise((resolve, reject) => {
        // Check if flatpickr already exists
        if (window.flatpickr) {
            flatpickrLoaded = true;
            resolve();
            return;
        }

        // Load CSS
        const css = document.createElement('link');
        css.rel = 'stylesheet';
        css.href = 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/flatpickr.min.css';
        document.head.appendChild(css);

        // Load JS
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/flatpickr.min.js';
        script.onload = () => {
            // // console.log('Flatpickr loaded successfully');
            flatpickrLoaded = true;
            loadFlatpickrLocales().then(resolve).catch(reject);
        };
        script.onerror = () => {
            // // console.error('Failed to load Flatpickr');
            reject(new Error('Failed to load Flatpickr'));
        };
        document.head.appendChild(script);
    });

    return flatpickrLoadPromise;
}

// Load Flatpickr locale files
function loadFlatpickrLocales() {
    const locales = {
        'ja': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/ja.js',
        'vi': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/vn.js',
        'zh': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/zh.js',
        'ko': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/ko.js'
    };

    const promises = Object.keys(locales).map(lang => {
        return new Promise((resolve) => {
            const script = document.createElement('script');
            script.src = locales[lang];
            script.onload = () => {
                // // console.log(`Flatpickr locale ${lang} loaded`);
                resolve();
            };
            script.onerror = () => {
                // // console.warn(`Failed to load Flatpickr locale ${lang}`);
                resolve(); // Continue even if locale fails
            };
            document.head.appendChild(script);
        });
    });

    return Promise.all(promises);
}

