// Get translated text
function getTranslation(category, type, index) {
    const lang = getCurrentLanguage();
    const langData = translations[lang] || translations['en'];

    if (!langData[category] || !langData[category][type]) {
        return translations['en'][category][type][index];
    }

    return langData[category][type][index];
}

