// Initialize widget
function initializeWidget() {
    // // console.log('Initializing schedule view widget...');

    // Load Flatpickr library and locales
    loadFlatpickrLibrary();

    widgetContainer = document.querySelector('.schedule-view-container');
    if (!widgetContainer) {
        // // console.warn('Widget container not found, retrying...');
        setTimeout(initializeWidget, 100);
        return;
    }

    const tbody = getWidgetElement('scheduleTableBody');
    if (tbody) {
        tbody.innerHTML = getLoadingSpinnerHTML();
    }

    setTimeout(() => {
        const searchInput = getWidgetElement('searchInput');
        const closeModal = getWidgetElement('closeModal');
        const cancelEdit = getWidgetElement('cancelEdit');
        const editForm = getWidgetElement('editForm');
        const prevBtn = getWidgetElement('prevBtn');
        const nextBtn = getWidgetElement('nextBtn');
        const closeDeleteModal = getWidgetElement('closeDeleteModal');
        const cancelDelete = getWidgetElement('cancelDelete');
        const confirmDeleteBtn = getWidgetElement('confirmDelete');

        if (!searchInput) {
            // // console.warn('Essential elements not found, retrying...');
            setTimeout(initializeWidget, 100);
            return;
        }

        // // console.log('Setting up event listeners...');

        if (searchInput) searchInput.addEventListener('input', filterSchedules);
        if (closeModal) closeModal.addEventListener('click', closeEditModal);
        if (cancelEdit) cancelEdit.addEventListener('click', closeEditModal);

        window.addEventListener('click', function (event) {
            const editModal = getWidgetElement('editModal');
            const deleteModal = getWidgetElement('deleteModal');
            if (editModal && widgetContainer && widgetContainer.contains(editModal) && event.target === editModal) {
                closeEditModal();
            }
            if (deleteModal && widgetContainer && widgetContainer.contains(deleteModal) && event.target === deleteModal) {
                closeDeleteModalFunc();
            }
        });

        if (editForm) editForm.addEventListener('submit', handleEditSubmit);

        if (closeDeleteModal) {
            closeDeleteModal.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                closeDeleteModalFunc();
            });
        }
        if (cancelDelete) {
            cancelDelete.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                closeDeleteModalFunc();
            });
        }
        if (confirmDeleteBtn) {
            confirmDeleteBtn.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                confirmDelete();
            });
        }

        if (prevBtn) {
            prevBtn.addEventListener('click', () => {
                if (currentPage > 1) {
                    goToPage(currentPage - 1);
                }
            });
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', () => {
                const totalPages = Math.ceil(filteredScheduleData.length / ROWS_PER_PAGE);
                if (currentPage < totalPages) {
                    goToPage(currentPage + 1);
                }
            });
        }

        const sortableHeaders = queryWidgetElements('.sortable');
        sortableHeaders.forEach(header => {
            header.addEventListener('click', function () {
                const column = this.getAttribute('data-sort');
                if (sortColumn === column) {
                    sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
                } else {
                    sortColumn = column;
                    sortDirection = 'asc';
                }
                updateSortIcons();
                sortSchedules();
            });
        });

        populateEditTimeOptions();

        // ===== Setup Dashboard State Subscription =====
        if (self.ctx.stateController) {
            // console.log('[schedule_view] ✅ Setting up dashboard state listener');

            let stateChangeTimeout;
            self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
                // console.log('[schedule_view] 📡 Dashboard state changed');

                if (stateChangeTimeout) {
                    clearTimeout(stateChangeTimeout);
                }

                stateChangeTimeout = setTimeout(function () {
                    // console.log('[schedule_view] ⏳ Debounce complete, reloading device...');
                    self.ctx.ngZone.run(function () {
                        loadDeviceFromState();
                    });
                }, 200); // Debounce 200ms
            });
        } else {
            // console.warn('[schedule_view] ⚠️ No stateController available for subscription');
        }

        // Load device from state and initial schedules
        setTimeout(function () {
            loadDeviceFromState();
            // No auto-refresh - webhook-only mode
        }, 300);
    }, 100);
}

// ===== Load Device from Dashboard State =====
function loadDeviceFromState() {
    if (!self.ctx || !self.ctx.stateController) {
        // console.warn('[schedule_view] ⚠️ No stateController available');
        showNoDeviceState();
        return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

    // console.log('[schedule_view] 📊 Loading device from state:', { deviceMode, stateParams });

    // ========= ALL DEVICES MODE =========
    if (deviceMode === 'ALL') {
        const entities = stateParams?.entities || stateParams?.entityIds || [];
        const deviceType = stateParams?.selectedDeviceType || stateParams?.type;

        // console.log('[schedule_view] 📋 ALL devices mode:', entities.length, 'devices');

        if (entities.length > 0) {
            loadAllDevicesSchedules(entities, deviceType);
        } else {
            showNoDeviceState();
        }
        return;
    }

    // ========= SINGLE DEVICE MODE =========
    if (deviceMode === 'SINGLE') {
        const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
        const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'Device';

        // console.log('[schedule_view] 📱 SINGLE device mode:', deviceName, deviceId);

        if (deviceId) {
            loadDeviceById(deviceId, deviceName);
        } else {
            showNoDeviceState();
        }
        return;
    }

    // ========= NONE OR NO MODE =========
    // console.log('[schedule_view] ⚠️ No device mode or NONE mode');
    showNoDeviceState();
}

// Helper: Load schedules for a single device
function loadDeviceById(deviceId, deviceName) {
    currentDeviceId = deviceId;
    currentDeviceName = deviceName;

    // console.log(`[schedule_view] ✅ Device selected: ${deviceName} (${deviceId})`);

    // Clear old data
    scheduleData = [];
    filteredScheduleData = [];

    // Load schedules for this device
    loadSchedules().then(() => {
        // console.log('[schedule_view] ✓ Schedules loaded');
    }).catch((error) => {
        // console.error('[schedule_view] Failed to load schedules:', error);
        renderTable();
        showStatus('Failed to load schedules. Please check server connection.', 'error');
    });
}

// Helper: Load and aggregate schedules from all devices
async function loadAllDevicesSchedules(entities, deviceType) {
    currentDeviceId = '__ALL__';
    currentDeviceName = `All ${deviceType || 'Devices'}`;
    scheduleData = [];
    filteredScheduleData = [];

    const tbody = getWidgetElement('scheduleTableBody');
    if (tbody) {
        tbody.innerHTML = getLoadingSpinnerHTML();
    }

    // console.log('[schedule_view] 🔄 Loading schedules from', entities.length, 'devices...');

    const FLASK_SERVER = getFlaskServerUrl();
    const tenantUsername = getTenantUsername();

    const headers = {
        'Content-Type': 'application/json'
    };
    if (tenantUsername) {
        headers['X-TB-Tenant-Username'] = tenantUsername;
    }

    try {
        // Fetch schedules from all devices in parallel
        const fetchPromises = entities.map(async (entity) => {
            const deviceId = entity.id || entity;
            try {
                const response = await fetch(`${FLASK_SERVER}/api/get-schedules`, {
                    method: 'POST',
                    headers: headers,
                    body: JSON.stringify({
                        deviceIds: [deviceId]
                    })
                });

                if (!response.ok) {
                    // console.warn('[schedule_view] ⚠️ Failed to fetch schedules for device:', deviceId);
                    return [];
                }

                const data = await response.json();
                if (data.success && Array.isArray(data.schedules)) {
                    // Add device info to each schedule
                    return data.schedules.map(item => ({
                        ...item,
                        _deviceId: deviceId,
                        _deviceName: entity.name || deviceId
                    }));
                }
                return [];
            } catch (error) {
                // console.warn('[schedule_view] ⚠️ Error fetching schedules for device:', deviceId, error);
                return [];
            }
        });

        const results = await Promise.all(fetchPromises);

        // Flatten and combine all schedules
        scheduleData = results.flat();

        // console.log('[schedule_view] ✅ Loaded', scheduleData.length, 'total schedules from', entities.length, 'devices');

        filterSchedules();

    } catch (error) {
        // console.error('[schedule_view] ❌ Error loading all devices schedules:', error);
        showStatus('Error loading schedules from devices: ' + error.message, 'error');
        scheduleData = [];
        filteredScheduleData = [];
        renderTable();
    }
}

