function populateEditTimeOptions() {
    const timeOptions = [];
    for (let hour = 0; hour < 24; hour++) {
        for (let minute = 0; minute < 60; minute += 5) {
            const timeString = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
            timeOptions.push(timeString);
        }
    }

    const editStartTimeSelect = getWidgetElement('editStartTime');
    const editStartTimeOptions = getWidgetElement('editStartTimeOptions');
    if (editStartTimeSelect && editStartTimeOptions) {
        timeOptions.forEach(time => {
            const option = document.createElement('option');
            option.value = time;
            option.textContent = time;
            editStartTimeSelect.appendChild(option);

            const customOption = document.createElement('div');
            customOption.className = 'custom-select-option';
            customOption.setAttribute('data-value', time);
            customOption.textContent = time;
            editStartTimeOptions.appendChild(customOption);
        });
    }

    const editEndTimeSelect = getWidgetElement('editEndTime');
    const editEndTimeOptions = getWidgetElement('editEndTimeOptions');
    if (editEndTimeSelect && editEndTimeOptions) {
        timeOptions.forEach(time => {
            const option = document.createElement('option');
            option.value = time;
            option.textContent = time;
            editEndTimeSelect.appendChild(option);

            const customOption = document.createElement('div');
            customOption.className = 'custom-select-option';
            customOption.setAttribute('data-value', time);
            customOption.textContent = time;
            editEndTimeOptions.appendChild(customOption);
        });
    }

    setupEditCustomSelect('editStartTimeSelect', 'editStartTime');
    setupEditCustomSelect('editEndTimeSelect', 'editEndTime');
}

function setupEditCustomSelect(selectId, hiddenSelectId) {
    const customSelect = getWidgetElement(selectId);
    const hiddenSelect = getWidgetElement(hiddenSelectId);
    if (!customSelect || !hiddenSelect) return;

    const trigger = customSelect.querySelector('.custom-select-trigger');
    const options = customSelect.querySelector('.custom-select-options');
    const valueSpan = customSelect.querySelector('.custom-select-value');

    if (trigger.hasAttribute('data-setup')) return;
    trigger.setAttribute('data-setup', 'true');

    trigger.addEventListener('click', function (e) {
        e.stopPropagation();
        const isOpen = customSelect.classList.contains('open');

        queryWidgetElements('.custom-select').forEach(sel => {
            if (sel !== customSelect) {
                sel.classList.remove('open');
            }
        });

        customSelect.classList.toggle('open', !isOpen);
    });

    options.querySelectorAll('.custom-select-option').forEach(option => {
        option.addEventListener('click', function (e) {
            e.stopPropagation();
            const value = this.getAttribute('data-value');
            valueSpan.textContent = value;
            hiddenSelect.value = value;
            customSelect.classList.remove('open');

            hiddenSelect.dispatchEvent(new Event('change', { bubbles: true }));
        });
    });

    document.addEventListener('click', function (e) {
        if (!customSelect.contains(e.target) &&
            (!widgetContainer || !widgetContainer.contains(e.target))) {
            customSelect.classList.remove('open');
        }
    });
}

function updateSortIcons() {
    const sortableHeaders = queryWidgetElements('.sortable');
    sortableHeaders.forEach(header => {
        const icon = header.querySelector('.sort-icon');
        const column = header.getAttribute('data-sort');
        if (column === sortColumn) {
            icon.textContent = sortDirection === 'asc' ? '↑' : '↓';
        } else {
            icon.textContent = '↕';
        }
    });
}

function sortSchedules() {
    if (!sortColumn) {
        filterSchedules();
        return;
    }

    filteredScheduleData.sort((a, b) => {
        let aVal = a[sortColumn];
        let bVal = b[sortColumn];

        if (sortColumn === 'priority') {
            const priorityOrder = { 'high': 3, 'medium': 2, 'low': 1 };
            aVal = priorityOrder[aVal] || 0;
            bVal = priorityOrder[bVal] || 0;
        }

        if (sortColumn === 'start_date' || sortColumn === 'end_date') {
            aVal = parseDateForSort(aVal);
            bVal = parseDateForSort(bVal);
        }

        if (sortColumn === 'name') {
            aVal = (aVal || '').toLowerCase();
            bVal = (bVal || '').toLowerCase();
        }

        if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
        return 0;
    });

    currentPage = 1;
    renderTable();
    renderPagination();
}

function parseDateForSort(dateStr) {
    if (!dateStr) return 0;
    try {
        const date = new Date(dateStr);
        return date.getTime();
    } catch (e) {
        return 0;
    }
}

function filterSchedules() {
    const searchInput = getWidgetElement('searchInput');

    if (!Array.isArray(scheduleData)) {
        scheduleData = [];
    }

    if (!searchInput) {
        filteredScheduleData = scheduleData.map((item, index) => {
            if (item) {
                item._originalIndex = index;
            }
            return item;
        }).filter(item => item != null);
        currentPage = 1;
        renderTable();
        renderPagination();
        return;
    }

    const searchTerm = searchInput.value.toLowerCase().trim();

    filteredScheduleData = scheduleData.map((item, index) => {
        if (!item) return null;

        if (searchTerm) {
            const name = (item.name || '').toLowerCase();
            if (!name.includes(searchTerm)) {
                return null;
            }
        }

        item._originalIndex = index;
        return item;
    }).filter(item => item != null);

    if (sortColumn) {
        sortSchedules();
    } else {
        currentPage = 1;
        renderTable();
        renderPagination();
    }
}

