async function loadSchedules(silent = false) {
    if (isLoadingSchedules) {
        // // console.log('Already loading schedules, skipping...');
        return;
    }

    // ✅ ADD: Check if device is selected
    if (!currentDeviceId) {
        // // console.warn('[ScheduleView] No device selected, cannot load schedules');
        scheduleData = [];
        filteredScheduleData = [];
        renderTable();
        return;
    }

    isLoadingSchedules = true;

    // Only show spinner if we don't have data yet
    if (scheduleData.length === 0) {
        const tbody = getWidgetElement('scheduleTableBody');
        if (tbody) {
            tbody.innerHTML = getLoadingSpinnerHTML();
        }
    }

    try {
        // ✅ MODIFIED: Load schedules for specific device
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        // // console.log(`[ScheduleView] Loading schedules for device: ${currentDeviceId}`);
        const response = await fetch(`${FLASK_SERVER}/api/get-schedules`, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({
                deviceIds: [currentDeviceId]
            })
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        if (data.success) {
            // ✅ MODIFIED: Filter schedules by current device
            const allSchedules = data.schedules || [];
            const newScheduleData = allSchedules.filter(s => s.device_id === currentDeviceId);

            // // console.log(`[ScheduleView] Loaded ${newScheduleData.length} schedules for device ${currentDeviceId} (total: ${allSchedules.length})`);

            // Always update data and render
            scheduleData = newScheduleData;
            isLoadingSchedules = false;
            filterSchedules();

            if (silent) {
                // // console.log('[ScheduleView] Schedules updated silently:', scheduleData.length, 'items');
            } else {
                // // console.log('[ScheduleView] Schedules updated:', scheduleData.length, 'items');
            }
        } else {
            if (!silent) {
                showStatus('Failed to load schedules: ' + (data.error || 'Unknown error'), 'error');
            } else {
                // // console.warn('Failed to load schedules:', data.error);
            }

            // FIXED: Set loading to false BEFORE rendering
            isLoadingSchedules = false;
            filterSchedules();
        }
    } catch (error) {
        // // console.error('Error loading schedules:', error);
        if (!silent) {
            showStatus('Error loading schedules: ' + error.message, 'error');
        }

        // FIXED: Set loading to false BEFORE rendering
        isLoadingSchedules = false;
        filterSchedules();
    } finally {
        isLoadingSchedules = false;
    }
}

function formatDateForDisplay(dateStr) {
    if (!dateStr) return 'N/A';
    try {
        let date;

        // Check if date string has format like "Jan 4, 2025 00:00:00" (English month format)
        const englishMonthPattern = /^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d+),\s+(\d+)\s+00:00:00$/;
        const englishMatch = dateStr.match(englishMonthPattern);

        if (englishMatch) {
            // Parse English month format: "Jan 4, 2025 00:00:00"
            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const monthIndex = monthNames.indexOf(englishMatch[1]);
            if (monthIndex !== -1) {
                const day = parseInt(englishMatch[2], 10);
                const year = parseInt(englishMatch[3], 10);
                date = new Date(year, monthIndex, day);
            } else {
                date = new Date(dateStr);
            }
        } else {
            // Check if date string has format like "1月 4, 2025 00:00:00" (Japanese month format)
            const japaneseMonthPattern = /^(\d+)月\s+(\d+),\s+(\d+)\s+00:00:00$/;
            const japaneseMatch = dateStr.match(japaneseMonthPattern);

            if (japaneseMatch) {
                // Parse Japanese month format: "1月 4, 2025 00:00:00"
                const month = parseInt(japaneseMatch[1], 10) - 1; // Month is 0-indexed
                const day = parseInt(japaneseMatch[2], 10);
                const year = parseInt(japaneseMatch[3], 10);
                date = new Date(year, month, day);
            } else if (dateStr.includes('/')) {
                // Parse DD/MM/YYYY format
                const parts = dateStr.split('/');
                if (parts.length === 3) {
                    const day = parseInt(parts[0], 10);
                    const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed
                    const year = parseInt(parts[2], 10);
                    date = new Date(year, month, day);
                } else {
                    date = new Date(dateStr);
                }
            } else if (dateStr.includes('T') || dateStr.includes('-')) {
                // ISO format or YYYY-MM-DD format
                date = new Date(dateStr);
            } else {
                // Try standard Date parsing
                date = new Date(dateStr);
            }
        }

        // Check if date is valid
        if (isNaN(date.getTime())) {
            // // console.warn('Invalid date format:', dateStr);
            return dateStr; // Return original string if can't parse
        }

        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        return `${day}/${month}/${year}`;
    } catch (e) {
        // // console.warn('Error parsing date:', dateStr, e);
        return dateStr;
    }
}

function formatPriority(priority) {
    if (!priority) return 'Medium';
    return priority.charAt(0).toUpperCase() + priority.slice(1).toLowerCase();
}

function getPriorityClass(priority) {
    const p = (priority || 'medium').toLowerCase();
    if (p === 'high') return 'priority-high';
    if (p === 'low') return 'priority-low';
    return 'priority-medium';
}

function renderTable() {
    const tbody = getWidgetElement('scheduleTableBody');
    if (!tbody) return;

    // Check if we're in ALL devices mode
    const isAllDevicesMode = currentDeviceId === '__ALL__';

    // FIXED: Only show loading spinner when actively loading
    if (isLoadingSchedules) {
        tbody.innerHTML = getLoadingSpinnerHTML();
        return;
    }

    tbody.innerHTML = '';

    if (filteredScheduleData.length === 0) {
        if (scheduleData.length === 0) {
            if (!currentDeviceId) {
                tbody.innerHTML = '<tr class="empty-row"><td colspan="5" class="empty-message">Please select a device</td></tr>';
            } else {
                tbody.innerHTML = '<tr class="empty-row"><td colspan="5" class="empty-message">No schedules found for this device</td></tr>';
            }
        } else {
            tbody.innerHTML = '<tr class="empty-row"><td colspan="5" class="empty-message">No schedules match the search criteria</td></tr>';
        }
        renderPagination();
        return;
    }

    const totalPages = Math.ceil(filteredScheduleData.length / ROWS_PER_PAGE);

    if (currentPage > totalPages && totalPages > 0) {
        currentPage = totalPages;
    }

    const startIndex = (currentPage - 1) * ROWS_PER_PAGE;
    const endIndex = Math.min(startIndex + ROWS_PER_PAGE, filteredScheduleData.length);
    const paginatedData = filteredScheduleData.slice(startIndex, endIndex);

    paginatedData.forEach((schedule) => {
        const row = document.createElement('tr');
        const originalIndex = schedule._originalIndex !== undefined ? schedule._originalIndex : scheduleData.findIndex(s => s.name === schedule.name && s.device_id === schedule.device_id);

        // Prepare action buttons based on mode
        let actionButtonsHTML;
        if (isAllDevicesMode) {
            // Disabled buttons in ALL devices mode
            actionButtonsHTML = `
                <div class="action-buttons">
                    <button class="action-btn edit disabled" disabled title="Not available in All Devices mode">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                            <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                            <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                        </svg>
                    </button>
                    <button class="action-btn delete disabled" disabled title="Not available in All Devices mode">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                            <polyline points="3 6 5 6 21 6"></polyline>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                        </svg>
                    </button>
                </div>
            `;
        } else {
            // Enabled buttons in SINGLE device mode
            actionButtonsHTML = `
                <div class="action-buttons">
                    <button class="action-btn edit" onclick="editSchedule(${originalIndex})" title="Edit">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                            <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                            <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                        </svg>
                    </button>
                    <button class="action-btn delete" onclick="deleteSchedule(${originalIndex})" title="Delete">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                            <polyline points="3 6 5 6 21 6"></polyline>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
