            <td>
                <span class="priority-badge ${getPriorityClass(schedule.priority)}">
                    ${formatPriority(schedule.priority)}
                </span>
            </td>
            <td>${formatDateForDisplay(schedule.start_date)}</td>
            <td>${formatDateForDisplay(schedule.end_date)}</td>
            <td>
                ${actionButtonsHTML}
            </td>
        `;

        tbody.appendChild(row);
    });

    renderPagination();
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function renderPagination() {
    const totalItems = filteredScheduleData.length;
    const totalPages = Math.ceil(totalItems / ROWS_PER_PAGE);
    const startIndex = totalItems === 0 ? 0 : (currentPage - 1) * ROWS_PER_PAGE + 1;
    const endIndex = Math.min(currentPage * ROWS_PER_PAGE, totalItems);

    const paginationText = getWidgetElement('paginationText');
    const prevBtn = getWidgetElement('prevBtn');
    const nextBtn = getWidgetElement('nextBtn');
    const pageNumbersContainer = getWidgetElement('pageNumbers');

    if (!paginationText || !prevBtn || !nextBtn || !pageNumbersContainer) return;

    paginationText.textContent = `Showing ${startIndex} to ${endIndex} out of ${totalItems} entries`;
    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;
    pageNumbersContainer.innerHTML = '';

    if (totalPages === 0) {
        return;
    }

    let startPage = Math.max(1, currentPage - 2);
    let endPage = Math.min(totalPages, startPage + 4);

    if (endPage - startPage < 4) {
        startPage = Math.max(1, endPage - 4);
    }

    for (let i = startPage; i <= endPage; i++) {
        const pageBtn = document.createElement('button');
        pageBtn.className = 'page-number';
        if (i === currentPage) {
            pageBtn.classList.add('active');
        }
        pageBtn.textContent = i;
        pageBtn.onclick = () => goToPage(i);
        pageNumbersContainer.appendChild(pageBtn);
    }
}

function goToPage(page) {
    const totalPages = Math.ceil(filteredScheduleData.length / ROWS_PER_PAGE);
    if (page < 1 || page > totalPages) {
        return;
    }

    currentPage = page;
    renderTable();

    const tableContainer = queryWidgetElements('.table-container')[0];
    if (tableContainer) {
        tableContainer.scrollTop = 0;
    }
}

// ===== Load device for edit modal from current state =====
async function loadEditDevices() {
    try {
        const deviceGroupSelect = getWidgetElement('editDeviceGroup');
        if (!deviceGroupSelect) {
            // console.warn('[schedule_view] Device select element not found');
            return;
        }

        // Clear existing options
        deviceGroupSelect.innerHTML = '';

        // Check if we have a current device from state
        if (!currentDeviceId || currentDeviceId === '__ALL__') {
            // No single device selected or in ALL mode
            deviceGroupSelect.innerHTML = '<option value="">No device selected</option>';
            // console.warn('[schedule_view] No single device selected for editing');
            return;
        }

        // Add current device as the only option
        const option = document.createElement('option');
        option.value = currentDeviceId;
        option.setAttribute('data-device-id', currentDeviceId);
        option.setAttribute('data-device-name', currentDeviceName || 'Unknown');
        option.textContent = currentDeviceName || currentDeviceId;
        option.selected = true;
        deviceGroupSelect.appendChild(option);

        // console.log(`[schedule_view] ✓ Loaded device for edit modal: ${currentDeviceName} (${currentDeviceId})`);

        // Load device tokens for the current device
        loadDeviceTokens([{
            id: currentDeviceId,
            name: currentDeviceName,
            type: 'DEVICE'
        }]);

    } catch (error) {
        // // console.error('Error loading devices from datasource:', error);
        const deviceGroupSelect = getWidgetElement('editDeviceGroup');
        if (deviceGroupSelect) {
            deviceGroupSelect.innerHTML = '<option value="">Error loading devices</option>';
        }
    }
}

async function loadDeviceTokens(devices) {
    try {
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        const response = await fetch(`${FLASK_SERVER}/api/devices`, {
            method: 'GET',
            headers: headers
        });
        const data = await response.json();

        if (data.success && data.devices) {
            const deviceGroupSelect = getWidgetElement('editDeviceGroup');
            if (!deviceGroupSelect) return;

            const options = deviceGroupSelect.querySelectorAll('option');
            options.forEach(option => {
                const deviceId = option.getAttribute('data-device-id');
                if (deviceId) {
                    const device = data.devices.find(d => d.id === deviceId);
                    if (device && device.token) {
                        option.setAttribute('data-device-token', device.token);
                    }
                }
            });
        }
    } catch (error) {
        // // console.error('Error loading device tokens:', error);
    }
}

// ✅ MODIFIED: Load content for specific device
async function loadEditContent(deviceId) {
    if (!deviceId) {
        // // console.log('No device selected, skipping content load');
        editAvailableContent = [];
        return;
    }

    try {
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        // // console.log(`Loading content for device: ${deviceId}`);
        const response = await fetch(`${FLASK_SERVER}/api/get-content?deviceId=${deviceId}`, {
            method: 'GET',
            headers: headers
        });
        const data = await response.json();

        if (data.success && data.content) {
            editAvailableContent = data.content;
            // // console.log(`✓ Loaded ${editAvailableContent.length} content items for device ${deviceId}`);
        } else {
            editAvailableContent = [];
            // // console.warn('No content found for device:', deviceId);
        }
    } catch (error) {
        // // console.error('Error loading content:', error);
        editAvailableContent = [];
    }
}

// ✅ MODIFIED: Handle device change in edit modal
function onEditDeviceChange() {
    const deviceGroupSelect = getWidgetElement('editDeviceGroup');
    if (!deviceGroupSelect) return;

    const selectedOption = deviceGroupSelect.options[deviceGroupSelect.selectedIndex];
    const deviceId = selectedOption.getAttribute('data-device-id') || deviceGroupSelect.value;

    if (deviceId && deviceId !== editCurrentDeviceId) {
        // // console.log('Edit device changed to:', deviceId);
        editCurrentDeviceId = deviceId;

        // Clear selected contents when device changes
        editSelectedContents = [];
        updateEditContentDisplay();

        // Load content for new device
        loadEditContent(deviceId);

        // Update hidden fields
        getWidgetElement('editDeviceId').value = deviceId;
        getWidgetElement('editDeviceToken').value = selectedOption.getAttribute('data-device-token') || '';
    }
}

function setupEditModalListeners() {
    const editModal = getWidgetElement('editModal');
    const weekdayToggles = editModal ? editModal.querySelectorAll('.weekday-toggle') : [];

    // Update weekday labels based on current language
    updateWeekdayLabels();

    weekdayToggles.forEach(toggle => {
        toggle.removeEventListener('click', handleEditWeekdayToggle);
        toggle.addEventListener('click', handleEditWeekdayToggle);
    });

    const selectAllBtn = getWidgetElement('editSelectAllWeekdays');
    const clearAllBtn = getWidgetElement('editClearAllWeekdays');

    if (selectAllBtn) {
        selectAllBtn.onclick = function () {
            weekdayToggles.forEach(toggle => {
                toggle.classList.add('active');
                const dayValue = toggle.getAttribute('data-value');
                if (!editSelectedWeekdays.includes(dayValue)) {
                    editSelectedWeekdays.push(dayValue);
                }
            });
        };
    }

    if (clearAllBtn) {
        clearAllBtn.onclick = function () {
            weekdayToggles.forEach(toggle => {
                toggle.classList.remove('active');
            });
            editSelectedWeekdays = [];
        };
    }

    // ✅ ADD: Device select change listener
    const deviceSelect = getWidgetElement('editDeviceGroup');
    if (deviceSelect) {
        deviceSelect.onchange = onEditDeviceChange;
    }

    const selectContentBtn = getWidgetElement('editSelectContentBtn');
    const closeContentModal = getWidgetElement('closeEditContentModal');
    const cancelContentBtn = getWidgetElement('cancelEditContentBtn');
    const confirmContentBtn = getWidgetElement('confirmEditContentBtn');
    const contentSearch = getWidgetElement('editContentSearch');

    if (selectContentBtn) {
        selectContentBtn.onclick = openEditContentModal;
    }

    if (closeContentModal) {
        closeContentModal.onclick = closeEditContentModalFunc;
    }

    if (cancelContentBtn) {
        cancelContentBtn.onclick = closeEditContentModalFunc;
    }

    if (confirmContentBtn) {
        confirmContentBtn.onclick = function () {
            const editContentModal = getWidgetElement('editContentModal');
            const selectedItems = editContentModal ? editContentModal.querySelectorAll('.content-item.selected') : [];
            if (selectedItems.length > 0) {
                selectedItems.forEach(item => {
                    const contentId = item.getAttribute('data-content-id');
                    const contentIndex = item.getAttribute('data-content-index');
                    const content = editAvailableContent[contentIndex];

                    if (content && !editSelectedContents.find(c => c.id === contentId)) {
                        editSelectedContents.push({
                            id: contentId,
                            name: content.file_name || content.fileName || 'Unknown',
                            store: content.store || 'Unknown',
                            data: content,
                            gender: '',
                            ageFrom: 1,
                            ageTo: 1
                        });
                    }
                });
                updateEditContentDisplay();
                closeEditContentModalFunc();
            } else {
                showStatus('Please select at least one content item', 'error');
            }
        };
    }

    if (contentSearch) {
        contentSearch.oninput = function () {
            renderEditContentList(this.value);
        };
    }
}

function handleEditWeekdayToggle() {
    const dayValue = this.getAttribute('data-value');
    this.classList.toggle('active');

    if (this.classList.contains('active')) {
        if (!editSelectedWeekdays.includes(dayValue)) {
            editSelectedWeekdays.push(dayValue);
        }
    } else {
        editSelectedWeekdays = editSelectedWeekdays.filter(d => d !== dayValue);
    }
}

// ✅ MODIFIED: Check if device is selected before opening modal
function openEditContentModal() {
    // Check if device is selected
    if (!editCurrentDeviceId) {
        showStatus('Please select a device first', 'error');
        return;
    }

    // Check if content is loaded
    if (editAvailableContent.length === 0) {
        showStatus('No content available for this device. Please upload content first.', 'error');
        return;
    }

    const modal = getWidgetElement('editContentModal');
    if (modal) {
        renderEditContentList();
        modal.style.display = 'block';
    }
}

function closeEditContentModalFunc() {
    const modal = getWidgetElement('editContentModal');
    if (modal) {
        modal.style.display = 'none';
    }
}

function renderEditContentList(searchTerm = '') {
    const contentList = getWidgetElement('editContentList');
    if (!contentList) return;

    if (editAvailableContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">No content available for this device</div>';
        return;
    }

    let filteredContent = editAvailableContent;
    if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        filteredContent = editAvailableContent.filter(item => {
            const store = (item.customer || item.store || '').toLowerCase();
            const fileName = (item.file_name || item.fileName || '').toLowerCase();
            const type = (item.type || item.contentType || '').toLowerCase();
            return store.includes(searchLower) ||
                fileName.includes(searchLower) ||
                type.includes(searchLower);
        });
    }

    if (filteredContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">No content found</div>';
        return;
    }

    function formatFileSize(bytes) {
        if (!bytes || bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
    }

    function getFileSizeDisplay(fileSize) {
        if (!fileSize) return '0 B';

        if (typeof fileSize === 'string' && /[A-Za-z]/.test(fileSize)) {
            return fileSize;
        }

        const numSize = parseInt(fileSize, 10);
        if (!isNaN(numSize)) {
            return formatFileSize(numSize);
        }

        return '0 B';
    }

    contentList.innerHTML = filteredContent.map((item, index) => {
        const isSelected = editSelectedContents.find(c => c.id === item.checksum);
        const fileName = item.file_name || item.fileName || 'Unknown';
        const type = item.type || item.contentType || 'video';
        const fileSize = item.file_size || item.fileSize || 0;
        const formattedSize = getFileSizeDisplay(fileSize);

        return `
            <div class="content-item ${isSelected ? 'selected' : ''}" 
                 data-content-id="${item.checksum}"
                 data-content-index="${index}">
                <div>
                    <div class="content-item-name">${item.customer || item.store || 'Unknown Store'}</div>
                    <div class="content-item-type">${fileName}</div>
                    <div class="content-item-meta">
                        <span class="content-item-type-label">Type: ${type}</span>
                        <span class="content-item-size-label">Size: ${formattedSize}</span>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    contentList.querySelectorAll('.content-item').forEach(item => {
        item.onclick = function () {
            this.classList.toggle('selected');
        };
    });
}

function updateEditContentDisplay() {
    const contentLabel = getWidgetElement('editContentLabel');
    const selectedContentList = getWidgetElement('editSelectedContentList');

    if (contentLabel) {
        contentLabel.textContent = editSelectedContents.length > 0
            ? `${editSelectedContents.length} Content Selected`
            : 'Select Content';
    }

    if (editSelectedContents.length > 0) {
        if (selectedContentList) {
            selectedContentList.style.display = 'block';
        }
        renderEditContentItems();
    } else {
        if (selectedContentList) {
            selectedContentList.style.display = 'none';
        }
    }
}

function renderEditContentItems() {
    const container = getWidgetElement('editContentItemsContainer');
    if (!container) return;

    container.innerHTML = editSelectedContents.map((content, index) => {
        return `
            <div class="content-item-with-filters" data-content-index="${index}">
                <div class="content-item-row">
                    <div class="content-info-column">
                        <div class="content-item-name-main">${content.name}</div>
                        <div class="content-item-store">${content.store}</div>
                    </div>

                    <div class="filters-info-column">
                        <div class="filter-group gender-filter-group">
                            <label>Gender</label>
                            <select class="content-gender-select" data-index="${index}">
                                <option value="">Select gender</option>
                                <option value="male" ${content.gender === 'male' ? 'selected' : ''}>Male</option>
                                <option value="female" ${content.gender === 'female' ? 'selected' : ''}>Female</option>
                                <option value="all" ${content.gender === 'all' ? 'selected' : ''}>All</option>
                            </select>
                        </div>

                        <div class="age-filters-row">
                            <div class="filter-group age-group">
                                <label>Age From</label>
                                <div class="number-input-group-small">
                                    <button type="button" class="number-btn-small age-dec" data-index="${index}" data-type="from">−</button>
                                    <input 
                                        type="number" 
                                        class="number-input-small age-from" 
                                        data-index="${index}"
                                        value="${content.ageFrom || 1}" 
                                        min="1"
                                    >
                                    <button type="button" class="number-btn-small age-inc" data-index="${index}" data-type="from">+</button>
                                </div>
                            </div>

                            <div class="filter-group age-group">
                                <label>To</label>
                                <div class="number-input-group-small">
                                    <button type="button" class="number-btn-small age-dec" data-index="${index}" data-type="to">−</button>
                                    <input 
                                        type="number" 
                                        class="number-input-small age-to" 
                                        data-index="${index}"
                                        value="${content.ageTo || 1}" 
                                        min="1"
                                    >
                                    <button type="button" class="number-btn-small age-inc" data-index="${index}" data-type="to">+</button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <button type="button" class="remove-content-item-btn" data-index="${index}">×</button>
                </div>
            </div>
        `;
    }).join('');

    container.querySelectorAll('.remove-content-item-btn').forEach(btn => {
        btn.onclick = function () {
            const index = parseInt(this.getAttribute('data-index'));
            editSelectedContents.splice(index, 1);
            updateEditContentDisplay();
        };
    });

    container.querySelectorAll('.content-gender-select').forEach(select => {
        select.onchange = function () {
            const index = parseInt(this.getAttribute('data-index'));
            if (editSelectedContents[index]) {
                editSelectedContents[index].gender = this.value;
            }
        };
    });

    container.querySelectorAll('.age-inc, .age-dec').forEach(btn => {
        btn.onclick = function () {
            const index = parseInt(this.getAttribute('data-index'));
            const isFrom = this.getAttribute('data-type') === 'from';
            const isInc = this.classList.contains('age-inc');
            const input = isFrom
                ? container.querySelector(`.age-from[data-index="${index}"]`)
                : container.querySelector(`.age-to[data-index="${index}"]`);

            if (input && editSelectedContents[index]) {
                let value = parseInt(input.value) || 1;
                value = isInc ? value + 1 : Math.max(1, value - 1);
                input.value = value;

                if (isFrom) {
                    editSelectedContents[index].ageFrom = value;
                    if (editSelectedContents[index].ageTo < value) {
                        editSelectedContents[index].ageTo = value;
                        const toInput = container.querySelector(`.age-to[data-index="${index}"]`);
                        if (toInput) toInput.value = value;
                    }
                } else {
                    editSelectedContents[index].ageTo = value;
                    if (value < editSelectedContents[index].ageFrom) {
                        editSelectedContents[index].ageFrom = value;
                        const fromInput = container.querySelector(`.age-from[data-index="${index}"]`);
                        if (fromInput) fromInput.value = value;
                    }
                }
            }
        };
    });

    container.querySelectorAll('.age-from, .age-to').forEach(input => {
        input.onchange = function () {
            const index = parseInt(this.getAttribute('data-index'));
            const isFrom = this.classList.contains('age-from');
            const value = parseInt(this.value) || 1;

            if (editSelectedContents[index]) {
                if (isFrom) {
                    editSelectedContents[index].ageFrom = value;
                    if (editSelectedContents[index].ageTo < value) {
                        editSelectedContents[index].ageTo = value;
                        const toInput = container.querySelector(`.age-to[data-index="${index}"]`);
                        if (toInput) toInput.value = value;
                    }
                } else {
                    editSelectedContents[index].ageTo = value;
                    if (value < editSelectedContents[index].ageFrom) {
                        editSelectedContents[index].ageFrom = value;
                        const fromInput = container.querySelector(`.age-from[data-index="${index}"]`);
                        if (fromInput) fromInput.value = value;
                    }
                }
            }
        };
    });
}

window.editSchedule = async function (index) {
    const schedule = scheduleData[index];

    if (!schedule) {
        showStatus('Schedule not found', 'error');
        return;
    }

    isModalOpen = true;

    editSelectedWeekdays = [];
    editSelectedContents = [];
    editCurrentDeviceId = schedule.device_id || null;

    await loadEditDevices();

    // ✅ MODIFIED: Load content for schedule's device
    if (editCurrentDeviceId) {
        await loadEditContent(editCurrentDeviceId);
    }

    // Update weekday labels before showing modal
    setTimeout(() => {
        updateWeekdayLabels();
        initializeDatePickers();
    }, 100);

    getWidgetElement('editIndex').value = index;
    getWidgetElement('editDeviceId').value = schedule.device_id || '';
    getWidgetElement('editScheduleName').value = schedule.name || '';
    getWidgetElement('editPriority').value = schedule.priority || 'medium';

