function setupContentItemListeners() {
    // Remove buttons
    document.querySelectorAll('.remove-content-item-btn').forEach(btn => {
        btn.addEventListener('click', function () {
            const index = parseInt(this.getAttribute('data-index'));
            selectedContents.splice(index, 1);
            updateContentDisplay();
        });
    });

    // Gender selects
    document.querySelectorAll('.content-gender-select').forEach(select => {
        select.addEventListener('change', function () {
            const index = parseInt(this.getAttribute('data-index'));
            if (selectedContents[index]) {
                selectedContents[index].gender = this.value;
            }
        });
    });

    // Age inputs
    document.querySelectorAll('.age-from, .age-to').forEach(input => {
        input.addEventListener('change', function () {
            const index = parseInt(this.getAttribute('data-index'));
            const isFrom = this.classList.contains('age-from');
            const value = parseInt(this.value) || 1;

            if (selectedContents[index]) {
                if (isFrom) {
                    selectedContents[index].ageFrom = value;
                    if (selectedContents[index].ageTo < value) {
                        selectedContents[index].ageTo = value;
                        const toInput = document.querySelector(`.age-to[data-index="${index}"]`);
                        if (toInput) toInput.value = value;
                    }
                } else {
                    selectedContents[index].ageTo = value;
                    if (value < selectedContents[index].ageFrom) {
                        selectedContents[index].ageFrom = value;
                        const fromInput = document.querySelector(`.age-from[data-index="${index}"]`);
                        if (fromInput) fromInput.value = value;
                    }
                }
            }
        });
    });

    // Age increment/decrement buttons
    document.querySelectorAll('.age-inc, .age-dec').forEach(btn => {
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();

            const index = parseInt(this.getAttribute('data-index'));
            const type = this.getAttribute('data-type');
            const isInc = this.classList.contains('age-inc');

            // Find the input in the same container
            const container = this.closest('.content-item-with-filters');
            const input = container ? container.querySelector(`.age-${type}[data-index="${index}"]`) : null;

            if (input && selectedContents[index]) {
                let value = parseInt(input.value) || 1;
                value = isInc ? value + 1 : Math.max(1, value - 1);
                input.value = value;

                // Update the data
                if (type === 'from') {
                    selectedContents[index].ageFrom = value;
                    if (selectedContents[index].ageTo < value) {
                        selectedContents[index].ageTo = value;
                        const toInput = container ? container.querySelector(`.age-to[data-index="${index}"]`) : null;
                        if (toInput) {
                            toInput.value = value;
                            toInput.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                    }
                } else {
                    selectedContents[index].ageTo = value;
                    if (value < selectedContents[index].ageFrom) {
                        selectedContents[index].ageFrom = value;
                        const fromInput = container ? container.querySelector(`.age-from[data-index="${index}"]`) : null;
                        if (fromInput) {
                            fromInput.value = value;
                            fromInput.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                    }
                }

                // Trigger change event to update the data
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }
        });
    });
}

async function handleFormSubmit(e) {
    e.preventDefault();

    // Clear previous errors
    document.querySelectorAll('.error-message').forEach(el => {
        el.classList.remove('show');
        el.textContent = '';
    });

    // Validate all required fields
    const scheduleName = document.getElementById('scheduleName');
    const deviceGroup = document.getElementById('deviceGroup');
    const startDate = document.getElementById('startDate');
    const endDate = document.getElementById('endDate');
    const startTime = document.getElementById('startTime');
    const endTime = document.getElementById('endTime');
    const priority = document.getElementById('priority');

    let isValid = true;

    if (!scheduleName.value.trim()) {
        showFieldError('scheduleName', 'Please type name');
        isValid = false;
    }

    if (!deviceGroup.value) {
        showFieldError('deviceGroup', 'Please select device');
        isValid = false;
    }

    if (!startDate.value) {
        showFieldError('startDate', 'Please select start date');
        isValid = false;
    }

    if (!endDate.value) {
        showFieldError('endDate', 'Please select end date');
        isValid = false;
    }

    // Helper function to parse DD/MM/YYYY format for validation
    function parseDateForValidation(dateStr) {
        if (!dateStr) return null;
        if (dateStr.includes('/')) {
            const parts = dateStr.split('/');
            if (parts.length === 3) {
                const day = parseInt(parts[0], 10);
                const month = parseInt(parts[1], 10) - 1;
                const year = parseInt(parts[2], 10);
                return new Date(year, month, day);
            }
        }
        return new Date(dateStr);
    }

    const startDateParsed = parseDateForValidation(startDate.value);
    const endDateParsed = parseDateForValidation(endDate.value);
    if (startDateParsed && endDateParsed && startDateParsed > endDateParsed) {
        showFieldError('endDate', 'End date must be after start date');
        isValid = false;
    }

    if (!startTime.value) {
        showFieldError('startTime', 'Please select start time');
        isValid = false;
    }

    if (!endTime.value) {
        showFieldError('endTime', 'Please select end time');
        isValid = false;
    }

    // Check if same date and validate times
    if (startDateParsed && endDateParsed &&
        startDateParsed.getTime() === endDateParsed.getTime() &&
        startTime.value && endTime.value && startTime.value >= endTime.value) {
        showFieldError('endTime', 'End time must be after start time');
        isValid = false;
    }

    if (!priority.value) {
        showFieldError('priority', 'Please select priority');
        isValid = false;
    }

    if (selectedWeekdays.length === 0) {
        showStatus('Please select at least one weekday', 'error');
        isValid = false;
    }

    if (selectedContents.length === 0) {
        showStatus('Please select at least one content', 'error');
        isValid = false;
    }

    if (!isValid) {
        showStatus('Please fill in all required fields correctly', 'error');
        return;
    }

    // Get selected device ID
    const selectedOption = deviceGroup.options[deviceGroup.selectedIndex];
    const deviceId = selectedOption.getAttribute('data-device-id') || deviceGroup.value;

    if (!deviceId) {
        showFieldError('deviceGroup', 'Device ID not found');
        return;
    }

    // Helper function to map weekday number to day name
    function getWeekdayName(dayValue) {
        const dayIndex = parseInt(dayValue);
        if (dayIndex >= 0 && dayIndex <= 6) {
            return getTranslation('weekdays', 'full', dayIndex);
        }
        return getTranslation('weekdays', 'full', 1); // Default to Monday
    }

    // Helper function to format date from DD/MM/YYYY (Flatpickr format) or YYYY-MM-DD to "Nov 4, 2025 00:00:00"
    function formatDateForSchedule(dateString) {
        if (!dateString) return '';

        // Parse DD/MM/YYYY format from Flatpickr
        let date;
        if (dateString.includes('/')) {
            const parts = dateString.split('/');
            if (parts.length === 3) {
                const day = parseInt(parts[0], 10);
                const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed
                const year = parseInt(parts[2], 10);
                date = new Date(year, month, day);
            } else {
                date = new Date(dateString);
            }
        } else {
            date = new Date(dateString + 'T00:00:00');
        }

        const monthName = getTranslation('months', 'short', date.getMonth());
        const day = date.getDate();
        const year = date.getFullYear();
        return `${monthName} ${day}, ${year} 00:00:00`;
    }

    // Create date_time array from selected weekdays
    const dateTimeArray = selectedWeekdays.map(dayValue => ({
        date: getWeekdayName(dayValue),
        start: startTime.value || '00:00',
        end: endTime.value || '00:00'
    }));

    // Get current timestamp for createdAt and updatedAt
    const now = new Date().toISOString();

    // Prepare schedule data in the required format for ThingsBoard
    const scheduleData = [{
        name: scheduleName.value.trim(),
        priority: priority.value || 'medium',
        contents: [{
            date_time: dateTimeArray,
            content: selectedContents.map(c => {
                const contentItem = c.data || {};

                const cleanContentItem = {};
                const contentItemFields = ['checksum', 'coordinate', 'createdAt', 'duration',
                    'file_name', 'file_size', 'touch_delay', 'type',
                    'URL', 'updatedAt'];

                contentItemFields.forEach(field => {
                    if (contentItem.hasOwnProperty(field)) {
                        cleanContentItem[field] = contentItem[field];
                    }
                });

                const condition = {
                    age_gte: c.ageFrom || 1,
                    age_lte: c.ageTo || 1
                };

                if (c.gender && c.gender !== '' && c.gender !== 'all') {
                    condition.gender = c.gender;
                }

                return {
                    condition: condition,
                    content_item: [cleanContentItem]
                };
            })
        }],
        createdAt: now,
        start_date: formatDateForSchedule(startDate.value),
        end_date: formatDateForSchedule(endDate.value),
        updatedAt: now,
        screen_type: 'fullscreen'
    }];

    // Submit schedule
    const createBtn = document.getElementById('createBtn');
    if (createBtn) {
        createBtn.disabled = true;
        createBtn.textContent = 'Creating...';
    }

    try {
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
            // // console.log('Using tenant username:', tenantUsername);
        }

        const response = await fetch(`${FLASK_SERVER}/api/update-device-content`, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({
                deviceId: deviceId,
                content: scheduleData
            })
        });

        const result = await response.json();

        if (result.success) {
            // // console.log('Schedule data sent to device:', scheduleData);
            showStatus('Schedule created and updated to device successfully!', 'success');

            setTimeout(() => {
                resetForm();
            }, 2000);
        } else {
            throw new Error(result.error || 'Failed to update device content');
        }

    } catch (error) {
        // // console.error('Error creating schedule:', error);
        showStatus('Error creating schedule: ' + error.message, 'error');
    } finally {
        if (createBtn) {
            createBtn.disabled = false;
            createBtn.textContent = 'Create';
        }
    }
}

function resetForm() {
    const form = document.getElementById('scheduleForm');
    if (form) {
        form.reset();
    }

    // Destroy date pickers
    if (startDatePicker) {
        startDatePicker.destroy();
        startDatePicker = null;
    }
    if (endDatePicker) {
        endDatePicker.destroy();
        endDatePicker = null;
    }

    // Reinitialize date pickers
    setTimeout(() => {
        initializeDatePickers();
    }, 100);

    // Reset device selection
    currentDeviceId = null;
    availableContent = [];

    // Reset custom selects
    const startTimeSelect = document.getElementById('startTimeSelect');
    const endTimeSelect = document.getElementById('endTimeSelect');
    if (startTimeSelect) {
        const valueSpan = startTimeSelect.querySelector('.custom-select-value');
        if (valueSpan) valueSpan.textContent = 'Select start time';
        startTimeSelect.classList.remove('open');
    }
    if (endTimeSelect) {
        const valueSpan = endTimeSelect.querySelector('.custom-select-value');
        if (valueSpan) valueSpan.textContent = 'Select end time';
        endTimeSelect.classList.remove('open');
    }

    selectedWeekdays = [];
    document.querySelectorAll('.weekday-toggle').forEach(toggle => {
        toggle.classList.remove('active');
    });

    selectedContents = [];
    updateContentDisplay();

    document.querySelectorAll('.error-message').forEach(el => {
        el.classList.remove('show');
        el.textContent = '';
    });

    const statusMessage = document.getElementById('statusMessage');
    if (statusMessage) {
        statusMessage.classList.remove('show');
    }

    document.querySelectorAll('input, select').forEach(field => {
        field.style.borderColor = '';
    });
}

function showStatus(message, type) {
    const statusMessage = document.getElementById('statusMessage');
    if (statusMessage) {
        statusMessage.textContent = message;
        statusMessage.className = `status-message ${type} show`;

        setTimeout(() => {
            statusMessage.classList.remove('show');
        }, 5000);
    }
}

// Close modal when clicking outside
window.addEventListener('click', function (e) {
    const contentModal = document.getElementById('contentModal');
    if (e.target === contentModal) {
        closeContentModalFunc();
    }
});

