descriptor.controllerScript:
self.onInit = function () {
  self.ctx.ngZone.run(function () {
    // form mặc định rỗng
    self.ctx.$scope.form = {
      command_service: '',
      name: '',
      version_code: '',
      version_name: '',
      main_launcher: '',
      serial: '',
      url: ''
    };
    self.ctx.$scope.selectedApkFile = null;
    self.ctx.$scope.selectedApkFileName = '';
    self.ctx.$scope.uploadingApk = false;
    self.ctx.$scope.apkUrl = '';
    self.ctx.$scope.apkUploadedSuccessfully = false; // Track if APK was uploaded successfully
    init();
    self.ctx.detectChanges();
  });
};

function init() {
  const s = self.ctx.settings || {};
  const scope = self.ctx.$scope;
  const $i = scope.$injector;

  // === Services ===
  const attributeService = $i.get(self.ctx.servicesMap.get('attributeService'));

  // === UI config ===
  scope.title = s.title || 'Update Device Attributes';
  scope.showTitle = !!(s.title && s.title.length);
  scope.buttonLabel = s.buttonText || 'Update';
  scope.statusMsg = '';
  //scope.error = '';
  scope.saving = false;

  // ===== LocalStorage Key =====
  const STORAGE_KEY = 'background_apk_config_state';

  // ===== Save state to localStorage =====
  function saveStateToStorage() {
    try {
      const state = {
        selectedDevice: currentDeviceId || '',
        form: scope.form,
        selectedApkFileName: scope.selectedApkFileName || '',
        apkUrl: scope.apkUrl || '',
        apkUploadedSuccessfully: scope.apkUploadedSuccessfully || false
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
      // // console.warn('Failed to save state to localStorage:', e);
    }
  }

  // ===== Load state from localStorage =====
  function loadStateFromStorage() {
    try {
      const savedState = localStorage.getItem(STORAGE_KEY);
      if (savedState) {
        const state = JSON.parse(savedState);
        return state;
      }
    } catch (e) {
      // // console.warn('Failed to load state from localStorage:', e);
    }
    return null;
  }

  // ===== Restore state =====
  function restoreState(savedState) {
    if (!savedState) return;

    // Restore form values
    if (savedState.form) {
      Object.keys(savedState.form).forEach(key => {
        if (scope.form.hasOwnProperty(key)) {
          scope.form[key] = savedState.form[key];
        }
      });
    }

    // Restore APK file name and URL
    if (savedState.selectedApkFileName) {
      scope.selectedApkFileName = savedState.selectedApkFileName;
    }
    if (savedState.apkUrl) {
      scope.apkUrl = savedState.apkUrl;
      // If we have a valid URL from saved state, mark as uploaded successfully
      if (savedState.apkUrl && savedState.apkUrl.startsWith('http')) {
        scope.apkUploadedSuccessfully = savedState.apkUploadedSuccessfully !== false;
      }
      updateUpdateDisabledState(); // Update button state
    }

    // Setup remove button listener if APK file was restored
    if (savedState.selectedApkFileName) {
      setTimeout(function () {
        setupRemoveButtonListener();
      }, 500);
    }

    // Device selection is now automatic, no need to restore
  }

  scope.styleButton = s.styleButton || { isPrimary: true, isRaised: true };
  scope.customStyle = (scope.styleButton.isPrimary === false)
    ? {
      'background-color': scope.styleButton.bgColor || '#e0e0e0',
      'color': scope.styleButton.textColor || '#000'
    }
    : {};

  // === Scope lưu trữ attributes của device đang bound ===
  const entityAttributeType = s.entityAttributeType || 'SERVER_SCOPE';
  const keyName = s.keyName || 'background';

  // Current device info (from datasource or defaultSubscription)
  let currentDeviceId = null;
  let currentDeviceName = null;

  // Empty form structure
  const emptyForm = {
    command_service: '',
    name: '',
    version_code: '',
    version_name: '',
    main_launcher: '',
    serial: '',
    url: ''
  };

  // === Helpers: entityId đang bound vào widget ===
  function boundEntityId() {
    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.targetDeviceId) {
      return { entityType: 'DEVICE', id: self.ctx.defaultSubscription.targetDeviceId };
    }
    return null;
  }

  // === Load attribute background for specific device ===
  function loadDeviceConfig(deviceId) {
    if (!deviceId) {
      scope.form = { ...emptyForm };
      scope.selectedApkFileName = '';
      scope.apkUrl = '';
      scope.apkUploadedSuccessfully = false;
      scope.statusMsg = '';
      //scope.error = '';
      updateUpdateDisabledState();
      self.ctx.detectChanges();
      return;
    }

    scope.statusMsg = 'Loading device config...';
    //scope.error = '';
    self.ctx.detectChanges();

    const eid = { entityType: 'DEVICE', id: deviceId };

    attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
      function success(resp) {
        if (resp && resp.length > 0 && resp[0].value) {
          try {
            const json = JSON.parse(resp[0].value);
            scope.form = { ...emptyForm, ...json };

            // Convert main_launcher boolean to string for dropdown
            if (scope.form.main_launcher === true || scope.form.main_launcher === 'true') {
              scope.form.main_launcher = 'true';
            } else if (scope.form.main_launcher === false || scope.form.main_launcher === 'false') {
              scope.form.main_launcher = 'false';
            } else {
              // Default to 'false' if no value
              scope.form.main_launcher = 'false';
            }

            // Restore APK info if exists
            if (scope.form.url && scope.form.url.startsWith('http')) {
              scope.apkUrl = scope.form.url;
              scope.apkUploadedSuccessfully = true;
              // Extract filename from URL
              const urlParts = scope.form.url.split('/');
              scope.selectedApkFileName = urlParts[urlParts.length - 1] || 'uploaded.apk';

              // Setup remove button
              setTimeout(function () {
                setupRemoveButtonListener();
              }, 100);
            } else {
              scope.selectedApkFileName = '';
              scope.apkUrl = '';
              scope.apkUploadedSuccessfully = false;
            }

            updateUpdateDisabledState();
            scope.statusMsg = '✅ Config loaded';
            //scope.error = '';

            // Clear status message after 2 seconds
            setTimeout(function () {
              self.ctx.ngZone.run(function () {
                scope.statusMsg = '';
                self.ctx.detectChanges();
              });
            }, 2000);
          } catch (e) {
            scope.form = { ...emptyForm };
            scope.selectedApkFileName = '';
            scope.apkUrl = '';
            scope.apkUploadedSuccessfully = false;
            updateUpdateDisabledState();
            scope.statusMsg = '';
            //scope.error = '⚠ Failed to parse config';
          }
        } else {
          // No config found for this device
          scope.form = { ...emptyForm };
          scope.selectedApkFileName = '';
          scope.apkUrl = '';
          scope.apkUploadedSuccessfully = false;
          updateUpdateDisabledState();
          scope.statusMsg = 'ℹ No config found for this device';
          //scope.error = '';

          // Clear status message after 2 seconds
          setTimeout(function () {
            self.ctx.ngZone.run(function () {
              scope.statusMsg = '';
              self.ctx.detectChanges();
            });
          }, 2000);
        }
        self.ctx.detectChanges();
      },
      function fail(error) {
        scope.form = { ...emptyForm };
        scope.selectedApkFileName = '';
        scope.apkUrl = '';
        scope.apkUploadedSuccessfully = false;
        updateUpdateDisabledState();
        scope.statusMsg = '';
        //scope.error = '⚠ Failed to load config: ' + (error.message || 'Unknown error');
        self.ctx.detectChanges();
      }
    );
  }

  // Don't auto-load on init - wait for user to select device
  scope.form = { ...emptyForm };
  updateUpdateDisabledState();

  // ===== Flask Server =====
  // Get from widget settings or use default
  const FLASK_SERVER = s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';

  // ===== Get Tenant Username (for multi-tenant support) =====
  function getTenantUsername() {
    try {
      // Try to get from ThingsBoard user context
      if (self.ctx.user && self.ctx.user.email) {
        return self.ctx.user.email;
      }
      // Try from userInfo
      if (self.ctx.userInfo && self.ctx.userInfo.email) {
        return self.ctx.userInfo.email;
      }
      // Try from $rootScope (ThingsBoard internal)
      const $rootScope = self.ctx.$scope.$root;
      if ($rootScope && $rootScope.currentUser && $rootScope.currentUser.email) {
        return $rootScope.currentUser.email;
      }
    } catch (e) {
      // // console.warn('Could not get tenant username:', e);
    }
    return null;
  }


  // ===== Load Device from Dashboard State =====
  function loadDeviceFromState() {
    if (!self.ctx || !self.ctx.stateController) {
      // console.warn('[background_apk] ⚠️ No stateController available');
      showNoDeviceState();
      return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

    // console.log('[background_apk] 📊 Loading device from state:', { deviceMode, stateParams });

    if (deviceMode === 'ALL') {
      // console.log('[background_apk] 📋 ALL devices mode - disabling upload');
      showAllDevicesMode();
      return;
    }

    if (deviceMode === 'SINGLE') {
      const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
      const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'Device';

      // console.log('[background_apk] 📱 SINGLE device mode:', deviceName, deviceId);

      if (deviceId) {
        loadDeviceById(deviceId, deviceName);
      } else {
        showNoDeviceState();
      }
      return;
    }

    // console.log('[background_apk] ⚠️ No device mode or NONE mode');
    showNoDeviceState();
  }

  function loadDeviceById(deviceId, deviceName) {
    currentDeviceId = deviceId;
    currentDeviceName = deviceName;
    // console.log(`[background_apk] ✅ Device selected: ${deviceName} (${deviceId})`);

    // Clear any previous error messages
    scope.error = '';

    enableUpload();
    loadDeviceConfig(deviceId);
  }


  function showAllDevicesMode() {
    currentDeviceId = '__ALL__';
    currentDeviceName = 'All Devices';
    scope.form = { ...emptyForm };
    scope.selectedApkFileName = '';
    scope.apkUrl = '';
    scope.apkUploadedSuccessfully = false;
    scope.statusMsg = '';
    scope.error = '⚠️ Cannot update APK in "All Devices". Please select a single device.';
    disableUpload();
    updateUpdateDisabledState();
    self.ctx.detectChanges();
  }

  function showNoDeviceState() {
    currentDeviceId = null;
    currentDeviceName = null;
    scope.form = { ...emptyForm };
    scope.selectedApkFileName = '';
    scope.apkUrl = '';
    scope.apkUploadedSuccessfully = false;
    scope.statusMsg = '';
    scope.error = '⚠️ No device selected. Please select a device from the store selector.';
    disableUpload();
    updateUpdateDisabledState();
    self.ctx.detectChanges();
  }


  function enableUpload() {
    const apkBrowseBtn = getElement('apkBrowseBtn');
    if (apkBrowseBtn) {
      apkBrowseBtn.disabled = false;
      apkBrowseBtn.style.opacity = '1';
      apkBrowseBtn.style.cursor = 'pointer';
    }
    const apkFileInput = getElement('apkFileInput');
    if (apkFileInput) apkFileInput.disabled = false;
    scope.clearAllDisabled = false;
  }

  function disableUpload() {
    const apkBrowseBtn = getElement('apkBrowseBtn');
    if (apkBrowseBtn) {
      apkBrowseBtn.disabled = true;
      apkBrowseBtn.style.opacity = '0.5';
      apkBrowseBtn.style.cursor = 'not-allowed';
    }
    const apkFileInput = getElement('apkFileInput');
    if (apkFileInput) apkFileInput.disabled = true;
    scope.updateDisabled = true;
    scope.clearAllDisabled = true;
  }

  function getElement(id) {
    if (self.ctx.$container && self.ctx.$container[0]) {
      return self.ctx.$container[0].querySelector(`#${id}`);
    }
    return document.getElementById(id);
  }

  if (self.ctx.stateController) {
    // console.log('[background_apk] ✅ Setting up dashboard state listener');
    let stateChangeTimeout;
    self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
      // console.log('[background_apk] 📡 Dashboard state changed');
      if (stateChangeTimeout) clearTimeout(stateChangeTimeout);
      stateChangeTimeout = setTimeout(function () {
        // console.log('[background_apk] ⏳ Debounce complete, reloading device...');
        self.ctx.ngZone.run(function () {
          loadDeviceFromState();
        });
      }, 200);
    });
  } else {
    // console.warn('[background_apk] ⚠️ No stateController available for subscription');
  }

  setTimeout(function () {
    loadDeviceFromState();
  }, 300);


  // Reload when widget data updates
  self.onDataUpdated = function () {
    // console.log('[background_apk] 📊 Widget data updated');
    self.ctx.ngZone.run(function () {
      loadDeviceFromState();
      self.ctx.detectChanges();
    });
  };

  // Cleanup when widget is destroyed
  self.onDestroy = function () {
    if (self.stateChangeSubscription) {
      self.stateChangeSubscription.unsubscribe();
      self.stateChangeSubscription = null;
      // console.log('[background_apk] ✅ Unsubscribed from state changes');
    }
  };


  function uploadApkFile(file) {
    // Get selected device ID from currentDeviceId
    if (!currentDeviceId) {
      //scope.error = '⚠ No device selected. Please configure device in widget datasource or dashboard entity selection.';
      scope.uploadingApk = false;
      self.ctx.detectChanges();
      return;
    }

    const deviceId = currentDeviceId;
    const deviceName = currentDeviceName || 'Unknown';

    if (!deviceId) {
      //scope.error = '⚠ Device ID not found.';
      scope.uploadingApk = false;
      self.ctx.detectChanges();
      return;
    }

    const formData = new FormData();
    formData.append('apk', file);
    formData.append('apkType', 'background');
    formData.append('deviceId', deviceId);
    formData.append('deviceName', deviceName);

    fetch(`${FLASK_SERVER}/upload-apk`, {
      method: 'POST',
      body: formData
    })
      .then(function (response) {
        return response.json();
      })
      .then(function (data) {
        self.ctx.ngZone.run(function () {
          if (data.success) {
            scope.apkUrl = data.apkUrl;
            scope.form.url = data.apkUrl; // Lưu URL vào form
            scope.uploadingApk = false;
            scope.apkUploadedSuccessfully = true; // Mark as uploaded successfully
            scope.statusMsg = '✅ APK uploaded successfully!';
            //scope.error = '';
            updateUpdateDisabledState(); // Update button state
            self.ctx.detectChanges();

            // Save state after successful upload
            setTimeout(function () {
              saveStateToStorage();
            }, 100);
          } else {
            scope.uploadingApk = false;
            scope.apkUploadedSuccessfully = false; // Mark as not uploaded
            scope.statusMsg = '';
            //scope.error = '⚠ Upload failed: ' + (data.error || 'Unknown error');
            updateUpdateDisabledState(); // Update button state
            self.ctx.detectChanges();
          }
        });
      })
      .catch(function (error) {
        self.ctx.ngZone.run(function () {
          scope.uploadingApk = false;
          scope.apkUploadedSuccessfully = false; // Mark as not uploaded
          scope.statusMsg = '';
          //scope.error = '⚠ Upload error: ' + error.message;
          updateUpdateDisabledState(); // Update button state
          self.ctx.detectChanges();
        });
      });
  }

  // ===== APK File Selection =====
  // Function to setup remove button listener
  function setupRemoveButtonListener() {
    let removeBtn = null;
    if (self.ctx.$container && self.ctx.$container[0]) {
      removeBtn = self.ctx.$container[0].querySelector('#apkRemoveBtn');
    }
    if (!removeBtn) {
      removeBtn = document.getElementById('apkRemoveBtn');
    }

    if (removeBtn) {
      // Remove existing listeners by cloning the button
      const newRemoveBtn = removeBtn.cloneNode(true);
      removeBtn.parentNode.replaceChild(newRemoveBtn, removeBtn);

      // Add click listener
      newRemoveBtn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        self.ctx.ngZone.run(function () {
          scope.clearApkFile();
        });
      });
    }
  }

  // Setup APK file picker similar to content widget
  self.ctx.ngZone.run(function () {
    setTimeout(function () {
      // Find elements within widget container to avoid ID conflicts
      let apkBrowseBtn = null;
      let apkFileInput = null;
      let apkRemoveBtn = null;
      if (self.ctx.$container && self.ctx.$container[0]) {
        apkBrowseBtn = self.ctx.$container[0].querySelector('#apkBrowseBtn');
        apkFileInput = self.ctx.$container[0].querySelector('#apkFileInput');
        apkRemoveBtn = self.ctx.$container[0].querySelector('#apkRemoveBtn');
      }
      if (!apkBrowseBtn) {
        apkBrowseBtn = document.getElementById('apkBrowseBtn');
      }
      if (!apkFileInput) {
        apkFileInput = document.getElementById('apkFileInput');
      }
      if (!apkRemoveBtn) {
        apkRemoveBtn = document.getElementById('apkRemoveBtn');
      }

      if (apkBrowseBtn && apkFileInput) {
        // Browse button click handler
        apkBrowseBtn.addEventListener('click', function (e) {
          e.preventDefault();
          e.stopPropagation();
          apkFileInput.click();
        });

        // File input change handler
        apkFileInput.addEventListener('change', function (e) {
          if (e.target.files.length > 0) {
            const file = e.target.files[0];
            if (file) {
              self.ctx.ngZone.run(function () {
                scope.selectedApkFile = file;
                scope.selectedApkFileName = file.name;
                scope.uploadingApk = true;
                scope.statusMsg = 'Uploading APK...';
                updateUpdateDisabledState(); // Update button state
                self.ctx.detectChanges();

                // Upload APK to server
                uploadApkFile(file);

                // Save state after file selection
                setTimeout(function () {
                  saveStateToStorage();
                }, 100);

                // Setup remove button listener after file is selected
                setTimeout(function () {
                  setupRemoveButtonListener();
                }, 100);
              });
            }
          }
        });
      }

      // Setup remove button listener if button exists
      if (apkRemoveBtn) {
        setupRemoveButtonListener();
      }

      // Retry if elements not found yet
      if (!apkBrowseBtn || !apkFileInput) {
        setTimeout(function () {
          let retryBrowseBtn = null;
          let retryFileInput = null;
          if (self.ctx.$container && self.ctx.$container[0]) {
            retryBrowseBtn = self.ctx.$container[0].querySelector('#apkBrowseBtn');
            retryFileInput = self.ctx.$container[0].querySelector('#apkFileInput');
          }
          if (!retryBrowseBtn) {
            retryBrowseBtn = document.getElementById('apkBrowseBtn');
          }
          if (!retryFileInput) {
            retryFileInput = document.getElementById('apkFileInput');
          }

          if (retryBrowseBtn && retryFileInput) {
            retryBrowseBtn.addEventListener('click', function (e) {
              e.preventDefault();
              e.stopPropagation();
              retryFileInput.click();
            });

            retryFileInput.addEventListener('change', function (e) {
              if (e.target.files.length > 0) {
                const file = e.target.files[0];
                if (file) {
                  self.ctx.ngZone.run(function () {
                    scope.selectedApkFile = file;
                    scope.selectedApkFileName = file.name;
                    scope.uploadingApk = true;
                    scope.statusMsg = 'Uploading APK...';
                    updateUpdateDisabledState(); // Update button state
                    self.ctx.detectChanges();

                    // Upload APK to server
                    uploadApkFile(file);

                    // Save state after file selection
                    setTimeout(function () {
                      saveStateToStorage();
                    }, 100);

                    // Setup remove button listener after file is selected
                    setTimeout(function () {
                      setupRemoveButtonListener();
                    }, 100);
                  });
                }
              }
            });
          }
        }, 300);
      }
    }, 200);
  });

  // ===== Watch form changes and save to localStorage =====
  scope.saveFormState = function () {
    saveStateToStorage();
  };

  // Note: We use ng-change on all input fields and event listeners for device select
  // This is more efficient than polling since $watch is not available in ThingsBoard widget context

  // ===== Buttons =====
  // Computed property for Update button disabled state
  function updateUpdateDisabledState() {
    // Disable only when uploading APK
    scope.updateDisabled = scope.uploadingApk;
  }

  // Initialize updateDisabled state
  scope.updateDisabled = false; // Start enabled
  scope.clearAllDisabled = false;


  scope.resetToTemplate = function () {
    scope.form = { ...emptyForm };
    scope.statusMsg = 'Form reset.';
    //scope.error = '';
    scope.apkUploadedSuccessfully = false; // Reset upload status
    updateUpdateDisabledState(); // Update button state
    // Clear saved state
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      // // console.warn('Failed to clear localStorage:', e);
    }
    self.ctx.detectChanges();
  };

  // Clear APK file only (keep other configs)
  scope.clearApkFile = function () {
    // Confirm with user before clearing
    if (!confirm('Are you sure you want to remove the APK file? This will only remove the file, other configurations will be kept.')) {
      return;
    }

    // Clear APK file related data
    scope.selectedApkFile = null;
    scope.selectedApkFileName = '';
    scope.apkUrl = '';
    scope.apkUploadedSuccessfully = false;
    scope.uploadingApk = false;

    // Clear URL from form if it exists
    if (scope.form.url) {
      scope.form.url = '';
    }

    // Clear file input value
    let apkFileInput = null;
    if (self.ctx.$container && self.ctx.$container[0]) {
      apkFileInput = self.ctx.$container[0].querySelector('#apkFileInput');
    }
    if (!apkFileInput) {
      apkFileInput = document.getElementById('apkFileInput');
    }
    if (apkFileInput) {
      apkFileInput.value = '';
    }

    // Update button state
    updateUpdateDisabledState();

    // Save state after clearing APK
    setTimeout(function () {
      saveStateToStorage();
    }, 100);

    self.ctx.detectChanges();
  };

  // Clear all: APK file, device selection, and all config
  scope.clearAll = function () {
    // Confirm with user before clearing all
    if (!confirm('Are you sure you want to clear all configurations? This will remove the APK file, device selection, and all form fields.')) {
      return;
    }

    const deviceId = currentDeviceId;

    // If device is selected, update shared attribute to empty JSON first
    if (deviceId) {
      scope.saving = true;
      updateUpdateDisabledState();
      scope.statusMsg = 'Clearing...';
      //scope.error = '';

      // Get tenant username for multi-tenant support
      const tenantUsername = getTenantUsername();

      // Prepare headers with tenant info (if available)
      const headers = {
        'Content-Type': 'application/json'
      };
      if (tenantUsername) {
        headers['X-TB-Tenant-Username'] = tenantUsername;
      }

      // Update shared attribute to empty JSON {} via API
      fetch(`${FLASK_SERVER}/api/update-device-background`, {
        method: 'POST',
        headers: headers,
        body: JSON.stringify({
          deviceId: deviceId,
          background: {}
        })
      })
        .then(function (response) {
          return response.json();
        })
        .then(function (data) {
          self.ctx.ngZone.run(function () {
            scope.saving = false;
            updateUpdateDisabledState();
            if (data.success) {
              scope.statusMsg = '✅ Cleared successfully!';
            } else {
              scope.statusMsg = '';
              //scope.error = '⚠ Clear failed: ' + (data.error || 'Unknown error');
            }
            // Continue with local clearing regardless of API result
            clearLocalState();
          });
        })
        .catch(function (error) {
          self.ctx.ngZone.run(function () {
            scope.saving = false;
            updateUpdateDisabledState();
            scope.statusMsg = '';
            //scope.error = '⚠ Clear error: ' + error.message;
            // Continue with local clearing regardless of API error
            clearLocalState();
          });
        });
    } else {
      // No device selected, just clear local state
      clearLocalState();
    }

    // Function to clear local state
    function clearLocalState() {
      // Reset form to empty values (not template)
      scope.form = {
        command_service: '',
        name: '',
        version_code: '',
        version_name: '',
        main_launcher: '',
        serial: '',
        url: ''
      };

      // Clear APK file related data
      scope.selectedApkFile = null;
      scope.selectedApkFileName = '';
      scope.apkUrl = '';
      scope.apkUploadedSuccessfully = false;
      scope.uploadingApk = false;

      // Clear file input value
      let apkFileInput = null;
      if (self.ctx.$container && self.ctx.$container[0]) {
        apkFileInput = self.ctx.$container[0].querySelector('#apkFileInput');
      }
      if (!apkFileInput) {
        apkFileInput = document.getElementById('apkFileInput');
      }
      if (apkFileInput) {
        apkFileInput.value = '';
      }

      // Clear status messages (if not already set by API call)
      if (!scope.statusMsg && !scope.error) {
        scope.statusMsg = '';
        //scope.error = '';
      }

      // Update button state
      updateUpdateDisabledState();

      // Clear localStorage
      try {
        localStorage.removeItem(STORAGE_KEY);
      } catch (e) {
        // // console.warn('Failed to clear localStorage:', e);
      }

      self.ctx.detectChanges();
    }
  };

  // Save toàn bộ form về 1 key background
  scope.save = function () {
    scope.statusMsg = '';
    //scope.error = '';

    if (!currentDeviceId) {
      //scope.error = '⚠ No device selected. Please configure device in widget datasource or dashboard entity selection.';
      self.ctx.detectChanges();
      return;
    }

    const deviceId = currentDeviceId;
    const deviceName = currentDeviceName || 'Unknown';

    if (!deviceId) {
      //scope.error = '⚠ Device ID not found.';
      self.ctx.detectChanges();
      return;
    }

    // Validate: APK must be uploaded successfully before allowing save
    if (!scope.apkUploadedSuccessfully && (!scope.form.url || !scope.form.url.startsWith('http'))) {
      //scope.error = '⚠ Please upload APK file successfully before saving.';
      self.ctx.detectChanges();
      return;
    }

    // If APK was uploaded successfully, ensure URL is set
    if (scope.apkUploadedSuccessfully && scope.apkUrl) {
      scope.form.url = scope.apkUrl;
    }

    scope.saving = true;
    updateUpdateDisabledState();

    const formData = {
      command_service: scope.form.command_service || '',
      name: scope.form.name || '',
      version_code: scope.form.version_code || '',
      version_name: scope.form.version_name || '',
      main_launcher: scope.form.main_launcher === 'true' || scope.form.main_launcher === true,
      serial: deviceName, // Use device name as serial
      url: scope.form.url || ''
    };

    if (typeof formData.version_code === 'string' && formData.version_code !== '') {
      formData.version_code = parseInt(formData.version_code) || 0;
    }

    // Get tenant username for multi-tenant support
    const tenantUsername = getTenantUsername();

    // Prepare headers with tenant info (if available)
    const headers = {
      'Content-Type': 'application/json'
    };
    if (tenantUsername) {
      headers['X-TB-Tenant-Username'] = tenantUsername;
      // // console.log('Using tenant username:', tenantUsername);
    }

    fetch(`${FLASK_SERVER}/api/update-device-background`, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify({
        deviceId: deviceId,
        background: formData
      })
    })
      .then(function (response) {
        return response.json();
      })
      .then(function (data) {
        self.ctx.ngZone.run(function () {
          scope.saving = false;
          updateUpdateDisabledState(); // Update button state
          if (data.success) {
            scope.statusMsg = '✅ Updated successfully!';
            //scope.error = '';
            // Save state after successful save
            saveStateToStorage();
          } else {
            scope.statusMsg = '';
            //scope.error = '⚠ Update failed: ' + (data.error || 'Unknown error');
          }
          self.ctx.detectChanges();
        });
      })
      .catch(function (error) {
        self.ctx.ngZone.run(function () {
          scope.saving = false;
          updateUpdateDisabledState(); // Update button state
          scope.statusMsg = '';
          //scope.error = '⚠ Update error: ' + error.message;
          self.ctx.detectChanges();
        });
      });
  };
}

