}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-50%) translateY(-30px);
    }
    to {
        opacity: 1;
        transform: translateY(-50%);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
