    border-radius: 10px 10px 0 0;
}

.modal-header h3 {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
}

.close {
    color: white;
    font-size: 26px;
    font-weight: 300;
    cursor: pointer;
    line-height: 1;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.2s ease;
}

.close:hover {
    background-color: rgba(255, 255, 255, 0.2);
    transform: rotate(90deg);
}

.modal-body {
    padding: 20px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}

.modal-footer {
    padding: 16px 20px;
    border-top: 1px solid #e0e0e0;
    background-color: #fafafa;
    border-radius: 0 0 10px 10px;
}

/* Form Styles */
.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 14px;
}

.form-group {
    margin-bottom: 14px;
}

.form-row .form-group {
    margin-bottom: 0;
}

.form-group label {
    display: block;
    margin-bottom: 6px;
    font-weight: 600;
    color: #495057;
    font-size: 13px;
}

.form-group label .required {
    color: #dc3545;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 9px 12px;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 13px;
    font-family: inherit;
    background-color: #fafafa;
    transition: all 0.2s ease;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #667eea;
    background-color: white;
    box-shadow: 0 0 0 2px rgba(102, 126, 234, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 70px;
}

.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.btn {
    padding: 9px 18px;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 13px;
    font-weight: 500;
    transition: all 0.2s ease;
    min-width: 90px;
}

.btn-primary {
    background-color: #2196F3;
    color: white;
    box-shadow: 0 2px 4px rgba(33, 150, 243, 0.2);
}

.btn-primary:hover {
    background-color: #1976D2;
    transform: translateY(-1px);
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background-color: #5a6268;
    transform: translateY(-1px);
}

.btn-danger {
    background-color: #dc3545;
    color: white;
    box-shadow: 0 2px 4px rgba(220, 53, 69, 0.2);
}

.btn-danger:hover {
    background-color: #c82333;
    transform: translateY(-1px);
}

.btn:disabled {
    background-color: #e9ecef;
    color: #adb5bd;
    cursor: not-allowed;
    transform: none;
}

/* Scrollbar */
.modal-body::-webkit-scrollbar,
.table-container::-webkit-scrollbar {
    width: 8px;
}

.modal-body::-webkit-scrollbar-track,
.table-container::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 4px;
}

.modal-body::-webkit-scrollbar-thumb,
.table-container::-webkit-scrollbar-thumb {
    background: #c1c1c1;
    border-radius: 4px;
}

.modal-body::-webkit-scrollbar-thumb:hover,
.table-container::-webkit-scrollbar-thumb:hover {
    background: #a8a8a8;
}

/* Responsive */
@media (max-width: 768px) {
    .content-view-container {
        padding: 12px;
    }

    .filter-section {
        padding: 12px;
    }

    .form-row {
        grid-template-columns: 1fr;
        gap: 14px;
    }

    .pagination-container {
        flex-direction: column;
        align-items: stretch;
    }

    .pagination-controls {
        justify-content: center;
    }

    .modal-content {
        width: 95%;
        top: 5%;
        transform: none;
        max-height: 90vh;
    }

    @keyframes slideDown {
        from {
            opacity: 0;
            transform: translateY(-30px);
        }   
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
}

descriptor.controllerScript:
self.onInit = function () {
  self.ctx.ngZone.run(function () {
    init();
    self.ctx.detectChanges();
  });
};

function init() {
  const s = self.ctx.settings || {};
  const scope = self.ctx.$scope;
  const $i = scope.$injector;

  // === Services ===
  const attributeService = $i.get(self.ctx.servicesMap.get('attributeService'));

  // === UI config ===
  scope.title = s.title || 'キオスク表示';
  scope.showTitle = !!(s.title && s.title.length);
  scope.statusMsg = '';
  scope.error = '';

  // Data storage
  let deviceConfigs = {
    ad2u: null,
    background: null,
    statistic: null
  };
  let allData = []; // All data before filtering
  let filteredData = []; // Data after filtering
  let currentDeviceId = null; // Current device ID from datasource
  let currentPage = 1;
  const ROWS_PER_PAGE = 10;

  // ===== LocalStorage Key =====
  const STORAGE_KEY = 'kiosk_view_state';

  // ===== Get last selected device =====
  function getLastSelectedDevice() {
    try {
      return localStorage.getItem('kiosk_view_last_selected_device') || '';
    } catch (e) {
      return '';
    }
  }

  // ===== Save last selected device =====
  function saveLastSelectedDevice(deviceId) {
    try {
      localStorage.setItem('kiosk_view_last_selected_device', deviceId || '');
    } catch (e) {
      // // console.warn('Failed to save last selected device:', e);
    }
  }

  // ===== Show status message =====
  function showStatus(message, type) {
    const statusEl = document.getElementById('statusMessage');
    if (!statusEl) return;

    if (!message) {
      statusEl.style.display = 'none';
      return;
    }

    statusEl.textContent = message;
    statusEl.className = `status-message ${type || 'success'}`;
    statusEl.style.display = 'block';

    if (type !== 'error') {
      setTimeout(function () {
        if (statusEl) {
          statusEl.style.display = 'none';
        }
      }, 3000);
    }
  }

  // ===== Create loading spinner HTML =====
  function getLoadingSpinnerHTML(message) {
    const loadingText = message || '設定を読み込み中...';
    return '<tr class="empty-row"><td colspan="3"><div class="loading-container"><div class="loading-spinner"></div><div class="loading-text">' + loadingText + '</div></div></td></tr>';
  }

  // ===== Show loading spinner in table =====
  function showLoadingSpinner(message) {
    const tbody = document.getElementById('kioskTableBody');
    if (tbody) {
      tbody.innerHTML = getLoadingSpinnerHTML(message);
    }
  }

  // ===== Hide loading spinner (no longer needed, but kept for compatibility) =====
  function hideLoadingSpinner() {
    // Spinner is now part of table, will be replaced by renderTable()
  }

  // ===== Load device configs from SHARED_SCOPE =====
  function loadDeviceConfigs(deviceId) {
    if (!deviceId) {
      deviceConfigs = {
        ad2u: null,
        background: null,
        statistic: null
      };
      renderTable();
      return;
    }

    showLoadingSpinner('設定を読み込み中...');
    self.ctx.detectChanges();

    const eid = { entityType: 'DEVICE', id: deviceId };
    const keys = ['ad2u', 'background', 'statistic'];

    // Load all three configs in parallel
    Promise.all(keys.map(key => {
      return new Promise((resolve) => {
        attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [key]).subscribe(
          function success(resp) {
            // // console.log(`Response for ${key}:`, resp);
            if (resp && resp.length > 0 && resp[0].value) {
              try {
                const json = JSON.parse(resp[0].value);
                // // console.log(`Parsed ${key} config:`, json);
                resolve({ key, data: json });
              } catch (e) {
                // // console.warn(`Failed to parse ${key} config:`, e, 'Raw value:', resp[0].value);
                resolve({ key, data: null });
              }
            } else {
              // // console.log(`No data found for ${key}`);
              resolve({ key, data: null });
            }
          },
          function fail(error) {
            // // console.error(`Failed to load ${key} config:`, error);
            resolve({ key, data: null });
          }
        );
      });
    })).then(function (results) {
      self.ctx.ngZone.run(function () {
        // Reset configs
        deviceConfigs = {
          ad2u: null,
          background: null,
          statistic: null
        };

        // Set loaded configs
        results.forEach(function (result) {
          // // console.log(`Loaded ${result.key}:`, result.data);
          // Check if data exists and is not an empty object
          if (result.data && typeof result.data === 'object' && Object.keys(result.data).length > 0) {
            deviceConfigs[result.key] = result.data;
          } else if (result.data && typeof result.data === 'object' && Object.keys(result.data).length === 0) {
            // // console.log(`${result.key} is an empty object, skipping`);
            deviceConfigs[result.key] = null;
          } else {
            deviceConfigs[result.key] = null;
          }
        });

        // // console.log('Device configs after loading:', deviceConfigs);

        // Build table data
        buildTableData();
        // // console.log('All data after build:', allData);
        // // console.log('Filtered data:', filteredData);
        renderTable();

        hideLoadingSpinner();
        self.ctx.detectChanges();
      });
    }).catch(function (error) {
      self.ctx.ngZone.run(function () {
        // // console.error('Error loading device configs:', error);
        hideLoadingSpinner();
        showStatus('⚠ 設定の読み込みに失敗しました', 'error');
        self.ctx.detectChanges();
      });
    });
  }

  // ===== Check if config has valid data =====
  function hasValidConfig(config) {
    if (!config || typeof config !== 'object') {
      return false;
    }
    // Check if object is empty
    if (Object.keys(config).length === 0) {
      return false;
    }
    // Check if at least one of the required fields exists
    return config.name !== undefined ||
      config.version_code !== undefined ||
      config.version_name !== undefined;
  }

  // ===== Build table data from configs =====
  function buildTableData() {
    allData = [];

    // Add ad2u config only if it has valid data
    if (hasValidConfig(deviceConfigs.ad2u)) {
      const ad2uData = {
        key: 'ad2u',
        name: deviceConfigs.ad2u.name || 'N/A',
        version_code: deviceConfigs.ad2u.version_code !== undefined && deviceConfigs.ad2u.version_code !== null ? deviceConfigs.ad2u.version_code : 'N/A',
        version_name: deviceConfigs.ad2u.version_name || 'N/A'
      };
      // // console.log('Adding ad2u data:', ad2uData);
      allData.push(ad2uData);
    } else {
      // // console.log('No valid ad2u config found (empty or null)');
    }

    // Add background config only if it has valid data
    if (hasValidConfig(deviceConfigs.background)) {
      const bgData = {
        key: 'background',
        name: deviceConfigs.background.name || 'N/A',
        version_code: deviceConfigs.background.version_code !== undefined && deviceConfigs.background.version_code !== null ? deviceConfigs.background.version_code : 'N/A',
        version_name: deviceConfigs.background.version_name || 'N/A'
      };
      // // console.log('Adding background data:', bgData);
      allData.push(bgData);
    } else {
      // // console.log('No valid background config found (empty or null)');
    }

    // Add statistic config only if it has valid data
    if (hasValidConfig(deviceConfigs.statistic)) {
      const statData = {
        key: 'statistic',
        name: deviceConfigs.statistic.name || 'N/A',
        version_code: deviceConfigs.statistic.version_code !== undefined && deviceConfigs.statistic.version_code !== null ? deviceConfigs.statistic.version_code : 'N/A',
        version_name: deviceConfigs.statistic.version_name || 'N/A'
      };
      // // console.log('Adding statistic data:', statData);
      allData.push(statData);
    } else {
      // // console.log('No valid statistic config found (empty or null)');
    }

    // Apply filter
    filterData();
  }

  // ===== Filter data based on search =====
  function filterData() {
    const searchInput = document.getElementById('searchInput');
    const searchTerm = searchInput ? searchInput.value.toLowerCase().trim() : '';

    if (!searchTerm) {
      // No search term, show all data
      filteredData = allData.slice();
    } else {
      // Filter by name
      filteredData = allData.filter(function (item) {
        const name = (item.name || '').toLowerCase();
        return name.includes(searchTerm);
      });
    }
  }

  // ===== Render table =====
  function renderTable() {
    const tbody = document.getElementById('kioskTableBody');
    if (!tbody) return;

    tbody.innerHTML = '';

    if (!currentDeviceId) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="3"><div class="loading-container"><div class="loading-text">デバイスが選択されていません。ウィジェットのデータソースでデバイスを設定してください。</div></div></td></tr>';
      renderPagination();
      return;
    }

    if (filteredData.length === 0) {
      const searchInput = document.getElementById('searchInput');
      const hasSearchTerm = searchInput && searchInput.value.trim().length > 0;
      const message = hasSearchTerm
        ? '検索条件に一致する設定がありません。'
        : 'このデバイスの設定が見つかりません。';
      tbody.innerHTML = '<tr class="empty-row"><td colspan="3" class="empty-message">' + message + '</td></tr>';
      renderPagination();
      return;
    }

    // Calculate pagination
    const totalItems = filteredData.length;
    const totalPages = Math.ceil(totalItems / ROWS_PER_PAGE);
    const startIndex = (currentPage - 1) * ROWS_PER_PAGE;
    const endIndex = Math.min(startIndex + ROWS_PER_PAGE, totalItems);

    // Render only current page items
    const pageItems = filteredData.slice(startIndex, endIndex);

    pageItems.forEach(function (item) {
      const row = document.createElement('tr');

      const nameCell = document.createElement('td');
      nameCell.style.textAlign = 'left';
      nameCell.textContent = item.name || 'N/A';
      row.appendChild(nameCell);

      const versionCodeCell = document.createElement('td');
      versionCodeCell.style.textAlign = 'center';
      versionCodeCell.textContent = item.version_code !== undefined && item.version_code !== null ? item.version_code : 'N/A';
      row.appendChild(versionCodeCell);

      const versionNameCell = document.createElement('td');
      versionNameCell.style.textAlign = 'center';
      versionNameCell.textContent = item.version_name || 'N/A';
      row.appendChild(versionNameCell);

      tbody.appendChild(row);
    });

    renderPagination();
  }

  // ===== Render pagination controls =====
  function renderPagination() {
    const totalItems = filteredData.length;
    const totalPages = Math.ceil(totalItems / ROWS_PER_PAGE);
    const startIndex = totalItems === 0 ? 0 : (currentPage - 1) * ROWS_PER_PAGE + 1;
    const endIndex = Math.min(currentPage * ROWS_PER_PAGE, totalItems);

    const paginationText = document.getElementById('paginationText');
    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');
    const pageNumbersContainer = document.getElementById('pageNumbers');

    if (!paginationText || !prevBtn || !nextBtn || !pageNumbersContainer) return;

    paginationText.textContent = totalItems + '件中 ' + startIndex + ' から ' + endIndex + ' を表示';
    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;
    pageNumbersContainer.innerHTML = '';

    if (totalPages === 0) return;

    let startPage = Math.max(1, currentPage - 2);
    let endPage = Math.min(totalPages, startPage + 4);

    if (endPage - startPage < 4) {
      startPage = Math.max(1, endPage - 4);
    }

    for (let i = startPage; i <= endPage; i++) {
      const pageBtn = document.createElement('button');
      pageBtn.className = 'page-number';
      if (i === currentPage) {
        pageBtn.classList.add('active');
      }
      pageBtn.textContent = i;
      pageBtn.addEventListener('click', function () {
        goToPage(i);
      });
      pageNumbersContainer.appendChild(pageBtn);
    }
  }

  // ===== Navigate to page =====
  function goToPage(page) {
    const totalPages = Math.ceil(filteredData.length / ROWS_PER_PAGE);
    if (page < 1 || page > totalPages) return;
    currentPage = page;
    renderTable();
  }


  // ===== Load Device from Dashboard State =====
  function loadDeviceFromState() {
    if (!self.ctx || !self.ctx.stateController) {
      // console.warn('[kiosk_view_JP] ⚠️ No stateController available');
      showNoDeviceState();
      return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

    // console.log('[kiosk_view_JP] 📊 Loading device from state:', { deviceMode, stateParams });

    if (deviceMode === 'ALL') {
      // console.log('[kiosk_view_JP] 📋 ALL devices mode - aggregating configs');
      showAllDevicesMode();
      return;
    }

    if (deviceMode === 'SINGLE') {
      const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
      const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'Device';

      // console.log('[kiosk_view_JP] 📱 SINGLE device mode:', deviceName, deviceId);

      if (deviceId) {
        loadDeviceById(deviceId, deviceName);
      } else {
        showNoDeviceState();
      }
      return;
    }

    // console.log('[kiosk_view_JP] ⚠️ No device mode or NONE mode');
    showNoDeviceState();
  }

  function loadDeviceById(deviceId, deviceName) {
    currentDeviceId = deviceId;
    // console.log(`[kiosk_view_JP] ✅ Device selected: ${deviceName} (${deviceId})`);
    saveLastSelectedDevice(deviceId);
    loadDeviceConfigs(deviceId);
  }

  function showAllDevicesMode() {
    currentDeviceId = '__ALL__';
    const stateParams = self.ctx.stateController.getStateParams();
    const entities = stateParams?.entities || stateParams?.entityIds || [];

    if (entities.length === 0) {
      showNoDeviceState();
      return;
    }

    showLoadingSpinner('すべてのデバイスの設定を読み込み中...');

    const keys = ['ad2u', 'background', 'statistic'];
    const configPromises = entities.map(entity => {
      const deviceId = entity.id;
      const deviceName = entity.name || 'Unknown';
      const eid = { entityType: 'DEVICE', id: deviceId };

      return Promise.all(keys.map(key => {
        return new Promise((resolve) => {
          attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [key]).subscribe(
            resp => {
              if (resp && resp.length > 0 && resp[0].value) {
                try {
                  const json = JSON.parse(resp[0].value);
                  resolve({ key, data: json });
                } catch (e) {
                  resolve({ key, data: null });
                }
              } else {
                resolve({ key, data: null });
              }
            },
            () => resolve({ key, data: null })
          );
        });
      })).then(results => {
        return { deviceId, deviceName, results };
      });
    });

    Promise.all(configPromises).then(allDeviceConfigs => {
      self.ctx.ngZone.run(() => {
        allData = [];

        allDeviceConfigs.forEach(deviceConfig => {
          const { deviceId, deviceName, results } = deviceConfig;
          const configs = {};

          results.forEach(result => {
            if (result.data && typeof result.data === 'object' && Object.keys(result.data).length > 0) {
              configs[result.key] = result.data;
            }
          });

          ['ad2u', 'background', 'statistic'].forEach(key => {
            if (hasValidConfig(configs[key])) {
              allData.push({
                key,
                name: configs[key].name || 'N/A',
                version_code: configs[key].version_code !== undefined && configs[key].version_code !== null ? configs[key].version_code : 'N/A',
                version_name: configs[key].version_name || 'N/A',
                deviceName: deviceName
              });
            }
          });
        });

        filterData();
        renderTable();
        self.ctx.detectChanges();
      });
    });
  }

  function showNoDeviceState() {
    currentDeviceId = null;
    deviceConfigs = { ad2u: null, background: null, statistic: null };
    allData = [];
    filteredData = [];
    renderTable();
  }

  if (self.ctx.stateController) {
    // console.log('[kiosk_view_JP] ✅ Setting up dashboard state listener');
    let stateChangeTimeout;
    self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
      // console.log('[kiosk_view_JP] 📡 Dashboard state changed');
      if (stateChangeTimeout) clearTimeout(stateChangeTimeout);
      stateChangeTimeout = setTimeout(function () {
        // console.log('[kiosk_view_JP] ⏳ Debounce complete, reloading device...');
        self.ctx.ngZone.run(function () {
          loadDeviceFromState();
        });
      }, 200);
    });
  } else {
    // console.warn('[kiosk_view_JP] ⚠️ No stateController available for subscription');
  }

  setTimeout(function () {
    loadDeviceFromState();
  }, 300);

  self.onDataUpdated = function () {
    // console.log('[kiosk_view_JP] 📊 Widget data updated');
    self.ctx.ngZone.run(function () {
      loadDeviceFromState();
      self.ctx.detectChanges();
    });
  };

  self.onDestroy = function () {
    if (self.stateChangeSubscription) {
      self.stateChangeSubscription.unsubscribe();
      self.stateChangeSubscription = null;
      // console.log('[kiosk_view_JP] ✅ Unsubscribed from state changes');
    }
  };


  // ===== Setup search input and pagination listeners =====
  setTimeout(function () {
    const searchInput = document.getElementById('searchInput');
    if (searchInput) {
      searchInput.addEventListener('input', function () {
        currentPage = 1; // Reset to first page on search
        filterData();
        renderTable();
      });
    }

    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');

    if (prevBtn) {
      prevBtn.addEventListener('click', function () {
        goToPage(currentPage - 1);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function () {
        goToPage(currentPage + 1);
      });
    }
  }, 500);
}

