descriptor.controllerScript:
self.onInit = function () {
    self.ctx.ngZone.run(function () {
        // Initialize scope variables
        self.ctx.$scope.isLoadingDeviceLabel = true;
        self.ctx.$scope.deviceLabel = '';
        self.ctx.$scope.isTabletDevice = false;
        self.ctx.$scope.isEdgeDevice = false;

        // Tablet widget variables
        self.ctx.$scope.form = {
            threshold: undefined,
            is_camera_uvc: false,
            is_rtsp_camera: true,
            is_live_camera: false,
            url_rtsp_camera: '',
            url_rtsp_device: ''
        };

        // Edge widget variables
        self.ctx.$scope.cameraConfigs = [];
        self.ctx.$scope.selectedCameraId = null;
        self.ctx.$scope.selectedCamera = null;
        self.ctx.$scope.isAddingNewCamera = false;
        self.ctx.$scope.newCamera = {
            id: '',
            url: '',
            mode: '',
            fps: 10,
            width: 1440,
            height: 810
        };

        init();
        self.ctx.detectChanges();
    });
};

function init() {
    const s = self.ctx.settings || {};
    const scope = self.ctx.$scope;
    const $i = scope.$injector;

    // === Services ===
    const attributeService = $i.get(self.ctx.servicesMap.get('attributeService'));

    // === UI config ===
    scope.title = s.title || 'Statistic Configuration';
    scope.showTitle = !!(s.title && s.title.length);
    scope.buttonLabel = s.buttonText || '更新';
    scope.statusMsg = '';
    scope.error = '';
    scope.saving = false;
    scope.updateDisabled = true;

    scope.styleButton = s.styleButton || { isPrimary: true, isRaised: true };
    scope.customStyle = (scope.styleButton.isPrimary === false)
        ? {
            'background-color': scope.styleButton.bgColor || '#e0e0e0',
            'color': scope.styleButton.textColor || '#000'
        }
        : {};

    // Current device info
    let currentDeviceId = null;
    let currentDeviceName = null;

    // Tablet widget variables
    let preservedPoints = null;
    const emptyForm = {
        threshold: undefined,
        is_camera_uvc: false,
        is_rtsp_camera: true,
        is_live_camera: false,
        url_rtsp_camera: '',
        url_rtsp_device: ''
    };

    // Edge widget variables
    const emptyCameraConfig = {
        id: '',
        url: '',
        mode: '',
        fps: 10,
        width: 1440,
        height: 810
    };

    // ===== Update button disabled state =====
    function updateUpdateDisabledState() {
        // Disable update if no device selected or in ALL mode
        scope.updateDisabled = !currentDeviceId || currentDeviceId === '__ALL__';
    }

    // ===== Get Device from Datasource =====
    function getDeviceFromDatasource() {
        try {
            if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.targetDeviceId) {
                const deviceId = self.ctx.defaultSubscription.targetDeviceId;
                const deviceName = self.ctx.defaultSubscription.targetDeviceName || 'Device';
                return {
                    id: deviceId,
                    name: deviceName,
                    type: 'DEVICE'
                };
            }

            const datasources = self.ctx.datasources;
            const deviceMap = new Map();

            if (datasources && datasources.length > 0) {
                datasources.forEach(function (datasource) {
                    if (datasource.type === 'entity' && datasource.entityType === 'DEVICE') {
                        const deviceId = datasource.entityId;
                        const deviceName = datasource.entityName || datasource.name || 'Unknown Device';

                        if (deviceId && !deviceMap.has(deviceId)) {
                            deviceMap.set(deviceId, {
                                id: deviceId,
                                name: deviceName,
                                type: datasource.entityType
                            });
                        }
                    } else if (datasource.entityFilter) {
                        if (datasource.dataKeys && datasource.dataKeys.length > 0) {
                            datasource.dataKeys.forEach(function (dataKey) {
                                if (dataKey.settings && dataKey.settings.entity) {
                                    const deviceId = dataKey.settings.entity.id;
                                    const deviceName = dataKey.settings.entity.name || dataKey.name || 'Unknown Device';

                                    if (deviceId && !deviceMap.has(deviceId)) {
                                        deviceMap.set(deviceId, {
                                            id: deviceId,
                                            name: deviceName,
                                            type: 'DEVICE'
                                        });
                                    }
                                }
                            });
                        }
                    }
                });

                if (self.ctx.data && self.ctx.data.length > 0) {
                    self.ctx.data.forEach(function (data) {
                        if (data.datasource && data.datasource.entityId && data.datasource.entityType === 'DEVICE') {
                            const deviceId = data.datasource.entityId;
                            const deviceName = data.datasource.entityName || data.datasource.name || 'Unknown Device';

                            if (deviceId && !deviceMap.has(deviceId)) {
                                deviceMap.set(deviceId, {
                                    id: deviceId,
                                    name: deviceName,
                                    type: 'DEVICE'
                                });
                            }
                        }
                    });
                }
            }

            const devices = Array.from(deviceMap.values());
            if (devices.length === 0) {
                return null;
            }
            return devices[0];

        } catch (error) {
            return null;
        }
    }

    // ===== Load deviceLabel and determine widget type =====
    function loadDeviceLabel(deviceId) {
        if (!deviceId) {
            scope.isLoadingDeviceLabel = false;
            scope.error = '⚠ デバイスが見つかりません。ウィジェットのデータソースまたはダッシュボードのエンティティ選択でデバイスを設定してください。';
            self.ctx.detectChanges();
            return;
        }

        // ✅ Strict State Check: Ensure we match the current dashboard state
        if (self.ctx.stateController) {
            const stateParams = self.ctx.stateController.getStateParams();
            const currentMode = stateParams?.selectedDeviceMode;

            // If Dashboard is in ALL mode, force widget to ALL mode
            if (currentMode === 'ALL') {
                deviceId = '__ALL__';
            }
            // If Dashboard is in SINGLE mode, but we somehow got ALL (mismatch), stop to avoid showing ALL view
            else if (currentMode === 'SINGLE' && deviceId === '__ALL__') {
                scope.isLoadingDeviceLabel = false;
                scope.statusMsg = 'デバイスを選択してください';
                scope.error = '';
                updateUpdateDisabledState();
                self.ctx.detectChanges();
                return;
            }
        }

        // ✅ Handle "All devices" mode - keep current form but disable buttons
        if (deviceId === '__ALL__') {
            scope.isLoadingDeviceLabel = false;
            // If no device type is set yet, default to Tablet
            if (!scope.isTabletDevice && !scope.isEdgeDevice) {
                scope.isTabletDevice = true;
                scope.isEdgeDevice = false;
                scope.form = { ...emptyForm };
            }
            // DON'T reset isTabletDevice or isEdgeDevice - keep current form visible
            scope.error = ''; // Clear error
            scope.statusMsg = `⚠️「すべての端末」では「Statisticアプリ構成」を更新できません。単一のデバイスを選択してください。`;
            updateUpdateDisabledState();
            self.ctx.detectChanges();
            return;
        }

        // ✅ Clear previous status/error to prevent scope overlap
        scope.statusMsg = '';
        scope.error = '';

        scope.isLoadingDeviceLabel = true;
        self.ctx.detectChanges();

        const eid = { entityType: 'DEVICE', id: deviceId };

        // Load deviceLabel from SERVER_SCOPE attributes
        attributeService.getEntityAttributes(eid, 'SERVER_SCOPE', ['deviceLabel']).subscribe(
            function success(resp) {
                if (resp && resp.length > 0 && resp[0].value) {
                    scope.deviceLabel = resp[0].value;

                    // Case-insensitive comparison
                    const labelLower = scope.deviceLabel.toLowerCase().trim();

                    if (labelLower === 'tablet-type') {
                        scope.isTabletDevice = true;
                        scope.isEdgeDevice = false;
                        loadTabletConfig(deviceId);

                        // Clear Edge config to ensure strict scope isolation
                        scope.cameraConfigs = [];
                        scope.selectedCameraId = null;
                        scope.selectedCamera = null;
                        scope.newCamera = { ...emptyCameraConfig };
                        scope.isAddingNewCamera = false;
                    } else if (labelLower === 'edge-type') {
                        scope.isTabletDevice = false;
                        scope.isEdgeDevice = true;
                        loadEdgeConfig(deviceId);

                        // Clear Tablet config to ensure strict scope isolation
                        scope.form = { ...emptyForm };
                        preservedPoints = null;
                    } else {
                        // Unknown device type
                        scope.isTabletDevice = false;
                        scope.isEdgeDevice = false;
                        scope.isLoadingDeviceLabel = false;
                    }
                } else {
                    // No deviceLabel found
                    scope.deviceLabel = '';
                    scope.isTabletDevice = false;
                    scope.isEdgeDevice = false;
                    scope.isLoadingDeviceLabel = false;
                    scope.error = '⚠ サーバー属性にdeviceLabelが見つかりません。';
                }
                self.ctx.detectChanges();
            },
            function fail(error) {
                scope.isLoadingDeviceLabel = false;
                scope.error = '⚠ deviceLabelの読み込みに失敗しました。: ' + (error.message || 'Unknown error');
                self.ctx.detectChanges();
            }
        );
    }

    // ===== Load Tablet Config (from statistic_config widget) =====
    function loadTabletConfig(deviceId) {
        const eid = { entityType: 'DEVICE', id: deviceId };
        const keyName = s.keyName || 'statistic_config';

        attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
            function success(resp) {
                if (resp && resp.length > 0 && resp[0].value) {
                    try {
                        const json = JSON.parse(resp[0].value);

                        // Preserve points field if it exists
                        if (json.points && Array.isArray(json.points)) {
                            preservedPoints = json.points;
                        } else {
                            preservedPoints = null;
                        }

                        scope.form = { ...emptyForm, ...json };
                        delete scope.form.points;

                        // Convert boolean fields to string for dropdown
                        if (scope.form.is_camera_uvc === true || scope.form.is_camera_uvc === 'true') {
                            scope.form.is_camera_uvc = 'true';
                        } else {
                            scope.form.is_camera_uvc = 'false';
                        }

                        if (scope.form.is_rtsp_camera === true || scope.form.is_rtsp_camera === 'true') {
                            scope.form.is_rtsp_camera = 'true';
                        } else {
                            scope.form.is_rtsp_camera = 'false';
                        }

                        // Ensure is_camera_uvc and is_rtsp_camera are always opposite
                        if (scope.form.is_camera_uvc === 'true') {
                            scope.form.is_rtsp_camera = 'false';
                        } else {
                            scope.form.is_rtsp_camera = 'true';
                        }

                        if (scope.form.is_live_camera === true || scope.form.is_live_camera === 'true') {
                            scope.form.is_live_camera = 'true';
                        } else {
                            scope.form.is_live_camera = 'false';
                        }

                        const urlRtspDevice = (scope.form.url_rtsp_device || '').trim();
                        if (!urlRtspDevice || urlRtspDevice.length === 0) {
                            scope.form.is_live_camera = 'false';
                        }

                        if (scope.form.threshold !== undefined && scope.form.threshold !== null) {
                            if (typeof scope.form.threshold === 'string') {
                                const parsed = parseFloat(scope.form.threshold);
                                scope.form.threshold = isNaN(parsed) ? undefined : parsed;
                            } else if (typeof scope.form.threshold !== 'number') {
                                scope.form.threshold = undefined;
                            }
                        }

                        scope.statusMsg = '✅ タブレット設定を読み込みました。';
                    } catch (e) {
                        scope.form = { ...emptyForm };
                        preservedPoints = null;
                        scope.error = '⚠ 設定の解析に失敗しました';
                    }
                } else {
                    scope.form = { ...emptyForm };
                    preservedPoints = null;
                    scope.statusMsg = 'ℹ このデバイスの設定が見つかりませんでした。';
                }

                scope.isLoadingDeviceLabel = false;
                updateUpdateDisabledState();
                self.ctx.detectChanges();

                // Clear status message after 2 seconds
                setTimeout(function () {
                    self.ctx.ngZone.run(function () {
                        scope.statusMsg = '';
                        self.ctx.detectChanges();
                    });
                }, 2000);
            },
            function fail(error) {
                scope.form = { ...emptyForm };
                preservedPoints = null;
                scope.isLoadingDeviceLabel = false;
                scope.error = '⚠ 設定の読み込みに失敗しました。: ' + (error.message || 'Unknown error');
                self.ctx.detectChanges();
            }
        );
    }

    // ===== Load Edge Config (from statistic_config_edge widget) =====
    function loadEdgeConfig(deviceId) {
        const eid = { entityType: 'DEVICE', id: deviceId };
        const keyName = s.keyName || 'statistic_config';

        attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
            function success(resp) {
                if (resp && resp.length > 0 && resp[0].value) {
                    try {
                        let json = resp[0].value;

                        if (typeof json === 'string') {
                            json = JSON.parse(json);
                        }
                        if (typeof json === 'string') {
                            json = JSON.parse(json);
                        }

                        if (Array.isArray(json)) {
                            scope.cameraConfigs = json.map(function (config) {
                                return {
                                    id: config.id || '',
                                    url: config.url || '',
                                    mode: config.mode || '',
                                    fps: config.fps || 10,
                                    width: config.width || 1440,
                                    height: config.height || 810,
                                    point: Array.isArray(config.point) ? config.point : [0, 0, 0, 0]
                                };
