                // Clear status message after 2 seconds
                setTimeout(function () {
                    self.ctx.ngZone.run(function () {
                        scope.statusMsg = '';
                        self.ctx.detectChanges();
                    });
                }, 2000);
            },
            function fail(error) {
                scope.cameraConfigs = [];
                scope.isLoadingDeviceLabel = false;
