descriptor.controllerScript:
self.onInit = function () {
  self.ctx.ngZone.run(function () {
    // form mặc định rỗng
    self.ctx.$scope.form = {
      threshold: undefined,
      is_live_camera: false,
      url_model: 'https://visiflow-dev.m-tech.com.vn/model/DLITE.zip'
    };
    init();
    self.ctx.detectChanges();
  });
};

function init() {
  const s = self.ctx.settings || {};
  const scope = self.ctx.$scope;
  const $i = scope.$injector;

  // === Services ===
  const attributeService = $i.get(self.ctx.servicesMap.get('attributeService'));

  // === UI config ===
  scope.title = s.title || '背景アプリ設定を更新';
  scope.showTitle = !!(s.title && s.title.length);
  scope.buttonLabel = s.buttonText || '更新';
  scope.statusMsg = '';
  scope.error = '';
  scope.saving = false;

  // ===== LocalStorage Key (per device) =====
  const STORAGE_KEY_PREFIX = 'background_app_config_state_';

  // ===== Get storage key for specific device =====
  function getStorageKey(deviceId) {
    return deviceId ? `${STORAGE_KEY_PREFIX}${deviceId}` : STORAGE_KEY_PREFIX + 'default';
  }

  // ===== Save state to localStorage (per device) =====
  function saveStateToStorage() {
    try {
      const selectedDevice = currentDeviceId || '';
      const storageKey = getStorageKey(selectedDevice);

      const state = {
        selectedDevice: selectedDevice,
        form: scope.form
      };
      localStorage.setItem(storageKey, JSON.stringify(state));

      // Also save last selected device separately
      if (currentDeviceId) {
        localStorage.setItem('background_app_last_selected_device', currentDeviceId);
      }
    } catch (e) {
      // // console.warn('Failed to save state to localStorage:', e);
    }
  }

  // ===== Load state from localStorage (per device) =====
  function loadStateFromStorage(deviceId) {
    try {
      const storageKey = getStorageKey(deviceId);
      const savedState = localStorage.getItem(storageKey);
      if (savedState) {
        const state = JSON.parse(savedState);
        return state;
      }
    } catch (e) {
      // // console.warn('Failed to load state from localStorage:', e);
    }
    return null;
  }

  // ===== Get last selected device =====
  function getLastSelectedDevice() {
    try {
      return localStorage.getItem('background_app_last_selected_device') || '';
    } catch (e) {
      return '';
    }
  }

  scope.styleButton = s.styleButton || { isPrimary: true, isRaised: true };
  scope.customStyle = (scope.styleButton.isPrimary === false)
    ? {
      'background-color': scope.styleButton.bgColor || '#e0e0e0',
      'color': scope.styleButton.textColor || '#000'
    }
    : {};

  // === Scope lưu trữ attributes của device đang bound ===
  const entityAttributeType = s.entityAttributeType || 'SERVER_SCOPE';
  const keyName = s.keyName || 'background_config';

  // ✅ Save to self so loadDeviceFromState can access them
  self.attributeService = attributeService;
  self.scope = scope;

  // Current device info (from dashboard state)
  self.currentDeviceId = null;
  self.currentDeviceName = null;

  // Empty form structure
  const emptyForm = {
    threshold: undefined,
    is_live_camera: false,
    url_model: 'https://visiflow-dev.m-tech.com.vn/model/DLITE.zip'
  };

  // === Load attribute background for specific device ===
  function loadDeviceConfig(deviceId) {
    if (!deviceId) {
      scope.form = { ...emptyForm };
      scope.statusMsg = '';
      scope.error = '';
      updateUpdateDisabledState();
      self.ctx.detectChanges();
      return;
    }

    scope.statusMsg = 'デバイス設定を読み込み中...';
    scope.error = '';
    self.ctx.detectChanges();

    const eid = { entityType: 'DEVICE', id: deviceId };

    attributeService.getEntityAttributes(eid, 'SHARED_SCOPE', [keyName]).subscribe(
      function success(resp) {
        if (resp && resp.length > 0 && resp[0].value) {
          try {
            const json = JSON.parse(resp[0].value);
            scope.form = { ...emptyForm, ...json };

            // Convert boolean field to string for dropdown
            if (scope.form.is_live_camera === true || scope.form.is_live_camera === 'true') {
              scope.form.is_live_camera = 'true';
            } else {
              scope.form.is_live_camera = 'false';
            }

            // Ensure threshold is a number if provided
            if (scope.form.threshold !== undefined && scope.form.threshold !== null) {
              if (typeof scope.form.threshold === 'string') {
                const parsed = parseFloat(scope.form.threshold);
                scope.form.threshold = isNaN(parsed) ? undefined : parsed;
              } else if (typeof scope.form.threshold !== 'number') {
                scope.form.threshold = undefined;
              }
            }

            updateUpdateDisabledState();
            scope.statusMsg = '✅ インストールプロセスがアップロードされました。';
            scope.error = '';

            // Clear status message after 2 seconds
            setTimeout(function () {
              self.ctx.ngZone.run(function () {
                scope.statusMsg = '';
                self.ctx.detectChanges();
              });
            }, 2000);
          } catch (e) {
            scope.form = { ...emptyForm };
            updateUpdateDisabledState();
            scope.statusMsg = '';
            scope.error = '⚠ 設定の解析に失敗しました';
          }
        } else {
          // No config found for this device
          scope.form = { ...emptyForm };
          updateUpdateDisabledState();
          scope.statusMsg = 'ℹ このデバイスの設定が見つかりませんでした。';
          scope.error = '';

          // Clear status message after 2 seconds
          setTimeout(function () {
            self.ctx.ngZone.run(function () {
              scope.statusMsg = '';
              self.ctx.detectChanges();
            });
          }, 2000);
        }
        self.ctx.detectChanges();
      },
      function fail(error) {
        scope.form = { ...emptyForm };
        updateUpdateDisabledState();
        scope.statusMsg = '';
        scope.error = '⚠ 設定の読み込みに失敗しました: ' + (error.message || '不明なエラー');
        self.ctx.detectChanges();
      }
    );
  }

  // Don't auto-load on init - wait for user to select device
  scope.form = { ...emptyForm };
  updateUpdateDisabledState();

  // ===== Flask Server =====
  // Get from widget settings or use default
  const FLASK_SERVER = s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';

  // ===== Get Tenant Username (for multi-tenant support) =====
  function getTenantUsername() {
    try {
      // Try to get from ThingsBoard user context
      if (self.ctx.user && self.ctx.user.email) {
        return self.ctx.user.email;
      }
      // Try from userInfo
      if (self.ctx.userInfo && self.ctx.userInfo.email) {
        return self.ctx.userInfo.email;
      }
      // Try from $rootScope (ThingsBoard internal)
      const $rootScope = self.ctx.$scope.$root;
      if ($rootScope && $rootScope.currentUser && $rootScope.currentUser.email) {
        return $rootScope.currentUser.email;
      }
    } catch (e) {
      // // console.warn('Could not get tenant username:', e);
    }
    return null;
  }


  // ===== Load device from dashboard state (NO datasource dependency) =====
  function loadDeviceFromState() {
    // console.log('[background_config_JP] 🔄 Loading device from dashboard state...');

    if (!scope) {
      // console.error('[background_config_JP] ❌ Scope not initialized yet');
      return;
    }

    if (!self.ctx.stateController) {
      // console.warn('[background_config_JP] ⚠️ No stateController available');
      scope.statusMsg = '';
      scope.error = '⚠ ダッシュボード状態コントローラーが利用できません';
      self.ctx.detectChanges();
      return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode;
    const selectedDeviceId = stateParams?.selectedDeviceId;
    const selectedDeviceName = stateParams?.selectedDeviceName;
    const deviceCount = stateParams?.selectedEntity?.count;

    // console.log('[background_config_JP] 📊 Dashboard State:', {
    //  mode: deviceMode,
    //  deviceId: selectedDeviceId,
    //  deviceName: selectedDeviceName,
    //  count: deviceCount
    //});

    if (!deviceMode || deviceMode === 'NONE') {
      // console.log('[background_config_JP] ℹ️ No device mode set yet');
      scope.form = { ...emptyForm };
      scope.statusMsg = 'ストア/デバイス セレクターからデバイスを選択します。';
      scope.error = '';
      self.currentDeviceId = null;
      self.currentDeviceName = null;
      updateUpdateDisabledState();
      self.ctx.detectChanges();
      return;
    }

    if (deviceMode === 'ALL') {
      // console.log('[background_config_JP] ✅ All devices mode');
      scope.form = { ...emptyForm };
      scope.statusMsg = `⚠️「すべての端末」では「Backgroundアプリ構成」を更新できません。単一のデバイスを選択してください。`;
      scope.error = '';
      self.currentDeviceId = '__ALL__';
      self.currentDeviceName = selectedDeviceName || 'すべての端末';
      updateUpdateDisabledState();
      self.ctx.detectChanges();
      return;
    }

    if (deviceMode === 'SINGLE' && selectedDeviceId && selectedDeviceId !== '__ALL__') {
      // console.log('[background_config_JP] ✅ Single device mode:', selectedDeviceId);
      self.currentDeviceId = selectedDeviceId;
      self.currentDeviceName = selectedDeviceName || 'デバイス';
      loadDeviceConfig(selectedDeviceId);
      return;
    }

    // console.log('[background_config_JP] ℹ️ No valid device state found');
    scope.form = { ...emptyForm };
    scope.statusMsg = 'ストア/デバイス セレクターからデバイスを選択します。';
    scope.error = '';
    self.currentDeviceId = null;
    self.currentDeviceName = null;
    updateUpdateDisabledState();
    self.ctx.detectChanges();
  }

  // ✅ Save reference to self so it can be accessed from subscription
  self.loadDeviceFromState = loadDeviceFromState;

  // Setup state change listener

  if (self.ctx.stateController) {
    // console.log('[background_config_JP] ✅ Setting up dashboard state listener');
    let stateChangeTimeout;
    self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
      // console.log('[background_config_JP] 📡 Dashboard state changed');
      if (stateChangeTimeout) clearTimeout(stateChangeTimeout);
      stateChangeTimeout = setTimeout(function () {
        // console.log('[background_config_JP] ⏳ Debounce complete, reloading...');
        self.ctx.ngZone.run(function () {
          if (self.loadDeviceFromState) {
            self.loadDeviceFromState();
          }
        });
      }, 200);
    });
  }

  // Load device from state on init with retry
  let retryCount = 0;
  function tryLoad() {
    if (self.scope && self.attributeService) {
      // console.log('[background_config_JP] ✅ Dependencies ready');
      loadDeviceFromState();
    } else {
      retryCount++;
      if (retryCount < 5) {
        // console.log('[background_config_JP] ⏳ Waiting... retry', retryCount);
        setTimeout(tryLoad, 100);
      }
    }
  }
  setTimeout(tryLoad, 300);

  self.onDataUpdated = function () {
    // console.log('[background_config_JP] 📊 Widget data updated');
    self.ctx.ngZone.run(function () {
      if (self.loadDeviceFromState) {
        self.loadDeviceFromState();
      }
      self.ctx.detectChanges();
    });
  };

  self.onDestroy = function () {
    if (self.stateChangeSubscription) {
      self.stateChangeSubscription.unsubscribe();
      self.stateChangeSubscription = null;
      // console.log('[background_config_JP] ✅ Unsubscribed');
    }
  };


  // ===== Watch form changes and save to localStorage =====
  scope.saveFormState = function () {
    saveStateToStorage();
  };

  // ===== Buttons =====
  function updateUpdateDisabledState() {
    // Disable update if no device selected or in ALL mode
    scope.updateDisabled = !self.currentDeviceId || self.currentDeviceId === '__ALL__';
  }

  scope.updateDisabled = false;

  scope.clearAll = function () {
    if (!confirm('すべての設定をクリアしてもよろしいですか？デバイス選択およびすべてのフォームフィールドが削除されます。')) {
      return;
    }

    const deviceId = self.currentDeviceId;

    if (deviceId) {
      scope.saving = true;
      updateUpdateDisabledState();
      scope.statusMsg = 'クリア中...';
      scope.error = '';

      // Get tenant username for multi-tenant support
      const tenantUsername = getTenantUsername();

      // Prepare headers with tenant info (if available)
      const headers = {
        'Content-Type': 'application/json'
      };
      if (tenantUsername) {
        headers['X-TB-Tenant-Username'] = tenantUsername;
      }

      // Clear 'background' attribute
      fetch(`${FLASK_SERVER}/api/update-device-background-config`, {
        method: 'POST',
        headers: headers,
        body: JSON.stringify({
          deviceId: deviceId,
          background_config: {}
        })
      })
        .then(function (response) {
          return response.json();
        })
        .then(function (data) {
          self.ctx.ngZone.run(function () {
            scope.saving = false;
            updateUpdateDisabledState();
            if (data.success) {
              scope.statusMsg = '✅ クリアが完了しました！';
            } else {
              scope.statusMsg = '';
              scope.error = '⚠ クリアに失敗しました: ' + (data.error || '不明なエラー');
            }
            clearLocalState();
          });
        })
        .catch(function (error) {
          self.ctx.ngZone.run(function () {
            scope.saving = false;
            updateUpdateDisabledState();
            scope.statusMsg = '';
            scope.error = '⚠ クリアエラー: ' + error.message;
            clearLocalState();
          });
        });
    } else {
      clearLocalState();
    }

    function clearLocalState() {
      scope.form = { ...emptyForm };

      if (!scope.statusMsg && !scope.error) {
        scope.statusMsg = '';
        scope.error = '';
      }

      updateUpdateDisabledState();

      // Clear localStorage for current device
      const selectedDevice = self.currentDeviceId || '';
      try {
        const storageKey = getStorageKey(selectedDevice);
        localStorage.removeItem(storageKey);
      } catch (e) {
        // // console.warn('Failed to clear localStorage:', e);
      }

      self.ctx.detectChanges();
    }
  };

  scope.save = function () {
    scope.statusMsg = '';
    scope.error = '';

    if (!self.currentDeviceId) {
      scope.error = '⚠ デバイスが選択されていません。ウィジェットのデータソースまたはダッシュボードのエンティティ選択でデバイスを設定してください。';
      self.ctx.detectChanges();
      return;
    }

    const deviceId = self.currentDeviceId;
    const deviceName = self.currentDeviceName || 'Unknown';

    if (!deviceId) {
      scope.error = '⚠ デバイスIDが見つかりませんでした。';
      self.ctx.detectChanges();
      return;
    }

    scope.saving = true;
    updateUpdateDisabledState();

    // Prepare form data with correct types
    let thresholdValue = undefined;
    if (scope.form.threshold !== undefined && scope.form.threshold !== null) {
      if (typeof scope.form.threshold === 'number') {
        thresholdValue = scope.form.threshold;
      } else if (typeof scope.form.threshold === 'string') {
        const parsed = parseFloat(scope.form.threshold);
        thresholdValue = isNaN(parsed) ? undefined : parsed;
      }
    }

    const formData = {
      threshold: thresholdValue,
      is_live_camera: scope.form.is_live_camera === 'true' || scope.form.is_live_camera === true,
      url_model: 'https://visiflow-dev.m-tech.com.vn/model/DLITE.zip'
    };

    // Prepare request data
    const requestData = {
      deviceId: deviceId,
      background_config: formData
    };

    // Get tenant username for multi-tenant support
    const tenantUsername = getTenantUsername();

    // Prepare headers with tenant info (if available)
    const headers = {
      'Content-Type': 'application/json'
    };
    if (tenantUsername) {
      headers['X-TB-Tenant-Username'] = tenantUsername;
      // // console.log('Using tenant username:', tenantUsername);
    }

    // // console.log('Sending update request to:', `${FLASK_SERVER}/api/update-device-background-config`);
    // // console.log('Request data:', JSON.stringify(requestData, null, 2));

    // Update 'background' attribute
    fetch(`${FLASK_SERVER}/api/update-device-background-config`, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(requestData)
    })
      .then(function (response) {
        // // console.log('Response status:', response.status, response.statusText);
        // // console.log('Response headers:', response.headers);

        if (!response.ok) {
          // Try to get error message from response
          return response.json().then(function (data) {
            throw new Error(data.error || `HTTP ${response.status}: ${response.statusText}`);
          }).catch(function () {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
          });
        }

        return response.json();
      })
      .then(function (data) {
        // // console.log('Response data:', data);
        self.ctx.ngZone.run(function () {
          scope.saving = false;
          updateUpdateDisabledState();
          if (data.success) {
            scope.statusMsg = '✅ 更新が完了しました！';
            scope.error = '';
            saveStateToStorage();
          } else {
            scope.statusMsg = '';
            scope.error = '⚠ 更新に失敗しました: ' + (data.error || '不明なエラー');
          }
          self.ctx.detectChanges();
        });
      })
      .catch(function (error) {
        // // console.error('Fetch error:', error);
        // // console.error('Error stack:', error.stack);
        self.ctx.ngZone.run(function () {
          scope.saving = false;
          updateUpdateDisabledState();
          scope.statusMsg = '';

          // More detailed error message
          let errorMsg = '⚠ 更新エラー: ';
          if (error.message) {
            errorMsg += error.message;
          } else if (error.name === 'TypeError' && error.message.includes('fetch')) {
            errorMsg += 'サーバーに接続できません。サーバーが ' + FLASK_SERVER + ' で実行されているか確認してください。';
          } else {
            errorMsg += '不明なエラーが発生しました。詳細についてはブラウザのコンソールを確認してください。';
          }

          scope.error = errorMsg;
          self.ctx.detectChanges();
        });
      });
  };
}

