descriptor.controllerScript:
// Content View Widget - Scoped to avoid conflicts with other widgets
(function () {
    'use strict';

    // Widget state - all variables scoped to this widget instance
    let contentData = [];
    let filteredContentData = [];

    // ===== Get Flask Server URL =====
    // Get from widget settings or use default
    function getFlaskServerUrl() {
        try {
            const s = self.ctx.settings || {};
            return s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';
        } catch (e) {
            return 'http://127.0.0.1:5003';
        }
    }

    // ===== Get Tenant Username (for multi-tenant support) =====
    // Note: Currently endpoints don't call ThingsBoard API, but this function
    // is available for future use if needed
    function getTenantUsername() {
        try {
            // Try to get from ThingsBoard user context
            if (self.ctx.user && self.ctx.user.email) {
                return self.ctx.user.email;
            }
            // Try from userInfo
            if (self.ctx.userInfo && self.ctx.userInfo.email) {
                return self.ctx.userInfo.email;
            }
            // Try from $rootScope (ThingsBoard internal)
            if (self.ctx.$scope && self.ctx.$scope.$root && self.ctx.$scope.$root.currentUser && self.ctx.$scope.$root.currentUser.email) {
                return self.ctx.$scope.$root.currentUser.email;
            }
        } catch (e) {
            // // console.warn('[ContentView] Could not get tenant username:', e);
        }
        return null;
    }

    // ⚠️ WEBHOOK-ONLY MODE: No polling
    // Widget only updates on:
    // 1. Initial load
    // 2. Manual refresh (user action)
    // 3. ThingsBoard webhook events (if configured)

    let isModalOpen = false;
    let currentContentHash = null;
    let isLoadingContent = false;
    let currentPage = 1;
    const ROWS_PER_PAGE = 10;
    let pendingDeleteIndex = null;
    let widgetContainer = null; // Widget container element
    let modalClickHandler = null; // Store handler for cleanup
    let autoRefreshInterval = null; // Auto-refresh interval reference

    // ===== Device Selection Variables =====
    let currentDeviceId = null;
    let currentDeviceName = null;

    // Cache configuration with unique prefix to avoid conflicts
    const CACHE_KEY_PREFIX = 'content_view_widget_';
    const CACHE_KEY = CACHE_KEY_PREFIX + 'cache';
    const CACHE_TIMESTAMP_KEY = CACHE_KEY_PREFIX + 'cache_timestamp';
    const CACHE_MAX_AGE = 5 * 60 * 1000; // 5 minutes cache

    // Get element within widget container scope
    function getElementById(id) {
        if (widgetContainer) {
            const element = widgetContainer.querySelector('#' + id);
            if (element) return element;
        }
        // Fallback to document if not found in container
        return document.getElementById(id);
    }

    // FIXED: Create properly structured loading spinner HTML
    function getLoadingSpinnerHTML() {
        return '<tr class="empty-row"><td colspan="4"><div class="loading-container"><div class="loading-spinner"></div><div class="loading-text">コンテンツを読み込み中...</div></div></td></tr>';
    }

    // Load from cache (per device)
    function loadFromCache() {
        try {
            if (!currentDeviceId) return false;

            const cacheKey = CACHE_KEY + '_' + currentDeviceId;
            const cacheTimestampKey = CACHE_TIMESTAMP_KEY + '_' + currentDeviceId;

            const cachedData = localStorage.getItem(cacheKey);
            const cacheTimestamp = localStorage.getItem(cacheTimestampKey);

            if (cachedData && cacheTimestamp) {
                const age = Date.now() - parseInt(cacheTimestamp);
                if (age < CACHE_MAX_AGE) {
                    const parsed = JSON.parse(cachedData);
                    if (Array.isArray(parsed) && parsed.length > 0) {
                        // // console.log('[ContentView] Loading from cache for device:', currentDeviceId, parsed.length, 'items');
                        contentData = parsed;
                        filterContent();
                        return true;
                    }
                } else {
                    // // console.log('[ContentView] Cache expired, age:', age, 'ms');
                }
            }
        } catch (error) {
            // // console.warn('[ContentView] Error loading from cache:', error);
        }
        return false;
    }

    // Save to cache (per device)
    function saveToCache(data) {
        try {
            if (!currentDeviceId) return;

            const cacheKey = CACHE_KEY + '_' + currentDeviceId;
            const cacheTimestampKey = CACHE_TIMESTAMP_KEY + '_' + currentDeviceId;

            localStorage.setItem(cacheKey, JSON.stringify(data));
            localStorage.setItem(cacheTimestampKey, Date.now().toString());
            // // console.log('[ContentView] Saved to cache for device:', currentDeviceId, data.length, 'items');
        } catch (error) {
            // // console.warn('[ContentView] Error saving to cache:', error);
        }
    }


    // ===== Load Device from Dashboard State =====
    function loadDeviceFromState() {
        if (!self.ctx || !self.ctx.stateController) {
            // console.warn('[content_view_jp] ⚠️ No stateController available');
            showNoDeviceState();
            return;
        }

        const stateParams = self.ctx.stateController.getStateParams();
        const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

        // console.log('[content_view_jp] 📊 Loading device from state:', { deviceMode, stateParams });

        // ========= ALL DEVICES MODE =========
        if (deviceMode === 'ALL') {
            const entities = stateParams?.entities || stateParams?.entityIds || [];
            const deviceType = stateParams?.selectedDeviceType || stateParams?.type;

            // console.log('[content_view_jp] 📋 ALL devices mode:', entities.length, 'devices');

            if (entities.length > 0) {
                loadAllDevicesContent(entities, deviceType);
            } else {
                showNoDeviceState();
            }
            return;
        }

        // ========= SINGLE DEVICE MODE =========
        if (deviceMode === 'SINGLE') {
            const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
            const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'デバイス';

            // console.log('[content_view_jp] 📱 SINGLE device mode:', deviceName, deviceId);

            if (deviceId) {
                loadDeviceById(deviceId, deviceName);
            } else {
                showNoDeviceState();
            }
            return;
        }

        // ========= NONE OR NO MODE =========
        // console.log('[content_view_jp] ⚠️ No device mode or NONE mode');
        showNoDeviceState();
    }

    // Helper: Load content for a single device
    function loadDeviceById(deviceId, deviceName) {
        const deviceChanged = currentDeviceId !== deviceId;
        currentDeviceId = deviceId;
        currentDeviceName = deviceName;

        // console.log(`[content_view_jp] ✅ Device selected: ${deviceName} (${deviceId})`);

        if (deviceChanged) {
            contentData = [];
            filteredContentData = [];
        }

        const cacheLoaded = loadFromCache();
        if (!cacheLoaded) {
            const tbody = getElementById('contentTableBody');
            if (tbody) {
                tbody.innerHTML = getLoadingSpinnerHTML();
            }
        }

        loadContent();
    }

    // Helper: Load and aggregate content from all devices
    async function loadAllDevicesContent(entities, deviceType) {
        currentDeviceId = '__ALL__';
        currentDeviceName = `すべての${deviceType || 'デバイス'}`;
        contentData = [];
        filteredContentData = [];

        const tbody = getElementById('contentTableBody');
        if (tbody) {
            tbody.innerHTML = getLoadingSpinnerHTML();
        }

        // console.log('[content_view_jp] 🔄 Loading content from', entities.length, 'devices...');

        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        try {
            // Fetch content from all devices in parallel
            const fetchPromises = entities.map(async (entity) => {
                const deviceId = entity.id || entity;
                try {
                    const response = await fetch(`${FLASK_SERVER}/api/get-content?deviceId=${deviceId}`, {
                        method: 'GET',
                        headers: headers
                    });

                    if (!response.ok) {
                        // console.warn('[content_view_jp] ⚠️ Failed to fetch content for device:', deviceId);
                        return [];
                    }

                    const data = await response.json();
                    if (data.success && Array.isArray(data.content)) {
                        // Add device info to each content item
                        return data.content.map(item => ({
                            ...item,
                            _deviceId: deviceId,
                            _deviceName: entity.name || deviceId
                        }));
                    }
                    return [];
                } catch (error) {
                    // console.warn('[content_view_jp] ⚠️ Error fetching content for device:', deviceId, error);
                    return [];
                }
            });

            const results = await Promise.all(fetchPromises);

            // Flatten and combine all content
            contentData = results.flat();

            // console.log('[content_view_jp] ✅ Loaded', contentData.length, 'total content items from', entities.length, 'devices');

            filterContent();

        } catch (error) {
            // console.error('[content_view_jp] ❌ Error loading all devices content:', error);
            showStatus('デバイスからコンテンツの読み込みエラー: ' + error.message, 'error');
            contentData = [];
            filteredContentData = [];
            renderTable();
        }
    }

    // Helper: Show no device state
    function showNoDeviceState() {
        currentDeviceId = null;
        currentDeviceName = null;
        contentData = [];
        filteredContentData = [];
        renderTable();
        showStatus('⚠️ デバイスが選択されていません。顧客セレクターからデバイスを選択してください。', 'error');
    }

    // Cleanup function
    function cleanup() {
        // // console.log('[content_view_jp] 🧹 Cleaning up widget...');

        stopAutoRefresh();

        // Unsubscribe from state changes
        if (self.stateChangeSubscription) {
            self.stateChangeSubscription.unsubscribe();
            self.stateChangeSubscription = null;
            // // console.log('[content_view_jp] ✅ Unsubscribed from state changes');
        }

        // Remove modal click handler
        if (modalClickHandler) {
            document.removeEventListener('click', modalClickHandler);
            modalClickHandler = null;
        }
    }

    // Initialize widget
    function initializeWidget() {
        // // console.log('[ContentView] Initializing widget...');

        // Get widget container - try to find the content-view-container
        widgetContainer = document.querySelector('.content-view-container');
        if (!widgetContainer) {
            // Fallback: try to find parent container
            const tbody = document.getElementById('contentTableBody');
            if (tbody) {
                widgetContainer = tbody.closest('.content-view-container');
            }
        }

        if (!widgetContainer) {
            // // console.warn('[ContentView] Widget container not found, using document scope');
        }

        // Ensure table body exists
        const tbody = getElementById('contentTableBody');
        if (tbody) {
            tbody.innerHTML = getLoadingSpinnerHTML();
        }

        setTimeout(() => {
            const searchInput = getElementById('searchInput');
            const closeModal = getElementById('closeModal');
            const cancelEdit = getElementById('cancelEdit');
            const editForm = getElementById('editForm');
            const prevBtn = getElementById('prevBtn');
            const nextBtn = getElementById('nextBtn');
            const closeDeleteModal = getElementById('closeDeleteModal');
            const cancelDelete = getElementById('cancelDelete');
            const confirmDeleteBtn = getElementById('confirmDelete');

            if (!searchInput) {
                // // console.warn('[ContentView] Essential elements not found, retrying...');
                setTimeout(initializeWidget, 100);
                return;
            }

            // // console.log('[ContentView] Setting up event listeners...');

            // Setup search input
            if (searchInput) searchInput.addEventListener('input', filterContent);

            // Setup modal close buttons
            if (closeModal) closeModal.addEventListener('click', closeEditModal);
            if (cancelEdit) cancelEdit.addEventListener('click', closeEditModal);

            // Setup modal click handler - scoped to widget
            modalClickHandler = function (event) {
                const editModal = getElementById('editModal');
                const deleteModal = getElementById('deleteModal');

                // Only handle clicks if modals are visible and click is on modal backdrop
                if (editModal && editModal.style.display === 'flex' && event.target === editModal) {
                    closeEditModal();
                }
                if (deleteModal && deleteModal.style.display === 'flex' && event.target === deleteModal) {
                    closeDeleteModalFunc();
                }
            };
            document.addEventListener('click', modalClickHandler);

            // Setup form submit
            if (editForm) editForm.addEventListener('submit', handleEditSubmit);

            // Touch delay increment/decrement buttons
            const touchDelayInc = getElementById('editTouchDelayInc');
            const touchDelayDec = getElementById('editTouchDelayDec');
            if (touchDelayInc) {
                touchDelayInc.addEventListener('click', function () {
                    const input = getElementById('editTouchDelay');
                    if (input) input.value = parseInt(input.value || 0) + 1;
                });
            }
            if (touchDelayDec) {
                touchDelayDec.addEventListener('click', function () {
                    const input = getElementById('editTouchDelay');
                    if (input) {
                        const currentValue = parseInt(input.value || 0);
                        if (currentValue > 0) {
                            input.value = currentValue - 1;
                        }
                    }
                });
            }

            // Delete modal handlers
            if (closeDeleteModal) {
                closeDeleteModal.addEventListener('click', function (e) {
                    e.stopPropagation();
                    e.preventDefault();
                    closeDeleteModalFunc();
                });
            }
            if (cancelDelete) {
                cancelDelete.addEventListener('click', function (e) {
                    e.stopPropagation();
                    e.preventDefault();
                    closeDeleteModalFunc();
                });
            }
            if (confirmDeleteBtn) {
                confirmDeleteBtn.addEventListener('click', function (e) {
                    e.stopPropagation();
                    e.preventDefault();
                    confirmDelete();
                });
            }

            // Pagination buttons
            if (prevBtn) {
                prevBtn.addEventListener('click', () => {
                    if (currentPage > 1) {
                        goToPage(currentPage - 1);
                    }
                });
            }

            if (nextBtn) {
                nextBtn.addEventListener('click', () => {
                    const totalPages = Math.ceil(filteredContentData.length / ROWS_PER_PAGE);
                    if (currentPage < totalPages) {
                        goToPage(currentPage + 1);
                    }
                });
            }

            // Setup event delegation for edit/delete buttons
            const tableBody = getElementById('contentTableBody');
            if (tableBody) {
                tableBody.addEventListener('click', function (e) {
                    const target = e.target.closest('button');
                    if (!target) return;

                    if (target.classList.contains('edit') || target.closest('.edit')) {
                        const indexAttr = target.getAttribute('data-index');
                        if (indexAttr !== null) {
                            e.preventDefault();
                            e.stopPropagation();
                            editContent(parseInt(indexAttr));
                        }
                    } else if (target.classList.contains('delete') || target.closest('.delete')) {
                        const indexAttr = target.getAttribute('data-index');
                        if (indexAttr !== null) {
                            e.preventDefault();
                            e.stopPropagation();
                            deleteContent(parseInt(indexAttr));
                        }
                    }
                });
            }

            // Setup state change listener
            if (self.ctx.stateController) {
                // console.log('[content_view_jp] ✅ Setting up dashboard state listener');

                let stateChangeTimeout;
                self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
                    // console.log('[content_view_jp] 📡 Dashboard state changed');

                    if (stateChangeTimeout) {
                        clearTimeout(stateChangeTimeout);
                    }

                    stateChangeTimeout = setTimeout(function () {
                        // console.log('[content_view_jp] ⏳ Debounce complete, reloading device...');
                        self.ctx.ngZone.run(function () {
                            loadDeviceFromState();
                        });
                    }, 200); // Debounce 200ms
                });
            } else {
                // console.warn('[content_view_jp] ⚠️ No stateController available for subscription');
            }

            // Load device from dashboard state on init (with slight delay)

            setTimeout(function () {
                loadDeviceFromState();
            }, 300);
        }, 50);
    }

    // Reload when widget data updates
    self.onDataUpdated = function () {
        // // console.log('[content_view_jp] Widget data updated, reloading device...');
        self.ctx.ngZone.run(function () {
            loadDeviceFromState();
            self.ctx.detectChanges();
        });
    };

    function filterContent() {
        // // console.log('[ContentView] Filtering content. Current data:', contentData.length, 'items');

        const searchInput = getElementById('searchInput');

        // Ensure contentData is an array
        if (!Array.isArray(contentData)) {
            // // console.error('[ContentView] contentData is not an array:', contentData);
            contentData = [];
        }

        // If element not found, just use all contentData
        if (!searchInput) {
            // // console.warn('[ContentView] Search input not found, showing all content');
            // Store original index in each item for easy lookup
            filteredContentData = contentData.map((item, index) => {
                if (item) {
                    item._originalIndex = index;
                }
                return item;
            }).filter(item => item != null);
            currentPage = 1;
            renderTable();
            renderPagination();
            return;
        }

        const searchTerm = searchInput.value.toLowerCase().trim();

        // Filter and preserve original index
        filteredContentData = contentData.map((item, index) => {
            if (!item) return null;

            if (searchTerm) {
                // Support both old format (store) and new format
                const store = (item.store || '').toLowerCase();
                // Support both old and new field names
                const itemType = (item.type || item.contentType || '').toLowerCase();
                const fileName = (item.file_name || item.fileName || '').toLowerCase();

                if (!store.includes(searchTerm) &&
                    !itemType.includes(searchTerm) &&
                    !fileName.includes(searchTerm)) {
                    return null;
                }
            }

            // Store original index for easy lookup
            item._originalIndex = index;
            return item;
        }).filter(item => item != null);

        // // console.log('[ContentView] Filtered content:', filteredContentData.length, 'items');
        currentPage = 1;
        renderTable();
        renderPagination();
    }

    // ⚠️ WEBHOOK-ONLY MODE: No auto-refresh
    // Content only loads on:
    // - Initial widget load
    // - Manual user action (edit/delete)
    // - ThingsBoard webhook trigger (requires Rule Chain setup)

    // ===== Auto Refresh Logic =====
    function startAutoRefresh() {
        if (autoRefreshInterval) return;

        // // console.log('[ContentView] Starting auto-refresh (10s interval)...');
        autoRefreshInterval = setInterval(() => {
            // Only refresh if modal is not open
            if (!isModalOpen) {
                loadContent(true); // Silent refresh
            }
        }, 10000); // 10 seconds
    }

    function stopAutoRefresh() {
        if (autoRefreshInterval) {
            clearInterval(autoRefreshInterval);
            autoRefreshInterval = null;
            // // console.log('[ContentView] Stopped auto-refresh');
        }
    }

    function editContent(index) {
        // Validate index and get item
        if (index < 0 || index >= contentData.length) {
            // // console.error('[ContentView] Invalid index for editContent:', index, 'ContentData length:', contentData.length);
            showStatus('エラー: 無効なコンテンツアイテムです', 'error');
            return;
        }

        const item = contentData[index];

        if (!item) {
            // // console.error('[ContentView] Item is undefined at index:', index, 'ContentData:', contentData);
            showStatus('エラー: コンテンツアイテムが見つかりませんでした', 'error');
            return;
        }

        // // console.log('[ContentView] Editing content item:', item, 'at index:', index);

        isModalOpen = true;

        // Get all form elements
        const editIdEl = getElementById('editId');
        const editCoordinateEl = getElementById('editCoordinate');
        const editRefLinkEl = getElementById('editRefLink');
        const editDurationEl = getElementById('editDuration');
        const editTouchDelayEl = getElementById('editTouchDelay');
        const editDescriptionEl = getElementById('editDescription');

        // Validate elements exist
        if (!editIdEl || !editCoordinateEl || !editRefLinkEl ||
            !editDurationEl || !editTouchDelayEl || !editDescriptionEl) {
            // // console.error('[ContentView] Edit form elements not found');
            showStatus('エラー: 編集フォームの準備ができていません', 'error');
            return;
        }

        // Populate form fields with full information from JSON
        editIdEl.value = index;

        // Coordinate - from content_item
        editCoordinateEl.value = item.coordinate !== undefined && item.coordinate !== null ? item.coordinate : 0;

        // Reference link - from store level (refLink)
        editRefLinkEl.value = item.refLink || item.ref_link || '';

        // Duration - from content_item, already in milliseconds, convert to seconds for display
        const durationMs = item.duration || 0;
        editDurationEl.value = Math.floor(durationMs / 1000);

        // Touch delay - from content_item (touch_delay), already in milliseconds, convert to seconds
        const touchDelayMs = item.touch_delay || item.touchDelay || 0;
        editTouchDelayEl.value = Math.floor(touchDelayMs / 1000);

        // Description - from store level
        editDescriptionEl.value = item.description || '';

        // // console.log('[ContentView] Form populated:', {
        //    coordinate: editCoordinateEl.value,
        //    refLink: editRefLinkEl.value,
        //    duration: editDurationEl.value,
        //    touchDelay: editTouchDelayEl.value,
        //    description: editDescriptionEl.value
        //});

        // Load video preview
        const videoPreview = getElementById('editVideoPreview');
        const videoError = getElementById('editVideoError');

        // Build video URL - support both old (videoUrl) and new (URL) format
        let videoUrl = null;

        // Method 1: Use URL field (new format) or videoUrl (old format)
        const urlField = item.URL || item.videoUrl;
        if (urlField) {
            // If it's a full URL, use it directly
            if (urlField.startsWith('http://') || urlField.startsWith('https://')) {
                videoUrl = urlField;
            } else if (urlField.startsWith('/')) {
                // Relative URL, prepend FLASK_SERVER
                const FLASK_SERVER = getFlaskServerUrl();
                videoUrl = `${FLASK_SERVER}${urlField}`;
            } else {
                // Just a path, construct full URL
                const FLASK_SERVER = getFlaskServerUrl();
                videoUrl = `${FLASK_SERVER}/videos/${urlField}`;
            }
        }

        // Method 2: Extract from URL if it contains /uploads/ or /videos/
        if (!videoUrl && urlField) {
            if (urlField.includes('/uploads/')) {
                // Extract filename from URL like "https://.../uploads/2025-11-05T09-25-40.352Z-cho.mp4"
                const filename = urlField.split('/uploads/')[1].split('?')[0];
                videoUrl = urlField; // Use full URL directly
            } else if (urlField.includes('/videos/')) {
                const filename = urlField.split('/videos/')[1].split('?')[0];
                const FLASK_SERVER = getFlaskServerUrl();
                videoUrl = `${FLASK_SERVER}/videos/${filename}`;
            }
        }

        // // console.log('[ContentView] Loading video preview. URL:', videoUrl, 'Item:', item);

        if (videoUrl && videoPreview) {
            videoPreview.src = videoUrl;
            videoPreview.style.display = 'block';
            if (videoError) videoError.style.display = 'none';

            videoPreview.onerror = function () {
                // // console.error('[ContentView] Video load error. URL:', videoUrl);
                if (videoPreview) videoPreview.style.display = 'none';
                if (videoError) videoError.style.display = 'flex';
            };

            videoPreview.onloadeddata = function () {
                // // console.log('[ContentView] Video loaded successfully:', videoUrl);
                if (videoPreview) videoPreview.style.display = 'block';
                if (videoError) videoError.style.display = 'none';
            };
        } else {
            // // console.warn('[ContentView] No video URL found for item:', item);
            if (videoPreview) videoPreview.style.display = 'none';
            if (videoError) videoError.style.display = 'flex';
        }

        const editModal = getElementById('editModal');
        if (editModal) editModal.style.display = 'flex';
    }

    function deleteContent(index) {
        const item = contentData[index];
        pendingDeleteIndex = index;

        isModalOpen = true;

        const deleteModal = getElementById('deleteModal');
        const deleteMessage = getElementById('deleteConfirmMessage');
        if (deleteModal && deleteMessage) {
            deleteMessage.textContent = `このコンテンツを削除してもよろしいですか？`;
            deleteModal.style.display = 'flex';
        }
    }

    async function confirmDelete() {
        if (pendingDeleteIndex === null) return;

        const index = pendingDeleteIndex;
        pendingDeleteIndex = null;

        contentData.splice(index, 1);

        closeDeleteModalFunc();

        try {
            const FLASK_SERVER = getFlaskServerUrl();
            const tenantUsername = getTenantUsername();

            // Prepare headers with tenant info (if available)
            const headers = {
                'Content-Type': 'application/json'
            };
            if (tenantUsername) {
                headers['X-TB-Tenant-Username'] = tenantUsername;
                // // console.log('[ContentView] Using tenant username:', tenantUsername);
            }

            const response = await fetch(`${FLASK_SERVER}/api/update-content`, {
                method: 'POST',
                headers: headers,
                body: JSON.stringify({
                    content: contentData,
                    deviceId: currentDeviceId
                })
            });

            const data = await response.json();

            if (data.success) {
                const deletedCount = data.deletedVideos || 0;
                const message = deletedCount > 0
                    ? `コンテンツが正常に削除されました。${deletedCount} 件の動画ファイルが削除されました。`
                    : 'コンテンツが正常に削除されました。';
                showStatus(message, 'success');
                // Reload content to get updated data
                await loadContent(true);
            } else {
                showStatus('削除に失敗しました: ' + (data.error || '不明なエラー'), 'error');
                // Reload content on error to ensure consistency
                await loadContent(true);
            }
        } catch (error) {
            // // console.error('[ContentView] Error deleting content:', error);
            showStatus('コンテンツの削除エラー: ' + error.message, 'error');
            loadContent();
        }
    }

    function closeDeleteModalFunc() {
        const deleteModal = getElementById('deleteModal');
        if (deleteModal) {
            deleteModal.style.display = 'none';
        }
        pendingDeleteIndex = null;
        isModalOpen = false;
    }

    function closeDeleteModal() {
        closeDeleteModalFunc();
    }

    async function loadContent(silent = false) {
        if (isLoadingContent) {
            // // console.log('[ContentView] Already loading content, skipping...');
            return;
        }

        if (!currentDeviceId) {
            // // console.warn('[ContentView] No device selected, cannot load content');
            contentData = [];
            filteredContentData = [];
            renderTable();
            return;
        }

        isLoadingContent = true;

        // FIXED: Don't show loading spinner if we have cached data
        // Only show spinner during actual fetch
        // FIXED: Don't show loading spinner if we have cached data OR if silent load
        // Only show spinner during actual fetch
        const tbody = getElementById('contentTableBody');
        if (tbody && contentData.length === 0 && !silent) {
            tbody.innerHTML = getLoadingSpinnerHTML();
        }

        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // // console.log('[ContentView] Fetching content from:', `${FLASK_SERVER}/api/get-content?deviceId=${currentDeviceId}`);

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        try {
            const response = await fetch(`${FLASK_SERVER}/api/get-content?deviceId=${currentDeviceId}`, {
                method: 'GET',
                headers: headers
            });

            // // console.log('[ContentView] Response status:', response.status, response.statusText);

            if (!response.ok) {
                const errorText = await response.text();
                // // console.error('[ContentView] HTTP error response:', errorText);
                throw new Error(`HTTP error! status: ${response.status} - ${errorText}`);
            }

            const data = await response.json();
            // // console.log('[ContentView] Response data:', data);

            if (data.success) {
                const newContentData = data.content || [];
                // // console.log('[ContentView] Loaded content data for device', currentDeviceId, ':', newContentData.length, 'items');
                // // console.log('[ContentView] Content items:', newContentData);

                // Ensure contentData is an array
                if (!Array.isArray(newContentData)) {
                    // // console.error('[ContentView] contentData is not an array:', newContentData);
                    contentData = [];
                } else {
                    contentData = newContentData;
                    // Save to cache for faster loading next time
                    saveToCache(newContentData);
                }

                // FIXED: Set loading to false BEFORE rendering
                isLoadingContent = false;

                // Always call filterContent to update filteredContentData and render
                // // console.log('[ContentView] Filtering content...');
                filterContent();

                // Try to sync hash (non-blocking)
                const FLASK_SERVER = getFlaskServerUrl();
                fetch(`${FLASK_SERVER}/api/check-updates?deviceId=${currentDeviceId}`, {
                    method: 'GET',
                    headers: { 'Content-Type': 'application/json' }
                }).then(hashResponse => {
                    if (hashResponse.ok) {
                        return hashResponse.json();
                    }
                }).then(hashData => {
                    if (hashData && hashData.success) {
                        currentContentHash = hashData.hash;
                    }
                }).catch(e => {
                    // // console.warn('[ContentView] Hash sync error (non-critical):', e);
                });

                // Start auto refresh after first successful load
                // Start auto refresh after first successful load
                if (!autoRefreshInterval) {
                    startAutoRefresh();
                }
            } else {
                // // console.error('[ContentView] API returned success=false:', data.error);
                // Clear content data on error
                contentData = [];
                filteredContentData = [];
                isLoadingContent = false; // FIXED: Set loading to false before rendering
                renderTable();

                if (!silent) {
                    showStatus('コンテンツの読み込みに失敗しました: ' + (data.error || '不明なエラー'), 'error');
                }
            }
        } catch (error) {
            const FLASK_SERVER = getFlaskServerUrl();
            // // console.error('[ContentView] Error loading content:', error);
            // // console.error('[ContentView] Error details:', {
            //    message: error.message,
            //    stack: error.stack,
            //    server: FLASK_SERVER
            //});

            // Clear content data on error
            contentData = [];
            filteredContentData = [];
            isLoadingContent = false; // FIXED: Set loading to false before rendering

            // Always render table, even on error
            renderTable();

            if (!silent) {
                const errorMsg = error.message || 'Unknown error';
                showStatus('コンテンツの読み込みエラー: ' + errorMsg + '。サーバーが ' + FLASK_SERVER + ' で実行されているか確認してください。', 'error');
            }
        } finally {
            isLoadingContent = false;
            // // console.log('[ContentView] Loading completed. Content items:', contentData.length);
        }
    }

    function renderTable() {
        const tbody = getElementById('contentTableBody');
        if (!tbody) {
            // // console.error('[ContentView] Table body not found');
            return;
        }

        // Check if we're in ALL devices mode
        const isAllDevicesMode = currentDeviceId === '__ALL__';
        const colspan = '4'; // Always 4 columns

        // // console.log('[ContentView] Rendering table. Content:', contentData.length, 'Filtered:', filteredContentData.length, 'Loading:', isLoadingContent);

        // FIXED: Only show loading spinner when actively loading (not when there's no data)
        // Show loading only if actively loading AND we haven't loaded any data yet
        if (isLoadingContent) {
            tbody.innerHTML = getLoadingSpinnerHTML();
            return;
        }

        tbody.innerHTML = '';

        if (filteredContentData.length === 0) {
            if (contentData.length === 0) {
                if (!currentDeviceId) {
                    tbody.innerHTML = `<tr class="empty-row"><td colspan="${colspan}" class="empty-message">デバイスが選択されていません。顧客セレクターからデバイスを選択してください。</td></tr>`;
                } else {
                    tbody.innerHTML = `<tr class="empty-row"><td colspan="${colspan}" class="empty-message">このデバイスのコンテンツが見つかりませんでした。</td></tr>`;
                }
            } else {
                tbody.innerHTML = `<tr class="empty-row"><td colspan="${colspan}" class="empty-message">検索条件に一致するコンテンツは見つかりませんでした</td></tr>`;
            }
            renderPagination();
            return;
        }

        const totalPages = Math.ceil(filteredContentData.length / ROWS_PER_PAGE);

        if (currentPage > totalPages && totalPages > 0) {
            currentPage = totalPages;
        }

        const startIndex = (currentPage - 1) * ROWS_PER_PAGE;
        const endIndex = Math.min(startIndex + ROWS_PER_PAGE, filteredContentData.length);
        const paginatedData = filteredContentData.slice(startIndex, endIndex);

        paginatedData.forEach((item, paginatedIndex) => {
            if (!item) {
                // // console.warn('[ContentView] Skipping null/undefined item at paginatedIndex:', paginatedIndex);
                return;
            }

            const row = document.createElement('tr');

            // Use stored original index if available (set during filter)
            let originalIndex = item._originalIndex;

            // If not available, try to find it
            if (originalIndex === undefined || originalIndex < 0 || originalIndex >= contentData.length) {
                // Try to find by direct reference (same object)
                originalIndex = contentData.findIndex(content => content === item);
            }

            // If still not found, try to find by properties
            if (originalIndex === -1) {
                originalIndex = contentData.findIndex(content => {
                    if (!content) return false;

                    // Match by checksum if available (new format)
                    if (content.checksum && item.checksum && content.checksum === item.checksum) {
                        return true;
                    }
                    // Match by ID if available
                    if (content.id && item.id && content.id === item.id) {
                        return true;
                    }
                    // Fallback: match by multiple properties
                    const contentFileName = content.file_name || content.fileName;
                    const itemFileName = item.file_name || item.fileName;
                    const contentType = content.type || content.contentType;
                    const itemType = item.type || item.contentType;
                    const contentStore = content.store || '';
                    const itemStore = item.store || '';

                    return contentStore === itemStore &&
                        contentFileName === itemFileName &&
                        contentType === itemType;
                });
            }

            // Validate that we have a valid index
            if (originalIndex === -1 || originalIndex < 0 || originalIndex >= contentData.length) {
                // // console.error('[ContentView] Could not find valid index for item:', item);
                return; // Skip rendering this row
            }

            // Double-check the item exists at this index
            if (!contentData[originalIndex]) {
                // // console.error('[ContentView] Item at originalIndex is undefined:', originalIndex);
                return; // Skip rendering this row
            }

            // Support both old and new format
            const store = item.customer || item.store || 'N/A';
            const type = item.type || item.contentType || 'N/A';
            const fileName = item.file_name || item.fileName || 'N/A';

            // Build row HTML
            let rowHTML = `
                <td>${escapeHtml(store)}</td>
                <td>${escapeHtml(type)}</td>
                <td>${escapeHtml(fileName)}</td>
            `;

            // Always show Actions column, but disable buttons in ALL devices mode
            const disabledAttr = isAllDevicesMode ? 'disabled' : '';
            const disabledClass = isAllDevicesMode ? 'disabled' : '';
            const dataIndex = isAllDevicesMode ? '' : `data-index="${originalIndex}"`;

            rowHTML += `
                <td>
                    <div class="action-buttons">
                        <button class="action-btn edit ${disabledClass}" ${dataIndex} ${disabledAttr} title="${isAllDevicesMode ? 'すべてのデバイスモードでは利用できません' : '編集'}">
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                            </svg>
                        </button>
                        <button class="action-btn delete ${disabledClass}" ${dataIndex} ${disabledAttr} title="${isAllDevicesMode ? 'すべてのデバイスモードでは利用できません' : '削除'}">
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <polyline points="3 6 5 6 21 6"></polyline>
                                <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                            </svg>
                        </button>
                    </div>
                </td>
            `;

            row.innerHTML = rowHTML;

            tbody.appendChild(row);
        });

        renderPagination();
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    function renderPagination() {
        const totalItems = filteredContentData.length;
        const totalPages = Math.ceil(totalItems / ROWS_PER_PAGE);
        const startIndex = totalItems === 0 ? 0 : (currentPage - 1) * ROWS_PER_PAGE + 1;
        const endIndex = Math.min(currentPage * ROWS_PER_PAGE, totalItems);

        const paginationText = getElementById('paginationText');
        const prevBtn = getElementById('prevBtn');
        const nextBtn = getElementById('nextBtn');
        const pageNumbersContainer = getElementById('pageNumbers');

        if (!paginationText || !prevBtn || !nextBtn || !pageNumbersContainer) return;

        paginationText.textContent = `${totalItems}件中${startIndex}〜${endIndex}件を表示`;
        prevBtn.disabled = currentPage === 1;
        nextBtn.disabled = currentPage === totalPages || totalPages === 0;
        pageNumbersContainer.innerHTML = '';

        if (totalPages === 0) {
            return;
        }

        let startPage = Math.max(1, currentPage - 2);
        let endPage = Math.min(totalPages, startPage + 4);

        if (endPage - startPage < 4) {
            startPage = Math.max(1, endPage - 4);
        }

        for (let i = startPage; i <= endPage; i++) {
            const pageBtn = document.createElement('button');
            pageBtn.className = 'page-number';
            if (i === currentPage) {
                pageBtn.classList.add('active');
            }
            pageBtn.textContent = i;
            pageBtn.onclick = () => goToPage(i);
            pageNumbersContainer.appendChild(pageBtn);
        }
    }

    function goToPage(page) {
        const totalPages = Math.ceil(filteredContentData.length / ROWS_PER_PAGE);
        if (page < 1 || page > totalPages) {
            return;
        }

        currentPage = page;
        renderTable();

        const tableContainer = widgetContainer ? widgetContainer.querySelector('.table-container') : document.querySelector('.table-container');
        if (tableContainer) {
            tableContainer.scrollTop = 0;
        }
    }

    function closeEditModal() {
        const editModal = getElementById('editModal');
        if (editModal) editModal.style.display = 'none';

        const editForm = getElementById('editForm');
        if (editForm) editForm.reset();

        // Reset video preview
        const videoPreview = getElementById('editVideoPreview');
        const videoError = getElementById('editVideoError');
        if (videoPreview) {
            videoPreview.src = '';
            videoPreview.style.display = 'none';
        }
        if (videoError) {
            videoError.style.display = 'flex';
        }

        isModalOpen = false;
        // startAutoRefresh(); // Removed: webhook-only mode
    }

    async function handleEditSubmit(e) {
        e.preventDefault();

        const editIdEl = getElementById('editId');
        if (!editIdEl) return;

        const index = parseInt(editIdEl.value);
        const originalItem = contentData[index];

        if (!originalItem) {
            showStatus('エラー: コンテンツアイテムが見つかりませんでした', 'error');
            return;
        }

        // Get form values
        const coordinate = parseInt(getElementById('editCoordinate').value) || 0;
        const durationSeconds = parseInt(getElementById('editDuration').value) || 0;
        const touchDelaySeconds = parseInt(getElementById('editTouchDelay').value) || 0;
        const refLink = (getElementById('editRefLink')?.value || '').trim();
        const description = (getElementById('editDescription')?.value || '').trim();

        // Convert seconds to milliseconds for storage
        const durationMs = durationSeconds * 1000;
        const touchDelayMs = touchDelaySeconds * 1000;

        // Update item with all fields from JSON format
        // Preserve all original fields and update only changed ones
        const updatedItem = {
            ...originalItem,
            // Content item fields (from content_item array)
            coordinate: coordinate,
            duration: durationMs,
            touch_delay: touchDelayMs,
            // Update timestamp
            updatedAt: new Date().toISOString(),
            // Store level fields (from store entry)
            store: originalItem.store || '',
            description: description, // Always use form value, even if empty
            refLink: refLink, // Always use form value, even if empty
            // Preserve category if it exists (not editable)
            category: originalItem.category,
            // Preserve deviceId and deviceName
            deviceId: originalItem.deviceId || currentDeviceId,
            deviceName: originalItem.deviceName || currentDeviceName
        };

        // Ensure all required fields are present
        if (!updatedItem.checksum && originalItem.checksum) {
            updatedItem.checksum = originalItem.checksum;
        }
        if (!updatedItem.createdAt && originalItem.createdAt) {
            updatedItem.createdAt = originalItem.createdAt;
        }
        if (!updatedItem.file_name && originalItem.file_name) {
            updatedItem.file_name = originalItem.file_name;
        }
        if (!updatedItem.file_size && originalItem.file_size) {
            updatedItem.file_size = originalItem.file_size;
        }
        if (!updatedItem.type && originalItem.type) {
            updatedItem.type = originalItem.type;
        }
        if (!updatedItem.URL && originalItem.URL) {
            updatedItem.URL = originalItem.URL;
        }

        contentData[index] = updatedItem;

        // Get submit button - it's outside the form with form="editForm" attribute
        const submitBtn = widgetContainer
            ? widgetContainer.querySelector('button[form="editForm"][type="submit"]')
            : document.querySelector('button[form="editForm"][type="submit"]');
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.textContent = '更新中...';
        }

        try {
            const FLASK_SERVER = getFlaskServerUrl();
            const tenantUsername = getTenantUsername();

            // Prepare headers with tenant info (if available)
            const headers = {
                'Content-Type': 'application/json'
            };
            if (tenantUsername) {
                headers['X-TB-Tenant-Username'] = tenantUsername;
                // // console.log('[ContentView] Using tenant username:', tenantUsername);
            }

            const response = await fetch(`${FLASK_SERVER}/api/update-content`, {
                method: 'POST',
                headers: headers,
                body: JSON.stringify({
                    content: contentData,
                    deviceId: currentDeviceId
                })
            });

            const data = await response.json();

            if (data.success) {
                showStatus('コンテンツが正常に更新されました', 'success');
                // Reload content from server to get updated data including updatedAt
                await loadContent(true);
                closeEditModal();
            } else {
                showStatus('更新に失敗しました: ' + (data.error || '不明なエラー'), 'error');
                // Reload content on error to ensure consistency
                await loadContent(true);
            }
        } catch (error) {
            // // console.error('[ContentView] Error updating content:', error);
            showStatus('コンテンツの更新エラー: ' + error.message, 'error');
            loadContent();
        } finally {
            // Reset submit button if it exists
            const submitBtn = widgetContainer
                ? widgetContainer.querySelector('button[form="editForm"][type="submit"]')
                : document.querySelector('button[form="editForm"][type="submit"]');
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = '更新';
            }
        }
    }

    function showStatus(message, type) {
        const statusEl = getElementById('statusMessage');
        if (!statusEl) return;

        statusEl.textContent = message;
        statusEl.className = `status-message ${type}`;
        statusEl.style.display = 'block';

        setTimeout(function () {
            if (statusEl) {
                statusEl.style.display = 'none';
            }
        }, 5000);
    }

    // ThingsBoard widget initialization
    self.onInit = function () {
        initializeWidget();
    };

    // ThingsBoard widget cleanup (if available)
    if (typeof self.onDestroy === 'undefined') {
        self.onDestroy = function () {
            cleanup();
        };
    } else {
        const originalOnDestroy = self.onDestroy;
        self.onDestroy = function () {
            cleanup();
            if (originalOnDestroy) originalOnDestroy();
        };
    }
})();

