        renderEditContentList();
        modal.style.display = 'block';
    }
}

function closeEditContentModalFunc() {
    const modal = getWidgetElement('editContentModal');
    if (modal) {
        modal.style.display = 'none';
    }
}

function renderEditContentList(searchTerm = '') {
    const contentList = getWidgetElement('editContentList');
    if (!contentList) return;

    if (editAvailableContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">No content available for this device</div>';
        return;
    }

    let filteredContent = editAvailableContent;
    if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        filteredContent = editAvailableContent.filter(item => {
            const store = (item.customer || item.store || '').toLowerCase();
            const fileName = (item.file_name || item.fileName || '').toLowerCase();
            const type = (item.type || item.contentType || '').toLowerCase();
            return store.includes(searchLower) ||
                fileName.includes(searchLower) ||
                type.includes(searchLower);
        });
    }

    if (filteredContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">No content found</div>';
        return;
    }

    function formatFileSize(bytes) {
        if (!bytes || bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
    }

    function getFileSizeDisplay(fileSize) {
        if (!fileSize) return '0 B';

        if (typeof fileSize === 'string' && /[A-Za-z]/.test(fileSize)) {
            return fileSize;
        }

        const numSize = parseInt(fileSize, 10);
        if (!isNaN(numSize)) {
            return formatFileSize(numSize);
        }

        return '0 B';
    }

    contentList.innerHTML = filteredContent.map((item, index) => {
        const isSelected = editSelectedContents.find(c => c.id === item.checksum);
        const fileName = item.file_name || item.fileName || 'Unknown';
        const type = item.type || item.contentType || 'video';
        const fileSize = item.file_size || item.fileSize || 0;
        const formattedSize = getFileSizeDisplay(fileSize);

        return `
            <div class="content-item ${isSelected ? 'selected' : ''}" 
                 data-content-id="${item.checksum}"
                 data-content-index="${index}">
                <div>
                    <div class="content-item-name">${item.customer || item.store || 'Unknown Store'}</div>
                    <div class="content-item-type">${fileName}</div>
                    <div class="content-item-meta">
                        <span class="content-item-type-label">Type: ${type}</span>
                        <span class="content-item-size-label">Size: ${formattedSize}</span>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    contentList.querySelectorAll('.content-item').forEach(item => {
        item.onclick = function () {
            this.classList.toggle('selected');
        };
    });
}

function updateEditContentDisplay() {
    const contentLabel = getWidgetElement('editContentLabel');
    const selectedContentList = getWidgetElement('editSelectedContentList');

    if (contentLabel) {
        contentLabel.textContent = editSelectedContents.length > 0
            ? `${editSelectedContents.length} コンテンツを選択済み`
            : 'コンテンツを選択';
    }

    if (editSelectedContents.length > 0) {
        if (selectedContentList) {
            selectedContentList.style.display = 'block';
        }
        renderEditContentItems();
    } else {
        if (selectedContentList) {
            selectedContentList.style.display = 'none';
        }
    }
}

