function parseDateForInput(dateStr) {
    if (!dateStr) return '';
    try {
        let date;

        // Check if date string has format like "Jan 4, 2025 00:00:00" (English month format)
        const englishMonthPattern = /^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d+),\s+(\d+)\s+00:00:00$/;
        const englishMatch = dateStr.match(englishMonthPattern);

        if (englishMatch) {
            // Parse English month format: "Jan 4, 2025 00:00:00"
            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const monthIndex = monthNames.indexOf(englishMatch[1]);
            if (monthIndex !== -1) {
                const day = parseInt(englishMatch[2], 10);
                const year = parseInt(englishMatch[3], 10);
                date = new Date(year, monthIndex, day);
            } else {
                date = new Date(dateStr);
            }
        } else {
            // Check if date string has format like "1月 4, 2025 00:00:00" (Japanese month format)
            const japaneseMonthPattern = /^(\d+)月\s+(\d+),\s+(\d+)\s+00:00:00$/;
            const japaneseMatch = dateStr.match(japaneseMonthPattern);

            if (japaneseMatch) {
                // Parse Japanese month format: "1月 4, 2025 00:00:00"
                const month = parseInt(japaneseMatch[1], 10) - 1; // Month is 0-indexed
                const day = parseInt(japaneseMatch[2], 10);
                const year = parseInt(japaneseMatch[3], 10);
                date = new Date(year, month, day);
            } else if (dateStr.includes('/')) {
                // Already in DD/MM/YYYY format, return as is
                return dateStr;
            } else if (dateStr.includes('T') || dateStr.includes('-')) {
                // ISO format or YYYY-MM-DD format
                date = new Date(dateStr);
            } else {
                // Try standard Date parsing
                date = new Date(dateStr);
            }
        }

        // Check if date is valid
        if (isNaN(date.getTime())) {
            // // console.warn('Invalid date format for input:', dateStr);
            return '';
        }

        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        return `${day}/${month}/${year}`;
    } catch (e) {
        // // console.warn('Error parsing date for input:', dateStr, e);
        return '';
    }
}

