async function confirmDelete() {
    if (pendingDeleteIndex === null) return;

    const index = pendingDeleteIndex;
    pendingDeleteIndex = null;

    const schedule = scheduleData[index];
    if (!schedule) {
        closeDeleteModalFunc();
        return;
    }

    try {
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        const deviceId = schedule.device_id;
        const scheduleName = schedule.name;

        // Get all schedules for this device
        const schedulesResponse = await fetch(`${FLASK_SERVER}/api/get-schedules`, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({ deviceIds: [deviceId] })
        });
        const schedulesData = await schedulesResponse.json();

        if (!schedulesData.success) {
            throw new Error('Failed to get schedules');
        }

        // Find the schedule index in the device's schedules
        let scheduleIndexInDevice = -1;
        const allSchedules = schedulesData.schedules || [];

        for (let i = 0; i < allSchedules.length; i++) {
            const s = allSchedules[i];
            if (s.device_id === deviceId &&
                s.name === scheduleName &&
                s.start_date === schedule.start_date &&
                s.end_date === schedule.end_date) {
                scheduleIndexInDevice = i;
                break;
            }
        }

        if (scheduleIndexInDevice === -1) {
            throw new Error('Schedule not found in device');
        }

        // Update headers for delete request (add logging)
        if (tenantUsername) {
            // // console.log('[ScheduleView] Using tenant username:', tenantUsername);
        }

        const deleteResponse = await fetch(`${FLASK_SERVER}/api/delete-schedule`, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({
                deviceId: deviceId,
                scheduleIndex: scheduleIndexInDevice
            })
        });

        const deleteData = await deleteResponse.json();

        if (deleteData.success) {
            scheduleData.splice(index, 1);
            closeDeleteModalFunc();
            showStatus('スケジュールが正常に削除されました', 'success');
            filterSchedules();
            // Reload schedules to reflect changes
            loadSchedules();
        } else {
            throw new Error(deleteData.error || 'Failed to delete schedule');
        }

    } catch (error) {
        // // console.error('Error deleting schedule:', error);
        showStatus('スケジュールの削除エラー: ' + error.message, 'error');
        closeDeleteModalFunc();
    }
}

function closeDeleteModalFunc() {
    const deleteModal = getWidgetElement('deleteModal');
    if (deleteModal) {
        deleteModal.style.display = 'none';
    }
    pendingDeleteIndex = null;
    isModalOpen = false;
}

async function handleEditSubmit(e) {
    e.preventDefault();

    const index = parseInt(getWidgetElement('editIndex').value);
    let deviceId = getWidgetElement('editDeviceId').value;
    let deviceToken = getWidgetElement('editDeviceToken').value;

    const schedule = scheduleData[index];
    if (!schedule) {
        showStatus('スケジュールが見つかりません', 'error');
        return;
    }

    if (editSelectedWeekdays.length === 0) {
        showStatus('少なくとも1つの曜日を選択してください', 'error');
        return;
    }

    if (editSelectedContents.length === 0) {
        showStatus('少なくとも1つのコンテンツを選択してください', 'error');
        return;
    }

    const scheduleName = getWidgetElement('editScheduleName').value.trim();
    if (!scheduleName) {
        showStatus('すべての必須フィールドに入力してください', 'error');
        return;
    }

    if (!deviceId) {
        const deviceSelect = getWidgetElement('editDeviceGroup');
        if (deviceSelect && deviceSelect.value) {
            const selectedOption = deviceSelect.options[deviceSelect.selectedIndex];
            if (selectedOption) {
                deviceId = selectedOption.getAttribute('data-device-id') || deviceSelect.value;
                deviceToken = selectedOption.getAttribute('data-device-token') || '';
                getWidgetElement('editDeviceId').value = deviceId;
                getWidgetElement('editDeviceToken').value = deviceToken;
            }
        }
    }

    // ✅ FIX: deviceToken is not required for /api/update-device-content
    // The endpoint only needs deviceId and will auto-detect tenant from deviceId
    // So we can skip the deviceToken check and fetching logic

    if (!deviceId) {
        showStatus('デバイスを選択してください', 'error');
        return;
    }

    // ✅ REMOVED: deviceToken check is not needed
    // Endpoint /api/update-device-content only requires deviceId

    const submitBtn = getWidgetElement('saveEditBtn');
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = '保存中...';
    }

    try {
        function getWeekdayName(dayValue) {
            const dayIndex = parseInt(dayValue);
            if (dayIndex >= 0 && dayIndex <= 6) {
                return getTranslation('weekdays', 'full', dayIndex);
            }
            return getTranslation('weekdays', 'full', 1); // Default to Monday
        }

        const startTime = getWidgetElement('editStartTime').value || '00:00';
        const endTime = getWidgetElement('editEndTime').value || '00:00';

        const dateTimeArray = editSelectedWeekdays.map(dayValue => ({
            date: getWeekdayName(dayValue),
            start: startTime,
            end: endTime
        }));

        const now = new Date().toISOString();

        const updatedSchedule = {
            name: scheduleName,
            contents: [{
                date_time: dateTimeArray,
                content: editSelectedContents.map(c => {
                    const contentItem = c.data || {};

                    const cleanContentItem = {};
                    const contentItemFields = ['checksum', 'coordinate', 'createdAt', 'duration',
                        'file_name', 'file_size', 'touch_delay', 'type',
                        'URL', 'updatedAt'];

                    contentItemFields.forEach(field => {
                        if (contentItem.hasOwnProperty(field)) {
                            cleanContentItem[field] = contentItem[field];
                        }
                    });

                    const condition = {
                        age_gte: c.ageFrom || 1,
                        age_lte: c.ageTo || 1
                    };

                    if (c.gender && c.gender !== '' && c.gender !== 'all') {
                        condition.gender = c.gender;
                    }

                    return {
                        condition: condition,
                        content_item: [cleanContentItem]
                    };
                })
            }],
            createdAt: schedule.createdAt || now,
            start_date: formatDateForSchedule(getWidgetElement('editStartDate').value),
            end_date: formatDateForSchedule(getWidgetElement('editEndDate').value),
            updatedAt: now,
            priority: getWidgetElement('editPriority').value || 'medium',
            screen_type: schedule.screen_type || 'fullscreen',
            device_id: deviceId
        };

        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
            // // console.log('[ScheduleView] Using tenant username:', tenantUsername);
        }

        const updateResponse = await fetch(`${FLASK_SERVER}/api/update-device-content`, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({
                deviceId: deviceId,
                content: [updatedSchedule]
            })
        });

        const updateData = await updateResponse.json();

        if (updateData.success) {
            scheduleData[index] = updatedSchedule;
            showStatus('スケジュールが正常に更新されました', 'success');
            filterSchedules();
            closeEditModal();
            // Reload schedules to reflect changes
            loadSchedules();
        } else {
            throw new Error(updateData.error || 'Failed to update schedule');
        }

    } catch (error) {
        // // console.error('Error updating schedule:', error);
        showStatus('スケジュールの更新エラー: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = '変更を保存';
        }
    }
}

function formatDateForSchedule(dateString) {
    if (!dateString) return '';

    // Parse DD/MM/YYYY format from Flatpickr
    let date;
    if (dateString.includes('/')) {
        const parts = dateString.split('/');
        if (parts.length === 3) {
            const day = parseInt(parts[0], 10);
            const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed
            const year = parseInt(parts[2], 10);
            date = new Date(year, month, day);
        } else {
            date = new Date(dateString);
        }
    } else {
        date = new Date(dateString + 'T00:00:00');
    }

    const monthName = getTranslation('months', 'short', date.getMonth());
    const day = date.getDate();
    const year = date.getFullYear();
    return `${monthName} ${day}, ${year} 00:00:00`;
}

function showStatus(message, type) {
    const statusEl = getWidgetElement('statusMessage');
    if (!statusEl) return;

    statusEl.textContent = message;
    statusEl.className = `status-message ${type}`;
    statusEl.style.display = 'block';

    setTimeout(function () {
        if (statusEl) {
            statusEl.style.display = 'none';
        }
    }, 5000);
}

