let selectedFile = null;

// ===== Get Flask Server URL =====
// Get from widget settings or use default
function getFlaskServerUrl() {
    try {
        const s = self.ctx.settings || {};
        return s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';
    } catch (e) {
        return 'http://127.0.0.1:5003';
    }
}

// ===== Get Tenant Username (for multi-tenant support) =====
function getTenantUsername() {
    try {
        // Try to get from ThingsBoard user context
        if (self.ctx.user && self.ctx.user.email) {
            return self.ctx.user.email;
        }
        // Try from userInfo
        if (self.ctx.userInfo && self.ctx.userInfo.email) {
            return self.ctx.userInfo.email;
        }
        // Try from $rootScope (ThingsBoard internal)
        const scope = self.ctx.$scope;
        if (scope && scope.$root && scope.$root.currentUser && scope.$root.currentUser.email) {
            return scope.$root.currentUser.email;
        }
    } catch (e) {
        // // console.warn('Could not get tenant username:', e);
    }
    return null;
}

// Current device info (from dashboard state)
let currentDeviceId = null;
let currentDeviceName = null;
let currentDeviceType = null; // Device type (Tablet/Edge) = Store

// Widget container for scoped element selection
let widgetContainer = null;

self.onInit = function () {
    self.ctx.ngZone.run(function () {
        // Get widget container
        widgetContainer = self.ctx.$container?.[0];
        if (!widgetContainer) {
            // console.warn('[add_content] Widget container not found, using document scope');
        }

        initializeWidget();
        self.ctx.detectChanges();
    });
};

// Helper: Get element within widget scope
function getElement(id) {
    if (widgetContainer) {
        return widgetContainer.querySelector('#' + id);
    }
    return document.getElementById(id);
}

// ===== Set Store from Device Type =====
function setStoreFromDeviceType() {
    const storeSelect = getElement('store');
    if (!storeSelect) return;

    // Clear all existing options
    storeSelect.innerHTML = '';

    if (currentDeviceType) {
        // Set store to device type
        const option = document.createElement('option');
        option.value = currentDeviceType;
        option.textContent = currentDeviceType;
        storeSelect.appendChild(option);
        storeSelect.value = currentDeviceType;
        // console.log(`[add_content] ✓ Set store from device type: ${currentDeviceType}`);
    } else {
        // No device type
        const defaultOption = document.createElement('option');
        defaultOption.value = '';
        defaultOption.textContent = 'No device type';
        defaultOption.disabled = true;
        defaultOption.selected = true;
        storeSelect.appendChild(defaultOption);
        // console.warn('[add_content] ⚠️ No device type available');
    }
}

// ===== Enable/Disable Upload Button =====
function enableUpload() {
    const submitBtn = getElement('submitBtn');
    if (submitBtn) {
        submitBtn.disabled = false;
    }
    hideAllDevicesMessage();
}

function disableUpload() {
    const submitBtn = getElement('submitBtn');
    if (submitBtn) {
        submitBtn.disabled = true;
    }
    showAllDevicesMessage();
}

function showAllDevicesMessage() {
    const statusEl = getElement('statusMessage');
    if (statusEl) {
        statusEl.textContent = 'ℹ️ コンテンツをアップロードするには単一のデバイスを選択してください。「すべての端末」モードではアップロードできません。';
        statusEl.className = 'status-message info';
        statusEl.style.display = 'block';
    }
}

function hideAllDevicesMessage() {
    const statusEl = getElement('statusMessage');
    if (statusEl && statusEl.className.includes('info')) {
        statusEl.style.display = 'none';
    }
}

// ===== Load Device from Dashboard State =====
function loadDeviceFromState() {
    if (!self.ctx || !self.ctx.stateController) {
        // console.warn('[add_content] ⚠️ No stateController available');
        showNoDeviceState();
        return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

    // console.log('[add_content] 📊 Loading device from state:', { deviceMode, stateParams });

    // ========= ALL DEVICES MODE =========
    if (deviceMode === 'ALL') {
        // console.log('[add_content] 📋 ALL devices mode - disabling upload button');
        currentDeviceId = '__ALL__';
        currentDeviceName = 'All Devices';
        currentDeviceType = stateParams?.selectedDeviceType || stateParams?.type || null;

        setStoreFromDeviceType();
        disableUpload();
        return;
    }

    // ========= SINGLE DEVICE MODE =========
    if (deviceMode === 'SINGLE') {
        const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
        const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'Device';
        const deviceType = stateParams?.selectedDeviceType || stateParams?.type;

        // console.log('[add_content] 📱 SINGLE device mode:', deviceName, deviceId, deviceType);

        if (deviceId) {
            currentDeviceId = deviceId;
            currentDeviceName = deviceName;
            currentDeviceType = deviceType;

            setStoreFromDeviceType();
            enableUpload();
            hideStatus();
        } else {
            showNoDeviceState();
        }
        return;
    }

    // ========= NONE OR NO MODE =========
    // console.log('[add_content] ⚠️ No device mode or NONE mode');
    showNoDeviceState();
}

function showNoDeviceState() {
    currentDeviceId = null;
    currentDeviceName = null;
    currentDeviceType = null;
    setStoreFromDeviceType();
    disableUpload();
    showStatus('⚠️ デバイスが選択されていません。顧客セレクターからデバイスを選択してください。', 'error');
}

function hideStatus() {
    const statusEl = getElement('statusMessage');
    if (statusEl) {
        statusEl.style.display = 'none';
    }
}

// Helper to get element within widget scope
function getElement(id) {
    const container = self.ctx.$container?.[0];
    return container ? container.querySelector('#' + id) : document.getElementById(id);
}

function initializeWidget() {
    const uploadArea = getElement('uploadArea');
    const fileInput = getElement('fileInput');
    const browseBtn = getElement('browseBtn');
    const submitBtn = getElement('submitBtn');

    // Number input handlers
    const touchDelayInc = getElement('touchDelayInc');
    const touchDelayDec = getElement('touchDelayDec');
    const durationInc = getElement('durationInc');
    const durationDec = getElement('durationDec');

    if (touchDelayInc) touchDelayInc.addEventListener('click', function () {
        incrementValue('touchDelay');
    });

    if (touchDelayDec) touchDelayDec.addEventListener('click', function () {
        decrementValue('touchDelay');
    });

    if (durationInc) durationInc.addEventListener('click', function () {
        incrementValue('duration');
    });

    if (durationDec) durationDec.addEventListener('click', function () {
        decrementValue('duration');
    });

    // Browse button
    browseBtn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        fileInput.click();
    });

    // Upload area click
    uploadArea.addEventListener('click', function (e) {
        if (e.target === browseBtn) return;
        fileInput.click();
    });

    // Drag and drop
    uploadArea.addEventListener('dragover', function (e) {
        e.preventDefault();
        uploadArea.classList.add('dragover');
    });

    uploadArea.addEventListener('dragleave', function () {
        uploadArea.classList.remove('dragover');
    });

    uploadArea.addEventListener('drop', function (e) {
        e.preventDefault();
        uploadArea.classList.remove('dragover');
        const files = e.dataTransfer.files;
        if (files.length > 0) {
            handleFile(files[0]);
        }
    });

    // File input change
    fileInput.addEventListener('change', function (e) {
        if (e.target.files.length > 0) {
            handleFile(e.target.files[0]);
        }
    });

    // Submit button
    submitBtn.addEventListener('click', function () {
        uploadContent();
    });

    // ===== Setup Dashboard State Subscription =====
    if (self.ctx.stateController) {
        // console.log('[add_content] ✅ Setting up dashboard state listener');

        let stateChangeTimeout;
        self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
            // console.log('[add_content] 📡 Dashboard state changed');

            if (stateChangeTimeout) {
                clearTimeout(stateChangeTimeout);
            }

            stateChangeTimeout = setTimeout(function () {
                // console.log('[add_content] ⏳ Debounce complete, reloading device...');
                self.ctx.ngZone.run(function () {
                    loadDeviceFromState();
                });
            }, 200); // Debounce 200ms
        });
    } else {
        // console.warn('[add_content] ⚠️ No stateController available for subscription');
    }

    // Load device from state on init (with slight delay)
    setTimeout(function () {
        loadDeviceFromState();
    }, 300);
}

// Cleanup
self.onDestroy = function () {
    if (self.stateChangeSubscription) {
        self.stateChangeSubscription.unsubscribe();
        self.stateChangeSubscription = null;
        // console.log('[add_content] ✅ Unsubscribed from state changes');
    }
}

// Reload when widget data updates
self.onDataUpdated = function () {
    // console.log('[add_content] 📊 Widget data updated, reloading device...');
    self.ctx.ngZone.run(function () {
        loadDeviceFromState();
        self.ctx.detectChanges();
    });
};

function incrementValue(id) {
    const input = getElement(id);
    if (input) input.value = parseInt(input.value) + 1;
}

function decrementValue(id) {
    const input = getElement(id);
    if (input && parseInt(input.value) > 0) {
        input.value = parseInt(input.value) - 1;
    }
}

function handleFile(file) {
    if (!file.type.startsWith('video/')) {
        showStatus('動画ファイルを選択してください', 'error');
        return;
    }

    selectedFile = file;
    const filePreview = getElement('filePreview');
    if (filePreview) {
        filePreview.style.display = 'block';
        filePreview.innerHTML = `📹 ${file.name} (${(file.size / 1024 / 1024).toFixed(2)} MB)`;
    }
}

function showStatus(message, type) {
    const statusEl = getElement('statusMessage');
    if (statusEl) {
        statusEl.textContent = message;
        statusEl.className = `status-message ${type}`;
        statusEl.style.display = 'block';

        setTimeout(function () {
            statusEl.style.display = 'none';
        }, 5000);
    }
}

async function uploadContent() {
    // Validate device is selected
    if (!currentDeviceId || currentDeviceId === '__ALL__') {
        showStatus('単一のデバイスを選択してください。「すべての端末」モードではアップロードできません。', 'error');
        return;
    }

    if (!currentDeviceType) {
        showStatus('デバイスタイプが利用できません。アップロードできません。', 'error');
        return;
    }

    // Validate required fields
    const store = getElement('store')?.value;
    const touchDelay = getElement('touchDelay')?.value;
    const duration = getElement('duration')?.value;
    const refLink = getElement('refLink')?.value;
    const description = getElement('description')?.value;
    const coordinate = getElement('coordinate')?.value || '0';

    if (!store || !touchDelay || !duration || !refLink || !description || !selectedFile) {
        showStatus('すべての必須フィールドに入力し、ファイルを選択してください', 'error');
        return;
    }

    const submitBtn = getElement('submitBtn');
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'アップロード中…';
    }

    try {
        // Upload to Flask server with deviceId and deviceName
        const formData = new FormData();
        formData.append('video', selectedFile);
        formData.append('store', store);
        formData.append('touchDelay', touchDelay);
        formData.append('duration', duration);
        formData.append('coordinate', coordinate);
        formData.append('contentType', getElement('contentType')?.value || 'video');
        formData.append('refLink', refLink);
        formData.append('description', description);
        // ✅ ADD: deviceId and deviceName
        formData.append('deviceId', currentDeviceId);
        formData.append('deviceName', currentDeviceName);

        // Get Flask server URL from settings
        const FLASK_SERVER = getFlaskServerUrl();

        // Note: FormData doesn't easily support custom headers, but server can auto-detect
        // tenant from deviceId if needed in the future
        const tenantUsername = getTenantUsername();
        if (tenantUsername) {
            // // console.log('Using tenant username:', tenantUsername);
        }

        const response = await fetch(`${FLASK_SERVER}/upload`, {
            method: 'POST',
            body: formData
        });

        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || 'Upload failed');
        }

        const result = await response.json();
        showStatus(`✓ 成功！デバイス ${currentDeviceName} のライブラリに ${result.contentCount} 個の動画があります`, 'success');

        // Reset form (keep store value from device)
        const touchDelayEl = getElement('touchDelay');
        const durationEl = getElement('duration');
        const coordinateEl = getElement('coordinate');
        const refLinkEl = getElement('refLink');
        const descriptionEl = getElement('description');
        const fileInputEl = getElement('fileInput');
        const filePreviewEl = getElement('filePreview');

        if (touchDelayEl) touchDelayEl.value = '1';
        if (durationEl) durationEl.value = '1';
        if (coordinateEl) coordinateEl.value = '0';
        if (refLinkEl) refLinkEl.value = '';
        if (descriptionEl) descriptionEl.value = '';
        if (fileInputEl) fileInputEl.value = '';
        if (filePreviewEl) filePreviewEl.style.display = 'none';
        selectedFile = null;

    } catch (error) {
        // // console.error('Upload error:', error);
        showStatus('✗ アップロード失敗: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'アップロード';
        }
    }
}

