    display: flex !important;
    flex-direction: column !important;
    gap: 4px;
    flex: 0 0 calc(50% - 8px);
    min-width: 0;
    max-width: calc(50% - 8px);
    box-sizing: border-box;
    width: calc(50% - 8px);
}

.content-item-name-main {
    font-size: 15px;
    font-weight: 600;
    color: #1a1a1a;
    word-wrap: break-word;
    display: block;
}

.content-item-store {
    font-size: 13px;
    color: #6c757d;
    display: block;
}

/* Right column: Filters (gender on top, age below in horizontal row) - 50% width */
.filters-info-column {
    display: flex !important;
    flex-direction: column !important;
    gap: 12px;
    flex: 0 0 calc(50% - 8px);
    min-width: 0;
    max-width: calc(50% - 8px);
    box-sizing: border-box;
    width: calc(50% - 8px);
