    gap: 16px;
    align-items: flex-end !important;
    flex-wrap: nowrap !important;
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
    min-width: 0;
}

/* Remove button - positioned at top right */
.remove-content-item-btn {
    background: none;
    border: none;
    color: #f44336;
    font-size: 24px;
    cursor: pointer;
    padding: 0;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    transition: background-color 0.2s;
    flex-shrink: 0;
    position: absolute;
    top: 0;
    right: 0;
