    max-width: 100%;
    width: 100%;
    display: flex !important;
    flex-direction: column !important;
    box-sizing: border-box;
}

.age-group {
    display: flex !important;
    flex-direction: column !important;
    box-sizing: border-box;
}

/* Age From - giữ nguyên width cố định */
.age-group:first-child {
    flex: 0 0 auto;
    min-width: 150px;
    max-width: 200px;
    width: auto;
}

/* Age To - nằm giữa Age From và cạnh phải container */
.age-group:last-child {
    flex: 1 1 0%;
    min-width: 100px;
    max-width: 100%;
    width: auto;
    box-sizing: border-box;
}

.filter-group label {
    font-size: 13px;
    font-weight: 500;
