}

.search-input {
    width: 100%;
    padding: 10px 16px;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    font-size: 14px;
}

.content-list {
    max-height: 400px;
    overflow-y: auto;
}

.content-item {
    padding: 12px;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    margin-bottom: 8px;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.content-item:hover {
    background-color: #f8f9fa;
    border-color: #2196F3;
}

.content-item.selected {
