}

.loading-content {
    text-align: center;
    padding: 40px;
    color: #6c757d;
}

/* Responsive Design */
@media (max-width: 768px) {
    .schedule-container {
        padding: 16px;
    }

    .schedule-form {
        padding: 20px;
    }

    .form-row {
        gap: 16px;
    }

    .weekday-toggle-container {
        gap: 6px;
    }

    .weekday-toggle {
        min-width: 50px;
