descriptor.controllerScript:
// ===== Get Flask Server URL =====
// Get from widget settings or use default
function getFlaskServerUrl() {
    try {
        const s = self.ctx.settings || {};
        return s.flaskServerUrl || 'https://visiflow-dev.m-tech.com.vn';
    } catch (e) {
        return 'http://127.0.0.1:5003';
    }
}

// ===== Get Tenant Username (for multi-tenant support) =====
function getTenantUsername() {
    try {
        // Try to get from ThingsBoard user context
        if (self.ctx.user && self.ctx.user.email) {
            return self.ctx.user.email;
        }
        // Try from userInfo
        if (self.ctx.userInfo && self.ctx.userInfo.email) {
            return self.ctx.userInfo.email;
        }
        // Try from $rootScope (ThingsBoard internal)
        if (self.ctx.$scope && self.ctx.$scope.$root && self.ctx.$scope.$root.currentUser && self.ctx.$scope.$root.currentUser.email) {
            return self.ctx.$scope.$root.currentUser.email;
        }
    } catch (e) {
        // // // console.warn('Could not get tenant username:', e);
    }
    return null;
}

let selectedWeekdays = [];
let selectedContents = [];
let availableContent = [];
let currentDeviceId = null; // Track current selected device
let currentDeviceName = null; // Track current device name


// ===== Load Device from Dashboard State =====
function loadDeviceFromState() {
    if (!self.ctx || !self.ctx.stateController) {
        // console.warn('[add_schedule] ⚠️ No stateController available');
        showNoDeviceState();
        return;
    }

    const stateParams = self.ctx.stateController.getStateParams();
    const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;

    // console.log('[add_schedule] 📊 Loading device from state:', { deviceMode, stateParams });

    // ========= ALL DEVICES MODE =========
    if (deviceMode === 'ALL') {
        // console.log('[add_schedule] 📋 ALL devices mode - disabling form');
        showAllDevicesMode();
        return;
    }

    // ========= SINGLE DEVICE MODE =========
    if (deviceMode === 'SINGLE') {
        const deviceId = stateParams?.selectedDeviceId || stateParams?.id;
        const deviceName = stateParams?.selectedDeviceName || stateParams?.name || 'Device';

        // console.log('[add_schedule] 📱 SINGLE device mode:', deviceName, deviceId);

        if (deviceId) {
            loadDeviceById(deviceId, deviceName);
        } else {
            showNoDeviceState();
        }
        return;
    }

    // ========= NONE OR NO MODE =========
    // console.log('[add_schedule] ⚠️ No device mode or NONE mode');
    showNoDeviceState();
}

// Helper: Load device by ID
function loadDeviceById(deviceId, deviceName) {
    currentDeviceId = deviceId;
    currentDeviceName = deviceName;

    // console.log(`[add_schedule] ✅ Device selected: ${deviceName} (${deviceId})`);

    // Update device dropdown
    const deviceGroupSelect = document.getElementById('deviceGroup');
    if (deviceGroupSelect) {
        deviceGroupSelect.innerHTML = '';
        const option = document.createElement('option');
        option.value = deviceId;
        option.setAttribute('data-device-id', deviceId);
        option.setAttribute('data-device-name', deviceName);
        option.textContent = deviceName;
        option.selected = true;
        deviceGroupSelect.appendChild(option);
    }

    // Enable form
    enableForm();

    // Load content for this device
    loadAvailableContent(deviceId);
}

// Helper: Show ALL devices mode message and disable form
function showAllDevicesMode() {
    currentDeviceId = '__ALL__';
    currentDeviceName = 'All Devices';

    // Update device dropdown
    const deviceGroupSelect = document.getElementById('deviceGroup');
    if (deviceGroupSelect) {
        deviceGroupSelect.innerHTML = '<option value="">すべての端末</option>';
    }

    // Disable form
    disableForm();

    // Show message
    showStatus('⚠️ 「すべての端末」モードではスケジュールを作成できません。単一のデバイスを選択してください。', 'error');
}

// Helper: Show no device state
function showNoDeviceState() {
    currentDeviceId = null;
    currentDeviceName = null;

    // Update device dropdown
    const deviceGroupSelect = document.getElementById('deviceGroup');
    if (deviceGroupSelect) {
        deviceGroupSelect.innerHTML = '<option value="">デバイスが選択されていません</option>';
    }

    // Disable form
    disableForm();

    // Show message
    showStatus('⚠️ デバイスが選択されていません。ストアセレクターからデバイスを選択してください。', 'error');
}

// Helper: Enable form
function enableForm() {
    const form = document.getElementById('scheduleForm');
    if (form) {
        const inputs = form.querySelectorAll('input, select, textarea, button');
        inputs.forEach(input => {
            if (input.id !== 'cancelBtn') { // Don't disable cancel button
                input.disabled = false;
            }
        });
    }
    hideStatus();
}

// Helper: Disable form
function disableForm() {
    const form = document.getElementById('scheduleForm');
    if (form) {
        const inputs = form.querySelectorAll('input, select, textarea, button');
        inputs.forEach(input => {
            if (input.id !== 'cancelBtn') { // Don't disable cancel button
                input.disabled = true;
            }
        });
    }
}

// Helper: Show status message
function showStatus(message, type) {
    const statusEl = document.getElementById('statusMessage');
    if (statusEl) {
        statusEl.textContent = message;
        statusEl.className = `status-message ${type}`;
        statusEl.style.display = 'block';
    }
}

// Helper: Hide status message
function hideStatus() {
    const statusEl = document.getElementById('statusMessage');
    if (statusEl) {
        statusEl.style.display = 'none';
    }
}


// Language translations
const translations = {
    en: {
        weekdays: {
            full: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
            short: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        },
        months: {
            full: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
            short: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
        }
    },
    ja: {
        weekdays: {
            full: ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'],
            short: ['日', '月', '火', '水', '木', '金', '土']
        },
        months: {
            full: ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'],
            short: ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月']
        }
    }
};

// Get current language from ThingsBoard
function getCurrentLanguage() {
    try {
        // Try to get language from ThingsBoard context
        if (self.ctx && self.ctx.settings && self.ctx.settings.language) {
            return self.ctx.settings.language;
        }
        // Fallback to user settings
        if (self.ctx && self.ctx.$scope && self.ctx.$scope.userLang) {
            return self.ctx.$scope.userLang;
        }
        // Check URL parameter
        const urlParams = new URLSearchParams(window.location.search);
        const lang = urlParams.get('lang');
        if (lang) return lang;

        // Force Japanese for this widget
        return 'ja';
    } catch (error) {
        // // console.warn('Error getting language:', error);
        return 'en';
    }
}

// Get translated text
function getTranslation(category, type, index) {
    const lang = getCurrentLanguage();
    const langData = translations[lang] || translations['en'];

    if (!langData[category] || !langData[category][type]) {
        return translations['en'][category][type][index];
    }

    return langData[category][type][index];
}

// Update weekday labels in the UI
function updateWeekdayLabels() {
    const weekdayToggles = document.querySelectorAll('.weekday-toggle .weekday-short[data-translate]');
    weekdayToggles.forEach(span => {
        const translateKey = span.getAttribute('data-translate');
        if (translateKey && translateKey.startsWith('weekday-')) {
            const dayIndex = parseInt(translateKey.split('-')[1]);
            span.textContent = getTranslation('weekdays', 'short', dayIndex);
        }
    });
}

// Load Flatpickr library dynamically
let flatpickrLoaded = false;
let flatpickrLoadPromise = null;

function loadFlatpickrLibrary() {
    if (flatpickrLoaded) {
        return Promise.resolve();
    }

    if (flatpickrLoadPromise) {
        return flatpickrLoadPromise;
    }

    flatpickrLoadPromise = new Promise((resolve, reject) => {
        // Check if flatpickr already exists
        if (window.flatpickr) {
            flatpickrLoaded = true;
            resolve();
            return;
        }

        // Load CSS
        const css = document.createElement('link');
        css.rel = 'stylesheet';
        css.href = 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/flatpickr.min.css';
        document.head.appendChild(css);

        // Load JS
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/flatpickr.min.js';
        script.onload = () => {
            // // console.log('Flatpickr loaded successfully');
            flatpickrLoaded = true;
            loadFlatpickrLocales().then(resolve).catch(reject);
        };
        script.onerror = () => {
            // // console.error('Failed to load Flatpickr');
            reject(new Error('Failed to load Flatpickr'));
        };
        document.head.appendChild(script);
    });

    return flatpickrLoadPromise;
}

// Load Flatpickr locale files
function loadFlatpickrLocales() {
    const locales = {
        'ja': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/ja.js',
        'vi': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/vn.js',
        'zh': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/zh.js',
        'ko': 'https://cdn.jsdelivr.net/npm/flatpickr@4.6.13/dist/l10n/ko.js'
    };

    const promises = Object.keys(locales).map(lang => {
        return new Promise((resolve) => {
            const script = document.createElement('script');
            script.src = locales[lang];
            script.onload = () => {
                // // console.log(`Flatpickr locale ${lang} loaded`);
                resolve();
            };
            script.onerror = () => {
                // // console.warn(`Failed to load Flatpickr locale ${lang}`);
                resolve(); // Continue even if locale fails
            };
            document.head.appendChild(script);
        });
    });

    return Promise.all(promises);
}

// Initialize date pickers with localization
let startDatePicker = null;
let endDatePicker = null;

function initializeDatePickers() {
    if (!window.flatpickr) {
        // // console.warn('Flatpickr not loaded yet, retrying...');
        setTimeout(initializeDatePickers, 500);
        return;
    }

    const lang = getCurrentLanguage();
    let locale = 'default';

    // Map ThingsBoard language codes to Flatpickr locale codes
    const localeMap = {
        'ja': 'ja',
        'vi': 'vn',
        'zh': 'zh',
        'ko': 'ko',
        'en': 'default'
    };

    if (lang && localeMap[lang] && window.flatpickr.l10ns[localeMap[lang]]) {
        locale = window.flatpickr.l10ns[localeMap[lang]];
    }

    const startDateInput = document.getElementById('startDate');
    const endDateInput = document.getElementById('endDate');

    if (startDateInput && !startDatePicker) {
        startDatePicker = flatpickr(startDateInput, {
            dateFormat: 'd/m/Y',
            locale: locale,
            allowInput: true,
            onChange: function (selectedDates, dateStr, instance) {
                // Update the input value
                startDateInput.value = dateStr;
            }
        });
    }

    if (endDateInput && !endDatePicker) {
        endDatePicker = flatpickr(endDateInput, {
            dateFormat: 'd/m/Y',
            locale: locale,
            allowInput: true,
            onChange: function (selectedDates, dateStr, instance) {
                // Update the input value
                endDateInput.value = dateStr;
            }
        });
    }

    // // console.log(`Date pickers initialized with locale: ${lang}`);
}

// Initialize widget
self.onInit = function () {
    initializeWidget();
};

function initializeWidget() {
    // // console.log('Initializing schedule widget...');

    // Load Flatpickr library and locales
    loadFlatpickrLibrary();

    // Don't load devices from datasource - use state instead
    populateTimeOptions();
    setupEventListeners();
    setupFormValidation();

    // Update weekday labels based on current language
    updateWeekdayLabels();

    // Initialize date pickers after a short delay to ensure Flatpickr is loaded
    setTimeout(() => {
        initializeDatePickers();
    }, 500);

    // ===== Setup Dashboard State Subscription =====
    if (self.ctx.stateController) {
        // console.log('[add_schedule] ✅ Setting up dashboard state listener');

        let stateChangeTimeout;
        self.stateChangeSubscription = self.ctx.stateController.stateChanged().subscribe(function (params) {
            // console.log('[add_schedule] 📡 Dashboard state changed');

            if (stateChangeTimeout) {
                clearTimeout(stateChangeTimeout);
            }

            stateChangeTimeout = setTimeout(function () {
                // console.log('[add_schedule] ⏳ Debounce complete, reloading device...');
                self.ctx.ngZone.run(function () {
                    loadDeviceFromState();
                });
            }, 200); // Debounce 200ms
        });
    } else {
        // console.warn('[add_schedule] ⚠️ No stateController available for subscription');
    }

    // Load device from state
    setTimeout(function () {
        loadDeviceFromState();
    }, 300);
}

// Cleanup when widget is destroyed
self.onDestroy = function () {
    if (self.stateChangeSubscription) {
        self.stateChangeSubscription.unsubscribe();
        self.stateChangeSubscription = null;
        // console.log('[add_schedule] ✅ Unsubscribed from state changes');
    }
};


// ✅ ADD: Handle dashboard entity selection changes
self.onDataUpdated = function () {
    // console.log('[add_schedule] 📊 Widget data updated');
    self.ctx.ngZone.run(function () {
        loadDeviceFromState();
        self.ctx.detectChanges();
    });
};

function populateTimeOptions() {
    // Generate time options from 00:00 to 23:55 with 5-minute intervals
    const timeOptions = [];
    for (let hour = 0; hour < 24; hour++) {
        for (let minute = 0; minute < 60; minute += 5) {
            const timeString = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
            timeOptions.push(timeString);
        }
    }

    // Populate start time custom dropdown and hidden select
    const startTimeSelect = document.getElementById('startTime');
    const startTimeOptions = document.getElementById('startTimeOptions');
    if (startTimeSelect && startTimeOptions) {
        timeOptions.forEach(time => {
            // Add to hidden select for form submission
            const option = document.createElement('option');
            option.value = time;
            option.textContent = time;
            startTimeSelect.appendChild(option);

            // Add to custom dropdown
            const customOption = document.createElement('div');
            customOption.className = 'custom-select-option';
            customOption.setAttribute('data-value', time);
            customOption.textContent = time;
            startTimeOptions.appendChild(customOption);
        });
    }

    // Populate end time custom dropdown and hidden select
    const endTimeSelect = document.getElementById('endTime');
    const endTimeOptions = document.getElementById('endTimeOptions');
    if (endTimeSelect && endTimeOptions) {
        timeOptions.forEach(time => {
            // Add to hidden select for form submission
            const option = document.createElement('option');
            option.value = time;
            option.textContent = time;
            endTimeSelect.appendChild(option);

            // Add to custom dropdown
            const customOption = document.createElement('div');
            customOption.className = 'custom-select-option';
            customOption.setAttribute('data-value', time);
            customOption.textContent = time;
            endTimeOptions.appendChild(customOption);
        });
    }

    // Setup custom dropdown interactions
    setupCustomSelect('startTimeSelect', 'startTime');
    setupCustomSelect('endTimeSelect', 'endTime');
}

function setupCustomSelect(selectId, hiddenSelectId) {
    const customSelect = document.getElementById(selectId);
    const hiddenSelect = document.getElementById(hiddenSelectId);
    if (!customSelect || !hiddenSelect) return;

    const trigger = customSelect.querySelector('.custom-select-trigger');
    const options = customSelect.querySelector('.custom-select-options');
    const valueSpan = customSelect.querySelector('.custom-select-value');

    // Toggle dropdown
    trigger.addEventListener('click', function (e) {
        e.stopPropagation();
        const isOpen = customSelect.classList.contains('open');

        // Close all other custom selects
        document.querySelectorAll('.custom-select').forEach(sel => {
            if (sel !== customSelect) {
                sel.classList.remove('open');
            }
        });

        customSelect.classList.toggle('open', !isOpen);
    });

    // Handle option selection
    options.querySelectorAll('.custom-select-option').forEach(option => {
        option.addEventListener('click', function (e) {
            e.stopPropagation();
            const value = this.getAttribute('data-value');
            valueSpan.textContent = value;
            hiddenSelect.value = value;
            customSelect.classList.remove('open');

            // Trigger change event for validation
            hiddenSelect.dispatchEvent(new Event('change', { bubbles: true }));
        });
    });

    // Close dropdown when clicking outside
    document.addEventListener('click', function (e) {
        if (!customSelect.contains(e.target)) {
            customSelect.classList.remove('open');
        }
    });
}


// ✅ MODIFIED: Load content for specific device
async function loadAvailableContent(deviceId) {
    if (!deviceId) {
        // // console.log('No device selected, skipping content load');
        availableContent = [];
        return;
    }

    try {
        const FLASK_SERVER = getFlaskServerUrl();
        const tenantUsername = getTenantUsername();

        // Prepare headers with tenant info (if available)
        const headers = {
            'Content-Type': 'application/json'
        };
        if (tenantUsername) {
            headers['X-TB-Tenant-Username'] = tenantUsername;
        }

        // // console.log(`Loading content for device: ${deviceId}`);
        const response = await fetch(`${FLASK_SERVER}/api/get-content?deviceId=${deviceId}`, {
            method: 'GET',
            headers: headers
        });
        const data = await response.json();

        if (data.success && data.content) {
            availableContent = data.content;
            // // console.log(`✓ Loaded ${availableContent.length} content items for device ${deviceId}`);
        } else {
            availableContent = [];
            // // console.warn('No content found for device:', deviceId);
        }
    } catch (error) {
        // // console.error('Error loading content:', error);
        availableContent = [];
    }
}

// ✅ MODIFIED: Handle device selection change
function onDeviceChange() {
    const deviceGroupSelect = document.getElementById('deviceGroup');
    if (!deviceGroupSelect) return;

    const selectedOption = deviceGroupSelect.options[deviceGroupSelect.selectedIndex];
    const deviceId = selectedOption.getAttribute('data-device-id') || deviceGroupSelect.value;

    if (deviceId && deviceId !== currentDeviceId) {
        // // console.log('Device changed to:', deviceId);
        currentDeviceId = deviceId;

        // Clear selected contents when device changes
        selectedContents = [];
        updateContentDisplay();

        // Load content for new device
        loadAvailableContent(deviceId);
    }
}

function setupEventListeners() {
    // ✅ ADD: Device selection change listener
    const deviceGroupSelect = document.getElementById('deviceGroup');
    if (deviceGroupSelect) {
        deviceGroupSelect.addEventListener('change', onDeviceChange);
    }

    // Weekday toggle buttons
    const weekdayToggles = document.querySelectorAll('.weekday-toggle');
    weekdayToggles.forEach(toggle => {
        toggle.addEventListener('click', function () {
            const dayValue = this.getAttribute('data-value');
            this.classList.toggle('active');

            if (this.classList.contains('active')) {
                if (!selectedWeekdays.includes(dayValue)) {
                    selectedWeekdays.push(dayValue);
                }
            } else {
                selectedWeekdays = selectedWeekdays.filter(d => d !== dayValue);
            }
        });
    });

    // Select All / Clear All buttons
    const selectAllBtn = document.getElementById('selectAllWeekdays');
    const clearAllBtn = document.getElementById('clearAllWeekdays');

    if (selectAllBtn) {
        selectAllBtn.addEventListener('click', function () {
            weekdayToggles.forEach(toggle => {
                toggle.classList.add('active');
                const dayValue = toggle.getAttribute('data-value');
                if (!selectedWeekdays.includes(dayValue)) {
                    selectedWeekdays.push(dayValue);
                }
            });
        });
    }

    if (clearAllBtn) {
        clearAllBtn.addEventListener('click', function () {
            weekdayToggles.forEach(toggle => {
                toggle.classList.remove('active');
            });
            selectedWeekdays = [];
        });
    }

    // Content selection
    const selectContentBtn = document.getElementById('selectContentBtn');
    const contentModal = document.getElementById('contentModal');
    const closeContentModal = document.getElementById('closeContentModal');
    const cancelContentBtn = document.getElementById('cancelContentBtn');
    const confirmContentBtn = document.getElementById('confirmContentBtn');
    const contentSearch = document.getElementById('contentSearch');

    if (selectContentBtn) {
        selectContentBtn.addEventListener('click', openContentModal);
    }

    if (closeContentModal) {
        closeContentModal.addEventListener('click', closeContentModalFunc);
    }

    if (cancelContentBtn) {
        cancelContentBtn.addEventListener('click', closeContentModalFunc);
    }

    if (confirmContentBtn) {
        confirmContentBtn.addEventListener('click', function () {
            const selectedItems = document.querySelectorAll('.content-item.selected');
            if (selectedItems.length > 0) {
                selectedItems.forEach(item => {
                    const contentId = item.getAttribute('data-content-id');
                    const contentIndex = item.getAttribute('data-content-index');
                    const content = availableContent[contentIndex];

                    if (content && !selectedContents.find(c => c.id === contentId)) {
                        selectedContents.push({
                            id: contentId,
                            name: content.file_name || content.fileName || '不明',
                            store: content.customer || content.store || '不明',
                            data: content,
                            gender: '',
                            ageFrom: 1,
                            ageTo: 1
                        });
                    }
                });
                updateContentDisplay();
                closeContentModalFunc();
            } else {
                showStatus('少なくとも1つのコンテンツアイテムを選択してください', 'error');
            }
        });
    }

    if (contentSearch) {
        contentSearch.addEventListener('input', function () {
            filterContentList(this.value);
        });
    }

    // Form submission
    const scheduleForm = document.getElementById('scheduleForm');
    if (scheduleForm) {
        scheduleForm.addEventListener('submit', handleFormSubmit);
    }

    // Cancel button
    const cancelBtn = document.getElementById('cancelBtn');
    if (cancelBtn) {
        cancelBtn.addEventListener('click', function () {
            if (confirm('本当にキャンセルしますか？すべての変更が失われます。')) {
                resetForm();
            }
        });
    }

    // Date validation
    const startDate = document.getElementById('startDate');
    const endDate = document.getElementById('endDate');

    if (startDate && endDate) {
        // Helper function to parse DD/MM/YYYY format
        function parseDate(dateStr) {
            if (!dateStr) return null;
            if (dateStr.includes('/')) {
                const parts = dateStr.split('/');
                if (parts.length === 3) {
                    const day = parseInt(parts[0], 10);
                    const month = parseInt(parts[1], 10) - 1;
                    const year = parseInt(parts[2], 10);
                    return new Date(year, month, day);
                }
            }
            return new Date(dateStr);
        }

        startDate.addEventListener('change', function () {
            const start = parseDate(this.value);
            const end = parseDate(endDate.value);
            if (start && end && start > end) {
                showFieldError('endDate', '終了日は開始日より後でなければなりません');
            } else {
                clearFieldError('endDate');
            }
        });

        endDate.addEventListener('change', function () {
            const start = parseDate(startDate.value);
            const end = parseDate(this.value);
            if (start && end && end < start) {
                showFieldError('endDate', '終了日は開始日より後でなければなりません');
            } else {
                clearFieldError('endDate');
            }
        });
    }

    // Time validation
    const startTime = document.getElementById('startTime');
    const endTime = document.getElementById('endTime');

    if (startTime && endTime) {
        // Validate times on change
        startTime.addEventListener('change', function () {
            validateTimes();
        });
        endTime.addEventListener('change', function () {
            validateTimes();
        });
    }
}

function setupFormValidation() {
    const form = document.getElementById('scheduleForm');
    if (!form) return;

    form.addEventListener('input', function (e) {
        if (e.target.hasAttribute('required')) {
            validateField(e.target);
        }
    });
}

function validateField(field) {
    const fieldId = field.id;

    if (!field.value.trim()) {
        showFieldError(fieldId, 'This field is required');
        return false;
    }

    clearFieldError(fieldId);
    return true;
}


function validateTimes() {
    const startDate = document.getElementById('startDate').value;
    const endDate = document.getElementById('endDate').value;
    const startTime = document.getElementById('startTime').value;
    const endTime = document.getElementById('endTime').value;

    if (startDate === endDate && startTime && endTime) {
        if (startTime >= endTime) {
            showFieldError('endTime', 'End time must be after start time');
            return false;
        }
    }

    clearFieldError('endTime');
    return true;
}

function showFieldError(fieldId, message) {
    const errorElement = document.getElementById(fieldId + 'Error');
    if (errorElement) {
        errorElement.textContent = message;
        errorElement.classList.add('show');
    }

    const field = document.getElementById(fieldId);
    if (field) {
        field.style.borderColor = '#f44336';
    }
}

function clearFieldError(fieldId) {
    const errorElement = document.getElementById(fieldId + 'Error');
    if (errorElement) {
        errorElement.textContent = '';
        errorElement.classList.remove('show');
    }

    const field = document.getElementById(fieldId);
    if (field) {
        field.style.borderColor = '';
    }
}

// ✅ MODIFIED: Check if device is selected before opening modal
function openContentModal() {
    // Check if device is selected
    if (!currentDeviceId) {
        showStatus('最初にデバイスを選択してください', 'error');
        return;
    }

    // Check if content is loaded
    if (availableContent.length === 0) {
        showStatus('このデバイスで利用可能なコンテンツがありません。最初にコンテンツをアップロードしてください。', 'error');
        return;
    }

    const modal = document.getElementById('contentModal');
    if (modal) {
        renderContentList();
        modal.classList.add('show');
    }
}

function closeContentModalFunc() {
    const modal = document.getElementById('contentModal');
    if (modal) {
        modal.classList.remove('show');
    }
}

function renderContentList(searchTerm = '') {
    const contentList = document.getElementById('contentList');
    if (!contentList) return;

    if (availableContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">このデバイスで利用可能なコンテンツがありません</div>';
        return;
    }

    let filteredContent = availableContent;
    if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        filteredContent = availableContent.filter(item => {
            const store = (item.customer || item.store || '').toLowerCase();
            const fileName = (item.file_name || item.fileName || '').toLowerCase();
            const type = (item.type || item.contentType || '').toLowerCase();
            return store.includes(searchLower) ||
                fileName.includes(searchLower) ||
                type.includes(searchLower);
        });
    }

    if (filteredContent.length === 0) {
        contentList.innerHTML = '<div class="loading-content">コンテンツが見つかりません</div>';
        return;
    }

    // Helper function to format file size
    function formatFileSize(bytes) {
        if (!bytes || bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
    }

    // Helper function to get file size display
    function getFileSizeDisplay(fileSize) {
        if (!fileSize) return '0 B';

        // If it's already a formatted string (contains letters like MB, KB, etc.)
        if (typeof fileSize === 'string' && /[A-Za-z]/.test(fileSize)) {
            return fileSize;
        }

        // If it's a number, format it
        const numSize = parseInt(fileSize, 10);
        if (!isNaN(numSize)) {
            return formatFileSize(numSize);
        }

        return '不明';
    }

    contentList.innerHTML = filteredContent.map((item, index) => {
        const isSelected = selectedContents.find(c => c.id === item.checksum);
        const fileName = item.file_name || item.fileName || '不明';
        const type = item.type || item.contentType || 'video';
        const fileSize = item.file_size || item.fileSize || 0;
        const formattedSize = getFileSizeDisplay(fileSize);

        return `
            <div class="content-item ${isSelected ? 'selected' : ''}" 
                 data-content-id="${item.checksum}"
                 data-content-index="${index}">
                <div>
                    <div class="content-item-name">${item.customer || item.store || '不明なストア'}</div>
                    <div class="content-item-type">${fileName}</div>
                    <div class="content-item-meta">
                        <span class="content-item-type-label">タイプ: ${type}</span>
                        <span class="content-item-size-label">サイズ: ${formattedSize}</span>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    // Add click listeners for multiple selection
    contentList.querySelectorAll('.content-item').forEach(item => {
        item.addEventListener('click', function () {
            this.classList.toggle('selected');
        });
    });
}

function filterContentList(searchTerm) {
