/* RPA Report Widget with Integrated Store Selector */

.rpa-report-widget {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: #ffffff;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    box-sizing: border-box;
}

/* Store Selector Section */
.store-selector-section {
    padding: 12px;
    border-bottom: 1px solid #E5E7EB;
    background: #ffffff;
    display: flex;
    align-items: center;
    gap: 12px;
}

.form-field {
    display: flex;
    align-items: center;
    gap: 8px;
    max-width: 50%;
}

.field-label {
    font-size: 13px;
    font-weight: 600;
    color: #374151;
    white-space: nowrap;
}

.select-wrapper {
    position: relative;
    flex: 1;
    min-height: 36px;
    background: #ffffff;
    border: 1px solid #E5E7EB;
    border-radius: 6px;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
}

.select-wrapper:hover {
    border-color: #D1D5DB;
    background: #F9FAFB;
    box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.05);
}

.select-wrapper:focus-within {
    border-color: #000000;
    box-shadow: 0 0 0 1px #000000, 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    background: #ffffff;
}

.mat-select {
    width: 100%;
    height: 100%;
    padding: 0 32px 0 12px;
    font-size: 13px;
    font-weight: 500;
    color: #111827;
    background: transparent;
    border: none;
    outline: none;
    cursor: pointer;
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    line-height: 1.5;
    border-radius: 6px;
}

.select-wrapper::after {
    content: '';
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 16px;
    background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M4 6L8 10L12 6' stroke='%236B7280' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.select-wrapper:hover::after {
    opacity: 1;
}

.status-text {
    font-size: 12px;
    color: #6B7280;
    font-weight: 500;
}

/* Report Display Section */
.iframe-container {
    flex: 1;
    position: relative;
    overflow: hidden;
}

iframe {
    width: 100%;
    height: 100%;
    border: none;
}

/* Loading Overlay */
.loading-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.95);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 10;
}

.loading-spinner {
    width: 40px;
    height: 40px;
    border: 3px solid #E5E7EB;
    border-top-color: #000000;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

.loading-text {
    margin-top: 12px;
    font-size: 13px;
    color: #6B7280;
}

/* Error Overlay */
.error-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: #FEF2F2;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 20px;
    z-index: 10;
}

.error-icon {
    font-size: 48px;
    margin-bottom: 12px;
}

.error-text {
    font-size: 14px;
    color: #991B1B;
    text-align: center;
    max-width: 400px;
}

descriptor.controllerScript:
const BASE_URL = 'https://visiflow-dev.m-tech.com.vn';

self.onInit = function () {
    //console.log('[RPA_report] Widget initialized');
    initializeWidget();
};

self.onDataUpdated = function () {
    //console.log('[RPA_report] 📊 Widget data updated');
};

function initializeWidget() {
    self.storeSelect = document.getElementById('storeSelect');
    self.statusEl = document.getElementById('status');

    // Add change listener
    self.storeSelect.addEventListener('change', () => {
        const selectedStore = self.storeSelect.value;
        if (selectedStore) {
            loadReport(selectedStore);
        }
    });

    // Initialize store list
    init();
}

async function init() {
    setStatus('Loading stores...');
    try {
        //console.log('[RPA_report] Initializing widget...');
        const stores = await fetchDeviceTypes();
        //console.log('[RPA_report] Fetched stores:', stores);
        fillSelect(self.storeSelect, stores, null);
        setStatus('');

        // Auto-select first store
        if (stores.length) {
            self.storeSelect.value = stores[0];
            loadReport(stores[0]);
        } else {
            //console.warn('[RPA_report] No stores found');
            setStatus('No stores available');
        }
    } catch (error) {
        //console.error('[RPA_report] Error in init():', error);
        setStatus('Error loading stores: ' + error.message);
    }
}

function fillSelect(selectEl, items, placeholder) {
    selectEl.innerHTML = '';

    if (placeholder) {
        const ph = document.createElement('option');
        ph.value = '';
        ph.textContent = placeholder;
        selectEl.appendChild(ph);
    }

    items.forEach(item => {
        const opt = document.createElement('option');
        opt.value = item;
        opt.textContent = item;
        selectEl.appendChild(opt);
    });
}

function setStatus(msg) {
    self.statusEl.textContent = msg || '';
}

function getToken() {
    const jwtToken = localStorage.getItem('jwt_token');
    const token = localStorage.getItem('token');
    return jwtToken || token || '';
}

async function apiGet(url) {
    const token = getToken();
    //console.log('[RPA_report] API GET:', url);

    const res = await fetch(url, {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
        }
    });

    //console.log('[RPA_report] API Response:', {
      //  url: url,
      //  status: res.status,
      //  ok: res.ok
    //});

    if (!res.ok) {
        const errorText = await res.text();
        //console.error('[RPA_report] API Error:', errorText);
        throw new Error(`HTTP ${res.status} when GET ${url}: ${errorText}`);
    }

    return res.json();
}

async function fetchDeviceTypes() {
    const user = self.ctx.currentUser;
    //console.log('[RPA_report] Fetching device types. User authority:', user ? user.authority : 'unknown');

    // CUSTOMER_USER: Fetch all assigned devices and extract unique types
    if (user && user.authority === 'CUSTOMER_USER') {
        const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
        if (!customerId) {
            //console.error('[RPA_report] ❌ Customer ID missing for CUSTOMER_USER');
            return [];
        }

        const pageSize = 1000;
        const url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=0`;
        //console.log('[RPA_report] Customer User: Fetching all devices to extract types from:', url);

        try {
            const r = await apiGet(url);
            const data = r.data || [];
            //console.log(`[RPA_report] Fetched ${data.length} devices for customer.`);

            const uniqueTypes = [...new Set(data.map(d => d.type))].filter(Boolean).sort();
            //console.log('[RPA_report] Extracted unique types from customer devices:', uniqueTypes);
            return uniqueTypes;
        } catch (e) {
            //console.error('[RPA_report] Error fetching customer devices for types:', e);
            return [];
        }
    }

    // TENANT_ADMIN: Fetch all device types from system
    //console.log('[RPA_report] Tenant Admin: Fetching all device types from /api/device/types');
    const r = await apiGet('/api/device/types');
    //console.log('[RPA_report] Raw response from /api/device/types:', r);

    let types = Array.isArray(r) ? r : (r.deviceTypes || []);

    if (types.length > 0 && typeof types[0] === 'object') {
        types = types.map(t => {
            const typeName = t.type || t.name || t.deviceType || t.label || JSON.stringify(t);
            return typeName;
        });
    }

    return types;
}

function loadReport(storeName) {
    const reportFrame = document.getElementById('reportFrame');
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');

    if (!storeName) {
        showError('No store selected. Please select a store from the dropdown.');
        return;
    }

    // Show loading
    if (loadingOverlay) {
        loadingOverlay.style.display = 'flex';
    }
    if (errorOverlay) {
        errorOverlay.style.display = 'none';
    }

    // Construct report URL (Always English)
    const fileName = 'rpa_report_eng.html';
    let reportUrl = `${BASE_URL}/web_server/${fileName}`;

    // Add store parameter
    reportUrl += `?store=${encodeURIComponent(storeName)}`;

    //console.log('[RPA_report] Loading report URL:', reportUrl);
    //console.log('[RPA_report] For store:', storeName);

    if (reportFrame) {
        reportFrame.src = reportUrl;

        // Handle iframe load
        reportFrame.onload = function () {
            //console.log('[RPA_report] Report iframe loaded successfully');
            if (loadingOverlay) {
                setTimeout(() => {
                    loadingOverlay.style.display = 'none';
                }, 500);
            }
        };

        // Handle iframe error
        reportFrame.onerror = function () {
            //console.error('[RPA_report] Failed to load report iframe');
            showError();
        };

        // Timeout fallback
        setTimeout(() => {
            if (loadingOverlay && loadingOverlay.style.display !== 'none') {
                loadingOverlay.style.display = 'none';
            }
        }, 5000);
    }
}

function showError(customMessage) {
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');
    const errorText = document.querySelector('.error-text');

    if (loadingOverlay) {
        loadingOverlay.style.display = 'none';
    }
    if (errorOverlay) {
        errorOverlay.style.display = 'flex';
    }
    if (errorText && customMessage) {
        errorText.textContent = customMessage;
    } else if (errorText) {
        errorText.textContent = 'No store selected or report not available';
    }
}

self.onResize = function () {
    // Handle widget resize if needed
};

self.onDestroy = function () {
    //console.log('[RPA_report] Widget destroyed');
};

