descriptor.controllerScript:
self.onInit = function () {
    self.ctx.$scope.actionWidget.onInit();

    var wc = self.ctx;
    var STORAGE_KEY = 'store_type_selection';

    var href = '';
    try { href = (window && window.location && window.location.href) ? window.location.href : ''; } catch (e) { }
    var isEditor = (href.indexOf('/widgets') !== -1) ||
        (href.indexOf('widgets-library') !== -1) ||
        (href.indexOf('/resources') !== -1 && href.indexOf('Widgets') !== -1);

    // Nếu không chắc: dùng thêm guard theo dashboard services
    if (!wc || !wc.stateController || isEditor) {
        // Chỉ apply 1 lần nhẹ để preview không bị "điên"
        try { applyDisabledOnce(); } catch (e) { }
        return;
    }

    function safeGetSelection() {
        try {
            var raw = localStorage.getItem(STORAGE_KEY);
            return raw ? JSON.parse(raw) : null;
        } catch (e) { return null; }
    }

    function safeGetStateParams() {
        try {
            return (wc.stateController && wc.stateController.getStateParams) ? (wc.stateController.getStateParams() || {}) : {};
        } catch (e) { return {}; }
    }

    function shouldDisable() {
        // Check BOTH localStorage AND state params
        var sel = safeGetSelection();
        var sp = safeGetStateParams();

        // Get values from localStorage
        var lsMode = sel ? String(sel.mode || '').toUpperCase() : '';
        var lsName = sel ? String(sel.deviceName || '').toLowerCase() : '';
        var lsLabel = sel ? String(sel.deviceLabel || '').toLowerCase() : '';

        // Get values from state params
        var spMode = String(sp.selectedDeviceMode || sp.mode || '').toUpperCase();
        var spName = String(sp.selectedDeviceName || sp.name || '').toLowerCase();
        var spLabel = String(sp.selectedDeviceLabel || sp.label || '').toLowerCase();

        // Use whichever has data (prefer state params as they're more current)
        var mode = spMode || lsMode;
        var name = spName || lsName;
        var label = spLabel || lsLabel;

        //console.log('[disable_device_label] Checking - mode:', mode, 'name:', name, 'label:', label);

        // Disable if: SINGLE mode AND (deviceName contains 'rockchip' OR deviceLabel is 'edge-type')
        var shouldDis = (mode === 'SINGLE' && (name.indexOf('rockchip') !== -1 || label === 'edge-type'));
        //console.log('[disable_device_label] Should disable:', shouldDis);
        return shouldDis;
    }

    function findButton() {
        if (!wc.$container) return null;
        var $btn = wc.$container.find('button').first();
        return ($btn && $btn.length) ? $btn : null;
    }

    function applyDisabledOnce() {
        var dis = shouldDisable();
        var $btn = findButton();
        if (!$btn) return;
        $btn.prop('disabled', dis);
        $btn.attr('aria-disabled', dis ? 'true' : 'false');
        $btn.css('pointer-events', dis ? 'none' : 'auto');
        $btn.css('opacity', dis ? '0.45' : '1');
        $btn.css('cursor', dis ? 'not-allowed' : 'pointer');
        $btn.css('filter', dis ? 'grayscale(1)' : 'none');
        $btn.attr('title', dis ? 'This device type does not support this action' : '');
    }

    // ===== Runtime watchdog =====
    // 1) apply ngay
    applyDisabledOnce();

    // 2) Subscribe to state changes (most reliable)
    if (wc.stateController && wc.stateController.stateChanged) {
        self._stateSubscription = wc.stateController.stateChanged().subscribe(function () {
            //console.log('[disable_device_label] State changed - reapplying');
            applyDisabledOnce();
            setTimeout(applyDisabledOnce, 100);
            setTimeout(applyDisabledOnce, 300);
        });
    }

    // 3) Listen for localStorage changes (cross-tab sync)
    self._storageHandler = function (e) {
        if (e.key === STORAGE_KEY) {
            //console.log('[disable_device_label] Storage changed - reapplying');
            applyDisabledOnce();
        }
    };
    window.addEventListener('storage', self._storageHandler);

    // 4) MutationObserver: chỉ observe CHANGES, nhưng throttle để không bắn quá nhiều
    var rootEl = wc.$container && wc.$container[0];
    if (rootEl && window.MutationObserver) {
        var scheduled = false;
        self._mo = new MutationObserver(function () {
            if (scheduled) return;
            scheduled = true;
            setTimeout(function () {
                scheduled = false;
                applyDisabledOnce();
            }, 50);
        });
        self._mo.observe(rootEl, { childList: true, subtree: true });
    }

    // 5) Interval ngắn hơn (500ms) để bắt kịp navigation
    self._timer = setInterval(function () {
        applyDisabledOnce();
    }, 500);

    // 6) Visibility change (when tab becomes visible again)
    self._visibilityHandler = function () {
        if (!document.hidden) {
            //console.log('[disable_device_label] Visibility changed - reapplying');
            applyDisabledOnce();
        }
    };
    document.addEventListener('visibilitychange', self._visibilityHandler);
};

self.onDestroy = function () {
    try { if (self._mo) self._mo.disconnect(); } catch (e) { }
    try { if (self._timer) clearInterval(self._timer); } catch (e) { }
    try { if (self._stateSubscription) self._stateSubscription.unsubscribe(); } catch (e) { }
    try { window.removeEventListener('storage', self._storageHandler); } catch (e) { }
    try { document.removeEventListener('visibilitychange', self._visibilityHandler); } catch (e) { }
};

self.actionSources = function () {
    return {
        'click': { name: 'widget-action.click', multiple: false }
    };
};

self.typeParameters = function () {
    return {
        dataKeysOptional: true,
        datasourcesOptional: true,
        maxDatasources: 1,
        maxDataKeys: 0,
        singleEntity: true,
        previewWidth: '200px',
        previewHeight: '80px',
        embedTitlePanel: true,
        overflowVisible: true,
        hideDataSettings: true
    };
};

(function () {
    let chart = null;

    // =========================
    // ✅ Coalesced Refresh (Hướng 1)
    // =========================
    const QUIET_TIME_MS = 350;          // thời gian “yên” để coi state/timewindow đã ổn định
    const SAME_SIG_SKIP_WINDOW_MS = 800; // chống spam khi TB bắn lại cùng chữ ký
    let refreshTimer = null;
    let lastAppliedSig = null;
    let lastAppliedAt = 0;
    let refreshSeq = 0;                // token tăng dần mỗi lần schedule -> dùng để hủy kết quả fetch cũ
    let lastRenderAt = 0;
    const FAST_UPDATE_WINDOW_MS = 700; // nếu switch dồn dập thì update không animation

    function stableStringify(obj) {
        // stringify ổn định để signature không bị lệch do thứ tự key
        const allKeys = [];
        JSON.stringify(obj, (k, v) => (allKeys.push(k), v));
        allKeys.sort();
        return JSON.stringify(obj, allKeys);
    }

    function getTimeWindowSafe() {
        const sub = self.ctx.defaultSubscription;
        const tw = sub?.subscriptionTimewindow;
        let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
        let endTime = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

        // Day mode -> fetch full day (00:00–23:59) để không mất data (display vẫn cắt 7–19 ở applyTimeScale)
        if (isDayMode(tw)) {
            const [s0, e24] = getDayWindowFull(tw);
            startTime = s0;
            endTime = e24;
        }
        return { sub, tw, startTime, endTime };
    }

    function getStateSafe() {
        const stateController = self.ctx.stateController;
        const stateParams = stateController ? stateController.getStateParams() : {};
        const deviceMode = stateParams?.selectedDeviceMode || stateParams?.mode;
        const entitiesFromState = stateParams?.entities || stateParams?.entityIds || [];
        const storeName = stateParams?.selectedDeviceName || stateParams?.name || 'All Devices';
        return { stateParams, deviceMode, entitiesFromState, storeName };
    }

    function getDataKeysSafe(sub) {
        return (sub?.data || []).map(dk => dk.dataKey?.name).filter(Boolean);
    }

    function makeSignature() {
        const { sub, startTime, endTime } = getTimeWindowSafe();
        const { deviceMode, entitiesFromState } = getStateSafe();
        const dataKeys = getDataKeysSafe(sub);

        const entityIds = (entitiesFromState || []).map(e => (e && e.id) ? e.id : e).filter(Boolean).sort();
        const sigObj = {
            deviceMode: deviceMode || '',
            entityIds,
            startTime: startTime || 0,
            endTime: endTime || 0,
            dataKeys: (dataKeys || []).slice().sort()
        };
        return stableStringify(sigObj);
    }

    function scheduleRefresh(reason) {
        if (!chart) return;

        // mỗi lần schedule tăng seq để invalidate fetch/update cũ
        const mySeq = ++refreshSeq;

        if (refreshTimer) clearTimeout(refreshTimer);

        refreshTimer = setTimeout(() => {
            if (!chart) return;

            // nếu trong thời gian chờ mà có schedule mới -> seq đã tăng -> bỏ lượt này
            if (mySeq !== refreshSeq) return;

            const sigNow = makeSignature();

            // nếu signature không đổi và vừa mới apply gần đây -> skip để tránh TB bắn lặp
            const now = Date.now();
            if (sigNow === lastAppliedSig && (now - lastAppliedAt) < SAME_SIG_SKIP_WINDOW_MS) {
                // console.log('[line_chart] ✅ Same signature - skip refresh', { reason });
                return;
            }

            lastAppliedSig = sigNow;
            lastAppliedAt = now;

            // console.log('[line_chart] 🔁 Coalesced refresh', { reason });
            processDataUpdate(mySeq);
        }, QUIET_TIME_MS);
    }

    // =========================
    // Widget lifecycle
    // =========================
    self.onInit = function () {
        if (typeof moment !== 'undefined') {
            moment.locale('en');
        }

        const canvas = self.ctx.$container[0].querySelector('#chart');
        const ctx = canvas.getContext('2d');

        chart = new Chart(ctx, {
            type: 'line',
            data: { datasets: [] },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: { duration: 800, easing: 'easeOutQuart' },
                legend: { display: true, position: 'top', labels: { usePointStyle: true, boxWidth: 3 } },
                tooltips: {
                    backgroundColor: '#FFFFFF',
                    titleFontColor: '#000000',
                    bodyFontColor: '#000000',
                    borderColor: 'rgba(0,0,0,0.15)',
                    borderWidth: 1,
                    displayColors: true,
                    intersect: false,
                    mode: 'index',
                    callbacks: {
                        title: function (items, data) {
                            const ti = items[0];
                            const ds = data.datasets[ti.datasetIndex];
                            const pt = ds && ds.data ? ds.data[ti.index] : null;
                            const ts = (pt && (pt.t || pt.x)) || ti.xLabel || ti.label;
                            const m = (typeof moment !== 'undefined') ? moment(Number(ts)) : null;
                            return m && m.isValid()
                                ? m.format('YYYY-MM-DD')
                                : (ti.label || ti.xLabel || '');
                        },
                        labelPointStyle: function () { return { PointStyle: 'true', rotation: 0 }; },
                        labelColor: function (tooltipItem, chart) {
                            const ds = chart.config.data.datasets[tooltipItem.datasetIndex];
                            const c = ds.borderColor || '#666';
                            return { borderColor: c, backgroundColor: c };
                        }
                    }
                },
                scales: {
                    xAxes: [{
                        type: 'time',
                        time: {
                            tooltipFormat: 'HH:mm',
                            displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'YYYY-MM-DD', month: 'MMM' }
                        },
                        distribution: 'linear',
                        scaleLabel: { display: true, labelString: 'Date Time' },
                        ticks: { source: 'data' },
                        offset: false
                    }],
                    yAxes: [{ scaleLabel: { display: true, labelString: 'People Count' }, ticks: { beginAtZero: true } }]
                },
                pan: { enabled: true, mode: 'x' },
                zoom: { enabled: true, mode: 'x' },
                elements: { point: { radius: 2, hoverRadius: 5, hitRadius: 6 } }
            }
        });

        // ✅ Subscribe to dashboard state changes -> chỉ schedule refresh (không render ngay)
        if (self.ctx.stateController) {
