                    if (!aggregatedData) return;

                    const datasets = buildDatasetsFromAggregatedData(
                        aggregatedData,
                        storeName,
                        startTime,
                        endTime,
                        { isMonthMode, isYearMode, isHourlyGapMode, colorMap, labelMap }
                    );

                    updateChart(datasets, startTime, endTime, { isMonthMode, isYearMode });
                })
                .catch(err => {
