  cursor: default;
}
.cam-card.cam-tablet .card-value {
  display: none;
}
.cam-card.cam-tablet .card-arrow {
  opacity: 0;
}
.cam-card.cam-tablet .hidden-select {
  pointer-events: none;
}

.card-content {
  display: flex;
