  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  width: fit-content;
  border: 1px solid #E5E7EB;
  height: 22px;
}
.cam-card.cam-tablet .cam-banner {
  display: inline-flex;
  align-items: center;
}

.card-arrow {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hidden-select {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  z-index: 10;
  pointer-events: none;
  border-radius: 12px;
  padding-left: var(--select-pad-left);
  padding-right: var(--select-pad-right);
}
