  color: #111827;
  background: #fff;
}

/* Cam uses custom dropdown */
.cam-hidden {
  pointer-events: none;
  opacity: 0;
}

.action-card .card-content.action { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; padding: 0; margin: 0; }
.action-card .card-content.action .card-label { display: none; }

.roi-btn {
  width: 100%;
  height: 100%;
  min-height: 48px;
  border-radius: 10px;
  border: none;
  background: transparent;
  color: #ED1C24;
  cursor: pointer;
  padding: 0;
  transition: background 0.08s ease, transform 0.1s ease;
  box-shadow: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border-radius: 12px;
  overflow: hidden;
