      }

      item.addEventListener('click', function(){
        var idx = parseInt(this.getAttribute('data-series-index'), 10);
        if (!state.hiddenSeries) state.hiddenSeries = {};
        state.hiddenSeries[idx] = !state.hiddenSeries[idx];
