    var S = Object.assign({
      labels: ['0-15', '16-25', '26-45', '>45'],
      colors: ['#0EA54D', '#38A5FF', '#FFAE2B', '#E97CFF'],
      legendPosition: 'bottom',
      datalabelFontSize: 16,
      paddingPx: 2,
      ringGapPx: 2,
      explodePx: 1
