/* Giữ widget full-size trong card của ThingsBoard */
:host, .tb-widget, .tb-widget-container {
  height: 100%;
}

#wrap {
  height: 100%; /* JS sẽ set 90% theo logic gốc khi init */
  width: 100%;
}

#gender-pie {
  display: block;
  width: 100%;
  height: 100%;
}

