descriptor.templateCss:
/* Banner Notify Widget */

.banner-notify-widget {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: #ffffff;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    box-sizing: border-box;
}

/* Status Section */
.status-section {
    padding: 12px;
    border-bottom: 1px solid #E5E7EB;
    background: #ffffff;
    min-height: 40px;
    display: flex;
    align-items: center;
}

.status-text {
    font-size: 12px;
    color: #6B7280;
    font-weight: 500;
}

/* Banner Display Section */
.iframe-container {
    flex: 1;
    position: relative;
    overflow: hidden;
}

iframe {
    width: 100%;
    height: 100%;
    border: none;
    opacity: 0;
    animation: fadeIn 0.8s ease-in forwards;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Loading Overlay - Hidden by default */
.loading-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.95);
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 10;
    opacity: 1;
    transition: opacity 0.5s ease-out;
}

.loading-overlay.show {
    display: flex;
}

.loading-overlay.fade-out {
    opacity: 0;
    pointer-events: none;
}

.loading-text {
    font-size: 13px;
    color: #6B7280;
    animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {

    0%,
    100% {
        opacity: 0.6;
    }

    50% {
        opacity: 1;
    }
}

/* Error Overlay - Hidden by default */
.error-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: #FEF2F2;
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 20px;
    z-index: 10;
}

.error-overlay.show {
    display: flex;
    animation: fadeIn 0.5s ease-in forwards;
}

.error-icon {
    font-size: 48px;
    margin-bottom: 12px;
}

.error-text {
    font-size: 14px;
    color: #991B1B;
    text-align: center;
    max-width: 400px;
}

descriptor.controllerScript:
const BASE_URL = 'https://visiflow-dev.m-tech.com.vn';

self.onInit = function () {
    //console.log('[banner_notify_JP] Widget initialized');

    // Track current store
    self.currentStore = null;

    // Initial load
    initializeWidget();

    // ✅ Subscribe to dashboard state changes (same as line_chart widget)
    if (self.ctx.stateController) {
        let stateDebounce = null;
        self.stateSubscription = self.ctx.stateController.stateChanged().subscribe(function () {
            //console.log('[banner_notify_JP] 📡 Dashboard state changed - triggering refresh');
            // Debounce state changes
            if (stateDebounce) clearTimeout(stateDebounce);
            stateDebounce = setTimeout(() => {
                checkStateChange();
            }, 200);
        });
    }
};

self.onDataUpdated = function () {
    //console.log('[banner_notify_JP] 📊 Data updated');
    // Check state when data updates
    checkStateChange();
};

function initializeWidget() {
    self.statusEl = document.getElementById('status');

    // Initial load
    loadBannerFromState();
}

function checkStateChange() {
    // Get current state
    const stateParams = self.ctx.stateController.getStateParams();
    const storeName = stateParams?.selectedDeviceType || 
                     stateParams?.store || 
                     stateParams?.deviceType ||
                     stateParams?.type;

    // Check if store changed
    if (self.currentStore !== storeName) {
        //console.log('[banner_notify_JP] 🔄 Store changed:', self.currentStore, '→', storeName);
        self.currentStore = storeName;
        loadBannerFromState();
    }
}

function loadBannerFromState() {
    //console.log('[banner_notify_JP] Loading banner from dashboard state');

    // Get store from dashboard state
    const stateParams = self.ctx.stateController.getStateParams();
    //console.log('[banner_notify_JP] State params:', stateParams);

    // Try multiple possible keys for store name
    // store_type widget sets: selectedDeviceType
    const storeName = stateParams?.selectedDeviceType || 
                     stateParams?.store || 
                     stateParams?.deviceType ||
                     stateParams?.type;

    //console.log('[banner_notify_JP] Extracted store name:', storeName);
    //console.log('[banner_notify_JP] Available keys:', Object.keys(stateParams || {}));

    if (storeName) {
        //console.log('[banner_notify_JP] ✓ Loading Japanese banner for store:', storeName);
        loadBanner(storeName);
    } else {
        //console.warn('[banner_notify_JP] ✗ No store found in dashboard state');
        showError('ダッシュボードから店舗を選択してください');
    }
}

function setStatus(msg) {
    if (self.statusEl) {
        self.statusEl.textContent = msg || '';
    }
}

function loadBanner(storeName) {
    const bannerFrame = document.getElementById('bannerFrame');
    const loadingOverlay = document.getElementById('loadingOverlay');
    const errorOverlay = document.getElementById('errorOverlay');

    if (!storeName) {
        showError('店舗が選択されていません。ダッシュボードから店舗を選択してください。');
        return;
    }

    // Hide error, don't show loading (keep white background)
    if (errorOverlay) {
        errorOverlay.classList.remove('show');
    }

    // Construct banner URL - Japanese version
    const fileName = 'banner_notify_jp.html';
    let bannerUrl = `${BASE_URL}/web_server/${fileName}`;

    // Add store parameter and timestamp to force reload
    bannerUrl += `?store=${encodeURIComponent(storeName)}&t=${Date.now()}`;

    //console.log('[banner_notify_JP] 📍 Loading Japanese banner URL:', bannerUrl);
    //console.log('[banner_notify_JP] 🏪 For store:', storeName);

    if (bannerFrame) {
        bannerFrame.src = bannerUrl;

        // Handle iframe load - no need to hide anything, just log
        bannerFrame.onload = function () {
            //console.log('[banner_notify_JP] ✅ Japanese banner iframe loaded successfully');
        };

        // Handle iframe error
        bannerFrame.onerror = function () {
            //console.error('[banner_notify_JP] ❌ Failed to load Japanese banner iframe');
            showError();
        };

        // Timeout fallback
        setTimeout(() => {
            if (loadingOverlay && loadingOverlay.style.display !== 'none') {
                loadingOverlay.style.display = 'none';
            }
        }, 5000);
    }
}

function showError(customMessage) {
    const errorOverlay = document.getElementById('errorOverlay');
    const errorText = document.querySelector('.error-text');

    if (errorOverlay) {
        errorOverlay.classList.add('show');
    }
    if (errorText && customMessage) {
        errorText.textContent = customMessage;
    } else if (errorText) {
        errorText.textContent = '店舗が選択されていないか、バナーが利用できません';
    }
}

self.onResize = function () {
    // Handle widget resize if needed
};

self.onDestroy = function () {
    //console.log('[banner_notify_JP] Widget destroyed');

    // ✅ Unsubscribe from state changes (same as line_chart widget)
    if (self.stateSubscription) {
        self.stateSubscription.unsubscribe();
        self.stateSubscription = null;
    }
};

