descriptor.controllerScript:
self.onInit = function () {
    // Initialize the action widget
    self.ctx.$scope.actionWidget.onInit();

    // Override the default click action to extract dashboard data
    const originalOnClick = self.ctx.$scope.actionWidget.onClick;

    self.ctx.$scope.actionWidget.onClick = function ($event) {
        console.log('=== AI Summary Button Clicked ===');

        // Extract dashboard data
        extractDashboardData();

        // Call original click handler if exists
        if (originalOnClick) {
            originalOnClick.call(this, $event);
        }
    };
}

// ===== Extract Dashboard Data =====
function extractDashboardData() {
    try {
        // 1. Extract Device Info from Dashboard State
        const deviceInfo = getDeviceInfo();
        console.log('📱 Device Info:', deviceInfo);

        // 2. Extract Timewindow Info
        const timewindowInfo = getTimewindowInfo();
        console.log('⏰ Timewindow Info:', timewindowInfo);

        // 3. Extract Telemetry Data (if device and timewindow are available)
        if (deviceInfo && deviceInfo.id && deviceInfo.id !== '__ALL__' && timewindowInfo) {
            fetchTelemetryData(deviceInfo, timewindowInfo);
        } else {
            console.warn('⚠️ Cannot fetch telemetry: Invalid device or timewindow');
        }

        // 4. Summary
        const summary = {
            device: deviceInfo,
            timewindow: timewindowInfo,
            timestamp: new Date().toISOString()
        };

        console.log('📊 Dashboard Data Summary:', summary);

        return summary;

    } catch (error) {
        console.error('❌ Error extracting dashboard data:', error);
        return null;
    }
}

// ===== Get Device Info from Dashboard State =====
function getDeviceInfo() {
    try {
        if (!self.ctx.stateController) {
            console.warn('⚠️ No stateController available');
            return null;
        }

        const stateParams = self.ctx.stateController.getStateParams();

        const deviceInfo = {
            mode: stateParams?.selectedDeviceMode || 'UNKNOWN',
            id: stateParams?.selectedDeviceId || null,
            name: stateParams?.selectedDeviceName || null,
            type: stateParams?.selectedDeviceType || null,
            count: stateParams?.count || 0
        };

        return deviceInfo;

    } catch (error) {
        console.error('❌ Error getting device info:', error);
        return null;
    }
}

// ===== Format Date to GMT+7 =====
function formatDateGMT7(timestampMs) {
    const vnDate = new Date(timestampMs + (7 * 60 * 60 * 1000)); // Convert to GMT+7
    return vnDate.toISOString().replace('Z', '+07:00');
}

// ===== Get Timewindow Info from Dashboard =====
function getTimewindowInfo() {
    try {
        const dashboard = self.ctx.dashboard;
        if (!dashboard) {
            console.warn('⚠️ No dashboard available');
            return null;
        }

        let tw = dashboard.dashboardTimewindow;
        if (!tw && dashboard.getDashboardTimewindow) {
            tw = dashboard.getDashboardTimewindow();
        }

        if (!tw) {
            console.warn('⚠️ No timewindow available');
            return null;
        }

        const startTimeMs = tw?.history?.fixedTimewindow?.startTimeMs;
        const endTimeMs = tw?.history?.fixedTimewindow?.endTimeMs;
        const interval = tw?.history?.interval || tw?.aggregation?.interval || tw?.interval;

        const timewindowInfo = {
            startTimeMs: startTimeMs,
            endTimeMs: endTimeMs,
            interval: interval,
            startDate: startTimeMs ? formatDateGMT7(startTimeMs) : null,
            endDate: endTimeMs ? formatDateGMT7(endTimeMs) : null,
            duration: (endTimeMs && startTimeMs) ? (endTimeMs - startTimeMs) : null
        };

        return timewindowInfo;

    } catch (error) {
        console.error('❌ Error getting timewindow info:', error);
        return null;
    }
}

// ===== Fetch Telemetry Data from ThingsBoard API =====
function fetchTelemetryData(deviceInfo, timewindowInfo) {
    try {
        console.log('📡 Fetching telemetry data...');

        const deviceId = deviceInfo.id;
        const startTs = timewindowInfo.startTimeMs;
        const endTs = timewindowInfo.endTimeMs;
        const interval = timewindowInfo.interval || 3600000; // Default 1 hour

        // ✅ Priority 1: Use specific keys requested by user
        let keys = ['watching_total', 'pass_total', 'paymented_total'];

        // ✅ Priority 2: Get additional keys from subscription (if available)
        if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) {
            const subscriptionKeys = self.ctx.defaultSubscription.data
                .map(dk => dk.dataKey?.name)
                .filter(Boolean);

            // Add subscription keys that are not already in the list
            subscriptionKeys.forEach(key => {
                if (!keys.includes(key)) {
                    keys.push(key);
                }
            });
        }

        console.log('📊 Telemetry keys to fetch:', keys);

        const keysStr = keys.join(',');

        // Build API URL
        const url = `/api/plugins/telemetry/DEVICE/${deviceId}/values/timeseries?keys=${encodeURIComponent(keysStr)}&startTs=${startTs}&endTs=${endTs}&limit=10000&agg=NONE`;

        console.log('📡 API URL:', url);

        // Get auth token
        const token = getToken();

        // Fetch data
        fetch(url, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
            }
        })
            .then(response => {
                console.log('📡 Response status:', response.status);
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                }
                return response.json();
            })
            .then(data => {
                console.log('✅ Telemetry Data Retrieved:', data);

                // Check if data is valid
                if (!data) {
                    console.warn('⚠️ No data returned from API');
                    return;
                }

                // Process and format data
                const formattedData = formatTelemetryData(data);
                console.log('📊 Formatted Telemetry Data:', formattedData);

                // Download data as TXT file
                downloadDataAsTxt(deviceInfo, timewindowInfo, formattedData);
            })
            .catch(error => {
                console.error('❌ Error fetching telemetry data:', error);
            });

    } catch (error) {
        console.error('❌ Error in fetchTelemetryData:', error);
    }
}

// ===== Format Telemetry Data =====
function formatTelemetryData(rawData) {
    const formatted = {};

    // Check if rawData is valid
    if (!rawData || typeof rawData !== 'object') {
        console.warn('⚠️ Invalid rawData:', rawData);
        return formatted;
    }

    for (const key in rawData) {
        if (rawData.hasOwnProperty(key)) {
            // Check if the value is an array
            if (Array.isArray(rawData[key])) {
                formatted[key] = rawData[key].map(item => ({
                    timestamp: item.ts,
                    date: new Date(item.ts).toISOString(),
                    value: item.value
                }));
            } else {
                console.warn(`⚠️ Key "${key}" is not an array:`, rawData[key]);
                formatted[key] = [];
            }
        }
    }

    return formatted;
}

// ===== Download Data as TXT File =====
function downloadDataAsTxt(deviceInfo, timewindowInfo, telemetryData) {
    try {
        console.log('📥 Preparing data for download...');

        // Build TXT content
        let txtContent = '';

        // Header
        txtContent += '='.repeat(80) + '\n';
        txtContent += 'DASHBOARD TELEMETRY DATA EXPORT\n';
        txtContent += '='.repeat(80) + '\n\n';

        // Export timestamp
        txtContent += `Export Time: ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}\n`;
        txtContent += `Export Timestamp: ${Date.now()}\n\n`;

        // Device Information
        txtContent += '-'.repeat(80) + '\n';
        txtContent += 'DEVICE INFORMATION\n';
        txtContent += '-'.repeat(80) + '\n';
        if (deviceInfo) {
            txtContent += `Device ID: ${deviceInfo.id || 'N/A'}\n`;
            txtContent += `Device Name: ${deviceInfo.name || 'N/A'}\n`;
            txtContent += `Device Type: ${deviceInfo.type || 'N/A'}\n`;
            txtContent += `Mode: ${deviceInfo.mode || 'N/A'}\n`;
        } else {
            txtContent += 'No device information available\n';
        }
        txtContent += '\n';

        // Timewindow Information
        txtContent += '-'.repeat(80) + '\n';
        txtContent += 'TIMEWINDOW INFORMATION\n';
        txtContent += '-'.repeat(80) + '\n';
        if (timewindowInfo) {
            txtContent += `Start Time: ${timewindowInfo.startDate || 'N/A'}\n`;
            txtContent += `End Time: ${timewindowInfo.endDate || 'N/A'}\n`;
        } else {
            txtContent += 'No timewindow information available\n';
        }
        txtContent += '\n';

        // Determine aggregation mode based on duration
        const durationDays = timewindowInfo?.duration ? timewindowInfo.duration / (24 * 60 * 60 * 1000) : 0;
        let aggregationMode = 'hour'; // default
        let aggregationLabel = 'Hourly';

        if (durationDays > 300) {
            // Year mode
            aggregationMode = 'month';
            aggregationLabel = 'Monthly';
        } else if (durationDays > 1) {
            // Month mode
            aggregationMode = 'day';
            aggregationLabel = 'Daily';
        } else {
            // Day mode
            aggregationMode = 'hour';
            aggregationLabel = 'Hourly';
        }

        txtContent += '-'.repeat(80) + '\n';
        txtContent += `AGGREGATION MODE: ${aggregationLabel}\n`;
        txtContent += '-'.repeat(80) + '\n\n';

        // Telemetry Data Summary (Total only)
        txtContent += '='.repeat(80) + '\n';
        txtContent += 'TELEMETRY DATA SUMMARY\n';
        txtContent += '='.repeat(80) + '\n\n';

        if (telemetryData && Object.keys(telemetryData).length > 0) {
            for (const key in telemetryData) {
                const dataPoints = telemetryData[key];


                if (dataPoints.length > 0) {
                    // Calculate total only
                    const values = dataPoints.map(d => parseFloat(d.value)).filter(v => !isNaN(v));
                    if (values.length > 0) {
                        const sum = values.reduce((a, b) => a + b, 0);
                        txtContent += `[${key.toUpperCase()}] Total: ${sum.toFixed(2)}\n`;
                    }
                }
            }
        } else {
            txtContent += 'No telemetry data available\n\n';
        }

        // Aggregated Data by Time Period
        txtContent += '='.repeat(80) + '\n';
        txtContent += `AGGREGATED DATA (${aggregationLabel})\n`;
        txtContent += '='.repeat(80) + '\n\n';

        if (telemetryData && Object.keys(telemetryData).length > 0) {
            for (const key in telemetryData) {
                const dataPoints = telemetryData[key];

                txtContent += '-'.repeat(80) + '\n';
                txtContent += `${key.toUpperCase()}\n`;
                txtContent += '-'.repeat(80) + '\n';

                if (dataPoints.length > 0) {
                    // Aggregate data by time period
                    const aggregated = aggregateDataByPeriod(dataPoints, aggregationMode);

                    // Format header based on aggregation mode
                    if (aggregationMode === 'hour') {
                        txtContent += 'Date'.padEnd(25) + 'Hour'.padEnd(15) + 'Total\n';
                    } else if (aggregationMode === 'day') {
                        txtContent += 'Date'.padEnd(40) + 'Total\n';
                    } else {
                        txtContent += 'Month'.padEnd(40) + 'Total\n';
                    }
                    txtContent += '-'.repeat(80) + '\n';

                    // Sort by timestamp
                    const sortedKeys = Object.keys(aggregated).sort((a, b) => Number(a) - Number(b));

                    sortedKeys.forEach(ts => {
                        const date = new Date(Number(ts));
                        let dateStr = '';

                        if (aggregationMode === 'hour') {
                            // Format: YYYY-MM-DD HH:00 (GMT+7)
                            const vnDate = new Date(date.getTime() + (7 * 60 * 60 * 1000));
                            const datePart = vnDate.toISOString().split('T')[0];
                            const hour = vnDate.getUTCHours().toString().padStart(2, '0') + ':00';
                            dateStr = datePart.padEnd(25) + hour.padEnd(15);
                        } else if (aggregationMode === 'day') {
                            // Format: YYYY-MM-DD (GMT+7)
                            const vnDate = new Date(date.getTime() + (7 * 60 * 60 * 1000));
                            dateStr = vnDate.toISOString().split('T')[0].padEnd(40);
                        } else {
                            // Format: YYYY-MM (GMT+7)
                            const vnDate = new Date(date.getTime() + (7 * 60 * 60 * 1000));
                            const year = vnDate.getUTCFullYear();
                            const month = (vnDate.getUTCMonth() + 1).toString().padStart(2, '0');
                            dateStr = `${year}-${month}`.padEnd(40);
                        }

                        txtContent += `${dateStr}${aggregated[ts].toFixed(2)}\n`;
                    });
                } else {
                    txtContent += 'No data points\n';
                }
                txtContent += '\n';
            }
        } else {
            txtContent += 'No data available for aggregation\n\n';
        }

        // Footer
        txtContent += '='.repeat(80) + '\n';
        txtContent += 'END OF REPORT\n';
        txtContent += '='.repeat(80) + '\n';

        // Create filename with timestamp and device info
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
        const deviceName = deviceInfo?.name ? deviceInfo.name.replace(/[^a-zA-Z0-9]/g, '_') : 'unknown';
        const filename = `telemetry_${deviceName}_${timestamp}.txt`;

        // Create blob and download
        const blob = new Blob([txtContent], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        console.log('✅ File downloaded successfully:', filename);

    } catch (error) {
        console.error('❌ Error downloading file:', error);
    }
}

// ===== Aggregate Data by Time Period =====
function aggregateDataByPeriod(dataPoints, mode) {
    const aggregated = {};

    dataPoints.forEach(point => {
        const ts = point.timestamp;
        const date = new Date(ts);
        let normalizedTs;

        if (mode === 'hour') {
            // Normalize to hour
            normalizedTs = new Date(date.getFullYear(), date.getMonth(), date.getDate(), date.getHours(), 0, 0, 0).getTime();
        } else if (mode === 'day') {
            // Normalize to day
            normalizedTs = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0).getTime();
        } else {
            // Normalize to month
            normalizedTs = new Date(date.getFullYear(), date.getMonth(), 1, 0, 0, 0, 0).getTime();
        }

        if (!aggregated[normalizedTs]) {
            aggregated[normalizedTs] = 0;
        }
        aggregated[normalizedTs] += parseFloat(point.value) || 0;
    });

    return aggregated;
}

// ===== Get Auth Token =====
function getToken() {
    const jwtToken = localStorage.getItem('jwt_token');
    const token = localStorage.getItem('token');
    return jwtToken || token || '';
}

self.actionSources = function () {
    return {
        'click': {
            name: 'widget-action.click',
            multiple: false
        }
    };
}

self.typeParameters = function () {
    return {
        dataKeysOptional: true,
        datasourcesOptional: true,
        maxDatasources: 1,
        maxDataKeys: 0,
        singleEntity: true,
        previewWidth: '200px',
        previewHeight: '80px',
        embedTitlePanel: true,
        overflowVisible: true,
        hideDataSettings: true
    };
}

self.onDestroy = function () {
}

